INSERT OR REPLACE INTO "units" VALUES(1005000210,'重装型高达','重装型高达',4,1,2,0,'10000000000500010','50','g0050u00200','FA-78-2',1,1,1,1,8826,89,1016,835,786,4,63544,239,7313,6012,6285,4,64266,242,7396,6081,6356,4,3,1,3,1,2,'在FSWS计划中，对MS所使用的武装部分也积极地进行著全新开发。
