INSERT OR REPLACE INTO "units" VALUES(1007000200,'G-3高达','G-3高达',4,1,2,0,'10000000000700010','70','g0070u00200','RX-78-3',1,1,1,1,7600,80,968,720,754,4,54720,228,6968,5184,5714,4,60876,254,7752,5768,6357,4,3,1,3,1,2,'联邦军推行的MS开发计划「V作战」下所开发的「高达」系列第3号机体，与其他的RX系列机一同运出SIDE7时，受到自护公国军特殊部队攻击而使机体局部损坏，因而由「白色基地」回收当作提供零件的备用机。
后来改造为搭载了新型教育电脑和热核反应炉用激光加速器等配备的新人类规格，在被用为电磁涂层处理的测试平台之后，将搭载兵器等改为正规配备，配至飞马级战舰上。
至于本机体的相关实际工作运用等方面的纪录，由于资讯庞杂，许多并不可靠。','{"id": 1007000200, "hp": 7600, "en": 80, "attack": 968, "defense": 720, "mobility": 754, "movement": 4, "max_hp": 54720, "max_en": 228, "max_attack": 6968, "max_defense": 5184, "max_mobility": 5714, "max_movement": 4, "sp_hp": 8455, "sp_en": 89, "sp_attack": 1077, "sp_defense": 801, "sp_mobility": 839, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 254, "sp_max_attack": 7752, "sp_max_defense": 5768, "sp_max_mobility": 6357, "sp_max_movement": 4}','{"unit_id": 1007000200, "unit_ssp_initial_release_set_id": 1007000200, "unit_ssp_custom_core_group_id": 1007000200, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 100700020001, "unit_ssp_custom_core_group_id": 1007000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100700020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100700020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100700020001, "weapon_change": {"id": 100700020001, "before_weapon_id": 0, "after_weapon_id": 100700020090, "weapon": {"id": 100700020090, "name": "超絕火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100700020090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100700020090, "weapon_status": {"id": 100700020090, "range_min": 2, "range_max": 4, "power": 5000, "e