INSERT OR REPLACE INTO "units" VALUES(1007000510,'高速度型渣古II后期型(强尼·莱汀专用)','高机动型渣古Ⅱ(尊尼‧莱登专用机)',3,2,2,0,'10000000000700010','70','g0070u00500','MS-06R-2',1,1,1,1,8608,65,639,861,750,4,61976,228,4600,6198,4590,4,73545,270,5458,7355,5447,4,3,1,3,1,2,'一年战争时期自护公国开发的「渣古Ⅱ」衍生机之一渣古ⅡR型的后期生产型。R型因为性能好，深受许多王牌驾驶员欢迎，但由于运行条件复杂，成本也高，没有像F型那样大量生产，也非常难被分配到。
「MS-06R-2」的外表虽然是渣古，但也有资料显示其内部采用了许多「盖古克」用的零件。其规格之高，一般视为渣古的最终型，亦是最顶尖的机体。
其中本机体是以「真红的闪电」闻名的尊尼‧莱登的专用机，MS整体都涂上了个人喜好配色的「红色」。','{"id": 1007000510, "hp": 8608, "en": 65, "attack": 639, "defense": 861, "mobility": 750, "movement": 4, "max_hp": 61976, "max_en": 228, "max_attack": 4600, "max_defense": 6198, "max_mobility": 4590, "max_movement": 4, "sp_hp": 10215, "sp_en": 77, "sp_attack": 759, "sp_defense": 1022, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 73545, "sp_max_en": 270, "sp_max_attack": 5458, "sp_max_defense": 7355, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1007000510, "unit_ssp_initial_release_set_id": 1007000510, "unit_ssp_custom_core_group_id": 1007000510, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 100700051001, "unit_ssp_custom_core_group_id": 1007000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100700051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100700051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100700051001, "weapon_change": {"id": 100700051001, "before_weapon_id": 0, "after_weapon_id": 100700051090, "weapon": {"id": 100700051090, "name": "巨型迫擊砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100700051090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100700051090, "weapon_status": {"id": 100700051090, "range_min": 2, "range_max": 4, "pow