INSERT OR REPLACE INTO "units" VALUES(1007000960,'完美吉翁号','完美自护号',4,3,2,0,'10000000000700010','70','g0070u00960','MSN-02',1,1,1,1,8063,80,839,724,838,5,58050,252,6038,5212,5746,5,64580,280,6717,5799,6392,5,3,1,3,1,2,'一年战争末期开发的脑波传导型MS「自护号」完全版，装有开发当初所计划的陆战用步行组件，是身高达38m的超大型MS。
其性能优异，除了地球和宇宙两方面都可运用，原本还预计会是头部、臂部、胸部、 腰部、腿部可以分解成七个组件发动「全方位攻击」的终极MS。
然而随著战局遽变和新人类相关技术快速成长，以致开发计划变更，改为搭载有线脑波传导兵器的宇宙用MS，测试机实际上并未装上步行组件。','{"id": 1007000960, "hp": 8063, "en": 80, "attack": 839, "defense": 724, "mobility": 838, "movement": 5, "max_hp": 58050, "max_en": 252, "max_attack": 6038, "max_defense": 5212, "max_mobility": 5746, "max_movement": 5, "sp_hp": 8970, "sp_en": 89, "sp_attack": 933, "sp_defense": 806, "sp_mobility": 933, "sp_movement": 5, "sp_max_hp": 64580, "sp_max_en": 280, "sp_max_attack": 6717, "sp_max_defense": 5799, "sp_max_mobility": 6392, "sp_max_movement": 5}','{"unit_id": 1007000960, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1007000960, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 100700096001, "unit_ssp_custom_core_group_id": 1007000960, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100700096001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100700096001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100700096001, "weapon_change": {"id": 100700096001, "before_weapon_id": 0, "after_weapon_id": 100700096090, "weapon": {"id": 100700096090, "name": "全方位攻擊 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100700096090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350007, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100700096090, "weapon_status": {"id": 100700096090, "range_min": 3, "range_max": 5