INSERT OR REPLACE INTO "units" VALUES(1007001160,'全装甲高达','全装甲型高达',4,1,2,0,'10000000000700010','70','g0070u01160','FA-78-1',1,1,1,1,7976,80,926,685,801,5,57422,240,6661,4927,5765,5,63882,267,7410,5481,6414,5,3,1,3,1,2,'依联邦军推行的MS武装增设方案「FSWS计划」开发而成的试作型MS。将附有背部「360mm加农砲」和「飞弹夹」等强力固定装备和推进装置的追加装甲装上「高达」，旨在同时实现高火力和高机动性。
然而本机体也因为其高规格而难以生产，机体的相关纪录不多，许多部分的细节并不明确，但是「为完成的MS安装追加装甲以期提高性能」的概念，在后来成了开发追加装甲计划案的基础。','{"id": 1007001160, "hp": 7976, "en": 80, "attack": 926, "defense": 685, "mobility": 801, "movement": 5, "max_hp": 57422, "max_en": 240, "max_attack": 6661, "max_defense": 4927, "max_mobility": 5765, "max_movement": 5, "sp_hp": 8873, "sp_en": 89, "sp_attack": 1030, "sp_defense": 762, "sp_mobility": 891, "sp_movement": 5, "sp_max_hp": 63882, "sp_max_en": 267, "sp_max_attack": 7410, "sp_max_defense": 5481, "sp_max_mobility": 6414, "sp_max_movement": 5}','{"unit_id": 1007001160, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1007001160, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 100700116001, "unit_ssp_custom_core_group_id": 1007001160, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100700116001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100700116001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100700116001, "weapon_change": {"id": 100700116001, "before_weapon_id": 0, "after_weapon_id": 100700116090, "weapon": {"id": 100700116090, "name": "360mm加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100700116090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100700116090, "weapon_status": {"id": 100700116090, "range