INSERT OR REPLACE INTO "units" VALUES(1008000110,'吉刚','盖刚',2,3,2,0,'10000000000800010','80','g0080u00100','MS-12',1,1,1,1,6611,70,741,664,735,4,47593,221,5335,4779,5040,4,60511,281,6783,6076,6408,4,3,1,3,1,2,'基于一年战争时期自护公国推进的「培曾计划」所开发的支援／防空用简易生产型MS。没有步行组件，以三轮行驶，实际上类似移动砲台。
