INSERT OR REPLACE INTO "units" VALUES(1008000210,'加尔巴迪α','哥邦迪α',3,1,2,0,'10000000000800010','80','g0080u00200','MS-17',1,1,1,1,6764,75,863,713,749,4,48698,225,6210,5130,5390,4,57788,267,7370,6088,6396,4,3,1,3,1,2,'基于一年战争时期自护公国推进的「培曾计划」所开发的泛用试作型MS。因计划以「盖古克」为基底提高性能，加入了在评选次世代主力MS时参与角逐的短兵交战专用MS「强人」所拥有的格斗能力设计而成的高性能机体。
本机体开发有陆战用的A型和宇宙战用的B型；A型的目标是要能在大气层内飞行，因此机体有减轻重量，并加大推进器的输出功率，还加装胸部热核喷射引擎，原本预期可达成更高境界的机动战，但据说实际上性能并未达标而中止了开发工作。','{"id": 1008000210, "hp": 6764, "en": 75, "attack": 863, "defense": 713, "mobility": 749, "movement": 4, "max_hp": 48698, "max_en": 225, "max_attack": 6210, "max_defense": 5130, "max_mobility": 5390, "max_movement": 4, "sp_hp": 8027, "sp_en": 89, "sp_attack": 1024, "sp_defense": 846, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 57788, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6088, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1008000210, "unit_ssp_initial_release_set_id": 1008000210, "unit_ssp_custom_core_group_id": 1008000210, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 100800021001, "unit_ssp_custom_core_group_id": 1008000210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100800021001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100800021001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100800021001, "weapon_change": {"id": 100800021001, "before_weapon_id": 0, "after_weapon_id": 100800021090, "weapon": {"id": 100800021090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100800021090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100800021090, "weapon_status"