et": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}], "units": null, "characters": null}}}}','葛夏','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1009000110,'兹达 (1号机)','积达 (1号机)',4,3,12,0,'10000000000900010','90','g0090u00100','EMS-10',1,1,1,1,8853,88,831,880,924,4,63741,278,5984,6336,6336,4,64465,281,6052,6408,6408,4,3,1,3,1,1,'ZIMMAD为了抢下自护公国军主力量产型MS甄选案而开发的试作型MS。开发案名为「EMS-04积达」，是具有高机动力的高性能机体，搭载了使用远比旧有燃料沉重的铅、锌、铋等重金属元素当作燃料使用的「土星引擎」 。
虽然因此而获得撼人的高机动性，但是高推力、高加速力加上使用AMBAC系统能剧烈改变方向，已超越了机体的极限，在公开飞行测试时引发了空中解体的事故。
本机体由于在测试中发生空中解体事故而未受采用，后来又以高性能机「EMS-10积达」的名义复活，据称大幅改良了EMS-04的机体结构，是超越渣古的全新机体，但结果并未改善初期机体的缺陷，甚至到底有没有修改过也不得而知。
被配备到实验支援舰「约顿海姆」，接受第603技术实验队评测实验的四架机体由于又在过程中发生空中解体事故而未被许可量产。
另外，本机体是约翰‧留克‧杜瓦少校驾驶的一号机，头部加装了代表指挥官机型的角状装饰。','{"id": 1009000110, "hp": 8853, "en": 88, "attack": 831, "defense": 880, "mobility": 924, "movement": 4, "max_hp": 63741, "max_en": 278, "max_attack": 5984, "max_defense": 6336, "max_mobility": 6336, "max_movement": 4, "sp_hp": 8954, "sp_en": 89, "sp_attack": 841, "sp_defense": 890, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 64465, "sp_max_en": 281, "sp_max_attack": 6052, "sp_max_defense": 6408, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1009000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000110, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 100900011001, "unit_ssp_custom_core_group_id": 1009000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900011001, "weapon_change": {"id": 100900011001, "before_weapon_id": 0, "after_weapon_id": 100900011090, "weapon": {"id": 100900011090, "name": "135mm對艦步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900011090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900011090, "weapon_status": {"id": 100900011090, "range_min": 3, "range_max": 5, "power": 4800, "