INSERT OR REPLACE INTO "units" VALUES(1009000200,'斗狼','战狼',4,3,6,0,'10000000000900010','90','g0090u00200','YMT-05',1,1,1,1,7577,81,840,760,843,4,54551,254,6044,5468,5780,4,60688,283,6724,6083,6430,4,1,1,3,1,2,'自护公国开发的试作机动坦克，整个机身巨大又包覆著厚实的装甲，同时最高时速能达到110km，口径达30公分的主砲可以填装「APFSDS弹」或「燃烧榴弹」等各式各样的砲弹发挥出高战斗力，是堪称超级战车的机体。
又，上半身变形成MS型态下，可用「挖土机手臂组件」格斗，也可携带「渣古机枪」等武装，能够支应对上MS时的近距离战斗。
其高战斗能力原本是受到相当期待，但在一开始的运用评价实验中并不受军方高层同意采用。虽然两年后再次交由「第603技术实验队」在地球评价实验，但实验结束后并没有回收，而是要直接配备到现场使用，所以事实上是当成了抛弃式机体在运用。','{"id": 1009000200, "hp": 7577, "en": 81, "attack": 840, "defense": 760, "mobility": 843, "movement": 4, "max_hp": 54551, "max_en": 254, "max_attack": 6044, "max_defense": 5468, "max_mobility": 5780, "max_movement": 4, "sp_hp": 8429, "sp_en": 90, "sp_attack": 934, "sp_defense": 845, "sp_mobility": 938, "sp_movement": 4, "sp_max_hp": 60688, "sp_max_en": 283, "sp_max_attack": 6724, "sp_max_defense": 6083, "sp_max_mobility": 6430, "sp_max_movement": 4}','{"unit_id": 1009000200, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000200, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 100900020001, "unit_ssp_custom_core_group_id": 1009000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900020001, "weapon_change": {"id": 100900020001, "before_weapon_id": 0, "after_weapon_id": 100900020090, "weapon": {"id": 100900020090, "name": "30cm砲 (APFSDS彈) SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900020090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900020090, "weapon_st