INSERT OR REPLACE INTO "units" VALUES(1009000210,'斗狼','战狼',4,1,6,0,'10000000000900010','90','g0090u00200','YMT-05',1,1,1,1,7984,88,1010,833,879,4,57481,264,7272,5996,6324,4,58134,267,7355,6064,6396,4,1,1,3,1,2,'自护公国开发的试作机动坦克，整个机身巨大又包覆著厚实的装甲，同时最高时速能达到110km，口径达30公分的主砲可以填装「APFSDS弹」或「燃烧榴弹」等各式各样的砲弹发挥出高战斗力，是堪称超级战车的机体。
又，上半身变形成MS型态下，可用「挖土机手臂组件」格斗，也可携带「渣古机枪」等武装，能够支应对上MS时的近距离战斗。
其高战斗能力原本是受到相当期待，但在一开始的运用评价实验中并不受军方高层同意采用。虽然两年后再次交由「第603技术实验队」在地球评价实验，但实验结束后并没有回收，而是要直接配备到现场使用，所以事实上是当成了抛弃式机体在运用。','{"id": 1009000210, "hp": 7984, "en": 88, "attack": 1010, "defense": 833, "mobility": 879, "movement": 4, "max_hp": 57481, "max_en": 264, "max_attack": 7272, "max_defense": 5996, "max_mobility": 6324, "max_movement": 4, "sp_hp": 8075, "sp_en": 89, "sp_attack": 1022, "sp_defense": 843, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 58134, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 6064, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1009000210, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000210, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 100900021001, "unit_ssp_custom_core_group_id": 1009000210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900021001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900021001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900021001, "weapon_change": {"id": 100900021001, "before_weapon_id": 0, "after_weapon_id": 100900021090, "weapon": {"id": 100900021090, "name": "30cm砲 (APFSDS彈) SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900021090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900021090, "weapon_