INSERT OR REPLACE INTO "units" VALUES(1009000400,'兹达','积达',3,2,12,0,'10000000000900010','90','g0090u00400','EMS-10',1,1,1,1,8808,60,592,736,694,4,63416,212,4261,5295,4246,4,80629,269,5418,6732,5399,4,3,1,3,1,1,'ZIMMAD为了抢下自护公国军主力量产型MS甄选案而开发的试作型MS。开发案名为「EMS-04积达」，是具有高机动力的高性能机体，搭载了使用远比旧有燃料沉重的铅、锌、铋等重金属元素当作燃料使用的「土星引擎」 。
虽然因此而获得撼人的高机动性，但是高推力、高加速力加上使用AMBAC系统能剧烈改变方向，已超越了机体的极限，在公开飞行测试时引发了空中解体的事故。
本机体由于在测试中发生空中解体事故而未受采用，后来又以高性能机「EMS-10积达」的名义复活，据称大幅改良了EMS-04的机体结构，是超越渣古的全新机体，但结果并未改善初期机体的缺陷，甚至到底有没有修改过也不得而知。
被配备到实验支援舰「约顿海姆」，接受第603技术实验队评测实验的四架机体由于又在过程中发生空中解体事故而未被许可量产。','{"id": 1009000400, "hp": 8808, "en": 60, "attack": 592, "defense": 736, "mobility": 694, "movement": 4, "max_hp": 63416, "max_en": 212, "max_attack": 4261, "max_defense": 5295, "max_mobility": 4246, "max_movement": 4, "sp_hp": 11199, "sp_en": 77, "sp_attack": 753, "sp_defense": 935, "sp_mobility": 883, "sp_movement": 4, "sp_max_hp": 80629, "sp_max_en": 269, "sp_max_attack": 5418, "sp_max_defense": 6732, "sp_max_mobility": 5399, "sp_max_movement": 4}','{"unit_id": 1009000400, "unit_ssp_initial_release_set_id": 1009000400, "unit_ssp_custom_core_group_id": 1009000400, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 100900040001, "unit_ssp_custom_core_group_id": 1009000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900040001, "weapon_change": {"id": 100900040001, "before_weapon_id": 0, "after_weapon_id": 100900040090, "weapon": {"id": 100900040090, "name": "盾牌精選 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900040090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 260001, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900040090, "weapon_status": {"id": 100900040090, "range_min": 1, "range_max"