INSERT OR REPLACE INTO "units" VALUES(1009000500,'比格·朗格','比格‧朗格',4,1,5,0,'10000000000900010','90','g0090u00500','MA-05Ad',1,1,1,1,8004,81,921,762,721,4,57624,217,6628,5484,5763,4,64106,241,7374,6101,6411,4,3,1,1,1,1,'沿用自护公国著手开发的超级MA的机体部分，结合开发目的是在宇宙中高速战斗的宇宙用量产型MA「宇宙魔蟹」制作而成的巨大MA。其使用目的是在最前线借由安装在身体部分的「活动补给厂组件」为机动艇补给武器弹药，或紧急整备机体让其继续战斗。
装备在机体上的武装除了核心组件的宇宙魔蟹拥有的「高输出米加粒子砲」和「钩爪臂」之外，还有安装在身体部位，称作「Ad组件」的「镭射扰乱幕」和「对舰飞弹」等，在混战状态的战场立下了巨大战果。但是身高138m，全长203m的巨大身躯让运动性难说有多高，而且还有著不容易应付正面之外攻击等许多问题。','{"id": 1009000500, "hp": 8004, "en": 81, "attack": 921, "defense": 762, "mobility": 721, "movement": 4, "max_hp": 57624, "max_en": 217, "max_attack": 6628, "max_defense": 5484, "max_mobility": 5763, "max_movement": 4, "sp_hp": 8904, "sp_en": 90, "sp_attack": 1025, "sp_defense": 848, "sp_mobility": 802, "sp_movement": 4, "sp_max_hp": 64106, "sp_max_en": 241, "sp_max_attack": 7374, "sp_max_defense": 6101, "sp_max_mobility": 6411, "sp_max_movement": 4}','{"unit_id": 1009000500, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000500, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 100900050001, "unit_ssp_custom_core_group_id": 1009000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900050001, "weapon_change": {"id": 100900050001, "before_weapon_id": 0, "after_weapon_id": 100900050090, "weapon": {"id": 100900050090, "name": "3連裝大型對艦飛彈 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900050090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 200001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusI