INSERT OR REPLACE INTO "units" VALUES(1009000510,'比格·朗格','比格‧朗格',4,2,5,0,'10000000000900010','90','g0090u00500','MA-05Ad',1,1,1,1,10120,75,820,1019,879,4,72864,264,5903,7331,5375,4,73692,267,5970,7414,5436,4,3,1,1,1,1,'沿用自护公国著手开发的超级MA的机体部分，结合开发目的是在宇宙中高速战斗的宇宙用量产型MA「宇宙魔蟹」制作而成的巨大MA。其使用目的是在最前线借由安装在身体部分的「活动补给厂组件」为机动艇补给武器弹药，或紧急整备机体让其继续战斗。
装备在机体上的武装除了核心组件的宇宙魔蟹拥有的「高输出米加粒子砲」和「钩爪臂」之外，还有安装在身体部位，称作「Ad组件」的「镭射扰乱幕」和「对舰飞弹」等，在混战状态的战场立下了巨大战果。但是身高138m，全长203m的巨大身躯让运动性难说有多高，而且还有著不容易应付正面之外攻击等许多问题。','{"id": 1009000510, "hp": 10120, "en": 75, "attack": 820, "defense": 1019, "mobility": 879, "movement": 4, "max_hp": 72864, "max_en": 264, "max_attack": 5903, "max_defense": 7331, "max_mobility": 5375, "max_movement": 4, "sp_hp": 10235, "sp_en": 76, "sp_attack": 830, "sp_defense": 1030, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 73692, "sp_max_en": 267, "sp_max_attack": 5970, "sp_max_defense": 7414, "sp_max_mobility": 5436, "sp_max_movement": 4}','{"unit_id": 1009000510, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000510, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 100900051001, "unit_ssp_custom_core_group_id": 1009000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900051001, "weapon_change": {"id": 100900051001, "before_weapon_id": 0, "after_weapon_id": 100900051090, "weapon": {"id": 100900051090, "name": "高輸出米加粒子砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900051090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatu