INSERT OR REPLACE INTO "units" VALUES(1009000700,'杰卡克','杰卡克',3,1,4,0,'10000000000900010','90','g0090u00700','MSM-07D',1,1,1,1,6989,70,811,598,699,4,50315,210,5837,4302,5027,4,63972,266,7421,5470,6391,4,3,3,1,1,1,'自护公国以卫星轨道上发动突袭为目的所开发，由机动潜航系统和其管制组件形成的机体，管制组件的基底沿用耐压耐冲击性佳，其中搭载有复合热核引擎的两栖用MS「魔蟹」，而在一只手臂换成感测臂之下，可以控制紧急制造出来的L.W.C.（大量兵器运输用船舱）。
本机体是「第603技术实验队」第三次运用实验的对象，在搭载扩散镭射砲「蒲公英式」的状态下，为了拦截从查布罗升空的敌方舰队而从平流层进入地球。在照射五秒以上就可能爆炸的危险情况下，成功击沉了五艘敌方船舰，但就在因为将蒲公英式从管制组件卸除，完全无战斗能力时遭到联邦军攻击而沉入海中。','{"id": 1009000700, "hp": 6989, "en": 70, "attack": 811, "defense": 598, "mobility": 699, "movement": 4, "max_hp": 50315, "max_en": 210, "max_attack": 5837, "max_defense": 4302, "max_mobility": 5027, "max_movement": 4, "sp_hp": 8885, "sp_en": 89, "sp_attack": 1031, "sp_defense": 760, "sp_mobility": 888, "sp_movement": 4, "sp_max_hp": 63972, "sp_max_en": 266, "sp_max_attack": 7421, "sp_max_defense": 5470, "sp_max_mobility": 6391, "sp_max_movement": 4}','{"unit_id": 1009000700, "unit_ssp_initial_release_set_id": 1009000700, "unit_ssp_custom_core_group_id": 1009000700, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 100900070001, "unit_ssp_custom_core_group_id": 1009000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900070001, "weapon_change": {"id": 100900070001, "before_weapon_id": 0, "after_weapon_id": 100900070090, "weapon": {"id": 100900070090, "name": "蒲公英式 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900070090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 130005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId