INSERT OR REPLACE INTO "units" VALUES(1009000800,'格鲁古古 (海尔贝特·冯·加斯潘专用)','盖古克 (赫伯特‧冯‧卡斯班专用)',4,2,2,0,'10000000000900010','90','g0090u00800','MS-14',1,1,1,1,9258,68,677,921,806,5,66658,240,4871,6630,4929,5,74157,267,5419,7376,5483,5,3,1,3,1,2,'继自护公国开发的主力MS「渣古Ⅱ」后的下期主力MS。由自护尼克、ZIMMAD、MIP企业共同开发，于大战末期完成，是堪称自护公国MS集大成的机体，也是自护公国第一架正式采用携带式镭射兵器的MS。
虽然是尺寸媲美「大魔」的大型机，但由于强化过推进力，机动性和运动性能非常高，更因搭载了镭射兵器，远近皆具备高超的战斗力，在一年战争末期发挥出几乎横扫联邦军主力MS的性能。
本机体是前往实验支援舰「约顿海姆」就任的「赫伯特‧冯‧卡斯班本上校」所驾驶的专用机，MS整体涂上以灰色为主色的配色，背部装有高机动型的背包，头部加装了代表指挥官机型的刀型天线。','{"id": 1009000800, "hp": 9258, "en": 68, "attack": 677, "defense": 921, "mobility": 806, "movement": 5, "max_hp": 66658, "max_en": 240, "max_attack": 4871, "max_defense": 6630, "max_mobility": 4929, "max_movement": 5, "sp_hp": 10300, "sp_en": 76, "sp_attack": 753, "sp_defense": 1025, "sp_mobility": 896, "sp_movement": 5, "sp_max_hp": 74157, "sp_max_en": 267, "sp_max_attack": 5419, "sp_max_defense": 7376, "sp_max_mobility": 5483, "sp_max_movement": 5}','{"unit_id": 1009000800, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1009000800, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 100900080001, "unit_ssp_custom_core_group_id": 1009000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900080001, "weapon_change": {"id": 100900080001, "before_weapon_id": 0, "after_weapon_id": 100900080090, "weapon": {"id": 100900080090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900080090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900080090, "weapon_status": {"id": 100900080090, "rang