INSERT OR REPLACE INTO "units" VALUES(1009000810,'格鲁古古 (海尔贝特·冯·加斯潘专用)','盖古克 (赫伯特‧冯‧卡斯班专用)',3,1,2,0,'10000000000900010','90','g0090u00800','MS-14',1,1,1,1,7500,75,865,639,749,4,54000,223,6223,4600,5390,4,64080,265,7384,5458,6396,4,3,1,3,1,2,'继自护公国开发的主力MS「渣古Ⅱ」后的下期主力MS。由自护尼克、ZIMMAD、MIP企业共同开发，于大战末期完成，是堪称自护公国MS集大成的机体，也是自护公国第一架正式采用携带式镭射兵器的MS。
虽然是尺寸媲美「大魔」的大型机，但由于强化过推进力，机动性和运动性能非常高，更因搭载了镭射兵器，远近皆具备高超的战斗力，在一年战争末期发挥出几乎横扫联邦军主力MS的性能。
本机体是前往实验支援舰「约顿海姆」就任的「赫伯特‧冯‧卡斯班本上校」所驾驶的专用机，MS整体涂上以灰色为主色的配色，背部装有高机动型的背包，头部加装了代表指挥官机型的刀型天线。','{"id": 1009000810, "hp": 7500, "en": 75, "attack": 865, "defense": 639, "mobility": 749, "movement": 4, "max_hp": 54000, "max_en": 223, "max_attack": 6223, "max_defense": 4600, "max_mobility": 5390, "max_movement": 4, "sp_hp": 8900, "sp_en": 89, "sp_attack": 1026, "sp_defense": 759, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 265, "sp_max_attack": 7384, "sp_max_defense": 5458, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1009000810, "unit_ssp_initial_release_set_id": 1009000810, "unit_ssp_custom_core_group_id": 1009000810, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 100900081001, "unit_ssp_custom_core_group_id": 1009000810, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 100900081001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 100900081001, "sort_order": 1, "release_function_type_index": 5, "target_id": 100900081001, "weapon_change": {"id": 100900081001, "before_weapon_id": 0, "after_weapon_id": 100900081090, "weapon": {"id": 100900081090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 100900081090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 100900081090, "weapon_status": {"id": 10090008109