INSERT OR REPLACE INTO "units" VALUES(1012000110,'陆战强袭型钢坦克','陆战强袭型太空坦克',3,1,6,0,'10000000001200010','120','g0120u00100','RTX-440',1,1,1,1,6804,75,863,707,750,4,48989,225,6210,5089,5400,4,58134,267,7370,6039,6408,4,1,1,3,1,2,'将太空坦克的试作机「RTX-44」针对对MS战改良而成的机体。武装相比基底机体丰富，能发动更多采多姿的攻击。
最大的特征是，展开前方的辅助履带时上半身能滑动前倾变形为「突击砲型态」，发挥凌驾于MS之上的机动力。
但由于开发资料被泄漏给敌方自护公国，于是被迫停止开发，未能进行量产。
剩余的试作机也为了保守机密，搭载了自爆装置，事实上就是废弃处分。','{"id": 1012000110, "hp": 6804, "en": 75, "attack": 863, "defense": 707, "mobility": 750, "movement": 4, "max_hp": 48989, "max_en": 225, "max_attack": 6210, "max_defense": 5089, "max_mobility": 5400, "max_movement": 4, "sp_hp": 8075, "sp_en": 89, "sp_attack": 1024, "sp_defense": 839, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 58134, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6039, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1012000110, "unit_ssp_initial_release_set_id": 1012000110, "unit_ssp_custom_core_group_id": 1012000110, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 101200011001, "unit_ssp_custom_core_group_id": 1012000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101200011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101200011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101200011001, "weapon_change": {"id": 101200011001, "before_weapon_id": 0, "after_weapon_id": 101200011090, "weapon": {"id": 101200011090, "name": "220mm滑腔砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101200011090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101200011090, "weapon_status": {"id": 101200011090, "range_min": 4, "range_max": 5, "power": 4800, "e