INSERT OR REPLACE INTO "units" VALUES(1013000100,'陆战型高达 (第08MS小队)','陆战型高达 (第08MS小队)',3,1,9,0,'10000000001300010','130','g0130u00100','RX-79[G]',1,1,1,1,7047,70,801,665,632,4,50733,188,5762,4783,5053,4,64503,239,7326,6081,6425,4,1,1,3,1,3,'以配备MS进行实战为第一要务的联邦军，利用「高达」的剩余零件制造的陆战型MS，是MS量产计划最初先行试作的机体之一。
此机体是在高达开发中尚未回收实际运作资料前先行实验性量产的产物，设计上省略宇宙空间战斗用的装备，故可运用的环境有限，但只限重力环境下的话，其高性能的机体规格可说是足以与高达匹敌。
然而因为使用残余零件制作生产，性能发挥不稳定，因此设计了限制器用以平均输出。因性能略逊于高达，故另外搭载可自行解除限制器发挥最高性能的「MAX模式」系统。
而本机，是分发至东南亚地区最前线的小岛大队所属之「第08MS小队」的机体，盾牌上画有代表部队徽章的「08」。','{"id": 1013000100, "hp": 7047, "en": 70, "attack": 801, "defense": 665, "mobility": 632, "movement": 4, "max_hp": 50733, "max_en": 188, "max_attack": 5762, "max_defense": 4783, "max_mobility": 5053, "max_movement": 4, "sp_hp": 8959, "sp_en": 89, "sp_attack": 1018, "sp_defense": 845, "sp_mobility": 804, "sp_movement": 4, "sp_max_hp": 64503, "sp_max_en": 239, "sp_max_attack": 7326, "sp_max_defense": 6081, "sp_max_mobility": 6425, "sp_max_movement": 4}','{"unit_id": 1013000100, "unit_ssp_initial_release_set_id": 1013000100, "unit_ssp_custom_core_group_id": 1013000100, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 101300010001, "unit_ssp_custom_core_group_id": 1013000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300010001, "weapon_change": {"id": 101300010001, "before_weapon_id": 0, "after_weapon_id": 101300010090, "weapon": {"id": 101300010090, "name": "180mm加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300010090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 30011, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300010090, "weapon_status": {"id": 101300010090, "range_min": 3, "range_max":