INSERT OR REPLACE INTO "units" VALUES(1013000200,'陆战型高达 (吉姆头)','陆战型高达 (吉姆头)',3,2,9,0,'10000000001300010','130','g0130u00200','RX-79[G]',1,1,1,1,8061,60,687,807,698,4,58036,210,4942,5809,4269,4,73788,267,6283,7385,5427,4,1,1,3,1,3,'由于联邦军陆战型MS「陆战型高达」的装甲与内部零件大多数是沿用标准的高达备用零件或复制品，纯正零件的存量并不充足，故各基地经常挪用其他机体或装备的零件做紧急修理。
