INSERT OR REPLACE INTO "units" VALUES(1013000300,'高达Ez8','高达Ez8',4,3,6,0,'10000000001300010','130','g0130u00300','RX-79[G]Ez-8',1,1,1,1,7979,81,847,719,837,4,57445,253,6099,5177,5735,4,63907,282,6785,5759,6380,4,1,1,3,1,2,'捕捉自护公国巨大MS「阿普撒拉斯Ⅱ」时严重破损的「陆战型高达」，透过沿用吉姆陆战型等的零件的方法现场改造出的特制机。
由于陆战型高达是联邦军MS量产计划最初期实验性少量生产的机种，装甲与内部零件大多为沿用标准的高达备用零件或复制品，故各个零件的存量并不充足。因此，在现场通常只能用其他机体的装备或零件进行紧急修理。
但是这架由「斯罗‧阿马达」驾驶，与阿普撒拉斯Ⅱ战斗后无法行动的陆战型高达则是经过大规模修理，并于分解重整时采用了至今的战斗资料与驾驶员本人的意见，进行了更适合地面战的改装，成为整体性能高过原型机的机体。
另外，「Ez8」是「EXTRA-ZERO-EIGHT」的意思，并非制式编号。而机体胸部装甲板上的「81」则是表示此为08小队的一号机，也就是队长机。','{"id": 1013000300, "hp": 7979, "en": 81, "attack": 847, "defense": 719, "mobility": 837, "movement": 4, "max_hp": 57445, "max_en": 253, "max_attack": 6099, "max_defense": 5177, "max_mobility": 5735, "max_movement": 4, "sp_hp": 8876, "sp_en": 90, "sp_attack": 943, "sp_defense": 800, "sp_mobility": 931, "sp_movement": 4, "sp_max_hp": 63907, "sp_max_en": 282, "sp_max_attack": 6785, "sp_max_defense": 5759, "sp_max_mobility": 6380, "sp_max_movement": 4}','{"unit_id": 1013000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1013000300, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 101300030001, "unit_ssp_custom_core_group_id": 1013000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300030001, "weapon_change": {"id": 101300030001, "before_weapon_id": 0, "after_weapon_id": 101300030090, "weapon": {"id": 101300030090, "name": "180mm加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300030090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10011, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300030090, "weapon_status": {"id": 101300030090, "range_min": 3, "r