INSERT OR REPLACE INTO "units" VALUES(1013000510,'狙击型吉姆','吉姆狙击型',3,3,9,0,'10000000001300010','130','g0130u00500','RGM-79[G]',1,1,1,1,7545,75,710,749,788,4,54324,237,5110,5390,5400,4,64465,281,6064,6396,6408,4,1,1,3,1,3,'将联邦军沿用「陆战型高达」生产线制造的陆战用MS「吉姆陆战型」变更配色并装备专用武器，进行一部分改装而成的机体。
由于运用目的与其他机体相异，享有「狙击手」的别名，但并未进行过专门改装，只有配合主武器「长程镭射步枪」调整而已。
这把长程镭射步枪不仅有媲美战舰主砲的威力，还可进行超长距离射击，射击间隔时间也胜过既有镭射步枪等等，是非常强力的武装。
但由于流经机体的能源量超过预测限制，机体与枪身的强制冷却需要透过有专用能源回路的散热装置，本机体在调整时也是以这种运用方式为前提。','{"id": 1013000510, "hp": 7545, "en": 75, "attack": 710, "defense": 749, "mobility": 788, "movement": 4, "max_hp": 54324, "max_en": 237, "max_attack": 5110, "max_defense": 5390, "max_mobility": 5400, "max_movement": 4, "sp_hp": 8954, "sp_en": 89, "sp_attack": 843, "sp_defense": 889, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 64465, "sp_max_en": 281, "sp_max_attack": 6064, "sp_max_defense": 6396, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1013000510, "unit_ssp_initial_release_set_id": 1013000510, "unit_ssp_custom_core_group_id": 1013000510, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 101300051001, "unit_ssp_custom_core_group_id": 1013000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300051001, "weapon_change": {"id": 101300051001, "before_weapon_id": 0, "after_weapon_id": 101300051090, "weapon": {"id": 101300051090, "name": "長程鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300051090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300051090, "weapon_status": {"id": 101300051090, "range_min": 3, "ra