INSERT OR REPLACE INTO "units" VALUES(1013000600,'初期型吉姆','初期型吉姆',2,3,2,0,'10000000001300010','130','g0130u00600','RGM-79[E]',1,1,1,1,6132,66,677,617,686,4,44149,207,4871,4440,4703,4,60450,283,6669,6079,6439,4,3,1,3,1,2,'联邦军开发的泛用量产型MS「吉姆」的先行量产机，是实验性试用「月神Ⅱ」生产线所生产的机体。
