INSERT OR REPLACE INTO "units" VALUES(1013000700,'铁球K型','铁球K型',1,3,5,0,'10000000001300010','130','g0130u00700','RB-79K',1,1,1,1,5975,61,566,603,630,4,43015,190,4074,4341,4317,4,63805,282,6042,6439,6403,4,3,1,1,1,1,'一年战争时期由联邦军开发，作为简易型MS的宇宙用战斗艇「铁球」的「K型」衍生机。
机体本身经过机械臂从两只变成4只等改良，搭载于运输船上作为工务用与护卫用，但各方面性能皆无法与MS相比，被前线戏称为「可动式棺材」。
此外，机体上端搭载的武装可以变更，除了本机体装备的15口径砲之外，也有其他型号会装备180mm加农砲。','{"id": 1013000700, "hp": 5975, "en": 61, "attack": 566, "defense": 603, "mobility": 630, "movement": 4, "max_hp": 43015, "max_en": 190, "max_attack": 4074, "max_defense": 4341, "max_mobility": 4317, "max_movement": 4, "sp_hp": 8862, "sp_en": 90, "sp_attack": 840, "sp_defense": 895, "sp_mobility": 934, "sp_movement": 4, "sp_max_hp": 63805, "sp_max_en": 282, "sp_max_attack": 6042, "sp_max_defense": 6439, "sp_max_mobility": 6403, "sp_max_movement": 4}','{"unit_id": 1013000700, "unit_ssp_initial_release_set_id": 1013000700, "unit_ssp_custom_core_group_id": 1013000700, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 101300070001, "unit_ssp_custom_core_group_id": 1013000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300070001, "weapon_change": {"id": 101300070001, "before_weapon_id": 0, "after_weapon_id": 101300070090, "weapon": {"id": 101300070090, "name": "15口徑砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300070090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10011, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300070090, "weapon_status": {"id": 101300070090, "range_min": 1, "range_max": 4, "p