INSERT OR REPLACE INTO "units" VALUES(1013000710,'铁球K型','铁球K型',2,1,5,0,'10000000001300010','130','g0130u00700','RB-79K',1,1,1,1,6288,70,804,668,700,4,45270,210,5785,4808,5040,4,57557,267,7355,6112,6408,4,3,1,1,1,1,'一年战争时期由联邦军开发，作为简易型MS的宇宙用战斗艇「铁球」的「K型」衍生机。
机体本身经过机械臂从两只变成4只等改良，搭载于运输船上作为工务用与护卫用，但各方面性能皆无法与MS相比，被前线戏称为「可动式棺材」。
此外，机体上端搭载的武装可以变更，除了本机体装备的15口径砲之外，也有其他型号会装备180mm加农砲。','{"id": 1013000710, "hp": 6288, "en": 70, "attack": 804, "defense": 668, "mobility": 700, "movement": 4, "max_hp": 45270, "max_en": 210, "max_attack": 5785, "max_defense": 4808, "max_mobility": 5040, "max_movement": 4, "sp_hp": 7994, "sp_en": 89, "sp_attack": 1022, "sp_defense": 849, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 57557, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 6112, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1013000710, "unit_ssp_initial_release_set_id": 1013000710, "unit_ssp_custom_core_group_id": 1013000710, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 101300071001, "unit_ssp_custom_core_group_id": 1013000710, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300071001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300071001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300071001, "weapon_change": {"id": 101300071001, "before_weapon_id": 0, "after_weapon_id": 101300071090, "weapon": {"id": 101300071090, "name": "15口徑砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300071090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300071090, "weapon_status": {"id": 101300071090, "range_min": 2, "range_max": 3, "