INSERT OR REPLACE INTO "units" VALUES(1013000800,'老虎特装型','老虎特装型',4,1,9,0,'10000000001300010','130','g0130u00800','MS-07B-3',1,1,1,1,7545,81,959,723,756,5,54321,229,6899,5206,5729,5,60432,255,7675,5791,6374,5,1,1,3,1,3,'自护公国以重力环境下运用为前提开发的陆 战用量产型MS「老虎」，其中在一年战争 最末期生产的改良型衍生机种之一，是远距 离攻击性能与可运用性、整备效率都大幅度 提升的机体。
左手的5连装75ｍｍ机关砲变更为一般的 机械手，右臂内藏的电热鞭也改为电热索， 达成整体的轻量化。
低落的火力则以3连装35ｍｍ格林机砲、 可内藏电热军刀的「格林机盾牌」等等选 择性装备来弥补，结果成了陆战能力超出规 格的机体。
本机体生产数量不多，主要是优先配发供给 「王牌级驾驶员」使用，战场上战果赫赫。','{"id": 1013000800, "hp": 7545, "en": 81, "attack": 959, "defense": 723, "mobility": 756, "movement": 5, "max_hp": 54321, "max_en": 229, "max_attack": 6899, "max_defense": 5206, "max_mobility": 5729, "max_movement": 5, "sp_hp": 8394, "sp_en": 90, "sp_attack": 1066, "sp_defense": 805, "sp_mobility": 841, "sp_movement": 5, "sp_max_hp": 60432, "sp_max_en": 255, "sp_max_attack": 7675, "sp_max_defense": 5791, "sp_max_mobility": 6374, "sp_max_movement": 5}','{"unit_id": 1013000800, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1013000800, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 101300080001, "unit_ssp_custom_core_group_id": 1013000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300080001, "weapon_change": {"id": 101300080001, "before_weapon_id": 0, "after_weapon_id": 101300080090, "weapon": {"id": 101300080090, "name": "電熱軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300080090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 30021, "weapon_effect": 250008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300080090, "weapon_status": {"id": 101300080090, "range_min": 1, "range_max": 3, "power": 5050, "en": 63,