INSERT OR REPLACE INTO "units" VALUES(1013000850,'老虎特装型 (EX)','老虎特装型 (EX)',5,2,36,0,'10000000001300010','130','g0130u00850','MS-07B-3',1,1,1,1,10951,85,1041,1194,960,5,78844,285,7493,8596,6180,5,78844,285,7493,8596,6180,5,2,1,3,1,3,'自护公国以重力环境下运用为前提开发的陆 战用量产型MS「老虎」，其中在一年战争 最末期生产的改良型衍生机种之一，是远距 离攻击性能与可运用性、整备效率都大幅度 提升的机体。
左手的5连装75ｍｍ机关砲变更为一般的 机械手，右臂内藏的电热鞭也改为电热索， 达成整体的轻量化。
低落的火力则以3连装35ｍｍ格林机砲、 可内藏电热军刀的「格林机盾牌」等等选 择性装备来弥补，结果成了陆战能力超出规 格的机体。
本机体生产数量不多，主要是优先配发供给 「王牌级驾驶员」使用，战场上战果赫赫。','{"id": 1013000850, "hp": 10951, "en": 85, "attack": 1041, "defense": 1194, "mobility": 960, "movement": 5, "max_hp": 78844, "max_en": 285, "max_attack": 7493, "max_defense": 8596, "max_mobility": 6180, "max_movement": 5, "sp_hp": 10951, "sp_en": 85, "sp_attack": 1041, "sp_defense": 1194, "sp_mobility": 960, "sp_movement": 5, "sp_max_hp": 78844, "sp_max_en": 285, "sp_max_attack": 7493, "sp_max_defense": 8596, "sp_max_mobility": 6180, "sp_max_movement": 5}','null','老虎特裝型 (EX)','scrape',1791488368,'v2026.10.08',1013001100);
INSERT OR REPLACE INTO "units" VALUES(1013000900,'飞行试验型老虎','老虎飞行型',3,1,15,0,'10000000001300010','130','g0130u00900','MS-07H-8',1,1,1,1,7017,71,803,597,701,5,50521,212,5782,4296,5042,5,64234,269,7351,5461,6410,5,1,3,3,3,1,'自护公国以重力环境下运用为前提开发的陆 战用量产型MS「老虎」，其中特制具备飞 行能力的衍生机种，成功实现开发初期就不 断研讨的「机体本身飞行」方案。
在「老虎」脚部及腰部装设热核能喷射引擎 以发挥安定的飞行性能，同时为了强化空中 远距离攻击性能，装备了可内藏电热军刀的 「格林机盾牌」等等选择性装备。
然而由于持续飞航距离与机动性都不算高， 「MS飞行方案」在少量量产本机体之后便 中止，扩充机动性与行动半径的任务移交给 「大魔」的热核能气垫式高速移动。','{"id": 1013000900, "hp": 7017, "en": 71, "attack": 803, "defense": 597, "mobility": 701, "movement": 5, "max_hp": 50521, "max_en": 212, "max_attack": 5782, "max_defense": 4296, "max_mobility": 5042, "max_movement": 5, "sp_hp": 8922, "sp_en": 90, "sp_attack": 1021, "sp_defense": 759, "sp_mobility": 891, "sp_movement": 5, "sp_max_hp": 64234, "sp_max_en": 269, "sp_max_attack": 7351, "sp_max_defense": 5461, "sp_max_mobility": 6410, "sp_max_movement": 5}','{"unit_id": 1013000900, "unit_ssp_initial_release_set_id": 1013000900, "unit_ssp_custom_core_group_id": 1013000900, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 101300090001, "unit_ssp_custom_core_group_id": 1013000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300090001, "weapon_change": {"id": 101300090001, "before_weapon_id": 0, "after_weapon_id": 101300090090, "weapon": {"id": 101300090090, "name": "格林機盾牌 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300090090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10022, "weapon_effect": 160006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300090090, "weapon_status": {"id": 101300090090, "range_m