INSERT OR REPLACE INTO "units" VALUES(1013001400,'陆战型吉姆','吉姆陆战型',2,2,9,0,'10000000001300010','130','g0130u01400','RGM-79[G]',1,1,1,1,8170,56,613,686,581,4,58822,177,4410,4933,3945,4,80541,242,6039,6754,5401,4,1,1,3,1,3,'联邦军沿用「陆战型高达」生产线制造的陆战用MS。虽然生产时间先于后续的联邦军主力机体「RGM-79吉姆」，机体名称里也含有「吉姆」的字眼，但机体本身完全是不同的东西。
与陆战型高达相比，武装部份去除了胸部火神砲与背部背包，动力炉也变更为输出力较低的制品，但装甲仍然采用月神钛合金制作，综合性能略胜联邦军的主力机吉姆。
此外，本机体是生产规格确立之后所生产的机体，故备用零件的供给率和可维修率都很高，各部队也都配给了足额份量，其中大部分都投入在敖迪沙战线与阿普撒拉斯开发基地攻防战。','{"id": 1013001400, "hp": 8170, "en": 56, "attack": 613, "defense": 686, "mobility": 581, "movement": 4, "max_hp": 58822, "max_en": 177, "max_attack": 4410, "max_defense": 4933, "max_mobility": 3945, "max_movement": 4, "sp_hp": 11187, "sp_en": 76, "sp_attack": 839, "sp_defense": 939, "sp_mobility": 795, "sp_movement": 4, "sp_max_hp": 80541, "sp_max_en": 242, "sp_max_attack": 6039, "sp_max_defense": 6754, "sp_max_mobility": 5401, "sp_max_movement": 4}','{"unit_id": 1013001400, "unit_ssp_initial_release_set_id": 1013001400, "unit_ssp_custom_core_group_id": 1013001400, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 101300140001, "unit_ssp_custom_core_group_id": 1013001400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300140001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300140001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300140001, "weapon_change": {"id": 101300140001, "before_weapon_id": 0, "after_weapon_id": 101300140090, "weapon": {"id": 101300140090, "name": "鐳射軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300140090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 20022, "weapon_effect": 240002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300140090, "weapon_status": {"id": 101300140090, "ran