INSERT OR REPLACE INTO "units" VALUES(1013001410,'陆战型吉姆','吉姆陆战型',2,3,9,0,'10000000001300010','130','g0130u01400','RGM-79[G]',1,1,1,1,6650,71,734,665,735,4,47880,223,5282,4788,5040,4,60876,284,6715,6088,6408,4,1,1,3,1,3,'联邦军沿用「陆战型高达」生产线制造的陆战用MS。虽然生产时间先于后续的联邦军主力机体「RGM-79吉姆」，机体名称里也含有「吉姆」的字眼，但机体本身完全是不同的东西。
与陆战型高达相比，武装部份去除了胸部火神砲与背部背包，动力炉也变更为输出力较低的制品，但装甲仍然采用月神钛合金制作，综合性能略胜联邦军的主力机吉姆。
此外，本机体是生产规格确立之后所生产的机体，故备用零件的供给率和可维修率都很高，各部队也都配给了足额份量，其中大部分都投入在敖迪沙战线与阿普撒拉斯开发基地攻防战。','{"id": 1013001410, "hp": 6650, "en": 71, "attack": 734, "defense": 665, "mobility": 735, "movement": 4, "max_hp": 47880, "max_en": 223, "max_attack": 5282, "max_defense": 4788, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8455, "sp_en": 90, "sp_attack": 933, "sp_defense": 846, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 284, "sp_max_attack": 6715, "sp_max_defense": 6088, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1013001410, "unit_ssp_initial_release_set_id": 1013001410, "unit_ssp_custom_core_group_id": 1013001410, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 101300141001, "unit_ssp_custom_core_group_id": 1013001410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300141001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300141001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300141001, "weapon_change": {"id": 101300141001, "before_weapon_id": 0, "after_weapon_id": 101300141090, "weapon": {"id": 101300141090, "name": "100mm機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300141090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300141090, "weapon_status": {"id": 101300141090, "r