INSERT OR REPLACE INTO "units" VALUES(1013001500,'量产型钢坦克','量产型太空坦克',1,1,9,0,'10000000001300010','130','g0130u01500','RX-75',1,1,1,1,6025,60,686,569,543,4,43378,162,4938,4096,4343,4,64343,241,7325,6076,6442,4,1,1,3,1,3,'联邦军试作MS之一，「太空坦克」的量产型。
废弃了原型机具备的「核心区块系统」，取而代之的是实现了上半身可旋转，主武装120mm加农砲的供弹系统也更效率化，重生为更适合原任务「远距离支援主力MS部队」的机体。
然而虽说是量产型，生产数量却算不上多。在阿普撒拉斯开发基地攻略战中为了砲击隐藏在岩山里的基地坑道，投入了少数机体。','{"id": 1013001500, "hp": 6025, "en": 60, "attack": 686, "defense": 569, "mobility": 543, "movement": 4, "max_hp": 43378, "max_en": 162, "max_attack": 4938, "max_defense": 4096, "max_mobility": 4343, "max_movement": 4, "sp_hp": 8937, "sp_en": 89, "sp_attack": 1018, "sp_defense": 844, "sp_mobility": 806, "sp_movement": 4, "sp_max_hp": 64343, "sp_max_en": 241, "sp_max_attack": 7325, "sp_max_defense": 6076, "sp_max_mobility": 6442, "sp_max_movement": 4}','{"unit_id": 1013001500, "unit_ssp_initial_release_set_id": 1013001500, "unit_ssp_custom_core_group_id": 1013001500, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 101300150001, "unit_ssp_custom_core_group_id": 1013001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101300150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101300150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101300150001, "weapon_change": {"id": 101300150001, "before_weapon_id": 0, "after_weapon_id": 101300150090, "weapon": {"id": 101300150090, "name": "肩部120mm加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101300150090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 30012, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101300150090, "weapon_status": {"id": 101300150090, "range_min": 3, "range