INSERT OR REPLACE INTO "units" VALUES(1017000100,'高达NT-1','高达NT-1',3,2,2,0,'10000000001700010','170','g0170u00100','RX-78NT-1',1,1,1,1,8729,60,680,741,706,4,62849,210,4895,5332,4320,4,79908,267,6223,6779,5493,4,3,1,3,1,2,'联邦军基于次世代机开发计划「G-4计划」，由地球奥古斯塔基地开发的高性能试作机，是架在驱动和操作系统处投入了最新技术的「新人类专用」MS。
为了对应新人类特有的过人反应速度，各驱动系统都采用了磁气镀膜技术，还设置了能在视线内战斗中确保宽广视线范围的360度显示幕，以及能够减轻震动和冲击传导造成伤害的悬吊式座椅座舱等，以减轻驾驶员的负担。
本机体原本预备配给至传闻中的新人类部队「第13独立部队」，然而却在最终测试阶段遭到自护军特殊部队袭击而受损，最后并未按照原订计划配给。','{"id": 1017000100, "hp": 8729, "en": 60, "attack": 680, "defense": 741, "mobility": 706, "movement": 4, "max_hp": 62849, "max_en": 210, "max_attack": 4895, "max_defense": 5332, "max_mobility": 4320, "max_movement": 4, "sp_hp": 11099, "sp_en": 76, "sp_attack": 865, "sp_defense": 942, "sp_mobility": 898, "sp_movement": 4, "sp_max_hp": 79908, "sp_max_en": 267, "sp_max_attack": 6223, "sp_max_defense": 6779, "sp_max_mobility": 5493, "sp_max_movement": 4}','{"unit_id": 1017000100, "unit_ssp_initial_release_set_id": 1017000100, "unit_ssp_custom_core_group_id": 1017000100, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 101700010001, "unit_ssp_custom_core_group_id": 1017000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700010001, "weapon_change": {"id": 101700010001, "before_weapon_id": 0, "after_weapon_id": 101700010090, "weapon": {"id": 101700010090, "name": "腕部格林機砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700010090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 160006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700010090, "weapon_status": {"id": 101700010090, "range_min": 1, 