INSERT OR REPLACE INTO "units" VALUES(1017000200,'高达NT-1 (乔巴姆装甲装备型)','高达NT-1 (乔巴姆装甲装备型)',4,2,2,0,'10000000001700010','170','g0170u00200','RX-78NT-1',1,1,1,1,8728,69,790,968,766,4,62841,229,5687,6965,4935,4,69910,255,6327,7749,5490,4,3,1,3,1,2,'联邦军方面基于次世代机开发计划「G-4计划」，由地球奥古斯塔基地开发的高性能试作机。
是架在驱动和操作系统处投入了最新技术的「新人类专用」MS。
为了应付新人类特有的过人反应速度，各驱动系统都采用了磁气镀膜技术，还设置了能在视线内战斗中确保宽广视线范围的360度显示幕，以及能够减轻震动和冲击传导造成伤害的悬吊式座椅座舱等，以减轻驾驶员的负担。
另外，本机体尚备有武装增设方案「FSWS计划」下的选配装备「复合装甲」。
这套外加装甲不只具有强力防弹性能，其构造是以装甲钢板夹藏贴有尼龙纤微网的钛合金板叠合而成，其机制是借由受破坏时会脱落以吸收冲击。','{"id": 1017000200, "hp": 8728, "en": 69, "attack": 790, "defense": 968, "mobility": 766, "movement": 4, "max_hp": 62841, "max_en": 229, "max_attack": 5687, "max_defense": 6965, "max_mobility": 4935, "max_movement": 4, "sp_hp": 9710, "sp_en": 76, "sp_attack": 879, "sp_defense": 1077, "sp_mobility": 853, "sp_movement": 4, "sp_max_hp": 69910, "sp_max_en": 255, "sp_max_attack": 6327, "sp_max_defense": 7749, "sp_max_mobility": 5490, "sp_max_movement": 4}','{"unit_id": 1017000200, "unit_ssp_initial_release_set_id": 1017000200, "unit_ssp_custom_core_group_id": 1017000200, "unit_ssp_add_status_id": 100008, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100008, "ssp_hp": 252, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 27, "ssp_mobility": 22, "ssp_max_hp": 5035, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 549, "ssp_max_mobility": 435}, "cores": [{"id": 101700020001, "unit_ssp_custom_core_group_id": 1017000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700020001, "weapon_change": {"id": 101700020001, "before_weapon_id": 0, "after_weapon_id": 101700020090, "weapon": {"id": 101700020090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700020090, "weapon_status": {"id": 101700020090, "range_min": 2, "rang