INSERT OR REPLACE INTO "units" VALUES(1017000300,'量产型钢加农','量产型镭射大砲',1,3,2,0,'10000000001700010','170','g0170u00300','RX-77D',1,1,1,1,5970,61,632,539,629,4,42984,190,4547,3875,4313,4,63760,282,6744,5747,6398,4,3,1,3,1,2,'联邦军为扭转战局而推动MS开发计划「V作战」，并开发出中距离支援型的MS「镭射大砲」。
此机体为其量产型，废除了「核心区块系统」，各部位的零件与主力量产机「吉姆」系列共用，同时装甲也改为钛合金陶瓷复合材。
但在诸如此类的压低成本的举措下，仍维持了与基底机同样的强力砲击能力及顽强的重装甲，虽然确实没有格斗武器，但是架高性能的支援型MS。
由于战争末期的主流是MS对MS的机动战斗，不太需要本机体这样的专门支援型机体，所以虽然是量产型，但生产数量不多。','{"id": 1017000300, "hp": 5970, "en": 61, "attack": 632, "defense": 539, "mobility": 629, "movement": 4, "max_hp": 42984, "max_en": 190, "max_attack": 4547, "max_defense": 3875, "max_mobility": 4313, "max_movement": 4, "sp_hp": 8856, "sp_en": 90, "sp_attack": 937, "sp_defense": 799, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 63760, "sp_max_en": 282, "sp_max_attack": 6744, "sp_max_defense": 5747, "sp_max_mobility": 6398, "sp_max_movement": 4}','{"unit_id": 1017000300, "unit_ssp_initial_release_set_id": 1017000300, "unit_ssp_custom_core_group_id": 1017000300, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 101700030001, "unit_ssp_custom_core_group_id": 1017000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700030001, "weapon_change": {"id": 101700030001, "before_weapon_id": 0, "after_weapon_id": 101700030090, "weapon": {"id": 101700030090, "name": "240mm加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700030090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700030090, "weapon_status": {"id": 101700030090, "range_min": 3, "range_max