INSERT OR REPLACE INTO "units" VALUES(1017000310,'量产型钢加农','量产型镭射大砲',2,3,2,0,'10000000001700010','170','g0170u00300','RX-77D',1,1,1,1,6690,70,735,663,734,4,48168,221,5292,4769,5030,4,61242,281,6729,6064,6396,4,3,1,3,1,2,'联邦军为扭转战局而推动MS开发计划「V作战」，并开发出中距离支援型的MS「镭射大砲」。
此机体为其量产型，废除了「核心区块系统」，各部位的零件与主力量产机「吉姆」系列共用，同时装甲也改为钛合金陶瓷复合材。
但在诸如此类的压低成本的举措下，仍维持了与基底机同样的强力砲击能力及顽强的重装甲，虽然确实没有格斗武器，但是架高性能的支援型MS。
由于战争末期的主流是MS对MS的机动战斗，不太需要本机体这样的专门支援型机体，所以虽然是量产型，但生产数量不多。','{"id": 1017000310, "hp": 6690, "en": 70, "attack": 735, "defense": 663, "mobility": 734, "movement": 4, "max_hp": 48168, "max_en": 221, "max_attack": 5292, "max_defense": 4769, "max_mobility": 5030, "max_movement": 4, "sp_hp": 8506, "sp_en": 89, "sp_attack": 935, "sp_defense": 843, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 61242, "sp_max_en": 281, "sp_max_attack": 6729, "sp_max_defense": 6064, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1017000310, "unit_ssp_initial_release_set_id": 1017000310, "unit_ssp_custom_core_group_id": 1017000310, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 101700031001, "unit_ssp_custom_core_group_id": 1017000310, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700031001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700031001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700031001, "weapon_change": {"id": 101700031001, "before_weapon_id": 0, "after_weapon_id": 101700031090, "weapon": {"id": 101700031090, "name": "240mm加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700031090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700031090, "weapon_status": {"id": 101700031090, "range_min": 3, "range_max