INSERT OR REPLACE INTO "units" VALUES(1017000400,'吉姆指挥型','吉姆指挥官用型',1,2,2,0,'10000000001700010','170','g0170u00400','RGM-79GS',1,1,1,1,7500,51,568,636,538,4,54000,161,4085,4577,3658,4,80100,239,6059,6789,5426,4,3,1,3,1,2,'联邦军于一年战争末期开发的「吉姆」的衍生机之一。
由于当务之急乃提高机动性，在重新审视原始设计后并没有对其进行全面改装，而是同时开发地球用（G型）与宇宙用（GS型）的机体。
本机体以主要从事据点防卫为前提设计，在将机能聚焦在最底限的需求下，得到了适合区域性战争的性能。
此外，也搭载了激光通讯机具以在米诺夫斯基粒子散布环境下展开复数机体作战行动的能力。
开发作为宇宙用（GS型）的本机，原本是以包含殖民卫星一带在内的相对宽广宙域下运用为目标，但在最高输出功率下的活动时间不长，被普遍认为大多局面并无法充分发挥其潜力。','{"id": 1017000400, "hp": 7500, "en": 51, "attack": 568, "defense": 636, "mobility": 538, "movement": 4, "max_hp": 54000, "max_en": 161, "max_attack": 4085, "max_defense": 4577, "max_mobility": 3658, "max_movement": 4, "sp_hp": 11125, "sp_en": 76, "sp_attack": 842, "sp_defense": 943, "sp_mobility": 798, "sp_movement": 4, "sp_max_hp": 80100, "sp_max_en": 239, "sp_max_attack": 6059, "sp_max_defense": 6789, "sp_max_mobility": 5426, "sp_max_movement": 4}','{"unit_id": 1017000400, "unit_ssp_initial_release_set_id": 1017000400, "unit_ssp_custom_core_group_id": 1017000400, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 101700040001, "unit_ssp_custom_core_group_id": 1017000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700040001, "weapon_change": {"id": 101700040001, "before_weapon_id": 0, "after_weapon_id": 101700040090, "weapon": {"id": 101700040090, "name": "鐳射槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700040090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700040090, "weapon_status": {"id": 101700040090, "rang