INSERT OR REPLACE INTO "units" VALUES(1017000410,'吉姆指挥型','吉姆指挥官用型',2,2,2,0,'10000000001700010','170','g0170u00400','RGM-79GS',1,1,1,1,8018,60,737,802,630,4,57729,189,5306,5773,4284,4,73398,241,6746,7340,5447,4,3,1,3,1,2,'联邦军于一年战争末期开发的「吉姆」的衍生机之一。
由于当务之急乃提高机动性，在重新审视原始设计后并没有对其进行全面改装，而是同时开发地球用（G型）与宇宙用（GS型）的机体。
本机体以主要从事据点防卫为前提设计，在将机能聚焦在最底限的需求下，得到了适合区域性战争的性能。
此外，也搭载了激光通讯机具以在米诺夫斯基粒子散布环境下展开复数机体作战行动的能力。
开发作为宇宙用（GS型）的本机，原本是以包含殖民卫星一带在内的相对宽广宙域下运用为目标，但在最高输出功率下的活动时间不长，被普遍认为大多局面并无法充分发挥其潜力。','{"id": 1017000410, "hp": 8018, "en": 60, "attack": 737, "defense": 802, "mobility": 630, "movement": 4, "max_hp": 57729, "max_en": 189, "max_attack": 5306, "max_defense": 5773, "max_mobility": 4284, "max_movement": 4, "sp_hp": 10195, "sp_en": 76, "sp_attack": 937, "sp_defense": 1020, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 73398, "sp_max_en": 241, "sp_max_attack": 6746, "sp_max_defense": 7340, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1017000410, "unit_ssp_initial_release_set_id": 1017000410, "unit_ssp_custom_core_group_id": 1017000410, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 101700041001, "unit_ssp_custom_core_group_id": 1017000410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700041001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700041001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700041001, "weapon_change": {"id": 101700041001, "before_weapon_id": 0, "after_weapon_id": 101700041090, "weapon": {"id": 101700041090, "name": "鐳射槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700041090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700041090, "weapon_status": {"id": 101700041090, "ran