INSERT OR REPLACE INTO "units" VALUES(1017000510,'狙击型吉姆Ⅱ','吉姆狙击型Ⅱ',4,3,2,0,'10000000001700010','170','g0170u00500','RGM-79SP',1,1,1,1,7984,97,879,789,967,4,57481,291,6324,5680,6956,4,58134,294,6396,5745,7035,4,3,1,3,1,2,'在一年战争时联邦军开发的泛用量产型MS「吉姆」的衍生机中，属于最后期开发的机体。
以「吉姆指挥官用型」系机体为基底施以极限化改装，是堪称吉姆颠峰的特装机。
头罩中装有精密射击用的激光光学复合式感测器，可借由关闭主摄影机的护罩冷却头部组件，以物理方式摒除混入的杂讯来实施超长距离狙击。
但此并不是狙击专用机，终究是属于维持通用性并提高整体性能的机体。
本机体性能非常强，就规格而言还超越了「高达」，但由于完成时已是大战末期，生产数量不多，而且因为生产成本已难归类在量产机等级，据说除了检测用的试验机外，并未生产其直系的后继机。','{"id": 1017000510, "hp": 7984, "en": 97, "attack": 879, "defense": 789, "mobility": 967, "movement": 4, "max_hp": 57481, "max_en": 291, "max_attack": 6324, "max_defense": 5680, "max_mobility": 6956, "max_movement": 4, "sp_hp": 8075, "sp_en": 98, "sp_attack": 889, "sp_defense": 798, "sp_mobility": 978, "sp_movement": 4, "sp_max_hp": 58134, "sp_max_en": 294, "sp_max_attack": 6396, "sp_max_defense": 5745, "sp_max_mobility": 7035, "sp_max_movement": 4}','{"unit_id": 1017000510, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1017000510, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 101700051001, "unit_ssp_custom_core_group_id": 1017000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700051001, "weapon_change": {"id": 101700051001, "before_weapon_id": 0, "after_weapon_id": 101700051090, "weapon": {"id": 101700051090, "name": "狙擊用步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700051090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700051090, "weapon_status": {"id": 101700051090, "range_