INSERT OR REPLACE INTO "units" VALUES(1017000600,'渣古Ⅱ改','渣古Ⅱ改',1,1,2,0,'10000000001700010','170','g0170u00600','MS-06FZ',1,1,1,1,5359,60,696,566,601,4,38585,180,5009,4074,4324,4,57234,267,7429,6043,6414,4,3,1,3,1,2,'自护公国依据一年战争后期实行的统合整备计划，重新设计其开发的量产型MS「渣古Ⅱ」而成，是属于渣古Ⅱ衍生机中最后期开发的机体。
性能上拥有匹敌王牌驾驶用S型的推进器输出力，同时操作性以F型为基准，是鲜为人知的名机。
但由于燃料的总装载量不变，据说在马力全开时的作战续航时间仅为原来的一半。
因为保留了杰作机渣古Ⅱ的高通用性，极好维修，除了可沿用联邦军所用机种的零件，有的机种还在头部安装了追加装甲等等，在配备地点修理改造之际，有容许依据驾驶员的意见著手改装的空间。
也由于本机体是在一年战争末期出厂，生产配备数不多，据说仅有极少数投入作战中。','{"id": 1017000600, "hp": 5359, "en": 60, "attack": 696, "defense": 566, "mobility": 601, "movement": 4, "max_hp": 38585, "max_en": 180, "max_attack": 5009, "max_defense": 4074, "max_mobility": 4324, "max_movement": 4, "sp_hp": 7950, "sp_en": 89, "sp_attack": 1032, "sp_defense": 840, "sp_mobility": 891, "sp_movement": 4, "sp_max_hp": 57234, "sp_max_en": 267, "sp_max_attack": 7429, "sp_max_defense": 6043, "sp_max_mobility": 6414, "sp_max_movement": 4}','{"unit_id": 1017000600, "unit_ssp_initial_release_set_id": 1017000600, "unit_ssp_custom_core_group_id": 1017000600, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 101700060001, "unit_ssp_custom_core_group_id": 1017000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700060001, "weapon_change": {"id": 101700060001, "before_weapon_id": 0, "after_weapon_id": 101700060090, "weapon": {"id": 101700060090, "name": "熱能斧 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700060090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250001, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700060090, "weapon_status": {"id": 101700060090, "range_min": 1, "range_max": 2, "power": 4800, "e