INSERT OR REPLACE INTO "units" VALUES(1017000700,'里克·大魔Ⅱ','力奇‧大魔Ⅱ',2,2,2,0,'10000000001700010','170','g0170u00700','MS-09R-2',1,1,1,1,7484,55,678,749,590,4,53880,175,4876,5387,4007,4,73774,240,6676,7376,5487,4,3,1,3,1,2,'自护公国据一年战争后期实行的统合整备计划，重新设计其开发的宇宙战斗用MS「力奇‧大魔」，追加更有利于宇宙空间运用的机能和改善流线造形而成的机体。
本机体除了以简略生产工程、增加机体的强度、提高推进器的推进力等强化改善各部位基础机能为目标外，在操作性也有所改善，因而对驾驶员的负担也减轻了。
此外，由于在量产体完全就绪前就面临战争结束，生产并配往实战的机体数非常少，但因其性能优异，在一年战争后仍长期有人使用。','{"id": 1017000700, "hp": 7484, "en": 55, "attack": 678, "defense": 749, "mobility": 590, "movement": 4, "max_hp": 53880, "max_en": 175, "max_attack": 4876, "max_defense": 5387, "max_mobility": 4007, "max_movement": 4, "sp_hp": 10247, "sp_en": 76, "sp_attack": 928, "sp_defense": 1025, "sp_mobility": 807, "sp_movement": 4, "sp_max_hp": 73774, "sp_max_en": 240, "sp_max_attack": 6676, "sp_max_defense": 7376, "sp_max_mobility": 5487, "sp_max_movement": 4}','{"unit_id": 1017000700, "unit_ssp_initial_release_set_id": 1017000700, "unit_ssp_custom_core_group_id": 1017000700, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 101700070001, "unit_ssp_custom_core_group_id": 1017000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700070001, "weapon_change": {"id": 101700070001, "before_weapon_id": 0, "after_weapon_id": 101700070090, "weapon": {"id": 101700070090, "name": "巨型迫擊砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700070090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700070090, "weapon_status": {"id": 101700070090, "range_min": 2, "range_m