INSERT OR REPLACE INTO "units" VALUES(1017000800,'格鲁古古J','盖古克J',2,1,2,0,'10000000001700010','170','g0170u00800','MS-14JG',1,1,1,1,6465,65,753,553,651,4,46543,194,5418,3979,4684,4,63728,266,7418,5448,6413,4,3,1,3,1,2,'自护公国依据一年战争后期实行的统合整备计划，重新设计了其开发的泛用量产型MS「盖古克」而成的衍生机，由于是以原本就具备高机动性的盖古克为基底再加以改装为精密射击规格，而拥有高射击精密度和最高水准的机动性，是性能非常高的机体。
本机体以指挥官层级使用为前提，搭载有高性能化的火器管制系统和提高输出功率的动力炉，后方裙甲则有三座喷射器组件和多组控制姿势用的推进器，此外，为了增加最高推进力下的续航时间，背包上可以装备增装燃料槽，但由于这在重力下的战斗中反而会拖累运动性，在地球上运用时会卸下。','{"id": 1017000800, "hp": 6465, "en": 65, "attack": 753, "defense": 553, "mobility": 651, "movement": 4, "max_hp": 46543, "max_en": 194, "max_attack": 5418, "max_defense": 3979, "max_mobility": 4684, "max_movement": 4, "sp_hp": 8852, "sp_en": 89, "sp_attack": 1031, "sp_defense": 757, "sp_mobility": 891, "sp_movement": 4, "sp_max_hp": 63728, "sp_max_en": 266, "sp_max_attack": 7418, "sp_max_defense": 5448, "sp_max_mobility": 6413, "sp_max_movement": 4}','{"unit_id": 1017000800, "unit_ssp_initial_release_set_id": 1017000800, "unit_ssp_custom_core_group_id": 1017000800, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 101700080001, "unit_ssp_custom_core_group_id": 1017000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700080001, "weapon_change": {"id": 101700080001, "before_weapon_id": 0, "after_weapon_id": 101700080090, "weapon": {"id": 101700080090, "name": "大型鐳射機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700080090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 160006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 1017