INSERT OR REPLACE INTO "units" VALUES(1017000900,'京宝梵','京宝梵',4,1,2,0,'10000000001700010','170','g0170u00900','MS-18E',1,1,1,1,8047,81,918,679,802,5,57935,241,6607,4883,5774,5,64452,268,7350,5432,6424,5,3,1,3,1,2,'自护公国依据一年战争后期实行的统合整备计划开发而成，仅生产极少量的高性能突袭用MS，本型为专精单身对MS战和具备突破敌方防线能力的E型（einhauen type=突袭型）机体。
其设计概念是应用机体各处的强推进力喷射推进器展开打带跑的突袭行动，以突破敌方防线攻克其据点，因此而设计成尽可能追求机动性和运动性的MS，最后实现了具爆发力的突击突破能力，但在减轻重量下，装甲方面则堪虑。
此外，因为本机体采用独立区块式构造，可在简易设施内组装，所以主要优先配发给潜 入敌地进行威力侦察和后方搅乱等工作的特殊部队。
顺带一提，「京宝梵」是德语的「战士」。','{"id": 1017000900, "hp": 8047, "en": 81, "attack": 918, "defense": 679, "mobility": 802, "movement": 5, "max_hp": 57935, "max_en": 241, "max_attack": 6607, "max_defense": 4883, "max_mobility": 5774, "max_movement": 5, "sp_hp": 8952, "sp_en": 90, "sp_attack": 1021, "sp_defense": 755, "sp_mobility": 893, "sp_movement": 5, "sp_max_hp": 64452, "sp_max_en": 268, "sp_max_attack": 7350, "sp_max_defense": 5432, "sp_max_mobility": 6424, "sp_max_movement": 5}','{"unit_id": 1017000900, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1017000900, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 101700090001, "unit_ssp_custom_core_group_id": 1017000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700090001, "weapon_change": {"id": 101700090001, "before_weapon_id": 0, "after_weapon_id": 101700090090, "weapon": {"id": 101700090090, "name": "鏈狀機雷 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700090090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290106, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700090090, "weapon_status": {"id": 101700090090, "range_min": 1, "range_max": 3, "power": 5100, "en": 64, "hit_rate": 105, "c