INSERT OR REPLACE INTO "units" VALUES(1017000950,'京宝梵 (EX)','京宝梵 (EX)',5,1,2,0,'10000000001700010','170','g0170u00950','MS-18E',1,1,1,1,8923,101,1153,951,1007,5,64243,302,8297,6845,7247,5,64243,302,8297,6845,7247,5,3,1,3,1,2,'自护公国依据一年战争后期实行的统合整备计划开发而成，仅生产极少量的高性能突袭用MS，本型为专精单身对MS战和具备突破敌方防线能力的E型（einhauen type=突袭型）机体。
其设计概念是应用机体各处的强推进力喷射推进器展开打带跑的突袭行动，以突破敌方防线攻克其据点，因此而设计成尽可能追求机动性和运动性的MS，最后实现了具爆发力的突击突破能力，但在减轻重量下，装甲方面则堪虑。
此外，因为本机体采用独立区块式构造，可在简易设施内组装，所以主要优先配发给潜 入敌地进行威力侦察和后方搅乱等工作的特殊部队。
顺带一提，「京宝梵」是德语的「战士」。','{"id": 1017000950, "hp": 8923, "en": 101, "attack": 1153, "defense": 951, "mobility": 1007, "movement": 5, "max_hp": 64243, "max_en": 302, "max_attack": 8297, "max_defense": 6845, "max_mobility": 7247, "max_movement": 5, "sp_hp": 8923, "sp_en": 101, "sp_attack": 1153, "sp_defense": 951, "sp_mobility": 1007, "sp_movement": 5, "sp_max_hp": 64243, "sp_max_en": 302, "sp_max_attack": 8297, "sp_max_defense": 6845, "sp_max_mobility": 7247, "sp_max_movement": 5}','null','京寶梵 (EX)','scrape',1791488368,'v2026.10.08',1017000400);
INSERT OR REPLACE INTO "units" VALUES(1017001000,'高战蟹','高魔蟹',3,1,9,0,'10000000001700010','170','g0170u01000','MSM-03C',1,1,1,1,6650,70,845,631,663,4,47876,199,6079,4542,5020,4,60870,253,7729,5775,6382,4,1,1,3,1,3,'自护公国依据一年战争时期实行的统合整备计划，重新设计并全面改装其开发的水陆两用量产型MS「战蟹」而成的机体。
借由将原本附有重装甲而过重的战蟹大幅减轻重量，显著提升了陆地及水中两方面的机动性和运动性，此外也改良了武装，装设在双臂的「镭射加农砲」在采用能源CAP技术下可以连射。
又，在备有诸如可安装在臂部的「手臂飞弹组件」，及装备在背部后，可在上陆时发挥强力猛攻能力的「喷射背包」等的选配武装下，性能获得了全面性的提升。
本机体由于是在一年战争末期开发，生产数量不多，这些机体配给了特殊部队等方面发挥实力。','{"id": 1017001000, "hp": 6650, "en": 70, "attack": 845, "defense": 631, "mobility": 663, "movement": 4, "max_hp": 47876, "max_en": 199, "max_attack": 6079, "max_defense": 4542, "max_mobility": 5020, "max_movement": 4, "sp_hp": 8455, "sp_en": 89, "sp_attack": 1074, "sp_defense": 803, "sp_mobility": 843, "sp_movement": 4, "sp_max_hp": 60870, "sp_max_en": 253, "sp_max_attack": 7729, "sp_max_defense": 5775, "sp_max_mobility": 6382, "sp_max_movement": 4}','{"unit_id": 1017001000, "unit_ssp_initial_release_set_id": 1017001000, "unit_ssp_custom_core_group_id": 1017001000, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 101700100001, "unit_ssp_custom_core_group_id": 1017001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700100001, "weapon_change": {"id": 101700100001, "before_weapon_id": 0, "after_weapon_id": 101700100090, "weapon": {"id": 101700100090, "name": "腕部飛彈組件 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 230004, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700100090, "weapon_status": {"id": 101700100090, "range_min": 3, "range_max": 5, "power": 