INSERT OR REPLACE INTO "units" VALUES(1017001200,'原型京宝梵','京宝梵原型机',3,3,2,0,'10000000001700010','170','g0170u01200','YMS-18',1,1,1,1,6312,78,697,629,770,4,45447,233,5019,4522,5542,4,57782,297,6381,5750,7046,4,3,1,3,1,2,'作为MS-18E京宝梵原型机（初期开发型）的试作重型MS。
