INSERT OR REPLACE INTO "units" VALUES(1017001210,'原型京宝梵','京宝梵原型机',4,1,2,0,'10000000001700010','170','g0170u01200','YMS-18',1,1,1,1,8871,88,1006,747,880,4,63867,264,7243,5375,6336,4,64593,267,7325,5436,6408,4,3,1,3,1,2,'作为MS-18E京宝梵原型机（初期开发型）的试作重型MS。
重视突袭的设计概念与机体的区块构造、装备高推力推进器等大部分要素皆有继承至MS-18E上。
另一方面，包含天线在内的头部及胸部、肩部形状皆与该机相异，此外腰部装甲较厚，且后侧为裙甲型。','{"id": 1017001210, "hp": 8871, "en": 88, "attack": 1006, "defense": 747, "mobility": 880, "movement": 4, "max_hp": 63867, "max_en": 264, "max_attack": 7243, "max_defense": 5375, "max_mobility": 6336, "max_movement": 4, "sp_hp": 8972, "sp_en": 89, "sp_attack": 1018, "sp_defense": 755, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 64593, "sp_max_en": 267, "sp_max_attack": 7325, "sp_max_defense": 5436, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1017001210, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1017001210, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 101700121001, "unit_ssp_custom_core_group_id": 1017001210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 101700121001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 101700121001, "sort_order": 1, "release_function_type_index": 5, "target_id": 101700121001, "weapon_change": {"id": 101700121001, "before_weapon_id": 0, "after_weapon_id": 101700121090, "weapon": {"id": 101700121090, "name": "巨型迫擊砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 101700121090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 101700121090, "weapon_status": {"id": 101700121090, "range_min": 2, "range_max": 4, "power": 4900,