INSERT OR REPLACE INTO "units" VALUES(1021000110,'精灵高达','妖精高达',4,1,9,0,'10000000002100010','210','g0210u00100','RX-78XX',1,1,1,1,7984,88,1012,833,877,4,57481,264,7287,5996,6311,4,58134,267,7370,6064,6383,4,1,1,3,1,3,'联邦军秘密开发的陆战用试作型MS，其主要目的是用以收集对MS短兵交战资料，取消了RX-78采用的「核心区块系统」等设计，藉大幅减轻重量将机动性和运动性提高至极限。
武装方面，是以便于后勤补给的实弹系为主，并备有攻击范围短但输出功率高的特殊武器「镭射短刀」等等，专门设计为机动近身战用。此外，机体表面还施加了特殊涂层，使其有一定程度的匿踪能力。
本机体有三架试作机，其中相当于2号机的机体原本预定配给「白色基地队」，但因受敌人妨碍而未能送达。','{"id": 1021000110, "hp": 7984, "en": 88, "attack": 1012, "defense": 833, "mobility": 877, "movement": 4, "max_hp": 57481, "max_en": 264, "max_attack": 7287, "max_defense": 5996, "max_mobility": 6311, "max_movement": 4, "sp_hp": 8075, "sp_en": 89, "sp_attack": 1024, "sp_defense": 843, "sp_mobility": 887, "sp_movement": 4, "sp_max_hp": 58134, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6064, "sp_max_mobility": 6383, "sp_max_movement": 4}','{"unit_id": 1021000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1021000110, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 102100011001, "unit_ssp_custom_core_group_id": 1021000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102100011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102100011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102100011001, "weapon_change": {"id": 102100011001, "before_weapon_id": 0, "after_weapon_id": 102100011090, "weapon": {"id": 102100011090, "name": "北極光攻擊 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102100011090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280010, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102100011090, "weapon_status": {"id": 102100011090, "range_min": 1, "range_max": 2, "power": 5100