INSERT OR REPLACE INTO "units" VALUES(1021000400,'精灵高达＆伊夫里特','妖精高达＆伊夫利特',4,1,9,0,'10000000002100010','210','g0210u00400','-',1,1,1,1,8018,80,927,678,806,4,57727,239,6674,4875,5798,4,64221,266,7424,5424,6450,4,1,1,3,1,3,'‧关于妖精高达
联邦军秘密开发的陆战用试作型MS，其主要目的是用以收集对MS短兵交战资料，取消了RX-78采用的「核心区块系统」等设计，藉大幅减轻重量将机动性和运动性提高至极限。
武装方面，是以便于后勤补给的实弹系为主，并备有攻击范围短但输出功率高的特殊武器「镭射短刀」等等，专门设计为机动近身战用。此外，机体表面还施加了特殊涂层，使其有一定程度的匿踪能力。
本机体有三架试作机，其中相当于2号机的机体原本预定配给「白色基地队」，但因受敌人妨碍而未能送达。

‧关于伊夫利特
由自护公国的地球方面军主导开发，定位在「老虎」和「大魔」中间的陆战用MS。虽然属于泛用机，但专为近距离战斗进行了调整，是与老虎一样专精于对MS战斗的机体。
含本机体在内，完成的试作机虽然都能发挥出相当高的性能，但因生产效率低不利量产，最终仅制造了八架。
另有一说是可能与地球方面军权限不高，而祖国又已开始著手下个世代主力机的开发工作等政治背景有关。
据传，投入实战中的试作机大多配给了特殊部队，其余机体则作为开发新兵器的实验机来利用。','{"id": 1021000400, "hp": 8018, "en": 80, "attack": 927, "defense": 678, "mobility": 806, "movement": 4, "max_hp": 57727, "max_en": 239, "max_attack": 6674, "max_defense": 4875, "max_mobility": 5798, "max_movement": 4, "sp_hp": 8920, "sp_en": 89, "sp_attack": 1032, "sp_defense": 754, "sp_mobility": 896, "sp_movement": 4, "sp_max_hp": 64221, "sp_max_en": 266, "sp_max_attack": 7424, "sp_max_defense": 5424, "sp_max_mobility": 6450, "sp_max_movement": 4}','{"unit_id": 1021000400, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1021000400, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 102100040001, "unit_ssp_custom_core_group_id": 1021000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102100040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102100040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102100040001, "weapon_change": {"id": 102100040001, "before_weapon_id": 0, "after_weapon_id": 102100040090, "weapon": {"id": 102100040090, "name": "北極光攻擊 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102100040090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280010, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102100040090, "weapon_status": {"id": 102100040090, "range_min": 1, "range_max": 3, "power": 5000, "en":