INSERT OR REPLACE INTO "units" VALUES(1022000210,'蓝色命运1号机【EXAM】','苍蓝命运1号机【EXAM】',4,1,9,0,'10000000002200010','220','g0220u00200','RX-79BD-1',1,1,1,1,8783,88,1012,838,794,5,63234,236,7287,6032,6349,5,63952,238,7370,6100,6421,5,1,1,3,1,3,'联邦军任命从自护公国的弗拉纳冈机关逃到地球联邦的「库鲁斯特‧摩杰斯」博士主导开发称作「EXAM系统」的特殊MS控制技术下制造的实验用MS，是联邦军内首架搭载EXAM的实验机。
原本是以「吉姆陆战型」为开发基底，但由于机体性能不能充分发挥EXAM系统的效能，而将搭载了系统的头部移殖到「陆战型高达」上，并全面展开改装工作。
由于更换机身，在动力炉输出功率提高及采用磁性覆膜等的帮助下改善了运动性能，而在武装方面，也加装了胸部机砲和有线导弹等等，整体火力大幅超越了基底机体。
但是其最大特征所在的EXAM系统虽然能在启动后发挥惊人的战斗能力，但由于系统本身极不稳定，不仅在试验时多次让搭乘的驾驶员失神，还发生了作战结束后误将友军当作敌人继续交战的意外。后来在为EXAM系统设下限制后，配给了「勇‧鹿岛」作为座机。
另外，本机体虽然是以重力下用规格运用，但设计上可在更换背包后对应宇宙空间中的战斗。','{"id": 1022000210, "hp": 8783, "en": 88, "attack": 1012, "defense": 838, "mobility": 794, "movement": 5, "max_hp": 63234, "max_en": 236, "max_attack": 7287, "max_defense": 6032, "max_mobility": 6349, "max_movement": 5, "sp_hp": 8883, "sp_en": 89, "sp_attack": 1024, "sp_defense": 848, "sp_mobility": 803, "sp_movement": 5, "sp_max_hp": 63952, "sp_max_en": 238, "sp_max_attack": 7370, "sp_max_defense": 6100, "sp_max_mobility": 6421, "sp_max_movement": 5}','{"unit_id": 1022000210, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1022000210, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 102200021001, "unit_ssp_custom_core_group_id": 1022000210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102200021001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102200021001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102200021001, "weapon_change": {"id": 102200021001, "before_weapon_id": 0, "after_weapon_id": 102200021090, "weapon": {"id": 102200021090, "name": "EXAM系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102200021090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102200021090, "weapon_status": {"id": 102200021090, "range_min": 1, "range_max": 2, "power": 5250, "en"