INSERT OR REPLACE INTO "units" VALUES(1022000300,'伊夫里特改','伊夫利特改',2,1,9,0,'10000000002200010','220','g0220u00300','MS-08TX[EXAM]',1,1,1,1,6452,65,750,550,656,5,46449,195,5394,3959,4718,5,63600,267,7386,5420,6460,5,1,1,3,1,3,'为实验自护公国中以研究新人类为主要任务 的「弗拉纳冈机关」所开发的特殊MS控制 技术「EXAM系统」而以陆战型MS「伊夫利特」为基底，大幅加强改装而成的特殊 实验机。
搭载系统的头部为了利于冷却而加大，机体 各处的推进器也加强过，以能充分发挥系统 启动时的效能，诸如此类，机体具有高机动 性能。
又，就战斗能力而言，由于有配合测试驾驶 员「尼姆巴斯‧舒特森」的特质调整，成为 专精独特格斗方式的机体，搭上EXAM系 统将能发挥优异的性能。
至于左右肩膀上的红色涂装，据说是反映了 驾驶员尼姆巴斯个人的喜好。','{"id": 1022000300, "hp": 6452, "en": 65, "attack": 750, "defense": 550, "mobility": 656, "movement": 5, "max_hp": 46449, "max_en": 195, "max_attack": 5394, "max_defense": 3959, "max_mobility": 4718, "max_movement": 5, "sp_hp": 8834, "sp_en": 89, "sp_attack": 1026, "sp_defense": 753, "sp_mobility": 898, "sp_movement": 5, "sp_max_hp": 63600, "sp_max_en": 267, "sp_max_attack": 7386, "sp_max_defense": 5420, "sp_max_mobility": 6460, "sp_max_movement": 5}','{"unit_id": 1022000300, "unit_ssp_initial_release_set_id": 1022000300, "unit_ssp_custom_core_group_id": 1022000300, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 102200030001, "unit_ssp_custom_core_group_id": 1022000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102200030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102200030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102200030001, "weapon_change": {"id": 102200030001, "before_weapon_id": 0, "after_weapon_id": 102200030090, "weapon": {"id": 102200030090, "name": "EXAM系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102200030090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102200030090, "weapon_status": {"id": 102200030090, "range_min": 1, "range_max": 2, "power": 5150, "en"