INSERT OR REPLACE INTO "units" VALUES(1022000600,'蓝色命运3号机','苍蓝命运3号机',3,2,2,0,'10000000002200010','220','g0220u00600','RX-79BD-3',1,1,1,1,8694,60,768,736,635,4,62597,189,5523,5298,4318,4,79588,240,7022,6736,5490,4,3,1,3,1,2,'联邦军任命从自护公国的弗拉纳冈机关逃到 地球联邦的「库鲁斯特‧摩杰斯」博士主导 开发称作「EXAM系统」的特殊MS控制 技术下制造的实验用MS3号机，原本是作 为1号机和2号机的备件机调度的机体。
基本性能与1号机一样，也设定有抑制 EXAM系统失控的限制。
配给「勇‧鹿岛」 当作座机，代替失去的1号机。
在地球上执行了几道任务后，为了执行追回 被尼姆巴斯抢走的2号机的任务，便紧急改 装成宇宙规格。
另外，3号机原本也预定采用蓝色涂装，但 由于克鲁斯特博士在事前死亡，后来便维持 原始涂装的模样投入实战。','{"id": 1022000600, "hp": 8694, "en": 60, "attack": 768, "defense": 736, "mobility": 635, "movement": 4, "max_hp": 62597, "max_en": 189, "max_attack": 5523, "max_defense": 5298, "max_mobility": 4318, "max_movement": 4, "sp_hp": 11054, "sp_en": 76, "sp_attack": 976, "sp_defense": 936, "sp_mobility": 808, "sp_movement": 4, "sp_max_hp": 79588, "sp_max_en": 240, "sp_max_attack": 7022, "sp_max_defense": 6736, "sp_max_mobility": 5490, "sp_max_movement": 4}','{"unit_id": 1022000600, "unit_ssp_initial_release_set_id": 1022000600, "unit_ssp_custom_core_group_id": 1022000600, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 102200060001, "unit_ssp_custom_core_group_id": 1022000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102200060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102200060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102200060001, "weapon_change": {"id": 102200060001, "before_weapon_id": 0, "after_weapon_id": 102200060090, "weapon": {"id": 102200060090, "name": "EXAM系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102200060090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102200060090, "weapon_status": {"id": 102200060090, "range_min": 1, "range_max": 2, 