INSERT OR REPLACE INTO "units" VALUES(1026000110,'陆战型高达','陆战型高达',3,2,9,0,'10000000002600010','260','g0260u00100','RX-79[G]',1,1,1,1,8608,64,713,865,675,4,61976,203,5130,6223,4590,4,73545,241,6088,7384,5447,4,1,1,3,1,3,'收到V作战的技术回馈，主力量产MS开发计划正逐步进行之际，苦无手段对抗自护公国军MS的前线再三要求及早配备MS。
为回应前线的需要，便利用开发高达时剩余的零件组装成陆战规格MS，以少数先行量产的机体。
光看开发过程虽会给人粗制滥造的印象，但由于使用的是高性能的高达剩余零件，本机成为超乎预期的高性能MS，并立下了丰硕战果。','{"id": 1026000110, "hp": 8608, "en": 64, "attack": 713, "defense": 865, "mobility": 675, "movement": 4, "max_hp": 61976, "max_en": 203, "max_attack": 5130, "max_defense": 6223, "max_mobility": 4590, "max_movement": 4, "sp_hp": 10215, "sp_en": 76, "sp_attack": 846, "sp_defense": 1026, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 73545, "sp_max_en": 241, "sp_max_attack": 6088, "sp_max_defense": 7384, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1026000110, "unit_ssp_initial_release_set_id": 1026000110, "unit_ssp_custom_core_group_id": 1026000110, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 102600011001, "unit_ssp_custom_core_group_id": 1026000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102600011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102600011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102600011001, "weapon_change": {"id": 102600011001, "before_weapon_id": 0, "after_weapon_id": 102600011090, "weapon": {"id": 102600011090, "name": "100mm機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102600011090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102600011090, "weapon_status": {"id": 102600011090, "range_min": 1, "rang