INSERT OR REPLACE INTO "units" VALUES(1029000210,'苍白骑士 (陆战重装规格)','苍白骑士 (陆战重装规格)',4,3,9,0,'10000000002900010','290','g0290u00200','RX-80PR',1,1,1,1,8783,89,924,794,923,4,63234,280,6653,5714,6324,4,63952,284,6729,5779,6396,4,1,1,3,1,3,'成功使吉姆量产化的地球联邦军集结了该时间点的最尖端技术，于研究次世代MS的过程中开发的机体。
作为基础的RX-80为投入当时所有技术才完成的试作机，虽是非常有魅力的高性能机体，但在生产、运用等方面的成本考量上，难以当作主力量产机配发，最后由某个研究机构接收作为测试机体。
本机于该机构内加装了衍生自「EXAM」、可使机体性能大幅提升的特殊系统「HADES」，并依据这点实施机体调整，成为了实验机。','{"id": 1029000210, "hp": 8783, "en": 89, "attack": 924, "defense": 794, "mobility": 923, "movement": 4, "max_hp": 63234, "max_en": 280, "max_attack": 6653, "max_defense": 5714, "max_mobility": 6324, "max_movement": 4, "sp_hp": 8883, "sp_en": 90, "sp_attack": 935, "sp_defense": 803, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 284, "sp_max_attack": 6729, "sp_max_defense": 5779, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1029000210, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1029000210, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 102900021001, "unit_ssp_custom_core_group_id": 1029000210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102900021001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102900021001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102900021001, "weapon_change": {"id": 102900021001, "before_weapon_id": 0, "after_weapon_id": 102900021090, "weapon": {"id": 102900021090, "name": "HADES SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102900021090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102900021090, "weapon_status": {"id": 102900021090, "range_min": 1, "range_max": 3, "