INSERT OR REPLACE INTO "units" VALUES(1029002110,'主教','主教',3,1,8,0,'10000000002900010','290','g0290u02100','MS-06Z',1,1,1,1,7485,75,861,642,749,4,53892,225,6198,4618,5390,4,63952,267,7355,5480,6396,4,3,1,2,1,2,'为了把自护公国将新人类使用于军事上的计划中立有战果的脑波传导系统搭载到MS上，而以渣古为基底开发而成的实验机。
开发过程中，脑波传导系统和两手镭射砲由于难以小型化，重新设计的手臂变成巨大的有线式镭射砲安装在手臂上的奇特形状。
这款俗称「主教」的机体试作了三架，以列牟利亚为旗舰的实验部队负责收集资料。而在列牟利亚搭便船的马可西亚斯队驾驶员「安涅罗瑟‧罗森海茵」由于具备新人类素质，而以备用机和剩余零件紧急制造出本机体，成为梦幻的4号机。','{"id": 1029002110, "hp": 7485, "en": 75, "attack": 861, "defense": 642, "mobility": 749, "movement": 4, "max_hp": 53892, "max_en": 225, "max_attack": 6198, "max_defense": 4618, "max_mobility": 5390, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 1022, "sp_defense": 762, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 5480, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1029002110, "unit_ssp_initial_release_set_id": 1029002110, "unit_ssp_custom_core_group_id": 1029002110, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 102900211001, "unit_ssp_custom_core_group_id": 1029002110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 102900211001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 102900211001, "sort_order": 1, "release_function_type_index": 5, "target_id": 102900211001, "weapon_change": {"id": 102900211001, "before_weapon_id": 0, "after_weapon_id": 102900211090, "weapon": {"id": 102900211090, "name": "全方位攻擊 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 102900211090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350009, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 102900211090, "weapon_status": 