INSERT OR REPLACE INTO "units" VALUES(1031000100,'全装甲高达 (雷霆宙域版)','全装甲型高达 (雷霆战线版)',4,3,2,0,'10000000003100010','310','g0310u00100','FA-78',1,1,1,1,8029,80,765,799,837,4,57808,252,5504,5752,5737,4,64311,280,6123,6400,6382,4,3,1,3,1,2,'配给隶属联邦军但已经毁灭的SIDE4战争难民组成的团体「姆亚同乡会」使用的高达型MS，规格与「FA-78-1」不同，是实验性搭载了各种系统和装备的机体。
本机体有著超乎其他同时代MS的重武装，右手臂上有加大并改用能源匣的「2连装镭射步枪」，左手臂上盾牌内侧装有五管「火箭发射器」，而背包上装备了「飞弹荚舱」和「大型镭射砲」，此外还搭载了六组备用的能源匣。
并且，不但可使用背包上的辅助臂安装四面盾牌，靠著安装在肩部腿部等机体各处的推进器和远地点踢进器，还有装在背包上的大型火箭推进器，据说推进力甚至可与高机动型MS匹敌。','{"id": 1031000100, "hp": 8029, "en": 80, "attack": 765, "defense": 799, "mobility": 837, "movement": 4, "max_hp": 57808, "max_en": 252, "max_attack": 5504, "max_defense": 5752, "max_mobility": 5737, "max_movement": 4, "sp_hp": 8933, "sp_en": 89, "sp_attack": 851, "sp_defense": 889, "sp_mobility": 931, "sp_movement": 4, "sp_max_hp": 64311, "sp_max_en": 280, "sp_max_attack": 6123, "sp_max_defense": 6400, "sp_max_mobility": 6382, "sp_max_movement": 4}','{"unit_id": 1031000100, "unit_ssp_initial_release_set_id": 1031000100, "unit_ssp_custom_core_group_id": 1031000100, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 103100010001, "unit_ssp_custom_core_group_id": 1031000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100010001, "weapon_change": {"id": 103100010001, "before_weapon_id": 0, "after_weapon_id": 103100010090, "weapon": {"id": 103100010090, "name": "大型鐳射砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100010090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100010090, "weapon_status": {"id": 103100010090, "ra