set_id": 0, "active_condition": null, "target_condition": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}], "units": null, "characters": null}}}}','全裝甲型高達 (雷霆戰線版)','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1031000150,'全装甲高达 (雷霆宙域版) (EX)','全装甲型高达 (雷霆战线版) (EX)',5,2,2,0,'10000000003100010','310','g0310u00150','FA-78',1,1,1,1,11515,86,1142,1155,893,4,82908,272,8216,8312,6068,4,82908,272,8216,8312,6068,4,3,1,3,1,2,'配给隶属联邦军但已经毁灭的SIDE4战争难民组成的团体「姆亚同乡会」使用的高达型MS，规格与「FA-78-1」不同，是实验性搭载了各种系统和装备的机体。
本机体有著超乎其他同时代MS的重武装，右手臂上有加大并改用能源匣的「2连装镭射步枪」，左手臂上盾牌内侧装有五管「火箭发射器」，而背包上装备了「飞弹荚舱」和「大型镭射砲」，此外还搭载了六组备用的能源匣。
并且，不但可使用背包上的辅助臂安装四面盾牌，靠著安装在肩部腿部等机体各处的推进器和远地点踢进器，还有装在背包上的大型火箭推进器，据说推进力甚至可与高机动型MS匹敌。','{"id": 1031000150, "hp": 11515, "en": 86, "attack": 1142, "defense": 1155, "mobility": 893, "movement": 4, "max_hp": 82908, "max_en": 272, "max_attack": 8216, "max_defense": 8312, "max_mobility": 6068, "max_movement": 4, "sp_hp": 11515, "sp_en": 86, "sp_attack": 1142, "sp_defense": 1155, "sp_mobility": 893, "sp_movement": 4, "sp_max_hp": 82908, "sp_max_en": 272, "sp_max_attack": 8216, "sp_max_defense": 8312, "sp_max_mobility": 6068, "sp_max_movement": 4}','null','全裝甲型高達 (雷霆戰線版) (EX)','scrape',1791488368,'v2026.10.08',1031000100);
INSERT OR REPLACE INTO "units" VALUES(1031000200,'吉姆 (雷霆宙域版)','吉姆 (雷霆战线版)',2,2,2,0,'10000000003100010','310','g0310u00200','RGM-79',1,1,1,1,7179,56,585,780,616,4,51686,186,4212,5616,3963,4,70770,254,5768,7690,5426,4,3,1,3,1,2,'以高达的资料为基础开发而成的地球联邦军量产型MS。
姆亚同胞团亦有获得配属，以奥也曾搭乘过。
在雷霆宙域运用时，施加了用以预防残骸影响的关节部位密封处理、增设用于搜索暗礁宙域的头部感应器、换装大型背包等改造。
其大型背包还备有可持有2面盾牌的辅助臂，以及镭射喷枪等装备使用的能源匣。
驾驶舱采用可进行紧急逃生的核心区块系统，核心区块能从机体上分离。
该核心区块还能将本体以外的部位卸除，具有逃生舱功能，借此提高驾驶员的生存率。
该机能曾在以奥驾驶吉姆遭达里尔机狙击时，拯救他脱离险境。','{"id": 1031000200, "hp": 7179, "en": 56, "attack": 585, "defense": 780, "mobility": 616, "movement": 4, "max_hp": 51686, "max_en": 186, "max_attack": 4212, "max_defense": 5616, "max_mobility": 3963, "max_movement": 4, "sp_hp": 9830, "sp_en": 76, "sp_attack": 801, "sp_defense": 1068, "sp_mobility": 843, "sp_movement": 4, "sp_max_hp": 70770, "sp_max_en": 254, "sp_max_attack": 5768, "sp_max_defense": 7690, "sp_max_mobility": 5426, "sp_max_movement": 4}','{"unit_id": 1031000200, "unit_ssp_initial_release_set_id": 1031000200, "unit_ssp_custom_core_group_id": 1031000200, "unit_ssp_add_status_id": 100008, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100008, "ssp_hp": 252, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 27, "ssp_mobility": 22, "ssp_max_hp": 5035, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 549, "ssp_max_mobility": 435}, "cores": [{"id": 103100020001, "unit_ssp_custom_core_group_id": 1031000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100020001, "weapon_change": {"id": 103100020001, "before_weapon_id": 0, "after_weapon_id": 103100020090, "weapon": {"id": 103100020090, "name": "鐳射噴槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100020090, "weapon_status": {"id": 103100020090, "range_min": 1, "range_max": 3, "power": 4600, "en": 57, 