INSERT OR REPLACE INTO "units" VALUES(1031000500,'钢加农 (雷霆宙域版)','镭射大砲 (雷霆战线版)',3,3,2,0,'10000000003100010','310','g0310u00500','RX-77',1,1,1,1,6972,70,665,700,738,4,50199,221,4788,5040,5061,4,63824,281,6088,6408,6434,4,3,1,3,1,2,'地球联邦军与高达同一时期开发的「RX系列」机种之一，主要运用方式为中距离支援砲击的量产型MS。
配属给姆亚同胞团的机体共有4架。
为了将身负击破敌方舰队（活死人师团）及排除敌方王牌狙击手任务的全装甲型高达送达最前线，作为肉盾（支援机）参加作战，并由同时补充的少年兵们负责驾驶。
在雷霆宙域运用时，施加了用以预防残骸影响的关节部位密封处理，及增设用于搜索暗礁宙域的头部感应器等改造。
其大型背包也增设了2门低反动加农砲和推进器。
标准装备为镭射步枪。','{"id": 1031000500, "hp": 6972, "en": 70, "attack": 665, "defense": 700, "mobility": 738, "movement": 4, "max_hp": 50199, "max_en": 221, "max_attack": 4788, "max_defense": 5040, "max_mobility": 5061, "max_movement": 4, "sp_hp": 8865, "sp_en": 89, "sp_attack": 846, "sp_defense": 890, "sp_mobility": 939, "sp_movement": 4, "sp_max_hp": 63824, "sp_max_en": 281, "sp_max_attack": 6088, "sp_max_defense": 6408, "sp_max_mobility": 6434, "sp_max_movement": 4}','{"unit_id": 1031000500, "unit_ssp_initial_release_set_id": 1031000500, "unit_ssp_custom_core_group_id": 1031000500, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 103100050001, "unit_ssp_custom_core_group_id": 1031000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100050001, "weapon_change": {"id": 103100050001, "before_weapon_id": 0, "after_weapon_id": 103100050090, "weapon": {"id": 103100050090, "name": "低反動加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100050090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100050090, "weapon_status": {"id": 103100050090, "range_min": 2, "range_max": 5, "power": 4800, "en": 60, "hit_rate": 105, 