INSERT OR REPLACE INTO "units" VALUES(1031000800,'格鲁古古 (雷霆宙域版)','盖古克 (雷霆战线版)',3,1,2,0,'10000000003100010','310','g0310u00800','MS-14',1,1,1,1,6288,70,805,664,703,4,45270,210,5796,4779,5061,4,57557,267,7370,6076,6434,4,3,1,3,1,2,'据称是在一年战争时开发的量产型MS中具有最高完成度的机体，以自护公国军首度采用的镭射兵器为标准装备。
配属于海妖机动舰队的机体，作为暗礁宙域规格对关节部位施加了密封处理，背部在搭载镭射发动机的大型背包上，设置四座装备了推进器的增装燃料槽，借此实现能够媲美高达的火力和高机动性。
武装为镭射薙刀、专用镭射步枪、盾牌。
尽管海妖机动舰队在救助费雪驾驶的力奇‧大魔后，作为活死人师团援军抵达了雷霆宙域，然而师团在全装甲型高达的肆虐下早已陷入等同全灭的惨状。
不过由于重渣古的活跃表现，姆亚同胞团同样遭到毁灭，成功地俘虏了以奥等联邦军士兵。','{"id": 1031000800, "hp": 6288, "en": 70, "attack": 805, "defense": 664, "mobility": 703, "movement": 4, "max_hp": 45270, "max_en": 210, "max_attack": 5796, "max_defense": 4779, "max_mobility": 5061, "max_movement": 4, "sp_hp": 7994, "sp_en": 89, "sp_attack": 1024, "sp_defense": 844, "sp_mobility": 894, "sp_movement": 4, "sp_max_hp": 57557, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6076, "sp_max_mobility": 6434, "sp_max_movement": 4}','{"unit_id": 1031000800, "unit_ssp_initial_release_set_id": 1031000800, "unit_ssp_custom_core_group_id": 1031000800, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 103100080001, "unit_ssp_custom_core_group_id": 1031000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100080001, "weapon_change": {"id": 103100080001, "before_weapon_id": 0, "after_weapon_id": 103100080090, "weapon": {"id": 103100080090, "name": "MMP-50機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100080090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100080090, "weapon_status": {"id": 103100080090, "range_min": 1, "range_max": 3, "power": 