INSERT OR REPLACE INTO "units" VALUES(1031000900,'里克·大魔 (雷霆宙域版)','力奇‧大魔 (雷霆战线版)',2,2,8,0,'10000000003100010','310','g0310u00900','MS-09R',1,1,1,1,8109,56,683,682,584,4,58383,176,4918,4905,3971,4,79940,241,6733,6715,5436,4,3,1,2,1,2,'活跃于一年战争末期的高机动量产型MS。
是将MS-09大魔改良为宇宙用的机体，特征和大魔相同，都具有能够在拓展为十字型的视野中进行立体搜寻的单眼球。
配属于活死人师团的机体作为暗礁宙域规格对关节部位施加了密封处理，背面设置了加装高机动用推进器的大型背包和增装燃料槽。
由于鱼干号搭载机主要以大砲进行狙击任务，所以采用热能斧及MMP-50机枪做为武装，由浩华和费雪驾驶。','{"id": 1031000900, "hp": 8109, "en": 56, "attack": 683, "defense": 682, "mobility": 584, "movement": 4, "max_hp": 58383, "max_en": 176, "max_attack": 4918, "max_defense": 4905, "max_mobility": 3971, "max_movement": 4, "sp_hp": 11103, "sp_en": 76, "sp_attack": 936, "sp_defense": 933, "sp_mobility": 800, "sp_movement": 4, "sp_max_hp": 79940, "sp_max_en": 241, "sp_max_attack": 6733, "sp_max_defense": 6715, "sp_max_mobility": 5436, "sp_max_movement": 4}','{"unit_id": 1031000900, "unit_ssp_initial_release_set_id": 1031000900, "unit_ssp_custom_core_group_id": 1031000900, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 103100090001, "unit_ssp_custom_core_group_id": 1031000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100090001, "weapon_change": {"id": 103100090001, "before_weapon_id": 0, "after_weapon_id": 103100090090, "weapon": {"id": 103100090090, "name": "MMP-50機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100090090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100090090, "weapon_status": {"id": 103100090090, "range_min": 1, "range_max": 3,