INSERT OR REPLACE INTO "units" VALUES(1031001400,'高达头','高达头',2,3,2,0,'10000000003100010','310','g0310u01400','RGM-79/GH',1,1,1,1,6519,65,617,653,678,4,46936,204,4442,4701,4645,4,64266,279,6082,6437,6360,4,3,1,3,1,2,'将地球联邦军量产型MS──吉姆的机体安装上高达头部组成的MS。
鉴于高达已成为自护心中深具威胁性的象征，遂利用这股影响力打造出这款机体，并投入阿‧巴瓦‧空战役对付自护军。
大型背包内配备有可持两面盾牌的辅助臂。
施加了用以预防太空垃圾影响的关节部位密封处理，也增设了用于搜索的头部感应器。
背面的挂架配备有一柄镭射军刀。
其他武装还有2连装镭射步枪以及突袭步枪。','{"id": 1031001400, "hp": 6519, "en": 65, "attack": 617, "defense": 653, "mobility": 678, "movement": 4, "max_hp": 46936, "max_en": 204, "max_attack": 4442, "max_defense": 4701, "max_mobility": 4645, "max_movement": 4, "sp_hp": 8926, "sp_en": 89, "sp_attack": 845, "sp_defense": 894, "sp_mobility": 928, "sp_movement": 4, "sp_max_hp": 64266, "sp_max_en": 279, "sp_max_attack": 6082, "sp_max_defense": 6437, "sp_max_mobility": 6360, "sp_max_movement": 4}','{"unit_id": 1031001400, "unit_ssp_initial_release_set_id": 1031001400, "unit_ssp_custom_core_group_id": 1031001400, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 103100140001, "unit_ssp_custom_core_group_id": 1031001400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100140001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100140001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100140001, "weapon_change": {"id": 103100140001, "before_weapon_id": 0, "after_weapon_id": 103100140090, "weapon": {"id": 103100140090, "name": "2連裝鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100140090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 470002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100140090, "weapon_status": {"id": 103100140090, "range_min": 2, "range_max": 5, "power": 4850, "en": 61, "hit_r