INSERT OR REPLACE INTO "units" VALUES(1031002200,'龟霸索敌型','龟霸索敌型',4,2,9,0,'10000000003100010','310','g0310u02200','MSM-04',1,1,1,1,9230,68,786,921,799,4,66452,240,5655,6628,4885,4,73928,267,6291,7374,5435,4,1,1,3,1,3,'有一派说法是，此机体本为一年战争时自护公国军所开发的水陆两用MS，战后由残党组织加以改造成了衍生机并投入运用。
一年战争时部署在雷霆宙域的自护公国军活死人师团之幸存者在与地球上的自护公国军残党组织会合后，便开始使用这种机体。
此机体不同于以往的龟霸，整体尺寸小了一号，同时机体构造也被大幅改造成了更适合执行隐密作战的规格。
机体各部位皆采可自由更动的设计，能够配合作战内容换上专用装备。此机体头部有感应器护罩、左手有感测臂，背部也配备了具有激光通讯功能的任务背包。
虽然是著重于搜索和指挥性能的规格，但在达里尔‧洛伦兹的操纵技术加持下，依然缔造了不俗的破敌战果。','{"id": 1031002200, "hp": 9230, "en": 68, "attack": 786, "defense": 921, "mobility": 799, "movement": 4, "max_hp": 66452, "max_en": 240, "max_attack": 5655, "max_defense": 6628, "max_mobility": 4885, "max_movement": 4, "sp_hp": 10268, "sp_en": 76, "sp_attack": 874, "sp_defense": 1025, "sp_mobility": 888, "sp_movement": 4, "sp_max_hp": 73928, "sp_max_en": 267, "sp_max_attack": 6291, "sp_max_defense": 7374, "sp_max_mobility": 5435, "sp_max_movement": 4}','{"unit_id": 1031002200, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1031002200, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 103100220001, "unit_ssp_custom_core_group_id": 1031002200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100220001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100220001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100220001, "weapon_change": {"id": 103100220001, "before_weapon_id": 0, "after_weapon_id": 103100220090, "weapon": {"id": 103100220090, "name": "火箭發射器 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100220090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 200001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100220090, "weapon_status": {"id": 103100220090, "range_min": 3, "range_max": 5, "power": 505