INSERT OR REPLACE INTO "units" VALUES(1031002300,'龟霸机动型','龟霸机动型',2,2,9,0,'10000000003100010','310','g0310u02300','MSM-04',1,1,1,1,7431,56,621,750,582,4,53503,176,4469,5400,3955,4,73258,241,6119,7393,5415,4,1,1,3,1,3,'在小队基本阵型中担任前锋，负责侦察和护卫友机的是被称为机动型的MSM-04龟霸衍生机。
未装备任何大型选配组件，由于与MSM-04的原始规格最为相近而保有原本的运动性能，可谓此机体的一大特征。
配备的组件作用著重于辅助友机，A、B两机共通的装备为盾牌。
A机配备的是沿用自MSM-03战蟹头部装甲的龟甲盾，B机则为十字型盾牌。
此外，A机还配备了沿用格斗战用热能斧刀刃的电热剑，背部则带有潜望镜任务背包。
B机的背部则为装载备用弹匣的任务背包。
可以说机动型A、B机的规格皆是专为担任小队中的支援角色而设计的。','{"id": 1031002300, "hp": 7431, "en": 56, "attack": 621, "defense": 750, "mobility": 582, "movement": 4, "max_hp": 53503, "max_en": 176, "max_attack": 4469, "max_defense": 5400, "max_mobility": 3955, "max_movement": 4, "sp_hp": 10175, "sp_en": 76, "sp_attack": 850, "sp_defense": 1027, "sp_mobility": 797, "sp_movement": 4, "sp_max_hp": 73258, "sp_max_en": 241, "sp_max_attack": 6119, "sp_max_defense": 7393, "sp_max_mobility": 5415, "sp_max_movement": 4}','{"unit_id": 1031002300, "unit_ssp_initial_release_set_id": 1031002300, "unit_ssp_custom_core_group_id": 1031002300, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 103100230001, "unit_ssp_custom_core_group_id": 1031002300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100230001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100230001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100230001, "weapon_change": {"id": 103100230001, "before_weapon_id": 0, "after_weapon_id": 103100230090, "weapon": {"id": 103100230090, "name": "火箭發射器 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100230090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 200001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100230090, "weapon_status": {"id": 103100230090, "range_min": 2, "range_max": 4, "power": 4850, "en"