INSERT OR REPLACE INTO "units" VALUES(1031002400,'龟霸火力型A','龟霸火力型A',3,1,9,0,'10000000003100010','310','g0310u02400','MSM-04',1,1,1,1,6706,71,835,633,661,4,48283,200,6007,4558,5008,4,61388,255,7637,5795,6367,4,1,1,3,1,3,'有一派说法是，此机体本为一年战争时自护公国军所开发的水陆两用MS，战后经过残党组织加以改造成了衍生机并投入运用。
一年战争时部署在雷霆宙域的自护公国军活死人师团之幸存者在与地球上的自护公国军残党组织会合后，便开始使用这种机体。
此机体不同于以往的龟霸，整体尺寸小了一号，同时机体构造也被大幅改造成了更适合执行隐密作战的规格。
机体各部位皆采可自由更动的设计，能够配合作战内容换上专用装备。此机体配备多合一的复合兵器组件，可依据战况选择最适合的兵器，借此发挥支援小队行动的效果。
背部装有结合推进系统和布雷装置功能的「殿后组件」，可以掩护部队撤退。','{"id": 1031002400, "hp": 6706, "en": 71, "attack": 835, "defense": 633, "mobility": 661, "movement": 4, "max_hp": 48283, "max_en": 200, "max_attack": 6007, "max_defense": 4558, "max_mobility": 5008, "max_movement": 4, "sp_hp": 8527, "sp_en": 90, "sp_attack": 1061, "sp_defense": 805, "sp_mobility": 841, "sp_movement": 4, "sp_max_hp": 61388, "sp_max_en": 255, "sp_max_attack": 7637, "sp_max_defense": 5795, "sp_max_mobility": 6367, "sp_max_movement": 4}','{"unit_id": 1031002400, "unit_ssp_initial_release_set_id": 1031002400, "unit_ssp_custom_core_group_id": 1031002400, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 103100240001, "unit_ssp_custom_core_group_id": 1031002400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100240001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100240001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100240001, "weapon_change": {"id": 103100240001, "before_weapon_id": 0, "after_weapon_id": 103100240090, "weapon": {"id": 103100240090, "name": "WCU（刺刀） SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100240090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 270008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100240090, "weapon_status": {"id": 103100240090, "range_min": 1, "range_max": 3, "power": 4950, "e