": {"id": 1000001, "trait_condition_set_id": 1000001, "group_id": "", "target": "Owner", "unit_tags": "", "unit_role": "", "unit_series": "", "unit_size": "", "tension": "", "standby_terrain": "", "weapon_attribute": "", "weapon_attack_attribute": "", "map_battle_action": "", "hp_type": 0, "hp_rate_lte_threshold": 0, "hp_rate_gte_threshold": 0, "en_rate_lte_threshold": 0, "en_rate_gte_threshold": 0, "en_value_lte_threshold": 0, "en_value_gte_threshold": 0, "use_hp_rate_lte_threshold": false, "attack_distance_gte_threshold": 0, "attack_distance_lte_threshold": 0, "turn_number": 0, "is_in_chance_step": false, "is_in_one_on_one": false, "unit_ids": "", "character_ids": "", "character_tags_id": "", "character_series_id": "", "tags": null, "series": null, "character_series": null, "character_tags": null}, "trait_boost": null, "granted_trait_set": null}}], "units": null, "characters": null}}}}','龜霸火力型A','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1031002500,'龟霸火力型B','龟霸火力型B',3,2,9,0,'10000000003100010','310','g0310u02500','MSM-04',1,1,1,1,8710,60,795,733,635,4,62711,191,5723,5273,4313,4,79732,242,7276,6705,5484,4,1,1,3,1,3,'MSM-04的小队编制中负责掩护和殿后的，是这种被称为龟霸火力型的特殊规格机体。
特征是其中一只手臂换成兵器集成组件，背包则置换为有「殿后组件」之称的布雷组件。
在小队基本阵型中位于后方两翼，负责支援僚机。
胸部的兵器集成组件是一种复合式兵器，A机与B机的内容物不同。
A机为渣古机枪、TOW飞弹发射器和对MS刺刀，B机则为渣古机枪、火焰放射器以及对MS流星索的组合。
殿后组件是兼具推进系统的布雷装置，从其名称便可想见是为撤退时争取时间而设计的兵器。
在执行对南洋同盟的谍报任务时，A机由比利‧西汉驾驶，B机则为赛巴斯钦‧摩斯所驾驶。','{"id": 1031002500, "hp": 8710, "en": 60, "attack": 795, "defense": 733, "mobility": 635, "movement": 4, "max_hp": 62711, "max_en": 191, "max_attack": 5723, "max_defense": 5273, "max_mobility": 4313, "max_movement": 4, "sp_hp": 11074, "sp_en": 77, "sp_attack": 1011, "sp_defense": 932, "sp_mobility": 807, "sp_movement": 4, "sp_max_hp": 79732, "sp_max_en": 242, "sp_max_attack": 7276, "sp_max_defense": 6705, "sp_max_mobility": 5484, "sp_max_movement": 4}','{"unit_id": 1031002500, "unit_ssp_initial_release_set_id": 1031002500, "unit_ssp_custom_core_group_id": 1031002500, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 103100250001, "unit_ssp_custom_core_group_id": 1031002500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100250001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100250001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100250001, "weapon_change": {"id": 103100250001, "before_weapon_id": 0, "after_weapon_id": 103100250090, "weapon": {"id": 103100250090, "name": "對MS流星索 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100250090, "attack_attr": 1, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 230004, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100250090, "weapon_status": {"id": 103100250090, "range_min": 2, "range_max": 4, "power": 