INSERT OR REPLACE INTO "units" VALUES(1031002800,'魔蟹（雷霆宙域版）','魔蟹（雷霆战线版）',3,3,9,0,'10000000003100010','310','g0310u02800','MSM-07',1,1,1,1,7055,70,666,697,732,4,50794,220,4794,5014,5018,4,64580,279,6095,6375,6380,4,1,1,3,1,3,'高夫曼部队的主力机。
不同于一年战争时的魔蟹，双手双脚皆使用了球形关节，肩部也有追加装甲。
为因应寒地作战，脚部也做了改造，可进行气垫滑行。
武装部分搭载了铁爪、手部的机枪以及头部的飞弹。','{"id": 1031002800, "hp": 7055, "en": 70, "attack": 666, "defense": 697, "mobility": 732, "movement": 4, "max_hp": 50794, "max_en": 220, "max_attack": 4794, "max_defense": 5014, "max_mobility": 5018, "max_movement": 4, "sp_hp": 8970, "sp_en": 89, "sp_attack": 847, "sp_defense": 886, "sp_mobility": 931, "sp_movement": 4, "sp_max_hp": 64580, "sp_max_en": 279, "sp_max_attack": 6095, "sp_max_defense": 6375, "sp_max_mobility": 6380, "sp_max_movement": 4}','{"unit_id": 1031002800, "unit_ssp_initial_release_set_id": 1031002800, "unit_ssp_custom_core_group_id": 1031002800, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 103100280001, "unit_ssp_custom_core_group_id": 1031002800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100280001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100280001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100280001, "weapon_change": {"id": 103100280001, "before_weapon_id": 0, "after_weapon_id": 103100280090, "weapon": {"id": 103100280090, "name": "機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100280090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100280090, "weapon_status": {"id": 103100280090, "range_min": 2, "range_max": 5, "power": 4750, "en": 59, "hit_rat