INSERT OR REPLACE INTO "units" VALUES(1031003100,'达勒（浮艇装备）','达利（浮艇装备）',2,2,13,0,'10000000003100010','310','g0310u03100','-',1,1,1,1,8070,56,557,683,652,4,58103,195,4004,4913,3987,4,79556,266,5482,6727,5459,4,1,1,3,3,1,'可说是水上型SFS的MS用「穿戴」小艇。
装在双脚的小腿处，水上航行时MS会呈双膝跪姿。
各浮艇配备两具推进器，左右共计有四具，速度甚至凌驾于水中航行时的龟霸。
浮艇本身并没有武装，但水上移动时MS的双手仍可自由活动，所以无损其战斗能力。
在有水域优势的南洋同盟领域内是极具效益的装备。','{"id": 1031003100, "hp": 8070, "en": 56, "attack": 557, "defense": 683, "mobility": 652, "movement": 4, "max_hp": 58103, "max_en": 195, "max_attack": 4004, "max_defense": 4913, "max_mobility": 3987, "max_movement": 4, "sp_hp": 11050, "sp_en": 76, "sp_attack": 762, "sp_defense": 935, "sp_mobility": 892, "sp_movement": 4, "sp_max_hp": 79556, "sp_max_en": 266, "sp_max_attack": 5482, "sp_max_defense": 6727, "sp_max_mobility": 5459, "sp_max_movement": 4}','{"unit_id": 1031003100, "unit_ssp_initial_release_set_id": 1031003100, "unit_ssp_custom_core_group_id": 1031003100, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 103100310001, "unit_ssp_custom_core_group_id": 1031003100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100310001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100310001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100310001, "weapon_change": {"id": 103100310001, "before_weapon_id": 0, "after_weapon_id": 103100310090, "weapon": {"id": 103100310090, "name": "火箭發射器 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100310090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 230004, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100310090, "weapon_status": {"id": 103100310090, "range_min": 3, "range_max": 4, "power": 4850, "en": 61, "hit