INSERT OR REPLACE INTO "units" VALUES(1031003200,'老虎（雷霆宙域版）','老虎（雷霆战线版）',3,3,67,0,'10000000003100010','310','g0310u03200','MS-07B',1,1,1,1,6607,71,734,669,737,5,47569,222,5285,4817,5054,5,60481,282,6719,6125,6425,5,1,3,3,1,3,'遗留在战场上的自护军MS老虎，经过南洋同盟的一番改造后投入实战使用。
作为飞行组件的背包上装有两具风扇。
飞行组件赋予其滞空、急速爬升等运动性能，还可协同德戴一起应对空中战。
武装有巨型迫击砲、渣古机枪、电热军刀、盾牌、电热鞭以及3连装格林机砲。
试图阻止斯巴达号进入南洋同盟支配区域。','{"id": 1031003200, "hp": 6607, "en": 71, "attack": 734, "defense": 669, "mobility": 737, "movement": 5, "max_hp": 47569, "max_en": 222, "max_attack": 5285, "max_defense": 4817, "max_mobility": 5054, "max_movement": 5, "sp_hp": 8401, "sp_en": 90, "sp_attack": 934, "sp_defense": 851, "sp_mobility": 937, "sp_movement": 5, "sp_max_hp": 60481, "sp_max_en": 282, "sp_max_attack": 6719, "sp_max_defense": 6125, "sp_max_mobility": 6425, "sp_max_movement": 5}','{"unit_id": 1031003200, "unit_ssp_initial_release_set_id": 1031003200, "unit_ssp_custom_core_group_id": 1031003200, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 103100320001, "unit_ssp_custom_core_group_id": 1031003200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100320001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100320001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100320001, "weapon_change": {"id": 103100320001, "before_weapon_id": 0, "after_weapon_id": 103100320090, "weapon": {"id": 103100320090, "name": "巨型迫擊砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100320090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100320090, "weapon_status": {"id": 103100320090, "range_min": 3, "range_max": 5, "power": 4900, "en": 61, "hit_rate