INSERT OR REPLACE INTO "units" VALUES(1031003300,'吉姆飞行器','吉姆飞行器',2,2,24,0,'10000000003100010','310','g0310u03300','-',1,1,1,1,8400,56,587,648,621,4,60475,186,4221,4661,3995,4,82805,254,5779,6382,5470,4,3,3,2,1,1,'投入阿‧巴瓦‧空攻防战的G装甲，内部搭载的并非高达，而是RGM-79吉姆。
此版本也解决了搭载的MS腹部会外露的结构性问题，
并加挂了用于收纳双臂的组件，整体性能皆获得提升。
然而，在迎战脑波传导高机动实验用渣古时，机首部位遭到破坏。随后驾驶员欲以内藏的吉姆加以反击，但还是遭到击破。','{"id": 1031003300, "hp": 8400, "en": 56, "attack": 587, "defense": 648, "mobility": 621, "movement": 4, "max_hp": 60475, "max_en": 186, "max_attack": 4221, "max_defense": 4661, "max_mobility": 3995, "max_movement": 4, "sp_hp": 11501, "sp_en": 76, "sp_attack": 803, "sp_defense": 887, "sp_mobility": 850, "sp_movement": 4, "sp_max_hp": 82805, "sp_max_en": 254, "sp_max_attack": 5779, "sp_max_defense": 6382, "sp_max_mobility": 5470, "sp_max_movement": 4}','{"unit_id": 1031003300, "unit_ssp_initial_release_set_id": 1031003300, "unit_ssp_custom_core_group_id": 1031003300, "unit_ssp_add_status_id": 100005, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100005, "ssp_hp": 298, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 23, "ssp_mobility": 22, "ssp_max_hp": 5950, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 458, "ssp_max_mobility": 435}, "cores": [{"id": 103100330001, "unit_ssp_custom_core_group_id": 1031003300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 103100330001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 103100330001, "sort_order": 1, "release_function_type_index": 5, "target_id": 103100330001, "weapon_change": {"id": 103100330001, "before_weapon_id": 0, "after_weapon_id": 103100330090, "weapon": {"id": 103100330090, "name": "鐳射噴槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 103100330090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 103100330090, "weapon_status": {"id": 103100330090, "range_min": 1, "range_max": 4,