INSERT OR REPLACE INTO "units" VALUES(1044000410,'伊夫里特夜战型','伊夫利特夜战型',4,1,9,0,'10000000004400010','440','g0440u00400','MS-08TX/N',1,1,1,1,8783,88,1015,748,882,4,63234,262,7301,5386,6349,4,63952,265,7384,5447,6421,4,1,1,3,1,3,'自护公国军将陆战用开发试作MS「伊夫利特」的其中一架改装而成的夜间战斗用特殊衍生机。为了活用伊夫利特系列具备的高超陆战性能，搭载了全新的专用技术体系。
强化推进器为此机体带来高机动性，外型如刀的实体剑「冷冻剑」以及可以投掷的「冷冻飞镖」令此机体获得极高的格斗能力。
本机最大的特征就是搭载了「干扰用特殊机器」，能对敌方雷达保持隐密性，在隐密行动时更能发挥机体的优越性能。
此外，本机体虽然是在一年战争中开发，但由于藏在敖迪沙基地被联邦军连带接收，故性能与存在皆未公诸于世。','{"id": 1044000410, "hp": 8783, "en": 88, "attack": 1015, "defense": 748, "mobility": 882, "movement": 4, "max_hp": 63234, "max_en": 262, "max_attack": 7301, "max_defense": 5386, "max_mobility": 6349, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 1026, "sp_defense": 757, "sp_mobility": 892, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 265, "sp_max_attack": 7384, "sp_max_defense": 5447, "sp_max_mobility": 6421, "sp_max_movement": 4}','{"unit_id": 1044000410, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1044000410, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 104400041001, "unit_ssp_custom_core_group_id": 1044000410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 104400041001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 104400041001, "sort_order": 1, "release_function_type_index": 5, "target_id": 104400041001, "weapon_change": {"id": 104400041001, "before_weapon_id": 0, "after_weapon_id": 104400041090, "weapon": {"id": 104400041090, "name": "冷凍劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 104400041090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 104400041090, "weapon_status": {"id": 104400041090, "range_min": 1, "range_max": 2, "power": 4900