INSERT OR REPLACE INTO "units" VALUES(1060000200,'高达试作1号机全方位推进型','高达试作1号机全方位推进型',4,1,8,0,'10000000006000010','600','g0600u00200','RX-78GP01Fb',1,1,1,1,8000,81,919,680,800,4,57600,243,6611,4896,5760,4,64080,270,7355,5447,6408,4,3,1,2,1,2,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」，在极机密状况下试作的实验用MS「高达试作１号机」。
但由于在宇宙与盖古克Ｍ（陆战）队战斗后严重破损，于阿纳海姆电子企业的冯‧布朗工厂进行大规模改装，成了这架宇宙规格的机体。
原本为确保泛用性，考量的是以换装主机体「核心战机Ⅱ」变更规格的简单方法。
但基于机体损坏状况，最终改变规格换成了完全宇宙用的机体。
除此之外更同时依各方案平行改装，并依据过去运作资料反映调整，于核心战机Ⅱ后方进行全面改造，装备䇲型推进器，并扩大上半身各喷射推进器的可动范围等等，机动性与运动性能皆比改修前提升了一个等级。','{"id": 1060000200, "hp": 8000, "en": 81, "attack": 919, "defense": 680, "mobility": 800, "movement": 4, "max_hp": 57600, "max_en": 243, "max_attack": 6611, "max_defense": 4896, "max_mobility": 5760, "max_movement": 4, "sp_hp": 8900, "sp_en": 90, "sp_attack": 1022, "sp_defense": 757, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 270, "sp_max_attack": 7355, "sp_max_defense": 5447, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1060000200, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1060000200, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 106000020001, "unit_ssp_custom_core_group_id": 1060000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000020001, "weapon_change": {"id": 106000020001, "before_weapon_id": 0, "after_weapon_id": 106000020090, "weapon": {"id": 106000020090, "name": "長程鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000020090, "weapon_status": {"id": 106000020090