INSERT OR REPLACE INTO "units" VALUES(1060000300,'高达试作2号机','高达试作2号机',3,2,2,0,'10000000006000010','600','g0600u00300','RX-78GP02A',1,1,1,1,7700,60,788,837,668,4,55440,200,5670,6024,4302,4,70488,254,7209,7659,5469,4,3,1,3,1,2,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」，在极机密状况下试作的实验用MS。
以任何环境与状况下都能歼灭敌人及其据点为主要目的，开发为「拥有最强攻击力的MS」的突袭用机体。
最大的特征就是搭载了名为「原子火箭砲」的核能兵器，为了承受自己释放的核爆炸，所有装甲皆经过耐热‧耐冲击处理，更必须携带组有冷却装置的专用盾牌。
机体双肩还装备了突袭‧脱离用的高输出推进器，具备异常的反应速度与机动性。
此外，本机体原订在特灵顿基地进行战术核弹发射测试，却受到「达拉斯舰队」突袭，因而直接被夺走。','{"id": 1060000300, "hp": 7700, "en": 60, "attack": 788, "defense": 837, "mobility": 668, "movement": 4, "max_hp": 55440, "max_en": 200, "max_attack": 5670, "max_defense": 6024, "max_mobility": 4302, "max_movement": 4, "sp_hp": 9790, "sp_en": 76, "sp_attack": 1002, "sp_defense": 1064, "sp_mobility": 849, "sp_movement": 4, "sp_max_hp": 70488, "sp_max_en": 254, "sp_max_attack": 7209, "sp_max_defense": 7659, "sp_max_mobility": 5469, "sp_max_movement": 4}','{"unit_id": 1060000300, "unit_ssp_initial_release_set_id": 1060000300, "unit_ssp_custom_core_group_id": 1060000300, "unit_ssp_add_status_id": 100008, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100008, "ssp_hp": 252, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 27, "ssp_mobility": 22, "ssp_max_hp": 5035, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 549, "ssp_max_mobility": 435}, "cores": [{"id": 106000030001, "unit_ssp_custom_core_group_id": 1060000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000030001, "weapon_change": {"id": 106000030001, "before_weapon_id": 0, "after_weapon_id": 106000030090, "weapon": {"id": 106000030090, "name": "原子火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000030090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290028, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000030090, "weapon_status": {"id": 106000030090, "range_min": 4, "range_max": 5, "powe