INSERT OR REPLACE INTO "units" VALUES(1060000350,'高达试作2号机 (EX)','高达试作2号机 (EX)',5,3,2,0,'10000000006000010','600','g0600u00350','RX-78GP02A',1,1,1,1,10060,100,950,1000,1044,4,72432,315,6840,7200,7157,4,72432,315,6840,7200,7157,4,3,1,3,1,2,'-','{"id": 1060000350, "hp": 10060, "en": 100, "attack": 950, "defense": 1000, "mobility": 1044, "movement": 4, "max_hp": 72432, "max_en": 315, "max_attack": 6840, "max_defense": 7200, "max_mobility": 7157, "max_movement": 4, "sp_hp": 10060, "sp_en": 100, "sp_attack": 950, "sp_defense": 1000, "sp_mobility": 1044, "sp_movement": 4, "sp_max_hp": 72432, "sp_max_en": 315, "sp_max_attack": 6840, "sp_max_defense": 7200, "sp_max_mobility": 7157, "sp_max_movement": 4}','null','高達試作2號機 (EX)','scrape',1791488368,'v2026.10.08',1060001500);
INSERT OR REPLACE INTO "units" VALUES(1060000400,'高达试做3号机雄蕊','高达试作3号机史迪蒙',3,1,2,0,'10000000006000010','600','g0600u00400','RX-78GP03S',1,1,1,1,6603,70,843,631,671,5,47536,199,6069,4541,5079,5,60438,253,7716,5773,6458,5,3,1,3,1,2,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」，在极机密状况下试作的高达系MS搭载型实验用机动兵器「典多洛比姆」，其MS部分的机体。
为了顾虑与「欧契斯武装基座」合体，设置「尾部支架」提升运动性能与机动性。
而为了控制大量的武装，驾驶舱不仅采用360度显示幕与悬吊式座椅座舱，手臂也内藏了和欧契斯武装基座连动所需的「折叠机械臂」。
此外，由于欧契斯武装基座补给需要花费相当长的时间，本机体亦可作为宇宙用MS单独进行战斗，具备高超的性能。','{"id": 1060000400, "hp": 6603, "en": 70, "attack": 843, "defense": 631, "mobility": 671, "movement": 5, "max_hp": 47536, "max_en": 199, "max_attack": 6069, "max_defense": 4541, "max_mobility": 5079, "max_movement": 5, "sp_hp": 8395, "sp_en": 89, "sp_attack": 1072, "sp_defense": 802, "sp_mobility": 853, "sp_movement": 5, "sp_max_hp": 60438, "sp_max_en": 253, "sp_max_attack": 7716, "sp_max_defense": 5773, "sp_max_mobility": 6458, "sp_max_movement": 5}','{"unit_id": 1060000400, "unit_ssp_initial_release_set_id": 1060000400, "unit_ssp_custom_core_group_id": 1060000400, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 106000040001, "unit_ssp_custom_core_group_id": 1060000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000040001, "weapon_change": {"id": 106000040001, "before_weapon_id": 0, "after_weapon_id": 106000040090, "weapon": {"id": 106000040090, "name": "摺疊式火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000040090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000040090, "weapon_status": {"id": 106000040090, "range_min": 2, "range_max": 4,