INSERT OR REPLACE INTO "units" VALUES(1060000550,'高达试做3号机 (EX)','高达试作3号机 (EX)',5,2,44,0,'10000000006000010','600','g0600u00550','RX-78GP03',1,2,1,1,13055,85,1087,994,954,5,93994,285,7824,7156,6140,5,93994,285,7824,7156,6140,5,3,2,1,1,1,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」，在极机密状况下试作，同时具备MS与MA的性能，网罗所有兵器要素，以高达开发计划的理念「史上最强机动兵器」所创造出的高达。
由于预定的主要用途在于防守宇宙空间据点，欧契斯武装基座本身成为巨大的武器库。
不仅透过大量的燃料带来高机动力，更装备了「米加镭射砲」为首的各种兵器，以及能令镭射兵器无效的「I力场发生器」等等，具备压倒性的战斗能力。','{"id": 1060000550, "hp": 13055, "en": 85, "attack": 1087, "defense": 994, "mobility": 954, "movement": 5, "max_hp": 93994, "max_en": 285, "max_attack": 7824, "max_defense": 7156, "max_mobility": 6140, "max_movement": 5, "sp_hp": 13055, "sp_en": 85, "sp_attack": 1087, "sp_defense": 994, "sp_mobility": 954, "sp_movement": 5, "sp_max_hp": 93994, "sp_max_en": 285, "sp_max_attack": 7824, "sp_max_defense": 7156, "sp_max_mobility": 6140, "sp_max_movement": 5}','null','高達試作3號機 (EX)','scrape',1791488368,'v2026.10.08',1060000100);
INSERT OR REPLACE INTO "units" VALUES(1060000600,'高达试做4号机','高达试作4号机',4,1,2,0,'10000000006000010','600','g0600u00600','RX-78GP04G',1,1,1,1,7252,81,915,761,799,4,52214,242,6583,5478,5753,4,58088,269,7324,6094,6400,4,3,1,3,1,2,'一年战争后所实施的联邦军重建计划其中一环的高达开发计划里，为实现最强MS的设计理念，参考过去自护公国开发的突袭用MS，以现代技术将其概念具体呈现的MS。
与增装燃料槽合为一体的飓风推进器所带来的爆发性推进力，并装备威力傲人的长型镭射步枪，设计上也具有强大近距离战斗能力，得以借由强行突击达成迅速镇压、歼灭敌方势力。
然而，由于本机部分概念与试作1号机重复，因而被从高达开发计划中剔除，并对外宣称中止开发，但却由阿纳海姆公司独自继续开发。
后来变更了外装与部分规格，改以「加贝拉‧迪特」之名让渡给了与阿纳海姆公司暗中交易的丝玛舰队，因此鲜少有人知道本机原本的模样。','{"id": 1060000600, "hp": 7252, "en": 81, "attack": 915, "defense": 761, "mobility": 799, "movement": 4, "max_hp": 52214, "max_en": 242, "max_attack": 6583, "max_defense": 5478, "max_mobility": 5753, "max_movement": 4, "sp_hp": 8068, "sp_en": 90, "sp_attack": 1018, "sp_defense": 847, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 58088, "sp_max_en": 269, "sp_max_attack": 7324, "sp_max_defense": 6094, "sp_max_mobility": 6400, "sp_max_movement": 4}','{"unit_id": 1060000600, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1060000600, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 106000060001, "unit_ssp_custom_core_group_id": 1060000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000060001, "weapon_change": {"id": 106000060001, "before_weapon_id": 0, "after_weapon_id": 106000060090, "weapon": {"id": 106000060090, "name": "長型鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000060090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000060090, "weapon_status": {"id": 106000060090, "range_min": 2, "range_max": 5