INSERT OR REPLACE INTO "units" VALUES(1060000700,'大功率吉姆','力量型吉姆',2,1,2,0,'10000000006000010','600','g0600u00700','RGM-79',1,1,1,1,5850,65,747,619,650,4,42120,195,5372,4455,4680,4,57672,267,7355,6100,6408,4,3,1,3,1,2,'联邦军于一年战争后开发的「吉姆」衍生机体之一，是「高达开发计划」的一环。
为了测试「高达试作１号机」用的大型背包先行开发品以及搭配用的新型避震器配件，而特地开发此机体。
由于是以后期生产型的「吉姆」为基底改装用以收集新型MS开发资料，输出与机动性都超出吉姆改许多，不过毕竟仅试作了几架实验用机体，并未特地设定新的型式编号。','{"id": 1060000700, "hp": 5850, "en": 65, "attack": 747, "defense": 619, "mobility": 650, "movement": 4, "max_hp": 42120, "max_en": 195, "max_attack": 5372, "max_defense": 4455, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8010, "sp_en": 89, "sp_attack": 1022, "sp_defense": 848, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 57672, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 6100, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1060000700, "unit_ssp_initial_release_set_id": 1060000700, "unit_ssp_custom_core_group_id": 1060000700, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 106000070001, "unit_ssp_custom_core_group_id": 1060000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000070001, "weapon_change": {"id": 106000070001, "before_weapon_id": 0, "after_weapon_id": 106000070090, "weapon": {"id": 106000070090, "name": "超絕火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000070090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000070090, "weapon_status": {"id": 106000070090, "range_m