INSERT OR REPLACE INTO "units" VALUES(1060000800,'吉姆特装型','吉姆特装型',3,1,2,0,'10000000006000010','600','g0600u00800','RGM-79N',1,1,1,1,6958,70,805,595,705,4,50098,210,5796,4284,5071,4,63696,267,7370,5447,6447,4,3,1,3,1,2,'联邦军于一年战争后开发的「吉姆」衍生机体之一，是为了改善量产机的综合性能平衡，实施动力炉输出提升与强化各部位辅助推进器等各种改装的机体。
此机体大多是调整提供王牌驾驶员使用，制作成本昂贵，生产率也低落，但因具备超过吉姆将近一倍的推进力，动力炉输出也相当于高达型，所以在「达拉斯纷争」发生之前，是联邦制量产机里最高级的机体。','{"id": 1060000800, "hp": 6958, "en": 70, "attack": 805, "defense": 595, "mobility": 705, "movement": 4, "max_hp": 50098, "max_en": 210, "max_attack": 5796, "max_defense": 4284, "max_mobility": 5071, "max_movement": 4, "sp_hp": 8847, "sp_en": 89, "sp_attack": 1024, "sp_defense": 757, "sp_mobility": 896, "sp_movement": 4, "sp_max_hp": 63696, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 5447, "sp_max_mobility": 6447, "sp_max_movement": 4}','{"unit_id": 1060000800, "unit_ssp_initial_release_set_id": 1060000800, "unit_ssp_custom_core_group_id": 1060000800, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 106000080001, "unit_ssp_custom_core_group_id": 1060000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000080001, "weapon_change": {"id": 106000080001, "before_weapon_id": 0, "after_weapon_id": 106000080090, "weapon": {"id": 106000080090, "name": "吉姆步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000080090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000080090, "weapon_status": {"id": 1060000