INSERT OR REPLACE INTO "units" VALUES(1060000900,'吉姆加农Ⅱ','吉姆大砲Ⅱ',2,3,2,0,'10000000006000010','600','g0600u00900','RGC-83',1,1,1,1,6188,65,683,618,682,4,44549,205,4914,4446,4671,4,60998,281,6729,6088,6396,4,3,1,3,1,2,'联邦军于一年战争后开发的「吉姆」衍生机体之一，设计理念纯粹只为了量产「RX-77镭射大砲」，可说是集合战争时期开发的中距离支援型MS「吉姆大砲」与「量产型镭射大砲」等机体优点的集大成机体。
随著技术基础与生产率的提升，变得可以搭载高输出动力炉，因此双肩装备的２门加农砲采用的是「镭射加农」。
此外，装甲最终采用的是等同反应装甲的复合式装甲，其他基础材料则以重视与吉姆型MS的零件通用性为前提进行设计。
包括制造成本在内，可说已经具备支援机完成品应有的性能，但由于运用上的前提是配合「吉姆特装型」，实际配备数量一直都不多。','{"id": 1060000900, "hp": 6188, "en": 65, "attack": 683, "defense": 618, "mobility": 682, "movement": 4, "max_hp": 44549, "max_en": 205, "max_attack": 4914, "max_defense": 4446, "max_mobility": 4671, "max_movement": 4, "sp_hp": 8472, "sp_en": 89, "sp_attack": 935, "sp_defense": 846, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 60998, "sp_max_en": 281, "sp_max_attack": 6729, "sp_max_defense": 6088, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1060000900, "unit_ssp_initial_release_set_id": 1060000900, "unit_ssp_custom_core_group_id": 1060000900, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 106000090001, "unit_ssp_custom_core_group_id": 1060000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000090001, "weapon_change": {"id": 106000090001, "before_weapon_id": 0, "after_weapon_id": 106000090090, "weapon": {"id": 106000090090, "name": "鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000090090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000090090, "weapon_status": {"id": 106000090090, "range_min": 2, "range_max"