INSERT OR REPLACE INTO "units" VALUES(1060001000,'吉姆镇暴型','吉姆Quel',3,1,2,0,'10000000006000010','600','g0600u01000','RGM-79Q',1,1,1,1,6311,71,804,664,695,4,45438,211,5785,4778,5003,4,57771,268,7355,6075,6360,4,3,1,3,1,2,'开发供泰坦斯专用的暴徒镇压用MS，系谱分属联邦军为王牌驾驶员开发的「吉姆特装型」，是吉姆一系MS最新锐的机体。
由于是开发提供联邦军特殊部队泰坦斯使用的主力机体，虽是量产机，却有著高水准的机体规格，和一般部队使用的吉姆系列机体完全不在一个等级上。
此机体是撑起泰坦斯创立初期的MS，但在格利普斯战役时已属旧款式，没有放在第一线运用。
此外，本机涂装的黑色与深蓝色配色，后来被称作「泰坦斯配色」，成为泰坦斯用MS的标准涂装色。','{"id": 1060001000, "hp": 6311, "en": 71, "attack": 804, "defense": 664, "mobility": 695, "movement": 4, "max_hp": 45438, "max_en": 211, "max_attack": 5785, "max_defense": 4778, "max_mobility": 5003, "max_movement": 4, "sp_hp": 8024, "sp_en": 90, "sp_attack": 1022, "sp_defense": 844, "sp_mobility": 884, "sp_movement": 4, "sp_max_hp": 57771, "sp_max_en": 268, "sp_max_attack": 7355, "sp_max_defense": 6075, "sp_max_mobility": 6360, "sp_max_movement": 4}','{"unit_id": 1060001000, "unit_ssp_initial_release_set_id": 1060001000, "unit_ssp_custom_core_group_id": 1060001000, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 106000100001, "unit_ssp_custom_core_group_id": 1060001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000100001, "weapon_change": {"id": 106000100001, "before_weapon_id": 0, "after_weapon_id": 106000100090, "weapon": {"id": 106000100090, "name": "吉姆步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000100090, "weapon_status": {"id": 106000100090, "range_min": 1, "range_max": 4, "power":