INSERT OR REPLACE INTO "units" VALUES(1060001200,'扎梅尔','萨米路',3,3,13,0,'10000000006000010','600','g0600u01200','YMS-16M',1,1,1,1,7000,70,669,698,734,4,50400,221,4817,5020,5030,4,64080,281,6125,6383,6396,4,1,1,3,3,1,'以中、长距离支援砲击为目的所开发的试作型MS。
由于设计概念上是「移动砲台」，采用了热核能喷射引擎与气垫式移动，所以外观虽然颇具重量，但拥有高机动力，只是运动性能极低，也几乎无法应付短兵交战。
此外，主武器为拥有傲人长远射程的折叠式６８０ｍｍ加农砲等，重视砲击战性能，故设计为操纵手与射击手的双人复座式机体，不过亦可透过切换操纵系统单人运用。','{"id": 1060001200, "hp": 7000, "en": 70, "attack": 669, "defense": 698, "mobility": 734, "movement": 4, "max_hp": 50400, "max_en": 221, "max_attack": 4817, "max_defense": 5020, "max_mobility": 5030, "max_movement": 4, "sp_hp": 8900, "sp_en": 89, "sp_attack": 851, "sp_defense": 887, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 281, "sp_max_attack": 6125, "sp_max_defense": 6383, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1060001200, "unit_ssp_initial_release_set_id": 1060001200, "unit_ssp_custom_core_group_id": 1060001200, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 106000120001, "unit_ssp_custom_core_group_id": 1060001200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000120001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000120001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000120001, "weapon_change": {"id": 106000120001, "before_weapon_id": 0, "after_weapon_id": 106000120090, "weapon": {"id": 106000120090, "name": "680mm加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000120090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000120090, "weapon_status": {"id": 106000120090, "range_m