INSERT OR REPLACE INTO "units" VALUES(1060001300,'格鲁古古M','盖古克M',3,2,2,0,'10000000006000010','600','g0600u01300','MS-14F',1,1,1,1,8050,60,595,804,702,4,57960,210,4284,5785,4293,4,73692,267,5447,7355,5458,4,3,1,3,1,2,'自护公国于一年战争末期开发的泛用量产型MS「盖古克」，其改装为海军登陆部队规格的衍生机种之一。
为了让作战初期阶段的登陆更方便，规格变更为可连结增装燃料槽，能进行长时间的作战行动。
至于武装部分，由于当时状况无法获得镭射步枪，且较为重视对多种战况的适应力，故标准武器是「90mm机枪」，盾牌也是用独家开发，可应付短兵交战的「钉盾」。
在U.C.0083时配备于丝玛舰队作为主力机体，参加过许多次实战。','{"id": 1060001300, "hp": 8050, "en": 60, "attack": 595, "defense": 804, "mobility": 702, "movement": 4, "max_hp": 57960, "max_en": 210, "max_attack": 4284, "max_defense": 5785, "max_mobility": 4293, "max_movement": 4, "sp_hp": 10235, "sp_en": 76, "sp_attack": 757, "sp_defense": 1022, "sp_mobility": 892, "sp_movement": 4, "sp_max_hp": 73692, "sp_max_en": 267, "sp_max_attack": 5447, "sp_max_defense": 7355, "sp_max_mobility": 5458, "sp_max_movement": 4}','{"unit_id": 1060001300, "unit_ssp_initial_release_set_id": 1060001300, "unit_ssp_custom_core_group_id": 1060001300, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 106000130001, "unit_ssp_custom_core_group_id": 1060001300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000130001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000130001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000130001, "weapon_change": {"id": 106000130001, "before_weapon_id": 0, "after_weapon_id": 106000130090, "weapon": {"id": 106000130090, "name": "90mm機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000130090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000130090, "weapon_status": {"id": 106000130090, "range_min": 1, "range_max": 4, "power": 4500, "e