INSERT OR REPLACE INTO "units" VALUES(1060001410,'格鲁古古M (指挥官用)','盖古克M (指挥官机)',4,1,2,0,'10000000006000010','600','g0600u01400','MS-14Fs',1,1,1,1,8360,89,1056,792,835,4,60192,254,7604,5703,6324,4,60876,257,7690,5768,6396,4,3,1,3,1,2,'以自护公国于一年战争末期开发的盖古克海军登陆部队特装机「盖古克M」进行改装，提供给指挥官用的机体。
相较于标准机体，特征是头部增设指挥官用的刀型天线与火神砲，并为了提升机体性能增设主要推进器，强化增装燃料槽装备上限数量等等。
此为「达拉斯舰队」中唯一持有专用「大型镭射步枪」的机体，且相较于标准机体使用的钉盾，此机体的防御兵器装备是专用的盾牌。
另外，由于此机体仅运用于作为海军登陆部队的丝玛舰队上，所以实质上就是舰队司令官「丝玛‧加拉豪」的专用机。','{"id": 1060001410, "hp": 8360, "en": 89, "attack": 1056, "defense": 792, "mobility": 835, "movement": 4, "max_hp": 60192, "max_en": 254, "max_attack": 7604, "max_defense": 5703, "max_mobility": 6324, "max_movement": 4, "sp_hp": 8455, "sp_en": 90, "sp_attack": 1068, "sp_defense": 801, "sp_mobility": 844, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 257, "sp_max_attack": 7690, "sp_max_defense": 5768, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1060001410, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1060001410, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 106000141001, "unit_ssp_custom_core_group_id": 1060001410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000141001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000141001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000141001, "weapon_change": {"id": 106000141001, "before_weapon_id": 0, "after_weapon_id": 106000141090, "weapon": {"id": 106000141090, "name": "專用大型鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000141090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000141090, "weapon_status": {"id": 106000141090, "range_min": 2, "range_max": 4, "powe