INSERT OR REPLACE INTO "units" VALUES(1060001600,'特拉杰','多拉杰',2,3,5,0,'10000000006000010','600','g0600u01600','MS-21C',1,1,1,1,5827,72,650,582,721,4,41952,215,4679,4184,5189,4,57442,294,6406,5729,7105,4,3,1,1,1,1,'自护残党达拉斯舰队以「渣古ⅡF2型」的身体零件为基底，加以组装宇宙高速战斗重轰炸机「卡托尔」的零件所生产出的量产型MS。
由于是宇宙战斗用，直接省略脚部，取而代之的是增装燃料槽，但以AMBAC组件而言还是比不上MS，为弥补这一点，双肩装设控制姿势用推进䇲。
因省略MS中故障率最高且消耗性零件也多的脚部组件，整备率和运用成本异常优秀。
此外，在「达拉斯纷争」后仍能确认回收到机体，故耐用年数也是值得一提。','{"id": 1060001600, "hp": 5827, "en": 72, "attack": 650, "defense": 582, "mobility": 721, "movement": 4, "max_hp": 41952, "max_en": 215, "max_attack": 4679, "max_defense": 4184, "max_mobility": 5189, "max_movement": 4, "sp_hp": 7978, "sp_en": 98, "sp_attack": 890, "sp_defense": 796, "sp_mobility": 987, "sp_movement": 4, "sp_max_hp": 57442, "sp_max_en": 294, "sp_max_attack": 6406, "sp_max_defense": 5729, "sp_max_mobility": 7105, "sp_max_movement": 4}','{"unit_id": 1060001600, "unit_ssp_initial_release_set_id": 1060001600, "unit_ssp_custom_core_group_id": 1060001600, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 106000160001, "unit_ssp_custom_core_group_id": 1060001600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000160001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000160001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000160001, "weapon_change": {"id": 106000160001, "before_weapon_id": 0, "after_weapon_id": 106000160090, "weapon": {"id": 106000160090, "name": "3連40ｍｍ火神砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000160090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000160090, "weapon_status": {"id": 106000160090, "range_min": 1, "range_max": 5, "power": 4500, 