INSERT OR REPLACE INTO "units" VALUES(1060001700,'瓦尔·瓦罗','巴尔‧巴洛',4,2,5,0,'10000000006000010','600','g0600u01700','MA-06',1,2,1,1,10463,68,860,800,760,4,75330,228,6190,5760,4896,4,83804,254,6887,6408,5447,4,3,1,1,1,1,'自护公国于一年战争末期所开发的宇宙战用MA，以过去MA获得的资料为基础，搭载内藏式「大型米加粒子砲」与特殊武器「等离子电磁场」等各式各样的武装，可说是自护公国集大成的MA机体。
相较于重视对舰攻击的原基底「宇宙魔蟹」，此机体的特征在于同时考量对MS战斗，除了坚硬装甲外还具备超高机动性，获得综合来说非常高的战斗能力。
一年战争结束后，原自护公国驾驶员「凯利‧雷兹纳」将机体藏在冯‧布朗市，并加以修理以期能参加「达拉斯舰队」。','{"id": 1060001700, "hp": 10463, "en": 68, "attack": 860, "defense": 800, "mobility": 760, "movement": 4, "max_hp": 75330, "max_en": 228, "max_attack": 6190, "max_defense": 5760, "max_mobility": 4896, "max_movement": 4, "sp_hp": 11640, "sp_en": 76, "sp_attack": 957, "sp_defense": 890, "sp_mobility": 846, "sp_movement": 4, "sp_max_hp": 83804, "sp_max_en": 254, "sp_max_attack": 6887, "sp_max_defense": 6408, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1060001700, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1060001700, "unit_ssp_add_status_id": 100005, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100005, "ssp_hp": 298, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 23, "ssp_mobility": 22, "ssp_max_hp": 5950, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 458, "ssp_max_mobility": 435}, "cores": [{"id": 106000170001, "unit_ssp_custom_core_group_id": 1060001700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000170001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000170001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000170001, "weapon_change": {"id": 106000170001, "before_weapon_id": 0, "after_weapon_id": 106000170090, "weapon": {"id": 106000170090, "name": "大型米加粒子砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000170090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000170090, "weapon_status": {"id": 106000170090, "range_min": 3, "range_max": 4, "powe