INSERT OR REPLACE INTO "units" VALUES(1060001800,'露维·捷露','露维‧捷露',4,2,5,0,'10000000006000010','600','g0600u01800','AMA-002',1,2,1,1,9980,68,912,845,723,5,71856,216,6567,6079,4914,5,79940,240,7306,6763,5466,5,3,1,1,1,1,'阿古捷斯运用当时最新锐技术独家开发的宇宙用攻击型巨大MA。
全身装备有高输出的推进器与强力的镭射兵器，手臂采用非新人类也能操纵且可发动全方位攻击的「有线式线控钩爪臂」，更搭载特殊防御装置「I力场发生器」作为防御兵器，可不受镭射兵器攻击。
此机体压倒性的战斗能力可说是绝强，但带给驾驶员的负担也是极大，想引出机体的性能需要有相当程度的实力。
于「达拉斯纷争」时作为星尘作战的饯行礼，由阿古捷斯先遣舰队转让给予「达拉斯舰队」，成为别名「所罗门恶梦」的「亚纳比路‧贾图」的座机，与地球联邦舰队展开激战。','{"id": 1060001800, "hp": 9980, "en": 68, "attack": 912, "defense": 845, "mobility": 723, "movement": 5, "max_hp": 71856, "max_en": 216, "max_attack": 6567, "max_defense": 6079, "max_mobility": 4914, "max_movement": 5, "sp_hp": 11103, "sp_en": 76, "sp_attack": 1015, "sp_defense": 940, "sp_mobility": 804, "sp_movement": 5, "sp_max_hp": 79940, "sp_max_en": 240, "sp_max_attack": 7306, "sp_max_defense": 6763, "sp_max_mobility": 5466, "sp_max_movement": 5}','{"unit_id": 1060001800, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1060001800, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 106000180001, "unit_ssp_custom_core_group_id": 1060001800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000180001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000180001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000180001, "weapon_change": {"id": 106000180001, "before_weapon_id": 0, "after_weapon_id": 106000180090, "weapon": {"id": 106000180090, "name": "偏向米加粒子砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000180090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290095, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000180090, "weapon_status": {"id": 106000180090, "range_min":