INSERT OR REPLACE INTO "units" VALUES(1060001850,'露维·捷露 (EX)','露维‧捷露 (EX)',5,1,44,0,'10000000006000010','600','g0600u01850','AMA-002',1,2,1,1,9955,101,1143,959,906,5,71676,271,8229,6902,7241,5,71676,271,8229,6902,7241,5,3,2,1,1,1,'阿古捷斯运用当时最新锐技术独家开发的宇宙用攻击型巨大MA。
全身装备有高输出的推进器与强力的镭射兵器，手臂采用非新人类也能操纵且可发动全方位攻击的「有线式线控钩爪臂」，更搭载特殊防御装置「I力场发生器」作为防御兵器，可不受镭射兵器攻击。
此机体压倒性的战斗能力可说是绝强，但带给驾驶员的负担也是极大，想引出机体的性能需要有相当程度的实力。
于「达拉斯纷争」时作为星尘作战的饯行礼，由阿古捷斯先遣舰队转让给予「达拉斯舰队」，成为别名「所罗门恶梦」的「亚纳比路‧贾图」的座机，与地球联邦舰队展开激战。','{"id": 1060001850, "hp": 9955, "en": 101, "attack": 1143, "defense": 959, "mobility": 906, "movement": 5, "max_hp": 71676, "max_en": 271, "max_attack": 8229, "max_defense": 6902, "max_mobility": 7241, "max_movement": 5, "sp_hp": 9955, "sp_en": 101, "sp_attack": 1143, "sp_defense": 959, "sp_mobility": 906, "sp_movement": 5, "sp_max_hp": 71676, "sp_max_en": 271, "sp_max_attack": 8229, "sp_max_defense": 6902, "sp_max_mobility": 7241, "sp_max_movement": 5}','null','露維‧捷露 (EX)','scrape',1791488368,'v2026.10.08',1060001503);
INSERT OR REPLACE INTO "units" VALUES(1060001900,'吉姆改','吉姆改',1,2,2,0,'10000000006000010','600','g0600u01900','RGM-79C',1,1,1,1,6873,51,510,690,603,4,49482,180,3672,4968,3687,4,73398,267,5447,7370,5469,4,3,1,3,1,2,'一年战争末期量产的联邦军泛用量产型MS，针对「吉姆」后期生产型提升各种输出并进行基本改装而成，是联邦军添加当时新锐技术所开发的暂订主力机体。
更因为此机体得到战争时MS运用资料的反馈，成为机动性与运动性能比一般吉姆提升许多的高性能机，因此为生产知识的确立带来巨大的贡献，成为往后联邦各系MS的基础。
U.C.0083时期在地球的特灵顿基地多有配备，参加了「达拉斯纷争」之战。','{"id": 1060001900, "hp": 6873, "en": 51, "attack": 510, "defense": 690, "mobility": 603, "movement": 4, "max_hp": 49482, "max_en": 180, "max_attack": 3672, "max_defense": 4968, "max_mobility": 3687, "max_movement": 4, "sp_hp": 10195, "sp_en": 76, "sp_attack": 757, "sp_defense": 1024, "sp_mobility": 894, "sp_movement": 4, "sp_max_hp": 73398, "sp_max_en": 267, "sp_max_attack": 5447, "sp_max_defense": 7370, "sp_max_mobility": 5469, "sp_max_movement": 4}','{"unit_id": 1060001900, "unit_ssp_initial_release_set_id": 1060001900, "unit_ssp_custom_core_group_id": 1060001900, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 106000190001, "unit_ssp_custom_core_group_id": 1060001900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000190001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000190001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000190001, "weapon_change": {"id": 106000190001, "before_weapon_id": 0, "after_weapon_id": 106000190090, "weapon": {"id": 106000190090, "name": "犢牛式機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000190090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000190090, "weapon_status": {"id": 106000190090, "range_min": 1, "range_max": 4, "power": 4500,