INSERT OR REPLACE INTO "units" VALUES(1060002010,'渣古ⅡF2型(诺渊·比达机)','渣古ⅡF2型 (诺恩‧比达机)',3,2,2,0,'10000000006000010','600','g0600u02000','MS-06F-2',1,1,1,1,9357,64,638,790,752,4,67365,223,4590,5682,4600,4,79940,265,5447,6742,5458,4,3,1,3,1,2,'一年战争时期由自护公国开发的量产型MS「渣古Ⅱ」，其衍生机种中号称泛用性最高的「F型」的后期量产型，是参照了登陆地球作战后实际运作资料的机体。
设计上的变更点以改善初期为人诟病的胸部装甲强度为主，包括外观在内与和其他同系机体的差异都是最大的。除此之外更轻量化机体并提升推进器推力，实现强化机动性的基本理念。
本机体为金巴莱多基地司令「诺恩‧比达」的特装专用机，除变更涂装配色并在头部设置代表指挥官机的刀型天线外，背包还增设了火箭推进器，与联邦军阿尔比昂队交战时展现了惊人的跳跃力。','{"id": 1060002010, "hp": 9357, "en": 64, "attack": 638, "defense": 790, "mobility": 752, "movement": 4, "max_hp": 67365, "max_en": 223, "max_attack": 4590, "max_defense": 5682, "max_mobility": 4600, "max_movement": 4, "sp_hp": 11103, "sp_en": 75, "sp_attack": 757, "sp_defense": 937, "sp_mobility": 892, "sp_movement": 4, "sp_max_hp": 79940, "sp_max_en": 265, "sp_max_attack": 5447, "sp_max_defense": 6742, "sp_max_mobility": 5458, "sp_max_movement": 4}','{"unit_id": 1060002010, "unit_ssp_initial_release_set_id": 1060002010, "unit_ssp_custom_core_group_id": 1060002010, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 106000201001, "unit_ssp_custom_core_group_id": 1060002010, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000201001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000201001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000201001, "weapon_change": {"id": 106000201001, "before_weapon_id": 0, "after_weapon_id": 106000201090, "weapon": {"id": 106000201090, "name": "渣古機槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000201090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000201090, "weapon_status": {"id": 106000201090,