INSERT OR REPLACE INTO "units" VALUES(1060002200,'渣古ⅡF2型','渣古ⅡF2型',1,1,2,0,'10000000006000010','600','g0600u02200','MS-06F-2',1,1,1,1,5433,60,690,568,599,4,39114,180,4968,4088,4312,4,58019,267,7370,6064,6396,4,3,1,3,1,2,'一年战争时期由自护公国开发的量产型MS「渣古Ⅱ」，其衍生机种中号称泛用性最高的「Ｆ型」后期量产型，是反映过地球降下作战后实际运作资料的机体。
设计上的变更点以改善初期为人诟病的胸部装甲强度为主，与和其他同系机体的差异包括外观在内都是最大的，除此之外更轻量化机体并提升推进器推力，实现强化机动性的基本理念。
此机体由于具备重力环境下的优秀适应力，操纵也比既有机体简单，被视为可在将近无改造的状况下投入标准军事行动。
但实际运用上由于自护公国的直线式领导结构及补给路线截断等种种因素，仅偏重配备于失陷后的所罗门周边宙域以及非洲战线等地。','{"id": 1060002200, "hp": 5433, "en": 60, "attack": 690, "defense": 568, "mobility": 599, "movement": 4, "max_hp": 39114, "max_en": 180, "max_attack": 4968, "max_defense": 4088, "max_mobility": 4312, "max_movement": 4, "sp_hp": 8059, "sp_en": 89, "sp_attack": 1024, "sp_defense": 843, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 58019, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6064, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1060002200, "unit_ssp_initial_release_set_id": 1060002200, "unit_ssp_custom_core_group_id": 1060002200, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 106000220001, "unit_ssp_custom_core_group_id": 1060002200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000220001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000220001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000220001, "weapon_change": {"id": 106000220001, "before_weapon_id": 0, "after_weapon_id": 106000220090, "weapon": {"id": 106000220090, "name": "熱能斧 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000220090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000220090, "weapon_status": {"id": 106000220090, "range_min": 1, "range_max"