INSERT OR REPLACE INTO "units" VALUES(1060002300,'大魔热带型','大魔热带型',2,2,7,0,'10000000006000010','600','g0600u02300','MS-09F/TROP',1,1,1,1,8125,55,609,683,650,4,58500,194,4384,4914,3978,4,80100,265,6003,6729,5447,4,1,1,3,3,2,'自护公国以「大魔热带型」与各种大魔衍生实验机的运用资料为基础，为沙漠与热带等局部战场所开发的大魔型MS衍生机体。
由于主要目的是延长在沙漠的作战行动时间并提升可整备率，脚部的热核能气垫引擎上装备了高性能的防尘过滤器，机体各部位更增设武器挂架，可运用以雷可顿火箭炮及铁拳火箭弹为首的各式武装，提高了泛用性。
此机体主要是以非洲中央为中心派发配备，战后则是袭击特灵顿基地的「达拉斯舰队」等部队在运用。','{"id": 1060002300, "hp": 8125, "en": 55, "attack": 609, "defense": 683, "mobility": 650, "movement": 4, "max_hp": 58500, "max_en": 194, "max_attack": 4384, "max_defense": 4914, "max_mobility": 3978, "max_movement": 4, "sp_hp": 11125, "sp_en": 75, "sp_attack": 834, "sp_defense": 935, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 80100, "sp_max_en": 265, "sp_max_attack": 6003, "sp_max_defense": 6729, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1060002300, "unit_ssp_initial_release_set_id": 1060002300, "unit_ssp_custom_core_group_id": 1060002300, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 106000230001, "unit_ssp_custom_core_group_id": 1060002300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106000230001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106000230001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106000230001, "weapon_change": {"id": 106000230001, "before_weapon_id": 0, "after_weapon_id": 106000230090, "weapon": {"id": 106000230090, "name": "雷可頓火箭炮 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106000230090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106000230090, "weapon_status": {"id": 106000230090, "range_min": 2, "range_max": 4, "power