INSERT OR REPLACE INTO "units" VALUES(1067000110,'高达试做0号机','高达试作0号机',4,2,2,0,'10000000006700010','670','g0670u00100','RX-78GP00',1,1,1,1,10978,75,746,924,886,4,79042,264,5365,6653,5418,4,79940,267,5426,6729,5480,4,3,1,3,1,2,'联邦军与阿纳海姆电子企业共同推行「高达开发计划」，在极机密状况下试作的实验用MS，也是「GP系列」实验阶段的机体。由于实验性要素较多，搭载了各式各样的装备。
机体背面搭载碟形广域感应器「米诺夫斯基粒子干扰波搜索装置」提升索敌效率，武器更是装备了虽然不能连射，但在当时MS中拥有最高级火力的「长距离镭射步枪」，长距离射击性能极高。
此外还有用以进行高速战斗的大型推进器及「核心区块系统」等等，以机动性为目的的装备也相当充实，原本是当时阿纳海姆电子企业投入所有技术，备受期待的万能MS。
但随后发生「一架机体搭载太多机能造成驾驶员负担」这种运用、操纵上的问题，便改变计划以复数机体各自追求不同性能，成为后续开发的「GP系列」。','{"id": 1067000110, "hp": 10978, "en": 75, "attack": 746, "defense": 924, "mobility": 886, "movement": 4, "max_hp": 79042, "max_en": 264, "max_attack": 5365, "max_defense": 6653, "max_mobility": 5418, "max_movement": 4, "sp_hp": 11103, "sp_en": 76, "sp_attack": 754, "sp_defense": 935, "sp_mobility": 896, "sp_movement": 4, "sp_max_hp": 79940, "sp_max_en": 267, "sp_max_attack": 5426, "sp_max_defense": 6729, "sp_max_mobility": 5480, "sp_max_movement": 4}','{"unit_id": 1067000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1067000110, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 106700011001, "unit_ssp_custom_core_group_id": 1067000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 106700011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 106700011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 106700011001, "weapon_change": {"id": 106700011001, "before_weapon_id": 0, "after_weapon_id": 106700011090, "weapon": {"id": 106700011090, "name": "長距離鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 106700011090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 106700011090, "weapon_status": {"id": 106700011090, "range_min": 2, "rang