INSERT OR REPLACE INTO "units" VALUES(1082000110,'零式','零式',4,3,2,0,'10000082008000810','820','g0820u00100','MSZ-000',1,1,1,1,8783,88,932,788,924,5,63234,278,6707,5669,6336,5,63952,281,6783,5733,6408,5,3,1,3,1,2,'过去担任高达开发者提姆‧尼尔助手的技术人员爱德华‧雷文所开发的机体。
首架符合第二世代机体专案标准的机体为力奇‧戴亚，而在开发后续机体的过程中，发起了借由可变结构来大幅强化移动能力的Z计划，却因为加入变形结构的骨架强度问题而导致计划中断，本机依旧保留了地上与宇宙皆能活动的MS此一理念，重新设计为非变形的资料收集机。
比起百式，本机与力奇‧戴亚有更多共通设计，而头部造型也接近Z高达，虽为处处都能窥见Z计划尝试错误过程的实验性机体，但泛用性优秀，尽管防御方面有著不安因素，仍然可以视为第二世代的高性能机体。
作为古华多罗‧巴兹拿的座机，本机与力奇‧戴亚同样刻意采用了令人联想到马沙‧阿兹纳布的红色机身，然而关于本机是否实际存在，众说纷纭，未有定论。','{"id": 1082000110, "hp": 8783, "en": 88, "attack": 932, "defense": 788, "mobility": 924, "movement": 5, "max_hp": 63234, "max_en": 278, "max_attack": 6707, "max_defense": 5669, "max_mobility": 6336, "max_movement": 5, "sp_hp": 8883, "sp_en": 89, "sp_attack": 942, "sp_defense": 797, "sp_mobility": 935, "sp_movement": 5, "sp_max_hp": 63952, "sp_max_en": 281, "sp_max_attack": 6783, "sp_max_defense": 5733, "sp_max_mobility": 6408, "sp_max_movement": 5}','{"unit_id": 1082000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1082000110, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 108200011001, "unit_ssp_custom_core_group_id": 1082000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108200011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108200011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108200011001, "weapon_change": {"id": 108200011001, "before_weapon_id": 0, "after_weapon_id": 108200011090, "weapon": {"id": 108200011090, "name": "踢擊 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108200011090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 230001, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108200011090, "weapon_status": {"id": 108200011090, "range_min": 1, "range_max":