INSERT OR REPLACE INTO "units" VALUES(1083000100,'ZⅡ','ZⅡ',2,3,2,0,'10830080008100950','830','g0830u00100','MSZ-008',1,1,1,1,6175,65,684,617,683,4,44460,205,4924,4438,4680,4,60876,281,6742,6076,6408,4,3,1,3,1,2,'奥干的可变MS「Z高达」的延伸发展机，加入了同为奥干的可变MS「密达斯」的可变构造等，借由简化Z高达复杂的变形构造，提升生产率及操纵性的机体。
虽然简化了变形构造，在WAVERIDER型态时仍维持了傲视其他MS的加速能力。武器方面，由于机体各部的动力炉直接连结能量发射器，其专用装备「米加镭射步枪」所发挥的威力得以与Z高达的「超绝米加巨砲」匹敌，在规格上与同时期的MS群比较起来毫不逊色，量产时在成本效益比上也得到相当高的评价。
但是，当时奥干财政拮据，并且因为优先开发具有多机能性能的可变合体MS「ZZ高达」，实际上并未被量产。
本机体的理念后来由可变量产型MS「里歇尔」所继承。','{"id": 1083000100, "hp": 6175, "en": 65, "attack": 684, "defense": 617, "mobility": 683, "movement": 4, "max_hp": 44460, "max_en": 205, "max_attack": 4924, "max_defense": 4438, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8455, "sp_en": 89, "sp_attack": 937, "sp_defense": 844, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 281, "sp_max_attack": 6742, "sp_max_defense": 6076, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1083000100, "unit_ssp_initial_release_set_id": 1083000100, "unit_ssp_custom_core_group_id": 1083000100, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 108300010001, "unit_ssp_custom_core_group_id": 1083000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108300010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108300010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108300010001, "weapon_change": {"id": 108300010001, "before_weapon_id": 0, "after_weapon_id": 108300010090, "weapon": {"id": 108300010090, "name": "米加鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108300010090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108300010090, "weapon_status": {"id": 108300010090, "range_min": 2, "range_max": 5, "power": 4800, "en": 60, "h