INSERT OR REPLACE INTO "units" VALUES(1083000400,'百式改','百式改',3,1,2,0,'10830080008100950','830','g0830u00400','MSR-00100S',1,1,1,1,7056,70,805,593,698,5,50804,210,5796,4267,5020,5,64593,267,7370,5426,6383,5,3,1,3,1,2,'奥干的MS「百式」的延伸发展机，是以轻量化与提升推进力为目的所开发的机体。
将百式的飞翼支架装备型背包变更为圆筒型偏向推进器与增加力矩型高机动喷射平衡翼，以提升运动性能与机动性。
武器方面，脉冲激光砲与镭射格林机砲等利用了肩部支撑点的固定武器亦相当充实，具有重视攻击力与扩充性的傲人性能。','{"id": 1083000400, "hp": 7056, "en": 70, "attack": 805, "defense": 593, "mobility": 698, "movement": 5, "max_hp": 50804, "max_en": 210, "max_attack": 5796, "max_defense": 4267, "max_mobility": 5020, "max_movement": 5, "sp_hp": 8972, "sp_en": 89, "sp_attack": 1024, "sp_defense": 754, "sp_mobility": 887, "sp_movement": 5, "sp_max_hp": 64593, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 5426, "sp_max_mobility": 6383, "sp_max_movement": 5}','{"unit_id": 1083000400, "unit_ssp_initial_release_set_id": 1083000400, "unit_ssp_custom_core_group_id": 1083000400, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 108300040001, "unit_ssp_custom_core_group_id": 1083000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108300040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108300040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108300040001, "weapon_change": {"id": 108300040001, "before_weapon_id": 0, "after_weapon_id": 108300040090, "weapon": {"id": 108300040090, "name": "脈衝激光砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108300040090, "attack_attr": 1, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110004, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108300040090, "weapon_status": {"id": 108300040090, "range_min": 2, "range_max": 5