INSERT OR REPLACE INTO "units" VALUES(1083000510,'高达Mk-Ⅲ','高达Mk-Ⅲ',4,2,2,0,'10830080008100950','830','g0830u00500','MSF-007',1,1,1,1,11440,75,797,880,831,4,82368,251,5737,6336,5354,4,83304,254,5802,6408,5415,4,3,1,3,1,2,'奥干解析于绿色诺亚1强行掠夺而来的泰坦斯的MS「高达Mk-Ⅱ」后，由阿纳海姆电子公司以该资料为基础独家开发的机体。
本机体将高达Mk-Ⅱ的可动骨架技术更进一步，导入高达琉姆合金γ（伽马），并同时采用奥干的独家技术，重现更接近人体的动态。此外，因重新制作动力炉与各种武器，获得了超越高达Mk-Ⅱ的性能。','{"id": 1083000510, "hp": 11440, "en": 75, "attack": 797, "defense": 880, "mobility": 831, "movement": 4, "max_hp": 82368, "max_en": 251, "max_attack": 5737, "max_defense": 6336, "max_mobility": 5354, "max_movement": 4, "sp_hp": 11570, "sp_en": 76, "sp_attack": 806, "sp_defense": 890, "sp_mobility": 841, "sp_movement": 4, "sp_max_hp": 83304, "sp_max_en": 254, "sp_max_attack": 5802, "sp_max_defense": 6408, "sp_max_mobility": 5415, "sp_max_movement": 4}','{"unit_id": 1083000510, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1083000510, "unit_ssp_add_status_id": 100005, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100005, "ssp_hp": 298, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 23, "ssp_mobility": 22, "ssp_max_hp": 5950, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 458, "ssp_max_mobility": 435}, "cores": [{"id": 108300051001, "unit_ssp_custom_core_group_id": 1083000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108300051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108300051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108300051001, "weapon_change": {"id": 108300051001, "before_weapon_id": 0, "after_weapon_id": 108300051090, "weapon": {"id": 108300051090, "name": "鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108300051090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108300051090, "weapon_status": {"id": 108300051090, "