INSERT OR REPLACE INTO "units" VALUES(1083000610,'尼摩Ⅲ','雷姆Ⅲ',2,1,2,0,'10830080008100950','830','g0830u00600','MSA-004K',1,1,1,1,6958,70,805,599,700,4,50098,210,5796,4310,5040,4,63696,267,7370,5480,6408,4,3,1,3,1,2,'为了弥补奥干的量产型MS「雷姆」缺乏火力的问题而开发的机体。
虽然最初曾为了改善缺乏力量的问题而以提升动力炉的输出为目的开发「雷姆Ⅱ」，但未能解决问题，最终以雷姆Ⅱ为基底，搭载镭射加农成为支援用MS。虽未提升动力炉的输出，但亦成功强化了火力。','{"id": 1083000610, "hp": 6958, "en": 70, "attack": 805, "defense": 599, "mobility": 700, "movement": 4, "max_hp": 50098, "max_en": 210, "max_attack": 5796, "max_defense": 4310, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8847, "sp_en": 89, "sp_attack": 1024, "sp_defense": 762, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 63696, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 5480, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1083000610, "unit_ssp_initial_release_set_id": 1083000610, "unit_ssp_custom_core_group_id": 1083000610, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 108300061001, "unit_ssp_custom_core_group_id": 1083000610, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108300061001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108300061001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108300061001, "weapon_change": {"id": 108300061001, "before_weapon_id": 0, "after_weapon_id": 108300061090, "weapon": {"id": 108300061090, "name": "鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108300061090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108300061090, "weapon_status": {"id": 108300061