INSERT OR REPLACE INTO "units" VALUES(1084000110,'Z高达3号机','Z高达3号机',4,3,2,0,'10000084008000810','840','g0840u00100','MSZ-006-3',1,1,1,1,8344,88,924,833,930,4,60072,278,6653,5996,6375,4,60755,281,6729,6064,6447,4,3,1,3,1,2,'阿纳海姆电子公司针对正在研讨购入用于大气层中的主力可变MS的卡拉巴所建造的Z高达系统机体。
由于原本便是以拥有傲人的高泛用性的Z高达为基底，藉著变形为WAVERIDER型态，除了提升机动性与具备单机冲入大气层的能力，还可作为「SFS（辅助飞行系统）」运用，在与友机的联合行动上发挥优秀的能力。
并且藉著装备配合卡拉巴的订单所准备的选配推进器，可增加航行距离与缩短抵达作战区域的时间，能于所需的最少时间内抵达地球上各区域。
此外，3号机之名并非所生产的第3架机体之意，而是表示机体规格的号码。','{"id": 1084000110, "hp": 8344, "en": 88, "attack": 924, "defense": 833, "mobility": 930, "movement": 4, "max_hp": 60072, "max_en": 278, "max_attack": 6653, "max_defense": 5996, "max_mobility": 6375, "max_movement": 4, "sp_hp": 8439, "sp_en": 89, "sp_attack": 935, "sp_defense": 843, "sp_mobility": 941, "sp_movement": 4, "sp_max_hp": 60755, "sp_max_en": 281, "sp_max_attack": 6729, "sp_max_defense": 6064, "sp_max_mobility": 6447, "sp_max_movement": 4}','{"unit_id": 1084000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1084000110, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 108400011001, "unit_ssp_custom_core_group_id": 1084000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 108400011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 108400011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 108400011001, "weapon_change": {"id": 108400011001, "before_weapon_id": 0, "after_weapon_id": 108400011090, "weapon": {"id": 108400011090, "name": "超絕米加巨砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 108400011090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 108400011090, "weapon_status": {"id": 108400011090, "range_min": 3, "range_max": 5, "power": 4800, "en": 60, "h