INSERT OR REPLACE INTO "units" VALUES(1098000510,'高机动型渣古Ⅱ (阿纳贝尔·卡多专用)','高机动型渣古Ⅱ (亚纳比路‧贾图专用)',3,1,8,0,'10000000009800010','980','g0980u00500','MS-06R-1A',1,1,1,1,7485,75,868,637,749,4,53892,225,6248,4581,5390,4,63952,267,7414,5436,6396,4,3,1,2,1,2,'一年战争时期自护公国开发的「渣古Ⅱ」衍生机之一，是改良被认为续航力不高的「MS-06R-1」而成的机体。
R型因为性能好，深受许多王牌驾驶员欢迎，但由于运行条件复杂，成本也高，没有像F型那样大量生产，也非常难被分配到。
本机体属其中之一，机体全涂装成别称「所罗门的恶梦」的「亚纳比路‧贾图」的个人喜好配色，为其专用机。','{"id": 1098000510, "hp": 7485, "en": 75, "attack": 868, "defense": 637, "mobility": 749, "movement": 4, "max_hp": 53892, "max_en": 225, "max_attack": 6248, "max_defense": 4581, "max_mobility": 5390, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 1030, "sp_defense": 755, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 267, "sp_max_attack": 7414, "sp_max_defense": 5436, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1098000510, "unit_ssp_initial_release_set_id": 1098000510, "unit_ssp_custom_core_group_id": 1098000510, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 109800051001, "unit_ssp_custom_core_group_id": 1098000510, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 109800051001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 109800051001, "sort_order": 1, "release_function_type_index": 5, "target_id": 109800051001, "weapon_change": {"id": 109800051001, "before_weapon_id": 0, "after_weapon_id": 109800051090, "weapon": {"id": 109800051090, "name": "渣古火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 109800051090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 109800051090, "weapon_status": {"id": 109800051090, "range_min": 2, "range_max": 4, "po