INSERT OR REPLACE INTO "units" VALUES(1098000700,'强人·厄俄斯','泛用试作型强人',4,2,2,0,'10000000009800010','980','g0980u00700','YMS-15E',1,1,1,1,9237,68,747,919,800,4,66505,240,5376,6611,4896,4,73987,267,5981,7355,5447,4,3,1,3,1,2,'以自护公国的泛用试作型MS「强人」为基底，在ZIMMAD与自护尼克企业联手合作下，改造成配备于实战的机体。
本机体主要针对提升空间机动性能及重新审视武器来进行修改。
借由移除内藏于专用盾牌的飞弹发射系统与更换装甲材料，进而提高短兵交战时的防御力，特征武器更采用前端能作为镭射军刀使用的枪剑型试作武器「镭射刺刀」来增强火力。
完成的两架试作机被投入自护公国突击机动军的旗舰护卫部队参与实战，但并未量产。','{"id": 1098000700, "hp": 9237, "en": 68, "attack": 747, "defense": 919, "mobility": 800, "movement": 4, "max_hp": 66505, "max_en": 240, "max_attack": 5376, "max_defense": 6611, "max_mobility": 4896, "max_movement": 4, "sp_hp": 10276, "sp_en": 76, "sp_attack": 831, "sp_defense": 1022, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 73987, "sp_max_en": 267, "sp_max_attack": 5981, "sp_max_defense": 7355, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1098000700, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1098000700, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 109800070001, "unit_ssp_custom_core_group_id": 1098000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 109800070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 109800070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 109800070001, "weapon_change": {"id": 109800070001, "before_weapon_id": 0, "after_weapon_id": 109800070090, "weapon": {"id": 109800070090, "name": "鐳射刺刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 109800070090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 270003, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 109800070090, "weapon_status": {"id": 109800070090, "range_min": 1, "range_max": 2, "power": 4650, "en": 58,