INSERT OR REPLACE INTO "units" VALUES(1098000800,'月神坦克','月神坦克',2,3,26,0,'10000000009800010','980','g0980u00800','G87',1,1,1,1,6487,65,617,653,683,4,46707,205,4438,4699,4680,4,63952,281,6076,6434,6408,4,3,1,2,1,1,'自护公国为了确保月球战力，开发用作MS辅助兵器的重机动砲台。通常是以履带配件移动，但战斗时能使用机体下方的火箭引擎飞行。
虽是特殊机体，但具有可以活用主要武器2连装实弹砲的机动性，因而被配备至格拉那达基地充当移动砲台用以防卫。
然而，使用履带配件的移动能力非常差，利用火箭引擎飞行的时间也很短暂等缺点，所以自护公国以问题繁多的本机体为基底，著手开发重型机动砲座「亚札姆」。','{"id": 1098000800, "hp": 6487, "en": 65, "attack": 617, "defense": 653, "mobility": 683, "movement": 4, "max_hp": 46707, "max_en": 205, "max_attack": 4438, "max_defense": 4699, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 844, "sp_defense": 894, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 281, "sp_max_attack": 6076, "sp_max_defense": 6434, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1098000800, "unit_ssp_initial_release_set_id": 1098000800, "unit_ssp_custom_core_group_id": 1098000800, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 109800080001, "unit_ssp_custom_core_group_id": 1098000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 109800080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 109800080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 109800080001, "weapon_change": {"id": 109800080001, "before_weapon_id": 0, "after_weapon_id": 109800080090, "weapon": {"id": 109800080090, "name": "2連裝實彈砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 109800080090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 109800080090, "weapon_status": {"id": 109800080090, "range_min":