INSERT OR REPLACE INTO "units" VALUES(1098001000,'毕格·路夫','比格‧和夫',2,1,5,0,'10000000009800010','980','g0980u01000','MA-05R',1,1,1,1,6500,66,747,619,584,4,46800,178,5372,4455,4671,4,64080,243,7355,6100,6396,4,3,1,1,1,1,'自护公国将宇宙用量产型MA「宇宙魔蟹」改造成对舰攻击用的强攻型机体，在机体下方装设全长超过100m的「大型飞弹」，并为了弥补因机体重量增加导致推进力不足的问题，追加了两座推进器，因此具备可以使用一击脱离战术的机动性，具有可以在舰队战打先锋，给与敌方舰队痛击的傲人性能。
然而，由于追加的装备增加了机体重量，因此在高速行进时的姿势控制需要驾驶员高超的操纵技术，是架独特的机体。','{"id": 1098001000, "hp": 6500, "en": 66, "attack": 747, "defense": 619, "mobility": 584, "movement": 4, "max_hp": 46800, "max_en": 178, "max_attack": 5372, "max_defense": 4455, "max_mobility": 4671, "max_movement": 4, "sp_hp": 8900, "sp_en": 90, "sp_attack": 1022, "sp_defense": 848, "sp_mobility": 800, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 243, "sp_max_attack": 7355, "sp_max_defense": 6100, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1098001000, "unit_ssp_initial_release_set_id": 1098001000, "unit_ssp_custom_core_group_id": 1098001000, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 109800100001, "unit_ssp_custom_core_group_id": 1098001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 109800100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 109800100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 109800100001, "weapon_change": {"id": 109800100001, "before_weapon_id": 0, "after_weapon_id": 109800100090, "weapon": {"id": 109800100090, "name": "大型飛彈 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 109800100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290028, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 109800100090, "weapon_status": {"id": 109800100090, "range_min": 2, "range_max": 4, "