INSERT OR REPLACE INTO "units" VALUES(1114000100,'Hi-ν高达','Hi-ν高达',4,2,2,0,'10000000011401100','1140','g1140u00100','RX-93-ν2',1,1,1,1,9182,69,763,917,724,5,66108,218,5492,6603,4918,5,73545,242,6110,7345,5471,5,3,1,3,1,2,'配备至解决第二次新自护战争的联邦军外围新兴部队「隆巴纳」的新人类专用MS，原本是亚纳海姆电子公司的冯‧布朗工厂开发的新型MS，后来由隆巴纳的指挥官「布拉度‧诺亚」筹备而成的机体。
基础设计采用升级历代高达型的平均值来作为标准设计，重视信赖度、耐久性及整备效率，挪出的空间则将自新生新自护军MS「精神感应德卡」中掳获的划时代新材料「精神感应框体」配置于驾驶舱周遭，内藏具备基础脑波传导功能的电脑晶片，借此确实操纵新人类专用的特殊武装「翼状感应砲」。
甚至能够发动3台以上的翼状感应砲来作为「I力场发生器」，使镭射武器无效化等，拥有攻防一体的高性能脑波传导型兵器，且为高达型首架完整配备的新人类专用机。','{"id": 1114000100, "hp": 9182, "en": 69, "attack": 763, "defense": 917, "mobility": 724, "movement": 5, "max_hp": 66108, "max_en": 218, "max_attack": 5492, "max_defense": 6603, "max_mobility": 4918, "max_movement": 5, "sp_hp": 10215, "sp_en": 77, "sp_attack": 849, "sp_defense": 1021, "sp_mobility": 805, "sp_movement": 5, "sp_max_hp": 73545, "sp_max_en": 242, "sp_max_attack": 6110, "sp_max_defense": 7345, "sp_max_mobility": 5471, "sp_max_movement": 5}','{"unit_id": 1114000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1114000100, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 111400010001, "unit_ssp_custom_core_group_id": 1114000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 111400010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 111400010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 111400010001, "weapon_change": {"id": 111400010001, "before_weapon_id": 0, "after_weapon_id": 111400010090, "weapon": {"id": 111400010090, "name": "翼狀感應砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 111400010090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340022, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 111400010090, "weapon_status": {"id": 111400010090, "range_min": 2, "