INSERT OR REPLACE INTO "units" VALUES(1114000450,'ν高达(双翼状感应炮装备型) (EX)','ν高达(双翼状感应砲装备型) (EX)',5,2,2,0,'10000000011401100','1140','g1140u00450','RX-93',1,1,1,1,10960,85,901,1208,955,5,78907,285,6485,8696,6151,5,78907,285,6485,8696,6151,5,3,1,3,1,2,'一年战争中威名远播的「阿宝‧尼尔」亲自设计的联邦军新人类专用试作型MS「ν高达」的试作案之一，背部搭载新人类专用的特殊兵器「翼状感应砲」，且借由左右均分感应砲来改善重量偏重左侧背包的问题，即便发射所有翼状感应砲也能保持ν高达的机动性，并发挥高度性能。','{"id": 1114000450, "hp": 10960, "en": 85, "attack": 901, "defense": 1208, "mobility": 955, "movement": 5, "max_hp": 78907, "max_en": 285, "max_attack": 6485, "max_defense": 8696, "max_mobility": 6151, "max_movement": 5, "sp_hp": 10960, "sp_en": 85, "sp_attack": 901, "sp_defense": 1208, "sp_mobility": 955, "sp_movement": 5, "sp_max_hp": 78907, "sp_max_en": 285, "sp_max_attack": 6485, "sp_max_defense": 8696, "sp_max_mobility": 6151, "sp_max_movement": 5}','null','ν高達(雙翼狀感應砲裝備型) (EX)','scrape',1791488368,'v2026.10.08',1110000103);
INSERT OR REPLACE INTO "units" VALUES(1114000600,'灵格斯特装型','灵格斯特装型',3,1,2,0,'10000000011401100','1140','g1140u00600','RGZ-91B',1,1,1,1,7056,70,804,594,698,4,50804,210,5785,4276,5020,4,64593,267,7355,5436,6383,4,3,1,3,1,2,'将联邦军的简易变形型MS「灵格斯」重新设计为供联邦军外围新兴部队「隆巴纳」的王牌驾驶员「阿宝‧尼尔」使用的专用机而开发的机体。
借由为了量产所开发的简易变形系统「BWS（背部武器系统）」与背包的一体化，得以不用移除BWS也能单独变形，甚至采用V字型的额部天线，强化侦测功能，因此连外观也几乎重拾Z高达原型机的概念，综合性能也有所提升。','{"id": 1114000600, "hp": 7056, "en": 70, "attack": 804, "defense": 594, "mobility": 698, "movement": 4, "max_hp": 50804, "max_en": 210, "max_attack": 5785, "max_defense": 4276, "max_mobility": 5020, "max_movement": 4, "sp_hp": 8972, "sp_en": 89, "sp_attack": 1022, "sp_defense": 755, "sp_mobility": 887, "sp_movement": 4, "sp_max_hp": 64593, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 5436, "sp_max_mobility": 6383, "sp_max_movement": 4}','{"unit_id": 1114000600, "unit_ssp_initial_release_set_id": 1114000600, "unit_ssp_custom_core_group_id": 1114000600, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 111400060001, "unit_ssp_custom_core_group_id": 1114000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 111400060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 111400060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 111400060001, "weapon_change": {"id": 111400060001, "before_weapon_id": 0, "after_weapon_id": 111400060090, "weapon": {"id": 111400060090, "name": "超絕鐳射軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 111400060090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 111400060090, "weapon_status": {