INSERT OR REPLACE INTO "units" VALUES(1114000800,'β·阿吉尔','β‧亚索龙',4,3,5,1,'10000000011401100','1140','g1140u00800','NZ-444',1,2,1,1,9443,95,910,950,996,4,67990,300,6550,6840,6827,4,63696,281,6137,6408,6396,4,3,1,1,1,1,'新生新自护开发的新人类专用超大型试作MA「α‧亚索龙」的延伸发展机，参考了过去开发的所有支援新人类的MA与MS，是加入了各种要素的机体。
相较于全面透过脑波传导的α‧亚索龙，在机体操纵与兵器控制上，由于搭载2连装大型对舰飞弹等不需依赖脑波传导的实弹武器而具有泛用性，也可以透过新人类的精神波远距离诱导无人攻击兵器「感应砲」进行全方位攻击，保有强大火力。
其具特征性的武器是在腹部内藏了直接连接动力炉的「超绝米加粒子砲」，具有连大型战舰都能一击击沉的惊人破坏力。
此外，虽然本机体为α‧亚索龙的延伸发展机，但培育出来的技术参考了许多新生新自护MS「夜莺」的部分，因此说是夜莺的延伸机体也不为过。','{"id": 1114000800, "hp": 9443, "en": 95, "attack": 910, "defense": 950, "mobility": 996, "movement": 4, "max_hp": 67990, "max_en": 300, "max_attack": 6550, "max_defense": 6840, "max_mobility": 6827, "max_movement": 4, "sp_hp": 8847, "sp_en": 89, "sp_attack": 853, "sp_defense": 890, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 63696, "sp_max_en": 281, "sp_max_attack": 6137, "sp_max_defense": 6408, "sp_max_mobility": 6396, "sp_max_movement": 4}','null','β‧亞索龍','scrape',1791488368,'v2026.10.08',NULL);
