INSERT OR REPLACE INTO "units" VALUES(1114000900,'基拉·德卡改','基拉‧德卡改',2,2,2,0,'10000000011401100','1140','g1140u00900','AMS-119S',1,1,1,1,8142,56,619,682,584,4,58617,176,4455,4905,3971,4,80261,241,6100,6715,5436,4,3,1,3,1,2,'以新生新自护开发的泛用量产型MS「基拉‧德卡」为基底，开发成指挥官用高性能机的机体。框体构造直接由装甲材料改为高达琉姆合金，更全面换新航空电子技术，大幅提升操纵性等全体性能。
