INSERT OR REPLACE INTO "units" VALUES(1115000100,'量产型ν高达（incom装备）','量产型ν高达（引导砲装备）',3,3,2,0,'10000000011501100','1150','g1150u00100','RX-94',1,1,1,1,6650,70,731,669,735,4,47880,221,5261,4817,5040,4,60876,281,6689,6125,6408,4,3,1,3,1,2,'联邦军新人类专用试作型MS「ν高达」的量产规格机，是为了用来取代积根而开发的下期主力MS候补之一。
继承ν高达的标准机体结构，以及内藏电脑晶片、具备基础脑波传导机能的划时代新材料「精神感应框体」， 成为在各种层面皆凌驾积根的高性能机。
此外，由于预定一般驾驶员亦能搭乘，因此选择将新人类专用特殊兵器「翼状感应砲」与准脑波传导式远距兵器「引导砲」装备在背部背包，让新人类驾驶员与一般驾驶员皆能驾驶。
为了增强对新生自护军MS的战力，联邦军外围新兴部队「隆巴纳」提出少量生产的开发计划方案，但联邦军并不积极开发新型MS，再加上与新生自护军的战争提早终结，因而被搁置计划。','{"id": 1115000100, "hp": 6650, "en": 70, "attack": 731, "defense": 669, "mobility": 735, "movement": 4, "max_hp": 47880, "max_en": 221, "max_attack": 5261, "max_defense": 4817, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8455, "sp_en": 89, "sp_attack": 929, "sp_defense": 851, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 281, "sp_max_attack": 6689, "sp_max_defense": 6125, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1115000100, "unit_ssp_initial_release_set_id": 1115000100, "unit_ssp_custom_core_group_id": 1115000100, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 111500010001, "unit_ssp_custom_core_group_id": 1115000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 111500010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 111500010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 111500010001, "weapon_change": {"id": 111500010001, "before_weapon_id": 0, "after_weapon_id": 111500010090, "weapon": {"id": 111500010090, "name": "引導砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 111500010090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350016, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 111500010090, "weapon_status": {"id": 111500010090, "ra