INSERT OR REPLACE INTO "units" VALUES(1115000300,'全装甲百式改','全装甲型百式改',4,2,2,0,'11150110008000810','1150','g1150u00300','FA-00100S',1,1,1,1,9247,68,911,924,721,4,66578,216,6555,6649,4898,4,74068,241,7292,7397,5449,4,3,1,3,1,2,'奥干的MS「百式改」上增设复合型装甲的型态，为强化百式改的武装及装甲而开发的机体。
装备许多高输出镭射武器以及实弹武器，也增设崭新设计的装甲与抗镭射防御构造「反射护板」等，具有傲人的攻防性能。
另外，为将重量增加导致的机动性低落控制在最小限度，各部位增设多个推进器，若去除增设装甲，也可以充当一般的百式改来使用。','{"id": 1115000300, "hp": 9247, "en": 68, "attack": 911, "defense": 924, "mobility": 721, "movement": 4, "max_hp": 66578, "max_en": 216, "max_attack": 6555, "max_defense": 6649, "max_mobility": 4898, "max_movement": 4, "sp_hp": 10288, "sp_en": 76, "sp_attack": 1013, "sp_defense": 1028, "sp_mobility": 802, "sp_movement": 4, "sp_max_hp": 74068, "sp_max_en": 241, "sp_max_attack": 7292, "sp_max_defense": 7397, "sp_max_mobility": 5449, "sp_max_movement": 4}','{"unit_id": 1115000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1115000300, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 111500030001, "unit_ssp_custom_core_group_id": 1115000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 111500030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 111500030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 111500030001, "weapon_change": {"id": 111500030001, "before_weapon_id": 0, "after_weapon_id": 111500030090, "weapon": {"id": 111500030090, "name": "長程米加破壞 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 111500030090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 111500030090, "weapon_status": {"id": 111500030090, "range_min": 3, "range_max": 4,