INSERT OR REPLACE INTO "units" VALUES(1115000320,'百式改',NULL,5,1,NULL,0,'11150110008000810','1150','g0830u00400',NULL,1,NULL,0,0,8057,100,925,761,716,5,58009,270,6660,5479,5721,5,58009,270,6660,5479,5721,5,NULL,NULL,NULL,NULL,NULL,NULL,'{"id": 1115000320, "hp": 8057, "en": 100, "attack": 925, "defense": 761, "mobility": 716, "movement": 5, "max_hp": 58009, "max_en": 270, "max_attack": 6660, "max_defense": 5479, "max_mobility": 5721, "max_movement": 5, "sp_hp": 8057, "sp_en": 100, "sp_attack": 925, "sp_defense": 761, "sp_mobility": 716, "sp_movement": 5, "sp_max_hp": 58009, "sp_max_en": 270, "sp_max_attack": 6660, "sp_max_defense": 5479, "sp_max_mobility": 5721, "sp_max_movement": 5}','null','百式改','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1115000350,'全装甲百式改 (EX)','全装甲型百式改 (EX)',5,1,2,0,'11150110008000810','1150','g1150u00350','FA-00100S',1,1,1,1,10033,100,1160,956,893,5,72238,270,8346,6880,7144,5,72238,270,8346,6880,7144,5,3,1,3,1,2,'奥干的MS「百式改」上增设复合型装甲的型态，为强化百式改的武装及装甲而开发的机体。
装备许多高输出镭射武器以及实弹武器，也增设崭新设计的装甲与抗镭射防御构造「反射护板」等，具有傲人的攻防性能。
另外，为将重量增加导致的机动性低落控制在最小限度，各部位增设多个推进器，若去除增设装甲，也可以充当一般的百式改来使用。','{"id": 1115000350, "hp": 10033, "en": 100, "attack": 1160, "defense": 956, "mobility": 893, "movement": 5, "max_hp": 72238, "max_en": 270, "max_attack": 8346, "max_defense": 6880, "max_mobility": 7144, "max_movement": 5, "sp_hp": 10033, "sp_en": 100, "sp_attack": 1160, "sp_defense": 956, "sp_mobility": 893, "sp_movement": 5, "sp_max_hp": 72238, "sp_max_en": 270, "sp_max_attack": 8346, "sp_max_defense": 6880, "sp_max_mobility": 7144, "sp_max_movement": 5}','null','全裝甲型百式改 (EX)','scrape',1791488368,'v2026.10.08',1080000203);
INSERT OR REPLACE INTO "units" VALUES(1115000400,'全装甲高达Mk-III','全装甲型高达Mk-III',4,3,2,0,'10000115008000810','1150','g1150u00400','FA-007GⅢ',1,1,1,1,7582,81,842,766,834,4,54589,253,6061,5515,5713,4,60730,281,6742,6136,6355,4,3,1,3,1,2,'奥干的MS「高达Mk-Ⅲ」增设复合型装甲的型态，活用高达Mk-Ⅲ所重视的机动性性能的同时，也采用增设装甲系统，在各部位设置推进器，减轻因重量增加导致机动性下滑的问题，并借由在脚部装备超绝镭射加农砲等各种镭射武器来增强火力。
透过前述更改，使其与过往全装甲型MS不同，不会扼杀基底机体的特性，也能大幅提升火力、推力，具有非常高阶且能力均衡的傲人性能。','{"id": 1115000400, "hp": 7582, "en": 81, "attack": 842, "defense": 766, "mobility": 834, "movement": 4, "max_hp": 54589, "max_en": 253, "max_attack": 6061, "max_defense": 5515, "max_mobility": 5713, "max_movement": 4, "sp_hp": 8435, "sp_en": 90, "sp_attack": 937, "sp_defense": 853, "sp_mobility": 927, "sp_movement": 4, "sp_max_hp": 60730, "sp_max_en": 281, "sp_max_attack": 6742, "sp_max_defense": 6136, "sp_max_mobility": 6355, "sp_max_movement": 4}','{"unit_id": 1115000400, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1115000400, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 111500040001, "unit_ssp_custom_core_group_id": 1115000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 111500040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 111500040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 111500040001, "weapon_change": {"id": 111500040001, "before_weapon_id": 0, "after_weapon_id": 111500040090, "weapon": {"id": 111500040090, "name": "腳部超絕鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 111500040090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 111500040090, "weapon_status": {"id": 111500040090, "range_min": 4, "range_max": 