INSERT OR REPLACE INTO "units" VALUES(1133000300,'德尔塔高达改','高达德尔塔凯',4,1,2,1,'10000000013301250','1330','g1330u00300','MSN-001Χ',1,1,1,1,8582,95,1099,905,947,4,61788,285,7912,6512,6815,4,57886,267,7412,6101,6385,4,3,1,3,1,2,'获得只存在白纸计划的「德尔塔高达」资料并透过「德尔塔普拉斯」开发资料反馈才完成的联邦军试作可变ＭＳ。
武装层面相较于原型机有大幅度强化，可选用各种多采多姿的武器，更可透过装备在背面的「原型翼状浮游飞翔砲」发动全方位攻击，具备任何战场皆可当场应对的通用性。
然而，更值得一提的是组装在机体之中的脑波传导装置「Ｎｉｔｒｏ」。
使用此系统即可获得等同于新人类的战斗能力，但实质却是每次使用都会强制窜改搭乘者的大脑，令搭乘者变质成为最适合系统的「强化人」。
此外，从驱动系统位置喷出的苍蓝火炎，是将人变质为强化人时产生的副作用产物。','{"id": 1133000300, "hp": 8582, "en": 95, "attack": 1099, "defense": 905, "mobility": 947, "movement": 4, "max_hp": 61788, "max_en": 285, "max_attack": 7912, "max_defense": 6512, "max_mobility": 6815, "max_movement": 4, "sp_hp": 8040, "sp_en": 89, "sp_attack": 1030, "sp_defense": 848, "sp_mobility": 887, "sp_movement": 4, "sp_max_hp": 57886, "sp_max_en": 267, "sp_max_attack": 7412, "sp_max_defense": 6101, "sp_max_mobility": 6385, "sp_max_movement": 4}','null','高達德爾塔凱','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1133000301,'德尔塔高达改','高达德尔塔凯',5,1,2,1,'10000000013301250','1330','g1330u00300','MSN-001Χ',1,1,1,1,9395,104,1203,991,1037,5,67642,312,8662,7129,7461,5,67642,312,8662,7129,7461,5,3,1,3,1,2,'获得只存在白纸计划的「德尔塔高达」资料并透过「德尔塔普拉斯」开发资料反馈才完成的联邦军试作可变ＭＳ。
武装层面相较于原型机有大幅度强化，可选用各种多采多姿的武器，更可透过装备在背面的「原型翼状浮游飞翔砲」发动全方位攻击，具备任何战场皆可当场应对的通用性。
然而，更值得一提的是组装在机体之中的脑波传导装置「Ｎｉｔｒｏ」。
使用此系统即可获得等同于新人类的战斗能力，但实质却是每次使用都会强制窜改搭乘者的大脑，令搭乘者变质成为最适合系统的「强化人」。
此外，从驱动系统位置喷出的苍蓝火炎，是将人变质为强化人时产生的副作用产物。','{"id": 1133000301, "hp": 9395, "en": 104, "attack": 1203, "defense": 991, "mobility": 1037, "movement": 5, "max_hp": 67642, "max_en": 312, "max_attack": 8662, "max_defense": 7129, "max_mobility": 7461, "max_movement": 5, "sp_hp": 9395, "sp_en": 104, "sp_attack": 1203, "sp_defense": 991, "sp_mobility": 1037, "sp_movement": 5, "sp_max_hp": 67642, "sp_max_en": 312, "sp_max_attack": 8662, "sp_max_defense": 7129, "sp_max_mobility": 7461, "sp_max_movement": 5}','null','高達德爾塔凱','scrape',1791488368,'v2026.10.08',NULL);
