INSERT OR REPLACE INTO "units" VALUES(1133000500,'银弹（感应炮实验型）','银弹(浮游圆锥砲实验型)',3,3,2,0,'10000000013301250','1330','g1330u00500','ARX-014P',1,1,1,1,6312,77,703,631,772,4,45447,231,5059,4541,5556,4,57782,294,6432,5773,7063,4,3,1,3,1,2,'阿纳海姆电子企业受联邦军委托，以第一次新自护战争后于阿古捷斯接收的新自护第四世代ＭＳ「达希鲁夫」为基底进行改造的试作型ＭＳ。
此机体省略了一部分与动力炉直接连结的武器，同时将构成外部装甲的材料换新，使机体大幅度轻量化，对各部位推进器的能源供给也更有效率，成功在维持高输出的状态下获得安定的敏捷能力。
此机体的开发主要目的是测试准脑波传导机体，也同时用作联邦开发中的感应砲兵器实验用机。
背部装备了内藏动力炉的「有线式大型浮游砲」，为后续开发的脑波传导装置搭载机体带来莫大贡献。','{"id": 1133000500, "hp": 6312, "en": 77, "attack": 703, "defense": 631, "mobility": 772, "movement": 4, "max_hp": 45447, "max_en": 231, "max_attack": 5059, "max_defense": 4541, "max_mobility": 5556, "max_movement": 4, "sp_hp": 8026, "sp_en": 98, "sp_attack": 894, "sp_defense": 802, "sp_mobility": 981, "sp_movement": 4, "sp_max_hp": 57782, "sp_max_en": 294, "sp_max_attack": 6432, "sp_max_defense": 5773, "sp_max_mobility": 7063, "sp_max_movement": 4}','{"unit_id": 1133000500, "unit_ssp_initial_release_set_id": 1133000500, "unit_ssp_custom_core_group_id": 1133000500, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 113300050001, "unit_ssp_custom_core_group_id": 1133000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 113300050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 113300050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 113300050001, "weapon_change": {"id": 113300050001, "before_weapon_id": 0, "after_weapon_id": 113300050090, "weapon": {"id": 113300050090, "name": "有線式大型浮游砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 113300050090, "attack_attr": 5, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350022, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 113300050090, "weapon_status": {"id": 113300050090, "range_min": 2, "range_max": 5, "powe