INSERT OR REPLACE INTO "units" VALUES(1133000600,'拜亚兰改装型2号机','拜亚兰‧特装型2号机',4,1,24,0,'10000000013301250','1330','g1330u00600','RX-160S-2',1,1,1,1,7205,81,925,756,804,5,51872,241,6658,5439,5788,5,57707,268,7407,6050,6439,5,3,3,2,1,1,'以泰坦斯开发的ＭＳ「拜亚兰」残存机体改良的技术性实验机体「拜亚兰‧特装型」再经进一步改修而成的２号机。
除了变更机体的配色，背部也换装为内藏镭射加农的可动支架，手臂构造更采用了五指型的机械手等等，各部位都有所改造。
此外，为减轻高速巡航时变换姿势造成的空气阻抗，新配备了飞航装甲，再加上选择性装备里的大型推进器，完成了当初原订于高海拔运用而设计的「执掌天空的机体」。','{"id": 1133000600, "hp": 7205, "en": 81, "attack": 925, "defense": 756, "mobility": 804, "movement": 5, "max_hp": 51872, "max_en": 241, "max_attack": 6658, "max_defense": 5439, "max_mobility": 5788, "max_movement": 5, "sp_hp": 8015, "sp_en": 90, "sp_attack": 1029, "sp_defense": 841, "sp_mobility": 895, "sp_movement": 5, "sp_max_hp": 57707, "sp_max_en": 268, "sp_max_attack": 7407, "sp_max_defense": 6050, "sp_max_mobility": 6439, "sp_max_movement": 5}','{"unit_id": 1133000600, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1133000600, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 113300060001, "unit_ssp_custom_core_group_id": 1133000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 113300060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 113300060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 113300060001, "weapon_change": {"id": 113300060001, "before_weapon_id": 0, "after_weapon_id": 113300060090, "weapon": {"id": 113300060090, "name": "長程鐳射軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 113300060090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240002, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 113300060090, "weapon_status": {"id": 113300060090, "range_min": 1, "r