INSERT OR REPLACE INTO "units" VALUES(1133001100,'里龙飞','改装型龙飞',3,3,2,0,'10000000013301250','1330','g1330u01100','AMX-107R',1,1,1,1,6650,70,730,668,740,5,47876,221,5254,4803,5072,5,60870,280,6680,6107,6449,5,3,1,3,1,2,'第一次新自护抗争时开发，具备可变合体构造的量产型ＭＳ「龙飞」，再经过新自护残党「带袖的」大幅度改造后的机体。
上半部「改装型龙飞攻击机」的驾驶舱周遭以及下半部「改装型龙飞连动机」的机头部分皆采用精神感应框体，可透过驾驶员的感应波进行完美的分离搭配机动行动。
赤红的机体颜色与华丽的装饰可证明本机体原是准备用作「弗尔‧伏朗托专用机」，但之后由于确定获得「新安州」，便转由其他新自护残党「带袖的」所属驾驶员搭乘参加多次实战。','{"id": 1133001100, "hp": 6650, "en": 70, "attack": 730, "defense": 668, "mobility": 740, "movement": 5, "max_hp": 47876, "max_en": 221, "max_attack": 5254, "max_defense": 4803, "max_mobility": 5072, "max_movement": 5, "sp_hp": 8455, "sp_en": 89, "sp_attack": 928, "sp_defense": 849, "sp_mobility": 941, "sp_movement": 5, "sp_max_hp": 60870, "sp_max_en": 280, "sp_max_attack": 6680, "sp_max_defense": 6107, "sp_max_mobility": 6449, "sp_max_movement": 5}','{"unit_id": 1133001100, "unit_ssp_initial_release_set_id": 1133001100, "unit_ssp_custom_core_group_id": 1133001100, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 113300110001, "unit_ssp_custom_core_group_id": 1133001100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 113300110001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 113300110001, "sort_order": 1, "release_function_type_index": 5, "target_id": 113300110001, "weapon_change": {"id": 113300110001, "before_weapon_id": 0, "after_weapon_id": 113300110090, "weapon": {"id": 113300110090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 113300110090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 113300110090, "weapon_status": {"id": 113300110090, "rang