INSERT OR REPLACE INTO "units" VALUES(1133001500,'KRAKE·祖鲁','克拉凯‧祖鲁',3,3,5,0,'10000000013301250','1330','g1330u01500','YAMS-130',1,1,1,1,7042,70,664,698,738,4,50698,220,4781,5019,5059,4,64459,280,6078,6382,6432,4,3,1,1,1,1,'新自护残党「带袖的」开发用作技术实验用的试作ＭＳ，继承一年战争时自护公国所开发的「脑波传导系统高机动实验机」理念，以Ｕ．Ｃ．００９６的技术重现的机体。
以基拉‧祖鲁（安杰罗‧梭裴专用机）为基底进行实验用的大幅改造，肩部追加的大型手臂内藏ＭＥＧＡ粒子砲，可作为线控式远距离兵器，下半身换装具备大推进力的推进器组件，背部则是装上超越机体大小的长距离飞航用大型燃料推进器，令推进力更加提升。','{"id": 1133001500, "hp": 7042, "en": 70, "attack": 664, "defense": 698, "mobility": 738, "movement": 4, "max_hp": 50698, "max_en": 220, "max_attack": 4781, "max_defense": 5019, "max_mobility": 5059, "max_movement": 4, "sp_hp": 8953, "sp_en": 89, "sp_attack": 845, "sp_defense": 887, "sp_mobility": 938, "sp_movement": 4, "sp_max_hp": 64459, "sp_max_en": 280, "sp_max_attack": 6078, "sp_max_defense": 6382, "sp_max_mobility": 6432, "sp_max_movement": 4}','{"unit_id": 1133001500, "unit_ssp_initial_release_set_id": 1133001500, "unit_ssp_custom_core_group_id": 1133001500, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 113300150001, "unit_ssp_custom_core_group_id": 1133001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 113300150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 113300150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 113300150001, "weapon_change": {"id": 113300150001, "before_weapon_id": 0, "after_weapon_id": 113300150090, "weapon": {"id": 113300150090, "name": "線控式盾牌組件 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 113300150090, "attack_attr": 5, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350024, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 113300150090, "weap