INSERT OR REPLACE INTO "units" VALUES(1144000500,'独角兽高达 3号机 凤凰 (毁灭模式)','独角兽高达3号机不死鸟 (毁灭模式)',4,1,38,0,'10000000014401250','1440','g1440u00500','RX-0',1,1,1,1,8028,80,927,685,797,5,57796,239,6672,4929,5735,5,64298,266,7422,5484,6380,5,3,2,3,1,3,'使用由阿纳海姆电子公司先行交货的全精神感应框体主体，并由地球联邦军自行组装完成的第三架RX-0。
本机的来历据说与参谋部门并不赞同毕斯特财团参与UC计划的想法有关。
虽于宇宙世纪0095年完成，却在机体评测实验中失控并击沉负责实验的母舰，从此下落不明。后来于宇宙世纪0097年再次出现在地球圈，因而变成掳获作战「狩猎不死鸟」的捕获目标。
机体性能与其他RX-0相等，借由装备了设计概念为利用精神感应框体的共鸣性来扩充机体性能的专用装备武装装甲DE，使机动性与攻击力获得提升。
本机持续在宇宙中徘徊，尽管处于推进剂等耗材早已耗尽的状态却仍保持运作，是一架充满谜团的机体。','{"id": 1144000500, "hp": 8028, "en": 80, "attack": 927, "defense": 685, "mobility": 797, "movement": 5, "max_hp": 57796, "max_en": 239, "max_attack": 6672, "max_defense": 4929, "max_mobility": 5735, "max_movement": 5, "sp_hp": 8931, "sp_en": 89, "sp_attack": 1031, "sp_defense": 762, "sp_mobility": 886, "sp_movement": 5, "sp_max_hp": 64298, "sp_max_en": 266, "sp_max_attack": 7422, "sp_max_defense": 5484, "sp_max_mobility": 6380, "sp_max_movement": 5}','{"unit_id": 1144000500, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1144000500, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 114400050001, "unit_ssp_custom_core_group_id": 1144000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400050001, "weapon_change": {"id": 114400050001, "before_weapon_id": 0, "after_weapon_id": 114400050090, "weapon": {"id": 114400050090, "name": "武裝裝甲DE SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400050090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340050, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400050090, "weapon_status": {"id": 114400050090, "range_min": 3, "range_max": 5, "power": 5000,