INSERT OR REPLACE INTO "units" VALUES(1144000800,'杰斯塔 (杰札尔队规格)','杰斯塔 (锡查尔队规格)',3,1,2,0,'10000000014401250','1440','g1440u00800','RGM-96X',1,1,1,1,6963,71,799,599,701,5,50128,212,5748,4309,5045,5,63734,269,7309,5478,6414,5,3,1,3,1,2,'在「狩猎不死鸟」的锡查尔队所配备的特务规格杰斯塔之中，负责追击不死鸟的A班所使用的高机动选配装备机。
杰斯塔承袭了与积根D型相同的设计理念，可透过更换选配装备来拓展用途，而锡查尔队机体的共通规格是在头部装备特殊感应器，以期提高搜敌与追踪能力。
在此基础之上，将部队区分为运用机动能力追逐目标的A班、
以长距离狙击牵制并拖延目标的B班，
以及使用捕捉枪掳获目标的C班等三个班，并各自装备了对应其职责的选配装备。
A班的机体装备了与武装强化型积根同型的背包，且腰部可以增设可卸式大型增装燃料槽兼推进器，以便接近高速飞行中的目标。','{"id": 1144000800, "hp": 6963, "en": 71, "attack": 799, "defense": 599, "mobility": 701, "movement": 5, "max_hp": 50128, "max_en": 212, "max_attack": 5748, "max_defense": 4309, "max_mobility": 5045, "max_movement": 5, "sp_hp": 8852, "sp_en": 90, "sp_attack": 1016, "sp_defense": 761, "sp_mobility": 891, "sp_movement": 5, "sp_max_hp": 63734, "sp_max_en": 269, "sp_max_attack": 7309, "sp_max_defense": 5478, "sp_max_mobility": 6414, "sp_max_movement": 5}','{"unit_id": 1144000800, "unit_ssp_initial_release_set_id": 1144000800, "unit_ssp_custom_core_group_id": 1144000800, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 114400080001, "unit_ssp_custom_core_group_id": 1144000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400080001, "weapon_change": {"id": 114400080001, "before_weapon_id": 0, "after_weapon_id": 114400080090, "weapon": {"id": 114400080090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400080090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400080090, "weapon_status": {"id": 114400080090, "range_min": 1, "range_max":