INSERT OR REPLACE INTO "units" VALUES(1144000900,'杰斯塔 (杰札尔队规格B／C装备)','杰斯塔 (锡查尔队规格B／C装备)',2,3,2,0,'10000000014401250','1440','g1440u00900','RGM-96X',1,1,1,1,6179,66,679,616,686,4,44483,205,4887,4433,4702,4,60907,281,6691,6069,6437,4,3,1,3,1,2,'阿纳海姆电子公司开发的特殊作战用MS。
在「狩猎不死鸟」行动中由锡查尔队使用，所有机体的头部都装备了瞄准镜型的感应器强化组件。
另外根据作战分工需求，投入了将背包换装为高机动型的A班、将米加镭射发射器搭配三脚架作为狙击装备使用的B班，以及搭乘89式燃料推进器、携带掳获用捕捉枪的C班各2架，总计6架机体的小队挑战「狩猎不死鸟」。','{"id": 1144000900, "hp": 6179, "en": 66, "attack": 679, "defense": 616, "mobility": 686, "movement": 4, "max_hp": 44483, "max_en": 205, "max_attack": 4887, "max_defense": 4433, "max_mobility": 4702, "max_movement": 4, "sp_hp": 8460, "sp_en": 90, "sp_attack": 930, "sp_defense": 843, "sp_mobility": 939, "sp_movement": 4, "sp_max_hp": 60907, "sp_max_en": 281, "sp_max_attack": 6691, "sp_max_defense": 6069, "sp_max_mobility": 6437, "sp_max_movement": 4}','{"unit_id": 1144000900, "unit_ssp_initial_release_set_id": 1144000900, "unit_ssp_custom_core_group_id": 1144000900, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 114400090001, "unit_ssp_custom_core_group_id": 1144000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400090001, "weapon_change": {"id": 114400090001, "before_weapon_id": 0, "after_weapon_id": 114400090090, "weapon": {"id": 114400090090, "name": "米加鐳射發射器 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400090090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110003, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400090090, "weapon_status": {"id