INSERT OR REPLACE INTO "units" VALUES(1144001000,'II新吉翁号','II新自护号',4,2,44,0,'10000000014401250','1440','g1440u01000','NZ-999',1,2,1,1,10067,69,760,846,715,5,72483,217,5469,6089,4861,5,80637,241,6084,6774,5408,5,3,2,1,1,1,'作为弗尔‧伏朗托的专用机而开发的新自护号。
使用开发时的备用零件而另外组装出的机体正是II（Second）新自护号。
为了提高机体刚度，在肩部武器舱的正面新增骨架，并拆除了武器舱的前方舱门。
新增的骨架被涂成红色，成为本机外观上的特征。
在武装方面为机体的手臂加入线控式诱导功能，使它得以做出与自护号相似的动作。','{"id": 1144001000, "hp": 10067, "en": 69, "attack": 760, "defense": 846, "mobility": 715, "movement": 5, "max_hp": 72483, "max_en": 217, "max_attack": 5469, "max_defense": 6089, "max_mobility": 4861, "max_movement": 5, "sp_hp": 11200, "sp_en": 76, "sp_attack": 845, "sp_defense": 941, "sp_mobility": 796, "sp_movement": 5, "sp_max_hp": 80637, "sp_max_en": 241, "sp_max_attack": 6084, "sp_max_defense": 6774, "sp_max_mobility": 5408, "sp_max_movement": 5}','{"unit_id": 1144001000, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1144001000, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 114400100001, "unit_ssp_custom_core_group_id": 1144001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400100001, "weapon_change": {"id": 114400100001, "before_weapon_id": 0, "after_weapon_id": 114400100090, "weapon": {"id": 114400100090, "name": "火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400100090, "weapon_status": {"id": 114400100090, "range_min": 2, "range_max": 4, "power": 4900, "en": 61, 