INSERT OR REPLACE INTO "units" VALUES(1144001110,'基拉·祖鲁 (埃里克机)','基拉‧祖鲁 (艾利克机)',4,3,2,0,'10000000014401250','1440','g1440u01100','AMS-129',1,1,1,1,8727,89,838,885,925,4,62828,278,6030,6368,6343,4,63542,281,6098,6440,6415,4,3,1,3,1,2,'为基拉‧祖鲁装备了重装背包与近距离战斗用武器的机体。
