INSERT OR REPLACE INTO "units" VALUES(1144001800,'里歇尔C型 (雷比尔将军号配备机)','里歇尔C型 (雷比尔将军号配备机)',3,1,30,0,'10000000014401250','1440','g1440u01800','RGZ-95C',1,1,1,1,6254,71,806,668,703,5,45025,211,5803,4807,5060,5,57246,268,7379,6112,6433,5,3,3,3,1,2,'以量产在格利普斯战役中展现优越性能的可变MS「Z高达」为目标所开发的「Refine Gundam Zeta」系列机体中，「里歇尔」的衍生机之一，是被称为「C型」的指挥官用改装机。
此机体解除了标准机体设定的推进力限制器上限，并为了提升整机可靠性而对全机进行了重新调整，将里歇尔原本具备的机体性能完全展现出来。
此外，此机体是配备于「雷比尔将军号」，施以专用涂装的特制规格机。','{"id": 1144001800, "hp": 6254, "en": 71, "attack": 806, "defense": 668, "mobility": 703, "movement": 5, "max_hp": 45025, "max_en": 211, "max_attack": 5803, "max_defense": 4807, "max_mobility": 5060, "max_movement": 5, "sp_hp": 7951, "sp_en": 90, "sp_attack": 1025, "sp_defense": 849, "sp_mobility": 894, "sp_movement": 5, "sp_max_hp": 57246, "sp_max_en": 268, "sp_max_attack": 7379, "sp_max_defense": 6112, "sp_max_mobility": 6433, "sp_max_movement": 5}','{"unit_id": 1144001800, "unit_ssp_initial_release_set_id": 1144001800, "unit_ssp_custom_core_group_id": 1144001800, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 114400180001, "unit_ssp_custom_core_group_id": 1144001800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400180001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400180001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400180001, "weapon_change": {"id": 114400180001, "before_weapon_id": 0, "after_weapon_id": 114400180090, "weapon": {"id": 114400180090, "name": "鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400180090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400180090, "weapon_status": {"id": 114400180090, "range_min": 2, "range_max": 5, "power": 4900, "en": 