INSERT OR REPLACE INTO "units" VALUES(1144001900,'杰刚A2型 (雷比尔将军号配备机)','积根A2型 (雷比尔将军号配备机)',2,1,2,0,'10000000014401250','1440','g1440u01900','RGM-89A2',1,1,1,1,5815,65,749,621,653,4,41868,194,5388,4465,4702,4,57326,266,7378,6113,6437,4,3,1,3,1,2,'联邦军主力量产MS「积根」经微幅改进的衍生机体之一，是以初期型为基底大幅度改造，提升综合性能而成的机体。
主要改良的部分为推进构造，在背包上追加辅助推进器，双腿也各自增设推进器，并提供专用的大型盾牌作为防御兵器等，整体规格都有提升。
此外，此机体是配备于「雷比尔将军号」，施以专用涂装的特制规格机。','{"id": 1144001900, "hp": 5815, "en": 65, "attack": 749, "defense": 621, "mobility": 653, "movement": 4, "max_hp": 41868, "max_en": 194, "max_attack": 5388, "max_defense": 4465, "max_mobility": 4702, "max_movement": 4, "sp_hp": 7962, "sp_en": 89, "sp_attack": 1025, "sp_defense": 849, "sp_mobility": 895, "sp_movement": 4, "sp_max_hp": 57326, "sp_max_en": 266, "sp_max_attack": 7378, "sp_max_defense": 6113, "sp_max_mobility": 6437, "sp_max_movement": 4}','{"unit_id": 1144001900, "unit_ssp_initial_release_set_id": 1144001900, "unit_ssp_custom_core_group_id": 1144001900, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 114400190001, "unit_ssp_custom_core_group_id": 1144001900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 114400190001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 114400190001, "sort_order": 1, "release_function_type_index": 5, "target_id": 114400190001, "weapon_change": {"id": 114400190001, "before_weapon_id": 0, "after_weapon_id": 114400190090, "weapon": {"id": 114400190090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 114400190090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 114400190090, "weapon_status": {"id": 114400190090, "range_min": 1, "range_max": 3, "power": 4900, "en": 