INSERT OR REPLACE INTO "units" VALUES(1144002002,'NT高达C装备 (觉醒)','叙述高达C装备 (觉醒)',5,3,38,1,'10000000014401250','1440','g1440u02002','RX-9/C',1,1,1,1,11432,121,1269,1138,1260,5,82310,379,9133,8190,8637,5,82310,379,9133,8190,8637,5,3,2,3,1,3,'-','{"id": 1144002002, "hp": 11432, "en": 121, "attack": 1269, "defense": 1138, "mobility": 1260, "movement": 5, "max_hp": 82310, "max_en": 379, "max_attack": 9133, "max_defense": 8190, "max_mobility": 8637, "max_movement": 5, "sp_hp": 11432, "sp_en": 121, "sp_attack": 1269, "sp_defense": 1138, "sp_mobility": 1260, "sp_movement": 5, "sp_max_hp": 82310, "sp_max_en": 379, "sp_max_attack": 9133, "sp_max_defense": 8190, "sp_max_mobility": 8637, "sp_max_movement": 5}','null','敘述高達C裝備 (覺醒)','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1150000100,'Ξ高达','Ξ高达',4,2,30,0,'10000000015001100','1500','g1500u00100','RX-105',1,1,1,1,9953,69,680,844,807,5,71662,241,4891,6070,4936,5,79724,268,5441,6753,5491,5,3,3,3,1,2,'马法狄准备用来袭击阿得雷德会议，阿纳海姆电子公司制造的第五世代MS。
本机虽为潘尼洛普的姊妹机，但从安装了机体内藏型的米诺夫斯基飞行组件看来，投入了更为先进的技术。
头顶高度超过26公尺，腕部也比标准的MS尺寸大上许多，尽管冠有「高达」之名，却是凸显出怪异轮廓的造型。','{"id": 1150000100, "hp": 9953, "en": 69, "attack": 680, "defense": 844, "mobility": 807, "movement": 5, "max_hp": 71662, "max_en": 241, "max_attack": 4891, "max_defense": 6070, "max_mobility": 4936, "max_movement": 5, "sp_hp": 11073, "sp_en": 76, "sp_attack": 756, "sp_defense": 938, "sp_mobility": 898, "sp_movement": 5, "sp_max_hp": 79724, "sp_max_en": 268, "sp_max_attack": 5441, "sp_max_defense": 6753, "sp_max_mobility": 5491, "sp_max_movement": 5}','{"unit_id": 1150000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1150000100, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 115000010001, "unit_ssp_custom_core_group_id": 1150000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 115000010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 115000010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 115000010001, "weapon_change": {"id": 115000010001, "before_weapon_id": 0, "after_weapon_id": 115000010090, "weapon": {"id": 115000010090, "name": "浮游砲飛彈 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 115000010090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290100, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 115000010090, "weapon_status": {"id": 115000010090, "range_min": 2, "range_max": 5, "power": 5