INSERT OR REPLACE INTO "units" VALUES(1150000200,'佩涅罗佩','潘尼洛普',4,1,30,0,'10000000015001100','1500','g1500u00200','RX-104FF',1,1,1,1,7166,80,928,762,800,5,51592,240,6679,5480,5754,5,57396,267,7430,6097,6401,5,3,3,3,1,2,'坚尼斯为了歼灭马法狄而投入战线，阿纳海姆电子公司制造的MS。
奥德修斯高达装备了FF（固定飞行）组件的型态就称为潘尼洛普。
本机是首次搭载小型化米诺夫斯基飞行组件的其中一架MS，拥有可在大气层内单独飞行的卓越能力。
虽然也具备超音速飞行能力，但必须变形为飞行型态才能使用。','{"id": 1150000200, "hp": 7166, "en": 80, "attack": 928, "defense": 762, "mobility": 800, "movement": 5, "max_hp": 51592, "max_en": 240, "max_attack": 6679, "max_defense": 5480, "max_mobility": 5754, "max_movement": 5, "sp_hp": 7972, "sp_en": 89, "sp_attack": 1032, "sp_defense": 847, "sp_mobility": 890, "sp_movement": 5, "sp_max_hp": 57396, "sp_max_en": 267, "sp_max_attack": 7430, "sp_max_defense": 6097, "sp_max_mobility": 6401, "sp_max_movement": 5}','{"unit_id": 1150000200, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1150000200, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 115000020001, "unit_ssp_custom_core_group_id": 1150000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 115000020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 115000020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 115000020001, "weapon_change": {"id": 115000020001, "before_weapon_id": 0, "after_weapon_id": 115000020090, "weapon": {"id": 115000020090, "name": "浮游砲飛彈 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 115000020090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290102, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 115000020090, "weapon_status": {"id": 115000020090, "range_min": 2, "range_max": 5, "power": 5100, "en": 64, "hit_rat