INSERT OR REPLACE INTO "units" VALUES(1150000250,'佩涅罗佩 (EX)','潘尼洛普 (EX)',5,2,30,0,'10000000015001100','1500','g1500u00250','RX-104FF',1,1,1,1,11505,86,850,1153,997,5,82834,303,6114,8301,6102,5,82834,303,6114,8301,6102,5,3,3,3,1,2,'坚尼斯为了歼灭马法狄而投入战线，阿纳海姆电子公司制造的MS。
奥德修斯高达装备了FF（固定飞行）组件的型态就称为潘尼洛普。
本机是首次搭载小型化米诺夫斯基飞行组件的其中一架MS，拥有可在大气层内单独飞行的卓越能力。
虽然也具备超音速飞行能力，但必须变形为飞行型态才能使用。','{"id": 1150000250, "hp": 11505, "en": 86, "attack": 850, "defense": 1153, "mobility": 997, "movement": 5, "max_hp": 82834, "max_en": 303, "max_attack": 6114, "max_defense": 8301, "max_mobility": 6102, "max_movement": 5, "sp_hp": 11505, "sp_en": 86, "sp_attack": 850, "sp_defense": 1153, "sp_mobility": 997, "sp_movement": 5, "sp_max_hp": 82834, "sp_max_en": 303, "sp_max_attack": 6114, "sp_max_defense": 8301, "sp_max_mobility": 6102, "sp_max_movement": 5}','null','潘尼洛普 (EX)','scrape',1791488368,'v2026.10.08',1150000201);
