INSERT OR REPLACE INTO "units" VALUES(1150000600,'梅萨F01型','梅萨F01型',3,1,22,0,'10000000015001100','1500','g1500u00600','Me02R-F01',1,1,1,1,6964,70,804,599,701,4,50138,210,5784,4312,5047,4,63747,267,7354,5482,6416,4,3,2,3,1,2,'马法狄作为主力运用的MS。
