INSERT OR REPLACE INTO "units" VALUES(1150001360,'阿利宙斯','阿利宙斯',4,3,30,0,'10000000015001100','1500','g1500u01360','TX-ff104',1,1,1,1,8022,81,756,804,835,5,57756,254,5442,5785,5725,5,64254,283,6055,6435,6369,5,3,3,3,1,2,'作为扫荡马法狄的王牌战力，坚尼斯加强配备打造出RX-104FF潘尼洛普。
