INSERT OR REPLACE INTO "units" VALUES(1211000102,'艾比安高达（EW版／狂飙回旋击装备）','高达艾比安（EW版／狂飙突进装备）',5,1,31,1,'10000211021002190','2110','g2110u00102','OZ-13MS',1,1,1,1,11970,121,1391,1009,1204,5,86184,361,10014,7264,8665,5,86184,361,10014,7264,8665,5,3,3,3,1,3,'高达艾比安专用的武装零件。在杜鲁斯的安排下，与桃乐丝一同被送到了积古斯身边。
