INSERT OR REPLACE INTO "units" VALUES(1211000300,'飞翼高达 (EW版)','飞翼高达 (EW版)',2,2,2,0,'10000211021002190','2110','g2110u00300','XXXG-01W',1,1,1,1,7515,55,635,745,656,4,54106,194,4568,5363,4012,4,74083,266,6255,7343,5493,4,3,1,3,1,2,'飞翼高达的「败者们的荣耀」漫画版造型。
