INSERT OR REPLACE INTO "units" VALUES(1211000500,'飞翼高达 零式原型机 (EW版)','飞翼高达零式原型机 (EW版)',3,1,31,0,'10000211021002190','2110','g2110u00500','XXXG-00W0',1,1,1,1,6286,70,809,664,698,5,45256,210,5823,4779,5023,5,57540,267,7403,6077,6387,5,3,3,3,1,3,'「败者们的荣耀」漫画版新设计的机体，改造成飞翼高达零式 (EW版) 前的原型机。
承袭电视动画系列版飞翼高达零式的造型，将双管破坏步枪和盾牌加大，并追加战机型态时的机翼。
和电视动画系列一样是由卡多鲁‧鲁宾‧温拿制造，之后移植上多鲁基斯F的翼状推进翼，改造成飞翼高达零式 (EW版)。','{"id": 1211000500, "hp": 6286, "en": 70, "attack": 809, "defense": 664, "mobility": 698, "movement": 5, "max_hp": 45256, "max_en": 210, "max_attack": 5823, "max_defense": 4779, "max_mobility": 5023, "max_movement": 5, "sp_hp": 7992, "sp_en": 89, "sp_attack": 1029, "sp_defense": 844, "sp_mobility": 887, "sp_movement": 5, "sp_max_hp": 57540, "sp_max_en": 267, "sp_max_attack": 7403, "sp_max_defense": 6077, "sp_max_mobility": 6387, "sp_max_movement": 5}','{"unit_id": 1211000500, "unit_ssp_initial_release_set_id": 1211000500, "unit_ssp_custom_core_group_id": 1211000500, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 121100050001, "unit_ssp_custom_core_group_id": 1211000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100050001, "weapon_change": {"id": 121100050001, "before_weapon_id": 0, "after_weapon_id": 121100050090, "weapon": {"id": 121100050090, "name": "雙管破壞步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100050090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120006, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100050090, "weapon_status": {"id": 121100050090, "range_min": 3, "range_max":