INSERT OR REPLACE INTO "units" VALUES(1211000700,'死神高达 (EW版/可变蝙翼)','死神高达 (EW版/可变蝙翼)',3,1,31,0,'10000211021002190','2110','g2110u00700','XXXG-01D',1,1,1,1,6606,71,841,636,663,4,47560,200,6050,4573,5025,4,60469,254,7692,5814,6389,4,3,3,3,1,3,'死神高达的「败者们的荣耀」漫画版造型。
虽然造型与电视动画系列登场的机体不同，但在设定上是相同机体。
脚部设置和地狱死神高达 (EW版) 一样的钉爪，主武装镭射镰刀的形状则经过更改。
此外，头部改为白色系，涂装配色和电视动画系列版有部分差异。
当本机处于背包两侧装上追加装备「可变蝙翼」的型态时，可张开翅膀飞行，在短时间内发挥出不亚于飞翼高达的机动性。','{"id": 1211000700, "hp": 6606, "en": 71, "attack": 841, "defense": 636, "mobility": 663, "movement": 4, "max_hp": 47560, "max_en": 200, "max_attack": 6050, "max_defense": 4573, "max_mobility": 5025, "max_movement": 4, "sp_hp": 8399, "sp_en": 90, "sp_attack": 1069, "sp_defense": 808, "sp_mobility": 843, "sp_movement": 4, "sp_max_hp": 60469, "sp_max_en": 254, "sp_max_attack": 7692, "sp_max_defense": 5814, "sp_max_mobility": 6389, "sp_max_movement": 4}','{"unit_id": 1211000700, "unit_ssp_initial_release_set_id": 1211000700, "unit_ssp_custom_core_group_id": 1211000700, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 121100070001, "unit_ssp_custom_core_group_id": 1211000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100070001, "weapon_change": {"id": 121100070001, "before_weapon_id": 0, "after_weapon_id": 121100070090, "weapon": {"id": 121100070090, "name": "破壞盾 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100070090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 230001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100070090, "weapon_status": {"id": 121100070090, "range_min": 2, "range_max": 4, 