INSERT OR REPLACE INTO "units" VALUES(1211000800,'重装高达 (EW版/刺猬弹库)','重砲手高达 (EW版/刺猬弹库)',3,1,32,0,'10000211021002190','2110','g2110u00800','XXXG-01H',1,1,1,1,7061,70,809,668,625,4,50834,189,5821,4807,4997,4,64632,241,7401,6112,6353,4,3,1,3,1,3,'重砲手高达的「败者们的荣耀」漫画版造型。
虽然造型与电视动画系列登场的机体不同，但在设定上是相同机体。
涂装配色与电视动画系列版相同，但机体某些部分的形状有所差异。
武装方面，形状和配置经过变更，大型化主武装「镭射格林机砲」。
当本机处于装上追加装备「刺猬弹库」的型态时，会在两肩增设武器货柜，脚部增设飞弹荚舱，并为了在重量增加下确保机动力而装设驱动装置。','{"id": 1211000800, "hp": 7061, "en": 70, "attack": 809, "defense": 668, "mobility": 625, "movement": 4, "max_hp": 50834, "max_en": 189, "max_attack": 5821, "max_defense": 4807, "max_mobility": 4997, "max_movement": 4, "sp_hp": 8977, "sp_en": 89, "sp_attack": 1028, "sp_defense": 849, "sp_mobility": 795, "sp_movement": 4, "sp_max_hp": 64632, "sp_max_en": 241, "sp_max_attack": 7401, "sp_max_defense": 6112, "sp_max_mobility": 6353, "sp_max_movement": 4}','{"unit_id": 1211000800, "unit_ssp_initial_release_set_id": 1211000800, "unit_ssp_custom_core_group_id": 1211000800, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 121100080001, "unit_ssp_custom_core_group_id": 1211000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100080001, "weapon_change": {"id": 121100080001, "before_weapon_id": 0, "after_weapon_id": 121100080090, "weapon": {"id": 121100080090, "name": "發射所有飛彈 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100080090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 200004, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100080090, "weapon_status": {"id": 121100080090, "range_min": 3, "ra