INSERT OR REPLACE INTO "units" VALUES(1211000900,'沙漠高达 (EW版/犰狳装甲)','沙漠高达 (EW版/犰狳装甲)',3,2,32,0,'10000211021002190','2110','g2110u00900','XXXG-01SR',1,1,1,1,7980,60,662,813,636,4,57456,190,4766,5849,4321,4,73051,241,6060,7436,5494,4,3,1,3,1,3,'沙漠高达的「败者们的荣耀」漫画版造型。
虽然造型与电视动画系列登场的机体不同，但在设定上是相同机体。
机体外观和沙漠高达改 (EW版) 基本上相同，一样把主武装「热流刀」加大，在盾牌前端追加钩爪。
当本机处于装上追加装备「追加装甲」的型态时，不仅强化防御力，还可借由追加辅助推进器提升推力。','{"id": 1211000900, "hp": 7980, "en": 60, "attack": 662, "defense": 813, "mobility": 636, "movement": 4, "max_hp": 57456, "max_en": 190, "max_attack": 4766, "max_defense": 5849, "max_mobility": 4321, "max_movement": 4, "sp_hp": 10146, "sp_en": 76, "sp_attack": 842, "sp_defense": 1033, "sp_mobility": 808, "sp_movement": 4, "sp_max_hp": 73051, "sp_max_en": 241, "sp_max_attack": 6060, "sp_max_defense": 7436, "sp_max_mobility": 5494, "sp_max_movement": 4}','{"unit_id": 1211000900, "unit_ssp_initial_release_set_id": 1211000900, "unit_ssp_custom_core_group_id": 1211000900, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 121100090001, "unit_ssp_custom_core_group_id": 1211000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100090001, "weapon_change": {"id": 121100090001, "before_weapon_id": 0, "after_weapon_id": 121100090090, "weapon": {"id": 121100090090, "name": "鐳射衝鋒槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100090090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100090090, "weapon_status": {"id": 121100090090, "range_min": 2, "range_max": 5, "powe