INSERT OR REPLACE INTO "units" VALUES(1211001000,'神龙高达 (EW版/獠牙装备)','神龙高达 (EW版/獠牙装备)',3,2,32,0,'10000211021002190','2110','g2110u01000','XXXG-01S',1,1,1,1,8744,60,689,733,700,4,62956,210,4958,5274,4282,4,80044,266,6303,6705,5444,4,3,1,3,1,3,'神龙高达的「败者们的荣耀」漫画版造型。
虽然造型与电视动画系列登场的机体不同，但在设定上是相同机体。
机体外观和双头龙高达 (EW版) 基本上相同，涂装配色则跟电视动画系列一样是蓝白红三色。
此外，加大神龙钳，部分武装也经过更改。
本机还追加装备青龙刀型的实体剑「獠牙」，其威力足以将力傲一刀两断。','{"id": 1211001000, "hp": 8744, "en": 60, "attack": 689, "defense": 733, "mobility": 700, "movement": 4, "max_hp": 62956, "max_en": 210, "max_attack": 4958, "max_defense": 5274, "max_mobility": 4282, "max_movement": 4, "sp_hp": 11118, "sp_en": 76, "sp_attack": 876, "sp_defense": 932, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 80044, "sp_max_en": 266, "sp_max_attack": 6303, "sp_max_defense": 6705, "sp_max_mobility": 5444, "sp_max_movement": 4}','{"unit_id": 1211001000, "unit_ssp_initial_release_set_id": 1211001000, "unit_ssp_custom_core_group_id": 1211001000, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 121100100001, "unit_ssp_custom_core_group_id": 1211001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100100001, "weapon_change": {"id": 121100100001, "before_weapon_id": 0, "after_weapon_id": 121100100090, "weapon": {"id": 121100100090, "name": "神龍鉗 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100100090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 260008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100100090, "weapon_status": {"id": 121100100090, "range_min": 2, "range_max": 4, "power": 4900, "en": 6