INSERT OR REPLACE INTO "units" VALUES(1211001100,'多鲁基斯F','多鲁基斯F',3,1,30,0,'10000211021002190','2110','g2110u01100','OZ-00MS',1,1,1,1,6357,70,803,660,706,5,45769,209,5777,4746,5081,5,58192,265,7345,6035,6460,5,3,3,3,1,2,'「败者们的荣耀」漫画版新设计的机体，多鲁基斯的宇宙规格。
霍华为了脱离OZ后登上宇宙的积古斯‧玛基斯改造的多鲁基斯。
背部的推进器组件换装上以四枚翅膀组成的翼状推进翼，获得惊人的机动性。
此外，头顶部位角的形状也经过变更。
本机的翼状推进翼之后移植到飞翼高达零式 (EW版) 上。','{"id": 1211001100, "hp": 6357, "en": 70, "attack": 803, "defense": 660, "mobility": 706, "movement": 5, "max_hp": 45769, "max_en": 209, "max_attack": 5777, "max_defense": 4746, "max_mobility": 5081, "max_movement": 5, "sp_hp": 8083, "sp_en": 89, "sp_attack": 1021, "sp_defense": 839, "sp_mobility": 898, "sp_movement": 5, "sp_max_hp": 58192, "sp_max_en": 265, "sp_max_attack": 7345, "sp_max_defense": 6035, "sp_max_mobility": 6460, "sp_max_movement": 5}','{"unit_id": 1211001100, "unit_ssp_initial_release_set_id": 1211001100, "unit_ssp_custom_core_group_id": 1211001100, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 121100110001, "unit_ssp_custom_core_group_id": 1211001100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121100110001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121100110001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121100110001, "weapon_change": {"id": 121100110001, "before_weapon_id": 0, "after_weapon_id": 121100110090, "weapon": {"id": 121100110090, "name": "杜賓槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121100110090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121100110090, "weapon_status": {"id": 121100110090, "range_min": 2, "range_max": 5, "power": 4850, "en": 61, "