INSERT OR REPLACE INTO "units" VALUES(1212000100,'斯德毕尔','斯德毕尔',4,2,2,0,'10000000021202100','2120','g2120u00100','OZ-16MSX-D',1,1,1,1,9258,68,683,925,794,4,66651,239,4916,6655,4857,4,74149,265,5469,7404,5404,4,3,1,3,1,2,'OZ以防卫据点用所开发的巨大MS。
具备变形构造，能分别使用近距离战斗用的MS型态，与机动性出色的MA型态战斗。
此外还搭载了MD系统，也可当作无人机来使用。
主要武装是有著镭射军刀跟镭射步枪功能的「镭射刺刀」，MA型态则能使用尾部的「电热鞭」。
还能装备可展开「行星防卫系统」的大型盾牌「A.S.行星防御系统」，具备极高防御力。
但由于机体大小是一般MS的1.5倍而放弃量产，仅制造一架的试作机也配备在无人工厂「火神号」作为防卫。
机体名称取自天蝎座。','{"id": 1212000100, "hp": 9258, "en": 68, "attack": 683, "defense": 925, "mobility": 794, "movement": 4, "max_hp": 66651, "max_en": 239, "max_attack": 4916, "max_defense": 6655, "max_mobility": 4857, "max_movement": 4, "sp_hp": 10299, "sp_en": 76, "sp_attack": 760, "sp_defense": 1029, "sp_mobility": 883, "sp_movement": 4, "sp_max_hp": 74149, "sp_max_en": 265, "sp_max_attack": 5469, "sp_max_defense": 7404, "sp_max_mobility": 5404, "sp_max_movement": 4}','{"unit_id": 1212000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1212000100, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 121200010001, "unit_ssp_custom_core_group_id": 1212000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121200010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121200010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121200010001, "weapon_change": {"id": 121200010001, "before_weapon_id": 0, "after_weapon_id": 121200010090, "weapon": {"id": 121200010090, "name": "鐳射刺刀 (步槍) SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121200010090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121200010090, "weapon_status": {"id": 121200010090, "range_min": 2, "range_max": 4, "power": 4950, "en": 62, "hit_rate": 105, "cri