INSERT OR REPLACE INTO "units" VALUES(1217000110,'高达杰姆纳斯01','高达杰姆纳斯01',4,1,2,0,'10000000021702100','2170','g2170u00100','OZX-GU01A',1,1,1,1,8360,88,1052,797,835,4,60192,251,7573,5737,6324,4,60876,254,7659,5802,6396,4,3,1,3,1,2,'资源卫星殖民地「MO-V」秘密开发出的试作型MS一号机。
将本体驾驶舱作为核心组件，各部位则依据不同用途组合相对应的零件「G-UNIT」，期望在各种环境下都能发挥高性能的机体。
不仅有著量产型MS无可比拟的超高基本性能，还装备了「加速步枪」及「镭射剑」等，武器方面也很完善。
此外，还搭载了可随著驾驶员的精神状态，一定时间内提升机体性能的「PX系统」，但发动此系统需要相当的才能及训练，并且必须依照各个驾驶员做调整。','{"id": 1217000110, "hp": 8360, "en": 88, "attack": 1052, "defense": 797, "mobility": 835, "movement": 4, "max_hp": 60192, "max_en": 251, "max_attack": 7573, "max_defense": 5737, "max_mobility": 6324, "max_movement": 4, "sp_hp": 8455, "sp_en": 89, "sp_attack": 1064, "sp_defense": 806, "sp_mobility": 844, "sp_movement": 4, "sp_max_hp": 60876, "sp_max_en": 254, "sp_max_attack": 7659, "sp_max_defense": 5802, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1217000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1217000110, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 121700011001, "unit_ssp_custom_core_group_id": 1217000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 121700011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 121700011001, "weapon_change": {"id": 121700011001, "before_weapon_id": 0, "after_weapon_id": 121700011090, "weapon": {"id": 121700011090, "name": "PX系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 121700011090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280012, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 121700011090, "weapon_status": {"id": 121700011090, "range_min": 1, "range_m