INSERT OR REPLACE INTO "units" VALUES(1304000110,'嫣红强袭+I.W.S.P.','突击高达‧红 (I.W.S.P.装备)',4,3,30,0,'10000000030403000','3040','g3040u00100','MBF-02+P202QX',1,1,1,1,7968,97,877,792,967,5,57367,291,6311,5703,6956,5,58019,294,6383,5768,7035,5,3,3,3,1,2,'突击高达‧红换装型态的其中一种。
「I.W.S.P.」是统合兵装突击装备背包的简称，将机动性、格斗战能力与砲击力等各种突击装备背包的特性整合为一。
原本是由P.M.P公司负责，但因为在开发足以供应大量电源的能源背包时遇到瓶颈，结果无法达成实用化。
之后，拥有大容量能源背包技术的奥布取得此装备，暗中改良至实用化的阶段，最终在奥布沦陷后才于草薙号内完成。然而，即使装备在突击高达‧红上后实施了多次运用测试，驾驶员无法掌握复杂的火器管制系统，终究仍未被采用。','{"id": 1304000110, "hp": 7968, "en": 97, "attack": 877, "defense": 792, "mobility": 967, "movement": 5, "max_hp": 57367, "max_en": 291, "max_attack": 6311, "max_defense": 5703, "max_mobility": 6956, "max_movement": 5, "sp_hp": 8059, "sp_en": 98, "sp_attack": 887, "sp_defense": 801, "sp_mobility": 978, "sp_movement": 5, "sp_max_hp": 58019, "sp_max_en": 294, "sp_max_attack": 6383, "sp_max_defense": 5768, "sp_max_mobility": 7035, "sp_max_movement": 5}','{"unit_id": 1304000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1304000110, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 130400011001, "unit_ssp_custom_core_group_id": 1304000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400011001, "weapon_change": {"id": 130400011001, "before_weapon_id": 0, "after_weapon_id": 130400011090, "weapon": {"id": 130400011090, "name": "齊射 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400011090, "attack_attr": 1, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 180005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400011090, "weapon_status": {"id": 13040001