INSERT OR REPLACE INTO "units" VALUES(1304000200,'105短剑','105达加',2,1,2,0,'10000000030403000','3040','g3040u00200','GAT-01A1',1,1,1,1,5862,65,747,619,649,4,42205,195,5372,4455,4671,4,57788,267,7355,6100,6396,4,3,1,3,1,2,'以「GAT-X系列」的资料为基础开发出的地球联合军量产型MS。
突击高达的正式量产机。
本机装备了突击达加为了提高生产率而舍弃的突击装备背包连结插座，头部感应器换上与突击高达有相等性能的款式。
基于成本考量，未采用「PS装甲」及「TP装甲」，而是以「积层装甲」取代，大幅提升对镭射兵器的防御力。
本机体正式名称虽为「达加」，通常冠上原型机突击高达的机体型号GAT-X105，而以「105达加」称呼。','{"id": 1304000200, "hp": 5862, "en": 65, "attack": 747, "defense": 619, "mobility": 649, "movement": 4, "max_hp": 42205, "max_en": 195, "max_attack": 5372, "max_defense": 4455, "max_mobility": 4671, "max_movement": 4, "sp_hp": 8027, "sp_en": 89, "sp_attack": 1022, "sp_defense": 848, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 57788, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 6100, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1304000200, "unit_ssp_initial_release_set_id": 1304000200, "unit_ssp_custom_core_group_id": 1304000200, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130400020001, "unit_ssp_custom_core_group_id": 1304000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400020001, "weapon_change": {"id": 130400020001, "before_weapon_id": 0, "after_weapon_id": 130400020090, "weapon": {"id": 130400020090, "name": "ES01 鐳射軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400020090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240006, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400020090, "weapon_status": {"id": 130400020090, "range_min": 1, "range_max": 2