INSERT OR REPLACE INTO "units" VALUES(1304000400,'105短剑 (重炮型攻击装备)','105达加 (砲战型突击装备)',2,1,2,0,'10000000030403000','3040','g3040u00400','GAT-01A1+AQM/E-X03',1,1,1,1,5850,65,745,617,654,4,42120,195,5361,4438,4709,4,57672,267,7340,6076,6447,4,3,1,3,1,2,'105达加的换装型态之一。
装上「砲战型突击装备背包」，强化砲击战斗能力的型态。
此装备的组成包含极为强力的MS携带用火器大型镭射砲「阿耆尼」，以及由近距离防御用的火神砲和重砲发射器组合成的「复合兵器组件」。
因为极具重量导致机动力下降，主要用于仰赖其高火力对远方的舰队或要塞发动攻击。','{"id": 1304000400, "hp": 5850, "en": 65, "attack": 745, "defense": 617, "mobility": 654, "movement": 4, "max_hp": 42120, "max_en": 195, "max_attack": 5361, "max_defense": 4438, "max_mobility": 4709, "max_movement": 4, "sp_hp": 8010, "sp_en": 89, "sp_attack": 1020, "sp_defense": 844, "sp_mobility": 896, "sp_movement": 4, "sp_max_hp": 57672, "sp_max_en": 267, "sp_max_attack": 7340, "sp_max_defense": 6076, "sp_max_mobility": 6447, "sp_max_movement": 4}','{"unit_id": 1304000400, "unit_ssp_initial_release_set_id": 1304000400, "unit_ssp_custom_core_group_id": 1304000400, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130400040001, "unit_ssp_custom_core_group_id": 1304000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400040001, "weapon_change": {"id": 130400040001, "before_weapon_id": 0, "after_weapon_id": 130400040090, "weapon": {"id": 130400040090, "name": "320mm超高脈衝砲「阿耆尼」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400040090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400040090, "weapon_status": {"id": 130400040090, "range_min": 3, "range_max": 5, "pow