INSERT OR REPLACE INTO "units" VALUES(1304000500,'炮筒型105短剑','105砲筒型达加',3,1,30,0,'10000000030403000','3040','g3040u00500','GAT-01A1+AQM/E-X04',1,1,1,1,6313,70,805,664,700,4,45451,210,5796,4779,5040,4,57788,267,7370,6076,6408,4,3,3,3,1,2,'105达加装上「砲筒型突击装备背包」的机体。
砲筒型突击装备原是专为穆‧拉‧布拉加开发的突击装备，但因为穆与大天使号一同叛逃联合军，使得计划受阻。
突击高达的活跃对联合军本部而言，原本是意图作为宣示自然人的力量，而非仰赖调整者的力量。因此打算将突击高达授予英雄布拉加少校，并宣称至今为止都是由他操纵进行战斗。
随后机体转交给经由适性检查，判断出也具有兵器砲筒操作能力的摩根‧雪佛兰，但并非装在突击高达上，而是装在他的惯用机105达加上，以此参与无数场战役。
本机体在波亚兹攻防战中一马当先，立下丰硕的战果。','{"id": 1304000500, "hp": 6313, "en": 70, "attack": 805, "defense": 664, "mobility": 700, "movement": 4, "max_hp": 45451, "max_en": 210, "max_attack": 5796, "max_defense": 4779, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8027, "sp_en": 89, "sp_attack": 1024, "sp_defense": 844, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 57788, "sp_max_en": 267, "sp_max_attack": 7370, "sp_max_defense": 6076, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1304000500, "unit_ssp_initial_release_set_id": 1304000500, "unit_ssp_custom_core_group_id": 1304000500, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130400050001, "unit_ssp_custom_core_group_id": 1304000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400050001, "weapon_change": {"id": 130400050001, "before_weapon_id": 0, "after_weapon_id": 130400050090, "weapon": {"id": 130400050090, "name": "有線式全領域攻擊兵裝「兵器砲筒」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400050090, "attack_attr": 5, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350014, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400050090, "weapon_status": {"id": 130400050090, "range_min": 2, "range_max": 5, "power": 4850, "e