INSERT OR REPLACE INTO "units" VALUES(1304000600,'暴风短剑','暴风达加',2,3,2,0,'10000000030403000','3040','g3040u00600','GAT/A-01E2',1,1,1,1,5839,72,649,585,718,4,42036,215,4671,4212,5169,4,57557,294,6396,5768,7077,4,3,1,3,1,2,'地球联合军量产型MS105达加的衍生机。
参考了暴风高达，将105达加装上突击装备背包，针对砲击战强化性能的机体。
在设计阶段发现光是替换背包无法完全对应，因此也对机体本身进行改良。
即便如此，由于与105达加有许多共用零件，故能在同一生产线进行生产。
起初也考虑了瘟神高达的武装，但判断重武装不利于量产后，采用与暴风高达相同的兵器构成。','{"id": 1304000600, "hp": 5839, "en": 72, "attack": 649, "defense": 585, "mobility": 718, "movement": 4, "max_hp": 42036, "max_en": 215, "max_attack": 4671, "max_defense": 4212, "max_mobility": 5169, "max_movement": 4, "sp_hp": 7994, "sp_en": 98, "sp_attack": 889, "sp_defense": 801, "sp_mobility": 983, "sp_movement": 4, "sp_max_hp": 57557, "sp_max_en": 294, "sp_max_attack": 6396, "sp_max_defense": 5768, "sp_max_mobility": 7077, "sp_max_movement": 4}','{"unit_id": 1304000600, "unit_ssp_initial_release_set_id": 1304000600, "unit_ssp_custom_core_group_id": 1304000600, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 130400060001, "unit_ssp_custom_core_group_id": 1304000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400060001, "weapon_change": {"id": 130400060001, "before_weapon_id": 0, "after_weapon_id": 130400060090, "weapon": {"id": 130400060090, "name": "94mm高輸出收束火線步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400060090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400060090, "weapon_status": {"id": 130400060090, "range_min": 2, "range_max": 5, "po