INSERT OR REPLACE INTO "units" VALUES(1304000700,'M1A异端','M1A迷惘高达',2,1,2,0,'10000000030403000','3040','g3040u00700','MBF-M1A',1,1,1,1,6151,65,785,585,617,4,44283,186,5650,4212,4671,4,60633,254,7736,5768,6396,4,3,1,3,1,2,'奥布军M1迷惘高达的衍生机。
为了防卫奥布的静止轨道太空站「天之御柱」而开发的宇宙战用M1迷惘高达。
因为活动领域仅预设在宇宙空间，将脚部构造大幅简略，只能进行最低限度的步行，但控制姿势用的AMBAC运作时的反应性提升了30%。
另外也加装并强化推进器，背部装上新型推进剂及冷却剂的储藏槽。
主武装为狙击型镭射步枪，是开发作为在轨道上执行超长距离射击用的武器，因此内藏高准度感应器及资料连动型的瞄准系统，能发挥极高的准绳度。
有少量分配给搭乘草薙号的驾驶员，人称「拳神」的巴瑞‧何也是驾驶本机体立下丰硕的战果。','{"id": 1304000700, "hp": 6151, "en": 65, "attack": 785, "defense": 585, "mobility": 617, "movement": 4, "max_hp": 44283, "max_en": 186, "max_attack": 5650, "max_defense": 4212, "max_mobility": 4671, "max_movement": 4, "sp_hp": 8422, "sp_en": 89, "sp_attack": 1075, "sp_defense": 801, "sp_mobility": 844, "sp_movement": 4, "sp_max_hp": 60633, "sp_max_en": 254, "sp_max_attack": 7736, "sp_max_defense": 5768, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1304000700, "unit_ssp_initial_release_set_id": 1304000700, "unit_ssp_custom_core_group_id": 1304000700, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 130400070001, "unit_ssp_custom_core_group_id": 1304000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400070001, "weapon_change": {"id": 130400070001, "before_weapon_id": 0, "after_weapon_id": 130400070090, "weapon": {"id": 130400070090, "name": "71-44式改狙擊型鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400070090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400070090, "weapon_status": {"id": 130400070090, "range_min": 2, "range_max": 4, "