INSERT OR REPLACE INTO "units" VALUES(1304000800,'决斗短剑','决斗达加',2,1,2,0,'10000000030403000','3040','g3040u00800','GAT-01D1',1,1,1,1,6500,65,747,554,652,4,46800,194,5372,3986,4690,4,64080,265,7355,5458,6421,4,3,1,3,1,2,'地球联合军量产型MS长达加的改装机。
