INSERT OR REPLACE INTO "units" VALUES(1304000900,'决斗短剑 (强化装甲装备型)','决斗达加 (强化装甲装备)',2,1,2,0,'10000000030403000','3040','g3040u00900','GAT-01D1',1,1,1,1,6552,65,747,551,649,4,47175,195,5372,3963,4671,4,64593,267,7355,5426,6396,4,3,1,3,1,2,'决斗达加的追加装甲装备型态。
「强袭护甲」是札多军为强夺来的决斗高达开发的专用装备。体认到其实用性，地球联合军开发了同样的装备「强化装甲」。
本机体是将长达加装上强化装甲，追加了装甲及推进器，并在肩部设置线性加农，火力、防御力和推进力都大幅提升。','{"id": 1304000900, "hp": 6552, "en": 65, "attack": 747, "defense": 551, "mobility": 649, "movement": 4, "max_hp": 47175, "max_en": 195, "max_attack": 5372, "max_defense": 3963, "max_mobility": 4671, "max_movement": 4, "sp_hp": 8972, "sp_en": 89, "sp_attack": 1022, "sp_defense": 754, "sp_mobility": 889, "sp_movement": 4, "sp_max_hp": 64593, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 5426, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1304000900, "unit_ssp_initial_release_set_id": 1304000900, "unit_ssp_custom_core_group_id": 1304000900, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 130400090001, "unit_ssp_custom_core_group_id": 1304000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400090001, "weapon_change": {"id": 130400090001, "before_weapon_id": 0, "after_weapon_id": 130400090090, "weapon": {"id": 130400090090, "name": "強化裝甲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400090090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 180006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400090090, "weapon_status": {"id": 130400090090, "range_min": 2, "range_max": 5, "