INSERT OR REPLACE INTO "units" VALUES(1304001000,'高机动型基恩','高机动型捷武',2,3,2,0,'10000000030403000','3040','g3040u01000','ZGMF-1017M',1,1,1,1,6526,65,618,648,683,4,46988,205,4446,4662,4680,4,64337,281,6088,6383,6408,4,3,1,3,1,2,'札多军量产型MS捷武的高机动衍生机。
为了提升机动性和续航距离，强化并增加了推进器的数量。
作为填补札多的新型主力机基捷开发延误的战力缺口，虽然未配备镭射兵器等特殊装备，但由於单纯以既有技术构成，因此机体的安定性很高。
以捷武为基础，故操作性良好，分配到本机体的驾驶员对其评价也都很高，基捷开始生产后也鲜少有人要求更换配置。
量产型1号机由拉‧鲁‧古鲁谢驾驶，立下丰硕的战果，并多次与穆‧拉‧布拉加驾驶的米别斯零式展开激烈的战斗。','{"id": 1304001000, "hp": 6526, "en": 65, "attack": 618, "defense": 648, "mobility": 683, "movement": 4, "max_hp": 46988, "max_en": 205, "max_attack": 4446, "max_defense": 4662, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8936, "sp_en": 89, "sp_attack": 846, "sp_defense": 887, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 64337, "sp_max_en": 281, "sp_max_attack": 6088, "sp_max_defense": 6383, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1304001000, "unit_ssp_initial_release_set_id": 1304001000, "unit_ssp_custom_core_group_id": 1304001000, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 130400100001, "unit_ssp_custom_core_group_id": 1304001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400100001, "weapon_change": {"id": 130400100001, "before_weapon_id": 0, "after_weapon_id": 130400100090, "weapon": {"id": 130400100090, "name": "JDP2-MMX22 試製27mm機甲突擊槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400100090, "weapon_status": {"id": 130400100090, "range_min": 1, 