INSERT OR REPLACE INTO "units" VALUES(1304001100,'光束武器试验型席古','镭射武器试验型捷高',3,1,2,0,'10000000030403000','3040','g3040u01100','YFX-200',1,1,1,1,6986,70,805,667,630,4,50300,189,5796,4798,5040,4,63952,241,7370,6100,6408,4,3,1,3,1,2,'札多军量产型MS捷高的衍生机。
札多军利用从「GAT-X系列」取得的技术，将试验性开发的镭射兵器搭载到捷高上的测试机。
初期型镭射组件为了优先确保动作的安定性，导致震动组件全长超过10m。
为了因应搭载巨大组件造成的负荷增加，动力组件及冷却系统也换成改良高输出型。
由于镭射砲的性能符合期待，之后开发的镭射兵器都是以此组件为基础。
负责开发震动系统的志保‧哈尼夫斯在开发结束后被分配到尊路队，驾驶本机体参与了扬京‧杜埃攻防战。','{"id": 1304001100, "hp": 6986, "en": 70, "attack": 805, "defense": 667, "mobility": 630, "movement": 4, "max_hp": 50300, "max_en": 189, "max_attack": 5796, "max_defense": 4798, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 1024, "sp_defense": 848, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 241, "sp_max_attack": 7370, "sp_max_defense": 6100, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1304001100, "unit_ssp_initial_release_set_id": 1304001100, "unit_ssp_custom_core_group_id": 1304001100, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 130400110001, "unit_ssp_custom_core_group_id": 1304001100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400110001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400110001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400110001, "weapon_change": {"id": 130400110001, "before_weapon_id": 0, "after_weapon_id": 130400110090, "weapon": {"id": 130400110090, "name": "JDP8-MSY0270 試製指向性熱能砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400110090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400110090, "weapon_status": {"id": 130400110090, "range_min": 1, "rang