INSERT OR REPLACE INTO "units" VALUES(1304001210,'剑装灾厄高达','巨剑型瘟神高达',4,1,40,0,'10000000030403000','3040','g3040u01200','GAT-X133',1,1,1,1,7984,88,1008,833,880,5,57481,264,7258,5996,6336,5,58134,267,7340,6064,6408,5,3,1,3,3,2,'地球联合军的瘟神高达的衍生机种。
在瘟神高达的开发过程中，作为以开发出万能机为目的的「再造1416计划」其中一环而诞生的机体。
与原型机相比最值得一提的变更点在于，将主力兵器长距离镭射砲「冲击」换成巨大对舰刀「枪刀」。
另外也继承了重剑型突击装备搭载的镭射回力镖和火箭锚等，相较于擅长中、远距离砲击战的原型机，是重视格斗战的机体。
本机体与瘟神几乎同一时期开发完成，共制造了三架，其中两架试验性投入维多利亚基地夺回作战。','{"id": 1304001210, "hp": 7984, "en": 88, "attack": 1008, "defense": 833, "mobility": 880, "movement": 5, "max_hp": 57481, "max_en": 264, "max_attack": 7258, "max_defense": 5996, "max_mobility": 6336, "max_movement": 5, "sp_hp": 8075, "sp_en": 89, "sp_attack": 1020, "sp_defense": 843, "sp_mobility": 890, "sp_movement": 5, "sp_max_hp": 58134, "sp_max_en": 267, "sp_max_attack": 7340, "sp_max_defense": 6064, "sp_max_mobility": 6408, "sp_max_movement": 5}','{"unit_id": 1304001210, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1304001210, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130400121001, "unit_ssp_custom_core_group_id": 1304001210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130400121001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130400121001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130400121001, "weapon_change": {"id": 130400121001, "before_weapon_id": 0, "after_weapon_id": 130400121090, "weapon": {"id": 130400121090, "name": "15.78m對艦刀「槍刀」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130400121090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240005, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130400121090, "weapon_status": {"id": 130400121090, "range_min": 1, "range_max": 3, "power": 