INSERT OR REPLACE INTO "units" VALUES(1305000100,'异端高达红色机','迷惘高达红色机',2,2,2,0,'10000000030503000','3050','g3050u00100','MBF-P02',1,1,1,1,7490,56,618,748,584,4,53928,176,4446,5382,3971,4,73840,241,6088,7370,5436,4,3,1,3,1,2,'奥布的摩根雷堤社流用「GAT-X系列」的资料所开发的试作MS「迷惘高达」系列之一。
虽然放弃采用「PS装甲」，但由于使用发泡金属作为装甲，并大幅削减装甲来减轻机身重量，获得了极为出色的运动性能。
武装方面也有当时札多军MS未采用的可携式镭射兵器。
本机为迷惘高达2号机，是自然人也可操纵MS的实验机，搭载了开发中的试作OS。
虽然在中立殖民地「海利欧波里斯」制造，但由于札多的古鲁谢队与联合军战斗使得殖民地崩坏，之后由废物商的朗‧加路回收并成为他的爱机。
另外，由于镭射军刀会消耗大量能源，因而追加装备了MS用巨大武士刀「菊一文字」作为主要武器。','{"id": 1305000100, "hp": 7490, "en": 56, "attack": 618, "defense": 748, "mobility": 584, "movement": 4, "max_hp": 53928, "max_en": 176, "max_attack": 4446, "max_defense": 5382, "max_mobility": 3971, "max_movement": 4, "sp_hp": 10256, "sp_en": 76, "sp_attack": 846, "sp_defense": 1024, "sp_mobility": 800, "sp_movement": 4, "sp_max_hp": 73840, "sp_max_en": 241, "sp_max_attack": 6088, "sp_max_defense": 7370, "sp_max_mobility": 5436, "sp_max_movement": 4}','{"unit_id": 1305000100, "unit_ssp_initial_release_set_id": 1305000100, "unit_ssp_custom_core_group_id": 1305000100, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 130500010001, "unit_ssp_custom_core_group_id": 1305000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500010001, "weapon_change": {"id": 130500010001, "before_weapon_id": 0, "after_weapon_id": 130500010090, "weapon": {"id": 130500010090, "name": "菊一文字 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500010090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280016, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500010090, "weapon_status": {"id": 130500010090, "range_min": 1, "range_max": 2, "power":