INSERT OR REPLACE INTO "units" VALUES(1305000200,'异端高达蓝色机','迷惘高达蓝色机',2,3,2,0,'10000000030503000','3050','g3050u00200','MBF-P03',1,1,1,1,6487,65,619,650,683,4,46707,205,4455,4680,4680,4,63952,281,6100,6408,6408,4,3,1,3,1,2,'奥布的摩根雷堤社流用「GAT-X系列」的资料所开发的试作MS「迷惘高达」系列之一。
虽然放弃采用「PS装甲」，但由于使用发泡金属作为装甲，并大幅削减装甲来减轻机身重量，获得了极为出色的运动性能。
武装方面也有当时札多军MS未采用的可携式镭射兵器。
本机为迷惘高达3号机，开发为选配装备验证机体，搭载OS也输入各式追加装备的资讯。
虽然在中立殖民地「海利欧波里斯」制造，但由于札多的克鲁泽队与联合军战斗使得殖民地崩坏，之后由废物商的朗‧加路尔回收。
之后本机让渡给佣兵部队「蛇尾」的队长丛云劾，并在跟地球联合军与札多军的战斗中立下巨大战果。','{"id": 1305000200, "hp": 6487, "en": 65, "attack": 619, "defense": 650, "mobility": 683, "movement": 4, "max_hp": 46707, "max_en": 205, "max_attack": 4455, "max_defense": 4680, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8883, "sp_en": 89, "sp_attack": 848, "sp_defense": 890, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 281, "sp_max_attack": 6100, "sp_max_defense": 6408, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1305000200, "unit_ssp_initial_release_set_id": 1305000200, "unit_ssp_custom_core_group_id": 1305000200, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 130500020001, "unit_ssp_custom_core_group_id": 1305000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500020001, "weapon_change": {"id": 130500020001, "before_weapon_id": 0, "after_weapon_id": 130500020090, "weapon": {"id": 130500020090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500020090, "weapon_status": {"id": 130500020090, "range_min": 1, "range_max": 4, "power": 