INSERT OR REPLACE INTO "units" VALUES(1305000500,'异端高达金色机','迷惘高达金色机',3,1,2,0,'10000000030503000','3050','g3050u00500','MBF-P01',1,1,1,1,6300,70,805,665,702,4,45360,208,5796,4788,5051,4,57672,265,7370,6088,6421,4,3,1,3,1,2,'奥布的摩根雷堤社流用「GAT-X系列」的资料所开发的试作MS「迷惘高达」系列之一。
虽然放弃采用「PS装甲」，但由于使用发泡金属作为装甲，并大幅削减装甲来减轻机身重量，获得了极为出色的运动性能。
武装方面也有当时札多军MS未采用的可携式镭射兵器。
本机为迷惘高达1号机，与其他迷惘高达不同，手掌搭载地球联合军规格的插座，能够直接使用GAT-X系列的武器。
虽然在中立殖民地「海利欧波里斯」制造，但在札多军袭击殖民地时下令废弃处置。
却被无视命令的隆德‧吉纳‧萨哈克运出，之后落入萨哈克家手中。','{"id": 1305000500, "hp": 6300, "en": 70, "attack": 805, "defense": 665, "mobility": 702, "movement": 4, "max_hp": 45360, "max_en": 208, "max_attack": 5796, "max_defense": 4788, "max_mobility": 5051, "max_movement": 4, "sp_hp": 8010, "sp_en": 89, "sp_attack": 1024, "sp_defense": 846, "sp_mobility": 892, "sp_movement": 4, "sp_max_hp": 57672, "sp_max_en": 265, "sp_max_attack": 7370, "sp_max_defense": 6088, "sp_max_mobility": 6421, "sp_max_movement": 4}','{"unit_id": 1305000500, "unit_ssp_initial_release_set_id": 1305000500, "unit_ssp_custom_core_group_id": 1305000500, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130500050001, "unit_ssp_custom_core_group_id": 1305000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500050001, "weapon_change": {"id": 130500050001, "before_weapon_id": 0, "after_weapon_id": 130500050090, "weapon": {"id": 130500050090, "name": "350mm電磁火箭砲「魔槍」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500050090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500050090, "weapon_status": {"id": 130500050090, "range_min": 2, "range_max": 4, "power": 4900