INSERT OR REPLACE INTO "units" VALUES(1305000610,'异端高达金色机 (独臂)','迷惘高达金色机 (独臂)',2,1,2,0,'10000000030503000','3050','g3050u00600','MBF-P01',1,1,1,1,7056,70,801,595,699,4,50804,210,5762,4284,5030,4,64593,267,7325,5447,6396,4,3,1,3,1,2,'奥布的摩根雷堤公司挪用「GAT-X系列」的资料所开发出的其中一架试作MS「迷惘高达系列」。
