INSERT OR REPLACE INTO "units" VALUES(1305000700,'异端高达金色机 天','迷惘高达金色机 天',4,1,2,0,'10000000030503000','3050','g3050u00700','MBF-P01-Re',1,1,1,1,7616,80,960,719,760,5,54830,228,6912,5174,5760,5,60998,254,7690,5756,6408,5,3,1,3,1,2,'以隆德‧吉纳‧萨哈克的命令下制造出的迷惘高达金色机天加以改修之后的完成型。
相较于未完成状态，背部装备了运用胶体技术来释放敌机能源，并由自机吸收的特殊武器「灾祸生太刀」，以及借由投掷PS装甲素材制造的长枪来攻击的试作武器「灾祸铗𫓴」。
其性能与改造前相比大幅提升，并由隆德‧吉纳‧萨哈克搭乘，让朗‧加路等人吃足苦头。','{"id": 1305000700, "hp": 7616, "en": 80, "attack": 960, "defense": 719, "mobility": 760, "movement": 5, "max_hp": 54830, "max_en": 228, "max_attack": 6912, "max_defense": 5174, "max_mobility": 5760, "max_movement": 5, "sp_hp": 8472, "sp_en": 89, "sp_attack": 1068, "sp_defense": 800, "sp_mobility": 846, "sp_movement": 5, "sp_max_hp": 60998, "sp_max_en": 254, "sp_max_attack": 7690, "sp_max_defense": 5756, "sp_max_mobility": 6408, "sp_max_movement": 5}','{"unit_id": 1305000700, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1305000700, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 130500070001, "unit_ssp_custom_core_group_id": 1305000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500070001, "weapon_change": {"id": 130500070001, "before_weapon_id": 0, "after_weapon_id": 130500070090, "weapon": {"id": 130500070090, "name": "攻盾系統「三犄改」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500070090, "attack_attr": 2, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280016, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500070090, "weapon_status": {"id": 130500070090, "range_min": 1, "range_max": 4, "power": 5050, "en