INSERT OR REPLACE INTO "units" VALUES(1305000900,'伊莱杰专用基恩改','伊莱杰专用捷武改',2,3,2,0,'10000000030503000','3050','g3050u00900','ZGMF-1017',1,1,1,1,6539,65,682,583,683,4,47081,205,4905,4196,4680,4,64465,281,6715,5745,6408,4,3,1,3,1,2,'伊莱杰专用捷武的改修机体。
伊莱杰的捷武在跟前札多的古德‧威亚战斗后中度损毁，将机体修理并改造后的机型。
由于用了威亚的捷武零件来修理，装甲颜色变成红蓝参半。
另外，由于威亚的捷武是改装机型，本机的性能也小幅上升。','{"id": 1305000900, "hp": 6539, "en": 65, "attack": 682, "defense": 583, "mobility": 683, "movement": 4, "max_hp": 47081, "max_en": 205, "max_attack": 4905, "max_defense": 4196, "max_mobility": 4680, "max_movement": 4, "sp_hp": 8954, "sp_en": 89, "sp_attack": 933, "sp_defense": 798, "sp_mobility": 935, "sp_movement": 4, "sp_max_hp": 64465, "sp_max_en": 281, "sp_max_attack": 6715, "sp_max_defense": 5745, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1305000900, "unit_ssp_initial_release_set_id": 1305000900, "unit_ssp_custom_core_group_id": 1305000900, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 130500090001, "unit_ssp_custom_core_group_id": 1305000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500090001, "weapon_change": {"id": 130500090001, "before_weapon_id": 0, "after_weapon_id": 130500090090, "weapon": {"id": 130500090090, "name": "M68貓式500mm無後座力砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500090090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 220001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500090090, "weapon_status": {"id": 130500090090, "range_min": 2, "range_max": 4, "power": 4700, "