INSERT OR REPLACE INTO "units" VALUES(1305001000,'工程用基恩','工程用捷武',1,2,12,0,'10000000030503000','3050','g3050u01000','-',1,1,1,1,7500,52,509,630,600,4,54000,182,3665,4536,3672,4,80100,270,5436,6729,5447,4,3,1,3,1,1,'隶属于废物商公会的作业用MS。
是改造废弃的札多捷武，转用于作业用的机体，由朗‧加路的废物商队伍使用。
背包改为小型，战斗力与机动力较一般的捷武低落，但能做出更为细致的机体操控。
左手换装了作业手，腰部也设置了吊车。
此外，紧急状况时可使用改造梅比乌斯搭载的「对装甲线性枪」，以及红色机用的盾牌来战斗。','{"id": 1305001000, "hp": 7500, "en": 52, "attack": 509, "defense": 630, "mobility": 600, "movement": 4, "max_hp": 54000, "max_en": 182, "max_attack": 3665, "max_defense": 4536, "max_mobility": 3672, "max_movement": 4, "sp_hp": 11125, "sp_en": 77, "sp_attack": 755, "sp_defense": 935, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 80100, "sp_max_en": 270, "sp_max_attack": 5436, "sp_max_defense": 6729, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1305001000, "unit_ssp_initial_release_set_id": 1305001000, "unit_ssp_custom_core_group_id": 1305001000, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 130500100001, "unit_ssp_custom_core_group_id": 1305001000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130500100001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130500100001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130500100001, "weapon_change": {"id": 130500100001, "before_weapon_id": 0, "after_weapon_id": 130500100090, "weapon": {"id": 130500100090, "name": "對裝甲線性砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130500100090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130500100090, "weapon_status": {"id": 130500100090, "range_min": 1, "range_max": 4, "power": 