INSERT OR REPLACE INTO "units" VALUES(1306000110,'重生高达','重生高达',4,1,2,0,'10000306030503000','3060','g3060u00100','ZGMF-X11A',1,1,1,1,7920,88,1017,836,877,4,57024,264,7316,6020,6311,4,57672,267,7399,6088,6383,4,3,1,3,1,2,'札多的试作型可变MS。
札多在夺取地球联合军的圣盾高达后，以其为基础所开发的机体。
除了MS型态，还有突击用的MA型态、MA巡航型态等，三种变形构造。
背包部分才是主体，就算MS部分在战斗中毁损，只要更换零件就能不断再生持续战斗。
而本机与流星的运用方式接近，因此只要是有接点的机体，不论联合或札多的机体都能连结并夺取控制。
此外，推进系统采用了名为「激光推进器」的激光加速系统，能从创世纪α来接收激光点燃推进剂，以此进行超加速。','{"id": 1306000110, "hp": 7920, "en": 88, "attack": 1017, "defense": 836, "mobility": 877, "movement": 4, "max_hp": 57024, "max_en": 264, "max_attack": 7316, "max_defense": 6020, "max_mobility": 6311, "max_movement": 4, "sp_hp": 8010, "sp_en": 89, "sp_attack": 1028, "sp_defense": 846, "sp_mobility": 887, "sp_movement": 4, "sp_max_hp": 57672, "sp_max_en": 267, "sp_max_attack": 7399, "sp_max_defense": 6088, "sp_max_mobility": 6383, "sp_max_movement": 4}','{"unit_id": 1306000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1306000110, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 130600011001, "unit_ssp_custom_core_group_id": 1306000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130600011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130600011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130600011001, "weapon_change": {"id": 130600011001, "before_weapon_id": 0, "after_weapon_id": 130600011090, "weapon": {"id": 130600011090, "name": "強襲模式 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130600011090, "attack_attr": 2, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280005, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130600011090, "weapon_status": {"id": 130600011090, "range_min": 1, "range_max": 3, "power": 5