INSERT OR REPLACE INTO "units" VALUES(1307000110,'异端高达蓝色机 (全武装)','迷惘高达蓝色机 (全武装)',3,1,2,0,'10000307030503000','3070','g3070u00100','MBF-P03',1,1,1,1,7545,75,860,713,674,4,54324,203,6186,5130,5390,4,64465,241,7340,6088,6396,4,3,1,3,1,2,'迷惘高达蓝色机装备了选配装备「全武装」的型态。
