INSERT OR REPLACE INTO "units" VALUES(1307000210,'异端高达蓝色机 (鳞形推进系统)','迷惘高达蓝色机 (鳞形推进系统)',3,3,9,0,'10000307030503000','3070','g3070u00200','MBF-P03',1,1,1,1,7500,76,788,674,788,4,54000,239,5670,4851,5400,4,64080,284,6729,5756,6408,4,1,1,3,1,3,'迷惘高达蓝色机装备了选配装备「鳞型系统」的型态。
机体各处装备了利用微小震动的推进系统「鳞型马达」，因此在水中也有优秀的机动性。
