INSERT OR REPLACE INTO "units" VALUES(1307000410,'异端高达红色机 空战型','迷惘高达红色机 (飞行组件)',4,2,30,0,'10000307030503000','3070','g3070u00400','MBF-P02',1,1,1,1,11000,76,748,923,880,5,79200,267,5386,6640,5386,5,80100,270,5447,6715,5447,5,3,3,3,1,2,'迷惘高达红色机装备飞行组件的型态。
飞行组件是朗独自改造M1迷惘高达的背包而来，装备飞行组件就能大幅提升红色机的飞行能力。
背包两侧的机翼也兼具燃料槽功能，能大幅强化移动距离。
还可由虚拟人格电脑8来操控背包自行飞行，并由红色机抓住背包来在空中移动。','{"id": 1307000410, "hp": 11000, "en": 76, "attack": 748, "defense": 923, "mobility": 880, "movement": 5, "max_hp": 79200, "max_en": 267, "max_attack": 5386, "max_defense": 6640, "max_mobility": 5386, "max_movement": 5, "sp_hp": 11125, "sp_en": 77, "sp_attack": 757, "sp_defense": 933, "sp_mobility": 890, "sp_movement": 5, "sp_max_hp": 80100, "sp_max_en": 270, "sp_max_attack": 5447, "sp_max_defense": 6715, "sp_max_mobility": 5447, "sp_max_movement": 5}','{"unit_id": 1307000410, "unit_ssp_initial_release_set_id": 1307000410, "unit_ssp_custom_core_group_id": 1307000410, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 130700041001, "unit_ssp_custom_core_group_id": 1307000410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130700041001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130700041001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130700041001, "weapon_change": {"id": 130700041001, "before_weapon_id": 0, "after_weapon_id": 130700041090, "weapon": {"id": 130700041090, "name": "鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130700041090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130700041090, "weapon_status": {"id": 130700041090, "range_min": 1, "range_max": 4, "power": 4800, "