INSERT OR REPLACE INTO "units" VALUES(1308000100,'勇士高达','勇士高达',3,3,2,0,'10000308030503000','3080','g3080u00100','YMF-X000A',1,1,1,1,6594,71,734,663,740,4,47474,222,5284,4767,5074,4,60359,282,6717,6061,6451,4,3,1,3,1,2,'札多开发的试作MS。
本机是以基捷为基础，并在头部搭载了「中子干扰调解器」，实现核能动力的试作机体。
具备强大动力，运作时间几乎无限，因此才能搭载「PS装甲」，以及会消耗大量电力的「龙骑兵系统」所运作的远距离遥控武器「鲨式镭射传导砲」。
本机体是由军方独断开发，原本在运用测试结束后便预定分解，除了机密零件外都会予以废弃。
但在西盖尔‧古兰尔的手段下被秘密带出，并在玛尔基奥导师的指引下，成为普雷亚‧雷腓力的座机。','{"id": 1308000100, "hp": 6594, "en": 71, "attack": 734, "defense": 663, "mobility": 740, "movement": 4, "max_hp": 47474, "max_en": 222, "max_attack": 5284, "max_defense": 4767, "max_mobility": 5074, "max_movement": 4, "sp_hp": 8384, "sp_en": 90, "sp_attack": 933, "sp_defense": 842, "sp_mobility": 941, "sp_movement": 4, "sp_max_hp": 60359, "sp_max_en": 282, "sp_max_attack": 6717, "sp_max_defense": 6061, "sp_max_mobility": 6451, "sp_max_movement": 4}','{"unit_id": 1308000100, "unit_ssp_initial_release_set_id": 1308000100, "unit_ssp_custom_core_group_id": 1308000100, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 130800010001, "unit_ssp_custom_core_group_id": 1308000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130800010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130800010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130800010001, "weapon_change": {"id": 130800010001, "before_weapon_id": 0, "after_weapon_id": 130800010090, "weapon": {"id": 130800010090, "name": "鯊式鐳射傳導砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130800010090, "attack_attr": 3, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340042, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130800010090, "weapon_status": {"id": 130800010090, "range_min": 3, "range_max": 5, "power