INSERT OR REPLACE INTO "units" VALUES(1308000200,'勇士高达 (盖兹头)','勇士高达 (基捷头)',2,1,2,0,'10000308030503000','3080','g3080u00200','YMF-X000A',1,1,1,1,6467,66,745,549,654,4,46557,197,5362,3950,4709,4,63747,269,7342,5408,6448,4,3,1,3,1,2,'勇士高达的改修机体。
因为头部在运送到地球途中被佣兵部队蛇尾夺走，故此型态是以基捷的头部替代。
由于失去「中子干扰调解器」而无法使用核引擎，只能使用一般电池，因此将能源消耗量大的「PS装甲」关闭来运用本机。
此外，同样要消耗大量能量的远距离遥控武器「鲨式镭射传导砲」，在使用上也受到限制。
之后蛇尾将机体头部送还。','{"id": 1308000200, "hp": 6467, "en": 66, "attack": 745, "defense": 549, "mobility": 654, "movement": 4, "max_hp": 46557, "max_en": 197, "max_attack": 5362, "max_defense": 3950, "max_mobility": 4709, "max_movement": 4, "sp_hp": 8854, "sp_en": 90, "sp_attack": 1020, "sp_defense": 752, "sp_mobility": 896, "sp_movement": 4, "sp_max_hp": 63747, "sp_max_en": 269, "sp_max_attack": 7342, "sp_max_defense": 5408, "sp_max_mobility": 6448, "sp_max_movement": 4}','{"unit_id": 1308000200, "unit_ssp_initial_release_set_id": 1308000200, "unit_ssp_custom_core_group_id": 1308000200, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 130800020001, "unit_ssp_custom_core_group_id": 1308000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130800020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130800020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130800020001, "weapon_change": {"id": 130800020001, "before_weapon_id": 0, "after_weapon_id": 130800020090, "weapon": {"id": 130800020090, "name": "大型鐳射軍刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130800020090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240002, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130800020090, "weapon_status": {"id": 130800020090, "range_min": 1, "range_max": 2, "power": 4850, "en": 61, "hit_rate": 105