INSERT OR REPLACE INTO "units" VALUES(1308000300,'海伯瑞安高达1号机','亥伯龙高达',4,1,2,0,'10000308030503000','3080','g3080u00300','CAT1-X1/3',1,1,1,1,8002,80,921,761,725,5,57612,216,6627,5476,5796,5,64093,240,7373,6092,6448,5,3,1,3,1,2,'欧亚联邦开发的试作MS。
隶属于地球联合的欧亚联邦，在获得民间企业阿克泰昂工业的技术协助后，独自开发的机体。
机体继承了大西洋联邦开发的「GAT-X系列」的特征，并加上了欧亚联邦擅长的光波防御带科技。
最大特征是双手及背包搭载的「装甲光罩」，能在机体周遭展开镭射盾牌，近乎完全无效外部的攻击。
由于展开盾牌要消耗大量能量，启动时间只有不到300秒，但也能用在近距离战斗，在攻守方面都能发挥出色性能。
本机是三架试作机体的一号机，由超级调整者实验体的卡纳得‧帕尔斯驾驶，并跟红色机等「高达」展开激烈战斗。','{"id": 1308000300, "hp": 8002, "en": 80, "attack": 921, "defense": 761, "mobility": 725, "movement": 5, "max_hp": 57612, "max_en": 216, "max_attack": 6627, "max_defense": 5476, "max_mobility": 5796, "max_movement": 5, "sp_hp": 8902, "sp_en": 89, "sp_attack": 1024, "sp_defense": 847, "sp_mobility": 806, "sp_movement": 5, "sp_max_hp": 64093, "sp_max_en": 240, "sp_max_attack": 7373, "sp_max_defense": 6092, "sp_max_mobility": 6448, "sp_max_movement": 5}','{"unit_id": 1308000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1308000300, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 130800030001, "unit_ssp_custom_core_group_id": 1308000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130800030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130800030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130800030001, "weapon_change": {"id": 130800030001, "before_weapon_id": 0, "after_weapon_id": 130800030090, "weapon": {"id": 130800030090, "name": "鐳射加農「自傲式」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130800030090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130800030090, "weapon_status": {"id": 130800030090, "range_min": 2, "range_max": 4, "power