INSERT OR REPLACE INTO "units" VALUES(1308000400,'X异端','X迷惘高达',4,3,2,0,'10000308030503000','3080','g3080u00400','YMF-X000A',1,1,1,1,8028,80,838,723,837,5,57802,251,6033,5201,5740,5,64305,279,6712,5786,6385,5,3,1,3,1,2,'勇士高达装上追加装备后的型态。
机体背部装备了四具大型龙骑兵组件。
龙骑兵组件是朗从安德列‧包扑菲杜获得设计资料后，在「天之御柱」制造并安装。
各龙骑兵组件与本体用缆线连结并供应能量，因此也可使用PS装甲。
此装备也可在大量砲塔间展开镭射形成防御力场。
本机体虽是兵器却以和平为使用目的，因此朗从偏离正道（迷惘）与机体背后的X型龙骑兵组件，将本机命名为X迷惘高达。
本机体由普雷亚‧雷腓力来运用，并跟脱离欧亚联邦的超级亥伯龙高达战斗，发挥出了强大能力。','{"id": 1308000400, "hp": 8028, "en": 80, "attack": 838, "defense": 723, "mobility": 837, "movement": 5, "max_hp": 57802, "max_en": 251, "max_attack": 6033, "max_defense": 5201, "max_mobility": 5740, "max_movement": 5, "sp_hp": 8932, "sp_en": 89, "sp_attack": 933, "sp_defense": 804, "sp_mobility": 932, "sp_movement": 5, "sp_max_hp": 64305, "sp_max_en": 279, "sp_max_attack": 6712, "sp_max_defense": 5786, "sp_max_mobility": 6385, "sp_max_movement": 5}','{"unit_id": 1308000400, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1308000400, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 130800040001, "unit_ssp_custom_core_group_id": 1308000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130800040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130800040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130800040001, "weapon_change": {"id": 130800040001, "before_weapon_id": 0, "after_weapon_id": 130800040090, "weapon": {"id": 130800040090, "name": "龍騎兵系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130800040090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350031, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130800040090, "weapon_status": {"id": 130800040090, "range_min": 3, "range_max": 5, "power": 4950, "en"