INSERT OR REPLACE INTO "units" VALUES(1308000500,'超级海伯瑞安高达','超级亥伯龙高达',4,2,2,1,'10000308030503000','3080','g3080u00500','CAT1-X1/3',1,1,1,1,11875,80,1082,1000,857,4,85500,254,7785,7197,5826,4,80100,238,7293,6742,5458,4,3,1,3,1,2,'亥伯龙高达1号机的改修机型。
是搭载核引擎为动力的亥伯龙高达。
卡纳得‧帕尔斯将机体从阿耳忒弥斯要塞夺走后，从月面托勒密基地抢夺「中子干扰调解器」，并在机体后裙甲加装核引擎。
由于获得近乎无限的能源，「装甲光罩」也可无限制使用。
本机用在跟普雷亚‧雷腓力的X迷惘高达的最后决战，双方展开激烈战斗。','{"id": 1308000500, "hp": 11875, "en": 80, "attack": 1082, "defense": 1000, "mobility": 857, "movement": 4, "max_hp": 85500, "max_en": 254, "max_attack": 7785, "max_defense": 7197, "max_mobility": 5826, "max_movement": 4, "sp_hp": 11125, "sp_en": 75, "sp_attack": 1013, "sp_defense": 937, "sp_mobility": 803, "sp_movement": 4, "sp_max_hp": 80100, "sp_max_en": 238, "sp_max_attack": 7293, "sp_max_defense": 6742, "sp_max_mobility": 5458, "sp_max_movement": 4}','null','超級亥伯龍高達','scrape',1791488368,'v2026.10.08',NULL);
