INSERT OR REPLACE INTO "units" VALUES(1308000502,'超级海伯瑞安高达','超级亥伯龙高达',5,2,2,1,'10000308030503000','3080','g3080u00502','CAT1-X1/3',1,1,1,1,15000,101,1366,1263,1083,5,108000,321,9834,9091,7359,5,108000,321,9834,9091,7359,5,3,1,3,1,2,'-','{"id": 1308000502, "hp": 15000, "en": 101, "attack": 1366, "defense": 1263, "mobility": 1083, "movement": 5, "max_hp": 108000, "max_en": 321, "max_attack": 9834, "max_defense": 9091, "max_mobility": 7359, "max_movement": 5, "sp_hp": 15000, "sp_en": 101, "sp_attack": 1366, "sp_defense": 1263, "sp_mobility": 1083, "sp_movement": 5, "sp_max_hp": 108000, "sp_max_en": 321, "sp_max_attack": 9834, "sp_max_defense": 9091, "sp_max_mobility": 7359, "sp_max_movement": 5}','null','超級亥伯龍高達','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1308000600,'海伯瑞安高达2号机','亥伯龙高达2号机',3,2,2,0,'10000308030503000','3080','g3080u00600','CAT1-X2/3',1,1,1,1,8030,60,662,812,634,4,57810,189,4763,5843,4307,4,73501,240,6056,7429,5476,4,3,1,3,1,2,'欧亚联邦开发的试作MS。
隶属于地球联合的欧亚联邦，在获得民间企业阿克泰昂工业的技术协助后，独自开发的机体。
机体继承了大西洋联邦开发的「GAT-X系列」的特征，并加上了欧亚联邦擅长的光波防御带科技。
最大特征是双手及背包搭载的「装甲光罩」，能在机体周遭展开镭射盾牌，近乎完全无效外部的攻击。
由于展开盾牌要消耗大量能量，启动时间只有不到300秒，但也能用在近距离战斗，在攻守方面都能发挥出色性能。
本机是三架试作机体的二号机，跟以白色为基调的一号机不同，采用灰色为主要配色。
由巴尔札姆‧艾连德搭乘，并用来追击驾驶一号机一同脱逃的卡纳得‧帕尔斯。','{"id": 1308000600, "hp": 8030, "en": 60, "attack": 662, "defense": 812, "mobility": 634, "movement": 4, "max_hp": 57810, "max_en": 189, "max_attack": 4763, "max_defense": 5843, "max_mobility": 4307, "max_movement": 4, "sp_hp": 10209, "sp_en": 76, "sp_attack": 842, "sp_defense": 1032, "sp_mobility": 806, "sp_movement": 4, "sp_max_hp": 73501, "sp_max_en": 240, "sp_max_attack": 6056, "sp_max_defense": 7429, "sp_max_mobility": 5476, "sp_max_movement": 4}','{"unit_id": 1308000600, "unit_ssp_initial_release_set_id": 1308000600, "unit_ssp_custom_core_group_id": 1308000600, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 130800060001, "unit_ssp_custom_core_group_id": 1308000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 130800060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 130800060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 130800060001, "weapon_change": {"id": 130800060001, "before_weapon_id": 0, "after_weapon_id": 130800060090, "weapon": {"id": 130800060090, "name": "RFW-99鐳射衝鋒槍「札斯塔瓦 聖痕式」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 130800060090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 160005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 130800060090, "weapon_status": {"id": 130800060090, "range_min": 1, "range_max": 4, 