INSERT OR REPLACE INTO "units" VALUES(1310000100,'盖兹强袭型(希瓦专用机)','基捷强袭型(希瓦专用机)',3,1,2,0,'10000000031003000','3100','g3100u00100','ZGMF-600AS',1,1,1,1,7028,70,804,595,699,5,50602,210,5785,4284,5030,5,64337,267,7355,5447,6396,5,3,1,3,1,2,'梅亚‧希瓦以柏齐‧察拉的亲信身份当上扬京‧杜埃防卫舰队司令，本机为改装成她专用的基捷。
装备了基捷用的强袭护甲，提升了机动性与防御力。
而基底的机体本身也经过身为MS开发人员的希瓦调整，唯有当她驾驶时，才能发挥出高超性能，成为正如其名的专用机。
主要武装拥有独自开发的镭射三叉戟「三股叉」。
另外也进行了试作武装「达摩鲁鼓」的运用测试。
「达摩鲁鼓」的灵感来自创世，为圆筒状的武器。
「达摩鲁鼓」被镭射砲击中后可将镭射汇聚于内部，进行转换后再度发射。
此时重新发射的镭射十分强力。','{"id": 1310000100, "hp": 7028, "en": 70, "attack": 804, "defense": 595, "mobility": 699, "movement": 5, "max_hp": 50602, "max_en": 210, "max_attack": 5785, "max_defense": 4284, "max_mobility": 5030, "max_movement": 5, "sp_hp": 8936, "sp_en": 89, "sp_attack": 1022, "sp_defense": 757, "sp_mobility": 889, "sp_movement": 5, "sp_max_hp": 64337, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 5447, "sp_max_mobility": 6396, "sp_max_movement": 5}','{"unit_id": 1310000100, "unit_ssp_initial_release_set_id": 1310000100, "unit_ssp_custom_core_group_id": 1310000100, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 131000010001, "unit_ssp_custom_core_group_id": 1310000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 131000010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 131000010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 131000010001, "weapon_change": {"id": 131000010001, "before_weapon_id": 0, "after_weapon_id": 131000010090, "weapon": {"id": 131000010090, "name": "高能收束轉換裝置「達摩魯鼓」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 131000010090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 131000010090, "weapon_status": {"id": 131000010090, "range_min": 3, "range_max": 4, "power": 5000, "en": 63, "hit