INSERT OR REPLACE INTO "units" VALUES(1310000200,'赛伊盖尔','赛伊盖尔',3,1,46,0,'10000000031003000','3100','g3100u00200','YMAF-X4BD',1,1,1,1,7014,70,807,664,630,4,50501,188,5808,4779,5040,4,64209,238,7384,6076,6408,4,3,3,2,3,2,'地球联合军为了实现既有的MA理念「足以单机完成任务的火力」、「与战斗机同级的机动力」、「防御攻击的重装甲」所试作的大型MA。
主砲的强大火力、大气层内的飞行能力、阳电子反射，为了实现此三项特征，本机搭载了多个大型电池。
然而，即使如此由于动力还是不稳定，存在著重大缺陷，在输出功率低落时，主砲、飞行能力、阳电子反射其中一项将无法使用，因而被半闲置在地球联合军的维多利亚基地机库之中。
本机的设计构想近似于后来开发的YMAF-X6BD撒姆沙。
共有五处装备了阳电子产生装置，可以根据敌人攻击，朝任意方向展开阳电子反射。
但是由于尚处试作阶段，加上有功率问题，只能对产生器展开的单一方向生成盾牌。
机体尽管有各种缺陷，仍在维多利亚基地摸索改善方案、勉强继续开发，但在察拉派残党的袭击事件之际，被认为可在短时间内有效防卫据点，因而被迫出击。','{"id": 1310000200, "hp": 7014, "en": 70, "attack": 807, "defense": 664, "mobility": 630, "movement": 4, "max_hp": 50501, "max_en": 188, "max_attack": 5808, "max_defense": 4779, "max_mobility": 5040, "max_movement": 4, "sp_hp": 8918, "sp_en": 89, "sp_attack": 1026, "sp_defense": 844, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 64209, "sp_max_en": 238, "sp_max_attack": 7384, "sp_max_defense": 6076, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1310000200, "unit_ssp_initial_release_set_id": 1310000200, "unit_ssp_custom_core_group_id": 1310000200, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 131000020001, "unit_ssp_custom_core_group_id": 1310000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 131000020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 131000020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 131000020001, "weapon_change": {"id": 131000020001, "before_weapon_id": 0, "after_weapon_id": 131000020090, "weapon": {"id": 131000020090, "name": "M526 複列位相能量砲「馬爾夏克」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 131000020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 131000020090, "weapon_status": {"id": 131000020090, "