INSERT OR REPLACE INTO "units" VALUES(1310000300,'龙骑兵突击高达','龙骑兵突击高达',4,1,30,0,'10000000031003000','3100','g3100u00300','MBF-03+P208QX',1,1,1,1,7172,80,919,765,800,5,51633,240,6611,5505,5760,5,57442,267,7355,6125,6408,5,3,3,3,1,2,'在上次大战中残存的GAT-X105突击高达使用了卡嘉莲提供的突击高达‧红备用零件重建的机体。
相转移装甲启动时，装甲颜色以联合的突击高达为准。
而双眼则因为使用的是突击高达‧红的备用零件，呈现绿色。
设计性能与GAT-X105初代突击高达同级，有时会跟不上成长为王牌驾驶员的基拉的能力。
尽管如此，将磨耗、劣化的零件更换为新品后，在反应速度与耐久度上还是勉强保持在高水准的设计性能。
龙骑兵突击装备的由来，是基拉与天意高达交战时得知了龙骑兵系统，他希望实验性采用该系统，使用联合试图运用龙骑兵而试作的突击背包设计资料，与奥布一同在Factory完成。
从运用了四座线控式兵器砲筒的AQM/E-X04砲筒型突击装备进化，装备了三座完全分离式的龙骑兵。
在设计阶段时，确认到突击高达的动力炉功率不足，于是便连结了数个完美突击高达也有搭载的电池背包，强硬解决并成功实用化。
虽然能源效率有问题，但火力无可挑剔，失去自由高达的基拉获得了能处理紧急情况的机体，能驾驶搭载龙骑兵的机体累积战斗经验，就这方面来说仍是有意义的机体。
基拉搭上突击自由高达后，之所以能立刻适应龙骑兵系统，推测可能是活用了搭乘本机进行事前验证的经验。','{"id": 1310000300, "hp": 7172, "en": 80, "attack": 919, "defense": 765, "mobility": 800, "movement": 5, "max_hp": 51633, "max_en": 240, "max_attack": 6611, "max_defense": 5505, "max_mobility": 5760, "max_movement": 5, "sp_hp": 7978, "sp_en": 89, "sp_attack": 1022, "sp_defense": 851, "sp_mobility": 890, "sp_movement": 5, "sp_max_hp": 57442, "sp_max_en": 267, "sp_max_attack": 7355, "sp_max_defense": 6125, "sp_max_mobility": 6408, "sp_max_movement": 5}','{"unit_id": 1310000300, "unit_ssp_initial_release_set_id": 1310000300, "unit_ssp_custom_core_group_id": 1310000300, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 131000030001, "unit_ssp_custom_core_group_id": 1310000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 131000030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 131000030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 131000030001, "weapon_change": {"id": 131000030001, "before_weapon_id": 0, "after_weapon_id": 131000030090, "weapon": {"id": 131000030090, "name": "龍騎兵系統 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 131000030090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340010, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 131000030090, "weapon_status": {"id": 131000030090, "range_min": 2, "range_max": 5, "pow