INSERT OR REPLACE INTO "units" VALUES(1310000400,'村雨 飞行能力试验型','姆拉沙美 飞行能力试验型',4,3,30,0,'10000000031003000','3100','g3100u00400','MVF-P11-1428T',1,1,1,1,7200,89,800,719,880,4,51840,267,5760,5174,6336,4,57672,297,6408,5756,7049,4,3,3,3,1,2,'以往奥布军的理念是专守防卫，然而在地球联合军的侵略中吞败的他们被迫要改变理念，加强了在敌人逼近本土前就进行打击的积极防御思想。
因此运用具备远征能力的航母变得不可或缺，他们于是开始研拟要开发能作为航母舰载机的主力机体。
在这个过程中，他们研讨了数个计划，同时多方试作，而本机是以量产为前提开发的姆拉沙美试验机之一，也是从众多资料上的设计图制造出来的试验用实机之一。
由于是试验用，机翼等部分零件为可替换品，借此让一架机体尽可能进行多种试验。
亚斯兰接受莉古丝委托，处理降落地球上的察拉派残党，考虑到任务性质，借用给他的机型选择了能长时间活动，也适合长距离飞行的零件。
另外，机体性能也非常高，但也导致难以驾驭，若非王牌级的驾驶员则无法发挥出其原本的性能。
结果而言，这些试验用零件并没有被量产的姆拉沙美采用。
然而成功收集了宝贵的实战运作资料，在这些资料的帮助下，完成了姆拉沙美的制式量产机。','{"id": 1310000400, "hp": 7200, "en": 89, "attack": 800, "defense": 719, "mobility": 880, "movement": 4, "max_hp": 51840, "max_en": 267, "max_attack": 5760, "max_defense": 5174, "max_mobility": 6336, "max_movement": 4, "sp_hp": 8010, "sp_en": 99, "sp_attack": 890, "sp_defense": 800, "sp_mobility": 979, "sp_movement": 4, "sp_max_hp": 57672, "sp_max_en": 297, "sp_max_attack": 6408, "sp_max_defense": 5756, "sp_max_mobility": 7049, "sp_max_movement": 4}','{"unit_id": 1310000400, "unit_ssp_initial_release_set_id": 1310000400, "unit_ssp_custom_core_group_id": 1310000400, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 131000040001, "unit_ssp_custom_core_group_id": 1310000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 131000040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 131000040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 131000040001, "weapon_change": {"id": 131000040001, "before_weapon_id": 0, "after_weapon_id": 131000040090, "weapon": {"id": 131000040090, "name": "72D5式鐳射步槍「百雷」 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 131000040090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 131000040090, "weapon_status": {"id": 131000040090, "range_min": 2, "range_max": 5, "pow