INSERT OR REPLACE INTO "units" VALUES(1333000100,'命运型脉冲高达','命运型冲击高达',4,1,30,0,'10000000033303300','3330','g3330u00100','ZGMF-X56S/θ',1,1,1,1,7662,81,956,719,760,5,55164,229,6882,5176,5759,5,61370,255,7656,5758,6407,5,3,3,3,1,2,'冲击高达的换装型态之一。
是冲击高达装备以「对应各种战况的万能兵器」来开发的「命运型魅影背包」的型态，本体也有部分进行了改良。
具有强攻型、双剑型、爆破型各魅影背包的特性，防御上也在手甲装备了镭射盾牌产生装置，攻防两方面都有极为出色的能力。
但由于各种重装备使机体承受巨大负担，以「伸缩砲筒延伸式镭射砲塔」为首的各种武装也都偏重镭射武器，因此一次战斗中就得进行数次重氢镭射充电。
也因此，在试作开发四架机体后便中止生产，由新开发的命运高达继承名称与机体设计理念。','{"id": 1333000100, "hp": 7662, "en": 81, "attack": 956, "defense": 719, "mobility": 760, "movement": 5, "max_hp": 55164, "max_en": 229, "max_attack": 6882, "max_defense": 5176, "max_mobility": 5759, "max_movement": 5, "sp_hp": 8524, "sp_en": 90, "sp_attack": 1064, "sp_defense": 800, "sp_mobility": 846, "sp_movement": 5, "sp_max_hp": 61370, "sp_max_en": 255, "sp_max_attack": 7656, "sp_max_defense": 5758, "sp_max_mobility": 6407, "sp_max_movement": 5}','{"unit_id": 1333000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1333000100, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 133300010001, "unit_ssp_custom_core_group_id": 1333000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133300010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133300010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133300010001, "weapon_change": {"id": 133300010001, "before_weapon_id": 0, "after_weapon_id": 133300010090, "weapon": {"id": 133300010090, "name": "MMI-710 石中劍激光對艦刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133300010090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280010, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133300010090, "weapon_status": {"id": 133300010090, "range_min": 1, "range_max": 3, "power": 5