INSERT OR REPLACE INTO "units" VALUES(1336000100,'漆黑强袭高达','漆黑突击高达',4,1,30,0,'10000000033603300','3360','g3360u00100','GAT-X105E+AQM/E-X09S',1,1,1,1,7194,81,914,767,798,5,51794,242,6576,5519,5741,5,57621,269,7316,6140,6387,5,3,3,3,1,2,'隶属于地球联合军特殊部队「幻痛」的突击高达再生产机。
本机是基于「第一期GAT-X系列」的再生计划「阿克泰昂计划」，将以突击高达为基础所开发的突击高达E型，再装备上专用的「漆黑突击装备背包」而成的机体。
机体搭载「可变式相转移装甲」及强化型动力组件「扩充电源」，强化了防御性能并延长运作时间。此外，透过改良OS与操作介面，操作性亦获得提升。
武器方面则装备了有著出色连射性能，并在近距离战斗也能灵活操作、效果出众的「短镭射步枪」，以及可与漆黑突击装备背包翼部兼用的大型刀「光神应答剑三式镭射刀」等武器，大幅强化了格斗性能。','{"id": 1336000100, "hp": 7194, "en": 81, "attack": 914, "defense": 767, "mobility": 798, "movement": 5, "max_hp": 51794, "max_en": 242, "max_attack": 6576, "max_defense": 5519, "max_mobility": 5741, "max_movement": 5, "sp_hp": 8003, "sp_en": 90, "sp_attack": 1017, "sp_defense": 853, "sp_mobility": 887, "sp_movement": 5, "sp_max_hp": 57621, "sp_max_en": 269, "sp_max_attack": 7316, "sp_max_defense": 6140, "sp_max_mobility": 6387, "sp_max_movement": 5}','{"unit_id": 1336000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1336000100, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 133600010001, "unit_ssp_custom_core_group_id": 1336000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600010001, "weapon_change": {"id": 133600010001, "before_weapon_id": 0, "after_weapon_id": 133600010090, "weapon": {"id": 133600010090, "name": "M8F-SB1 短鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600010090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600010090, "weapon_status": {"id": 133600010