INSERT OR REPLACE INTO "units" VALUES(1336000300,'蔚蓝决斗高达','蔚蓝决斗高达',3,3,2,0,'10000000033603300','3360','g3360u00300','GAT-X1022',1,1,1,1,7014,71,739,631,730,5,50496,222,5316,4542,5002,5,64202,282,6759,5775,6360,5,3,1,3,1,2,'隶属于地球联合军特殊部队「幻痛」的决斗高达再生产机。
本机是基于「第一期GAT-X系列」的再生计划「阿克泰昂计划」，以决斗高达强袭护甲装备为基础，全面进行改造的机体。
参考了札多制的强化装甲「强袭护甲」的运用资料，并重新设计联合制的「强化装甲」，改造为固定装备。
该强化装甲本身使用了「相转移装甲」材质，大幅提升了防御性能。
武装有肩部内设置的投掷兵器「短剑式投掷喷射对装甲贯入弹」，以及易于灵活操控的「收纳式镭射枪」等，更加特化为近距离战斗用。','{"id": 1336000300, "hp": 7014, "en": 71, "attack": 739, "defense": 631, "mobility": 730, "movement": 5, "max_hp": 50496, "max_en": 222, "max_attack": 5316, "max_defense": 4542, "max_mobility": 5002, "max_movement": 5, "sp_hp": 8917, "sp_en": 90, "sp_attack": 939, "sp_defense": 802, "sp_mobility": 928, "sp_movement": 5, "sp_max_hp": 64202, "sp_max_en": 282, "sp_max_attack": 6759, "sp_max_defense": 5775, "sp_max_mobility": 6360, "sp_max_movement": 5}','{"unit_id": 1336000300, "unit_ssp_initial_release_set_id": 1336000300, "unit_ssp_custom_core_group_id": 1336000300, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 133600030001, "unit_ssp_custom_core_group_id": 1336000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600030001, "weapon_change": {"id": 133600030001, "before_weapon_id": 0, "after_weapon_id": 133600030090, "weapon": {"id": 133600030090, "name": "M443 蠍式機動電磁砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600030090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 290098, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600030090, "weapon_status": {"id": 133600030090, "range_min": 2, "r