INSERT OR REPLACE INTO "units" VALUES(1336000400,'翠绿暴风高达','翠绿暴风高达',3,1,2,0,'10000000033603300','3360','g3360u00400','GAT-X103AP',1,1,1,1,7062,70,806,600,696,5,50844,210,5798,4317,5009,5,64644,267,7371,5488,6368,5,3,1,3,1,2,'隶属于地球联合军特殊部队「幻痛」的暴风高达再生产机。
本机是基于「第一期GAT-X系列」的再生计划「阿克泰昂计划」，以暴风高达为基础，全面进行改造的机体。
头部装备了高精密度的感应器与摄影机，并搭载与其连动的高性能武器管制系统，大幅提升砲击战的命中精度。
武装的「350mm重砲发射器」跟「94mm高出力镭射砲」移动到肩部，腰部则追加装备了枪刀「复合刺刀装备型镭射步枪」。
借此，本机体不只能进行远距离砲击，也能进行近距离战斗。','{"id": 1336000400, "hp": 7062, "en": 70, "attack": 806, "defense": 600, "mobility": 696, "movement": 5, "max_hp": 50844, "max_en": 210, "max_attack": 5798, "max_defense": 4317, "max_mobility": 5009, "max_movement": 5, "sp_hp": 8979, "sp_en": 89, "sp_attack": 1024, "sp_defense": 763, "sp_mobility": 885, "sp_movement": 5, "sp_max_hp": 64644, "sp_max_en": 267, "sp_max_attack": 7371, "sp_max_defense": 5488, "sp_max_mobility": 6368, "sp_max_movement": 5}','{"unit_id": 1336000400, "unit_ssp_initial_release_set_id": 1336000400, "unit_ssp_custom_core_group_id": 1336000400, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 133600040001, "unit_ssp_custom_core_group_id": 1336000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600040001, "weapon_change": {"id": 133600040001, "before_weapon_id": 0, "after_weapon_id": 133600040090, "weapon": {"id": 133600040090, "name": "齊射 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600040090, "attack_attr": 1, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 180005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600040090, "weapon_status": {"id": 133600040090, "range_min": 3, "range_max": 5, "power": 5000, "en": 63, "hi