INSERT OR REPLACE INTO "units" VALUES(1336000600,'民用型异端DSSD改良型','民用迷惘高达DSSD特装型',3,2,5,0,'10000000033603300','3360','g3360u00600','UT-1D',1,1,1,1,8089,60,594,808,697,5,58239,211,4277,5812,4266,5,74046,268,5438,7390,5423,5,3,1,1,1,1,'深宇宙探测开发机构「DSSD」的多用途MS。
是以奥布军的迷惘高达系MS为基础，并获得了奥布技术人员和废物商公会的协助所开发的机体。
头部装备由特殊护罩保护的高精度感应器，背部则搭载了「光轮推进翼」前身的电磁推进系统。
武装包含操作性优异的小型镭射枪，以及流用作业用装备的镭射焊枪。
DSSD将本机用在宇宙作业用与自身防卫，但在特殊部队「幻痛」的华金队袭击特洛伊太空站时，也使用本机来迎击敌人。','{"id": 1336000600, "hp": 8089, "en": 60, "attack": 594, "defense": 808, "mobility": 697, "movement": 5, "max_hp": 58239, "max_en": 211, "max_attack": 4277, "max_defense": 5812, "max_mobility": 4266, "max_movement": 5, "sp_hp": 10285, "sp_en": 76, "sp_attack": 756, "sp_defense": 1027, "sp_mobility": 887, "sp_movement": 5, "sp_max_hp": 74046, "sp_max_en": 268, "sp_max_attack": 5438, "sp_max_defense": 7390, "sp_max_mobility": 5423, "sp_max_movement": 5}','{"unit_id": 1336000600, "unit_ssp_initial_release_set_id": 1336000600, "unit_ssp_custom_core_group_id": 1336000600, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 133600060001, "unit_ssp_custom_core_group_id": 1336000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600060001, "weapon_change": {"id": 133600060001, "before_weapon_id": 0, "after_weapon_id": 133600060090, "weapon": {"id": 133600060090, "name": "鐳射槍KSM71/J SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600060090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600060090, "weapon_status": {"id": 133600060090, "range_min": 2, "range_