INSERT OR REPLACE INTO "units" VALUES(1336000700,'105歼灭短剑','105歼灭达加',2,1,30,0,'10000000033603300','3360','g3360u00700','GAT-01A2R+AQM/E-X01',1,1,1,1,6530,66,743,619,581,5,47016,177,5345,4456,4647,5,64375,242,7318,6101,6362,5,3,3,3,1,2,'地球联合军的量产型MS105达加的衍生机。
本机为特殊部队「幻痛」的主力MS。
幻痛将105达加独自进行微幅改进后，将配色也改为黑与灰色的专用色。
此外，本机还将强化后的「机动型突击装备背包」列为标准装备，在大气层内也可飞行，是能对应各种战况的万能MS。
其他还有装备各种突击背包的机体，泛用性相当出色。
武装有镭射军刀与能发射实弹与镭射的镭射步枪，脚部装备了对人镇压用的机砲。','{"id": 1336000700, "hp": 6530, "en": 66, "attack": 743, "defense": 619, "mobility": 581, "movement": 5, "max_hp": 47016, "max_en": 177, "max_attack": 5345, "max_defense": 4456, "max_mobility": 4647, "max_movement": 5, "sp_hp": 8941, "sp_en": 90, "sp_attack": 1017, "sp_defense": 848, "sp_mobility": 796, "sp_movement": 5, "sp_max_hp": 64375, "sp_max_en": 242, "sp_max_attack": 7318, "sp_max_defense": 6101, "sp_max_mobility": 6362, "sp_max_movement": 5}','{"unit_id": 1336000700, "unit_ssp_initial_release_set_id": 1336000700, "unit_ssp_custom_core_group_id": 1336000700, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 133600070001, "unit_ssp_custom_core_group_id": 1336000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600070001, "weapon_change": {"id": 133600070001, "before_weapon_id": 0, "after_weapon_id": 133600070090, "weapon": {"id": 133600070090, "name": "MX703G 鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600070090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600070090, "weapon_status": {"id": 133600070090, "range_min": 2, "range_max": 4, "power": 4