INSERT OR REPLACE INTO "units" VALUES(1336000800,'地狱猎犬型巴库','地狱猎犬型巴古',3,1,6,0,'10000000033603300','3360','g3360u00800','TMF/A-802W2',1,1,1,1,6278,71,805,668,696,5,45202,212,5790,4809,5011,5,57471,270,7362,6114,6371,5,1,1,3,1,2,'札多的四足兽型地面战用MS「巴古」的衍生机。
背部转盘装备新型接点，是能对应「魔法换装系统」的巴古改良机。
本机装备了四足兽型专用所开发的「地狱犬巫师系统」，本体头部也配合装备换装为搭载「镭射獠牙」的型号。
除了追加推进器提高机动性，三具头部装备的镭射砲跟镭射獠牙更能在近距离战斗时发挥出色的战斗能力。
在西欧亚大陆投入了大量机体进行实战，并参与攻击输送毁灭高达的地面战舰波拿巴号。','{"id": 1336000800, "hp": 6278, "en": 71, "attack": 805, "defense": 668, "mobility": 696, "movement": 5, "max_hp": 45202, "max_en": 212, "max_attack": 5790, "max_defense": 4809, "max_mobility": 5011, "max_movement": 5, "sp_hp": 7982, "sp_en": 90, "sp_attack": 1023, "sp_defense": 850, "sp_mobility": 885, "sp_movement": 5, "sp_max_hp": 57471, "sp_max_en": 270, "sp_max_attack": 7362, "sp_max_defense": 6114, "sp_max_mobility": 6371, "sp_max_movement": 5}','{"unit_id": 1336000800, "unit_ssp_initial_release_set_id": 1336000800, "unit_ssp_custom_core_group_id": 1336000800, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 133600080001, "unit_ssp_custom_core_group_id": 1336000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 133600080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 133600080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 133600080001, "weapon_change": {"id": 133600080001, "before_weapon_id": 0, "after_weapon_id": 133600080090, "weapon": {"id": 133600080090, "name": "地獄犬巫師系統 雙頭伸縮部位內藏鐳射砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 133600080090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100005, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 133600080090, "weapon_status": {"id": 133600080090, "range_min": 2, "range_max": 4,