INSERT OR REPLACE INTO "units" VALUES(1375000310,'铁人式槴子','铁人‧槴子',3,2,2,0,'10000000037503700','3750','g3750u00300','MSJ-06YIII-B',1,1,1,1,9375,64,734,793,746,4,67500,225,5279,5705,4563,4,80100,267,6264,6769,5415,4,3,1,3,1,2,'作为继承铁人的主力机种，由人类革新联盟开发的试作机。
