INSERT OR REPLACE INTO "units" VALUES(1376000300,'正义女神高达F型改','高达艾多利亚F型改',4,1,31,0,'10000000037603700','3760','g3760u00300','GNY-001F2',1,1,1,1,8004,80,925,684,801,5,57629,240,6655,4920,5763,5,64113,267,7404,5473,6412,5,3,3,3,1,3,'高达艾多利亚F型的改装机。
与联合国军的决战使得天人分崩离析后，将能天使高达的预备零件组装在F型上改良而成，也称作「F2型」。
汰换掉开发至今经过15年已老旧化的零件，也更改头部天线等一部分机体外观。
还装备了可在TRANS-AM时，透过控制释放的GN粒子来反射敌方镭射粒子的「GN反射」，整体性能获得提升。','{"id": 1376000300, "hp": 8004, "en": 80, "attack": 925, "defense": 684, "mobility": 801, "movement": 5, "max_hp": 57629, "max_en": 240, "max_attack": 6655, "max_defense": 4920, "max_mobility": 5763, "max_movement": 5, "sp_hp": 8905, "sp_en": 89, "sp_attack": 1029, "sp_defense": 761, "sp_mobility": 891, "sp_movement": 5, "sp_max_hp": 64113, "sp_max_en": 267, "sp_max_attack": 7404, "sp_max_defense": 5473, "sp_max_mobility": 6412, "sp_max_movement": 5}','{"unit_id": 1376000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1376000300, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 137600030001, "unit_ssp_custom_core_group_id": 1376000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137600030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137600030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137600030001, "weapon_change": {"id": 137600030001, "before_weapon_id": 0, "after_weapon_id": 137600030090, "weapon": {"id": 137600030090, "name": "TRANS-AM SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137600030090, "attack_attr": 4, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137600030090, "weapon_status": {"id": 137600030090, "range_min": 1, "range_max": 3, "power