INSERT OR REPLACE INTO "units" VALUES(1376000400,'星水女神高达F型','星水女神高达F型',3,1,31,0,'10000000037603700','3760','g3760u00400','GNY-002F',1,1,1,1,6260,70,810,666,703,5,45070,209,5827,4792,5061,5,57303,265,7408,6092,6435,5,3,3,3,1,3,'星水女神高达的改装机。
天人开始武力介入后，为了让其协力组织「天使」使用，将15年前开发的星水女神高达改良而成的机体。
更改了涂装配色，也强化了感应器性能。
此外，还在装备于两肩的感应盾上追加推进器的机能。
与联合国军的决战使得天人分崩离析后，本机又新增了生成「GN力场」的机能，但作用范围较狭窄，使用时需要高度的技术。','{"id": 1376000400, "hp": 6260, "en": 70, "attack": 810, "defense": 666, "mobility": 703, "movement": 5, "max_hp": 45070, "max_en": 209, "max_attack": 5827, "max_defense": 4792, "max_mobility": 5061, "max_movement": 5, "sp_hp": 7959, "sp_en": 89, "sp_attack": 1029, "sp_defense": 847, "sp_mobility": 894, "sp_movement": 5, "sp_max_hp": 57303, "sp_max_en": 265, "sp_max_attack": 7408, "sp_max_defense": 6092, "sp_max_mobility": 6435, "sp_max_movement": 5}','{"unit_id": 1376000400, "unit_ssp_initial_release_set_id": 1376000400, "unit_ssp_custom_core_group_id": 1376000400, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 137600040001, "unit_ssp_custom_core_group_id": 1376000400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137600040001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137600040001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137600040001, "weapon_change": {"id": 137600040001, "before_weapon_id": 0, "after_weapon_id": 137600040090, "weapon": {"id": 137600040090, "name": "TRANS-AM SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137600040090, "attack_attr": 1, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280003, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137600040090, "weapon_status": {"id": 137600040090, "range_min": 2, "range_max