INSERT OR REPLACE INTO "units" VALUES(1376001500,'黑秘典模组','黑秘典模组',4,2,30,0,'10000000037603700','3760','g3760u01500','GN-XXXB+GNR-000B',1,1,1,1,9182,64,882,843,725,5,66108,216,6346,6067,4636,5,73545,240,7060,6750,5157,5,3,3,3,1,2,'黑秘天使高达与黑GN典籍战机合体的强化型态。
和原型机的第一型态一样，背部装备的核心区块直接与太阳炉连结，借以取得强大的推力，并且能使用「GN试作型浮游砲」。
希克萨‧费米的复制体在迎战前往月球韦达的希克萨本尊时使用了本机，战斗中还追加更多浮游砲发动攻击。','{"id": 1376001500, "hp": 9182, "en": 64, "attack": 882, "defense": 843, "mobility": 725, "movement": 5, "max_hp": 66108, "max_en": 216, "max_attack": 6346, "max_defense": 6067, "max_mobility": 4636, "max_movement": 5, "sp_hp": 10215, "sp_en": 72, "sp_attack": 981, "sp_defense": 938, "sp_mobility": 806, "sp_movement": 5, "sp_max_hp": 73545, "sp_max_en": 240, "sp_max_attack": 7060, "sp_max_defense": 6750, "sp_max_mobility": 5157, "sp_max_movement": 5}','{"unit_id": 1376001500, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1376001500, "unit_ssp_add_status_id": 100015, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100015, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 137600150001, "unit_ssp_custom_core_group_id": 1376001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137600150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137600150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137600150001, "weapon_change": {"id": 137600150001, "before_weapon_id": 0, "after_weapon_id": 137600150090, "weapon": {"id": 137600150090, "name": "GN試作型浮游砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137600150090, "attack_attr": 5, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340052, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137600150090, "weapon_status": {"id": 137600150090, "range_min": 3, "range_max": 5, "power": 4