INSERT OR REPLACE INTO "units" VALUES(1378000110,'1.5高达','1.5高达',4,2,31,0,'10000000037803700','3780','g3780u00100','CB-001.5',1,1,1,1,11395,75,957,877,836,5,82039,251,6889,6311,5386,5,82971,254,6967,6383,5447,5,3,3,3,1,3,'1高达的改装机。
将与冯恩‧史帕克交战后严重受损的1高达进行修复、强化的机体。
背部追加两座平衡翼以提升机动力，并能变形成可放射高输出镭射的「阿尔瓦亚隆加农」，以及地上攻击用的「推进翼步枪」，攻击力获得强化。
所有机体性能都比原型机强化1.5倍，因此取名为「1.5高达」。
又因「1.5」形似「IS」，念作「I''S高达」。','{"id": 1378000110, "hp": 11395, "en": 75, "attack": 957, "defense": 877, "mobility": 836, "movement": 5, "max_hp": 82039, "max_en": 251, "max_attack": 6889, "max_defense": 6311, "max_mobility": 5386, "max_movement": 5, "sp_hp": 11524, "sp_en": 76, "sp_attack": 968, "sp_defense": 887, "sp_mobility": 846, "sp_movement": 5, "sp_max_hp": 82971, "sp_max_en": 254, "sp_max_attack": 6967, "sp_max_defense": 6383, "sp_max_mobility": 5447, "sp_max_movement": 5}','{"unit_id": 1378000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1378000110, "unit_ssp_add_status_id": 100005, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100005, "ssp_hp": 298, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 23, "ssp_mobility": 22, "ssp_max_hp": 5950, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 458, "ssp_max_mobility": 435}, "cores": [{"id": 137800011001, "unit_ssp_custom_core_group_id": 1378000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137800011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137800011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137800011001, "weapon_change": {"id": 137800011001, "before_weapon_id": 0, "after_weapon_id": 137800011090, "weapon": {"id": 137800011090, "name": "阿爾瓦亞隆加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137800011090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120009, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137800011090, "weapon_status": {"id": 137800011090, "range_min": 3, "range_max": 5, "power": 5050, "en": 63, "hit_rat