INSERT OR REPLACE INTO "units" VALUES(1379000300,'全装甲型0高达','全装甲型0高达',4,2,31,0,'10000000037903700','3790','g3790u00300','GN-000FA',1,1,1,1,9273,69,792,927,716,5,66764,217,5699,6670,4866,5,74275,242,6340,7420,5413,5,3,3,3,1,3,'由天人的支援组织「天使」设计的装备。
采用GN复合装甲作为全身追加装甲，能够在装甲内部形成稳定的GN力场。
同时利用由GN粒子带来的质量减轻效果，成功降低了追加装备的重量。
0高达与变革者进行最后决战时装备粒子储藏槽出击，然而由于利用储藏槽而非太阳炉，因此运用时并未使用粒子消耗量庞大的本装备。','{"id": 1379000300, "hp": 9273, "en": 69, "attack": 792, "defense": 927, "mobility": 716, "movement": 5, "max_hp": 66764, "max_en": 217, "max_attack": 5699, "max_defense": 6670, "max_mobility": 4866, "max_movement": 5, "sp_hp": 10316, "sp_en": 76, "sp_attack": 881, "sp_defense": 1031, "sp_mobility": 796, "sp_movement": 5, "sp_max_hp": 74275, "sp_max_en": 242, "sp_max_attack": 6340, "sp_max_defense": 7420, "sp_max_mobility": 5413, "sp_max_movement": 5}','{"unit_id": 1379000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1379000300, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 137900030001, "unit_ssp_custom_core_group_id": 1379000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137900030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137900030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137900030001, "weapon_change": {"id": 137900030001, "before_weapon_id": 0, "after_weapon_id": 137900030090, "weapon": {"id": 137900030090, "name": "鐳射火箭砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137900030090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120010, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137900030090, "weapon_status": {"id": 137900030090, "range_min": 2, "range_max": 4, 