INSERT OR REPLACE INTO "units" VALUES(1379000500,'进阶型厄运式','进阶型GN-X',2,1,30,0,'10000000037903700','3790','g3790u00500','GNX-604T',1,1,1,1,6499,65,680,588,685,5,46791,205,4896,4230,4691,5,64068,280,6704,5792,6423,5,3,3,3,1,2,'GN-X的特装机。
受到前线驾驶员的要求，将GN-X的后期生产型加以改良，在双肩设置的挂载点上追加防御棍，脚部则加装推进器。
另外还把GN-X专用的步枪特制成「进阶型GN镭射步枪」，并装备之后被GN-XⅢ正式采用的试作兵器「试作型GN长矛」，武装面也获得强化。
能调整到将驾驶员的能力发挥至极限，实战中也创下优异的成果，但生产数不到所有GN-X的3%，主要配置给联合国军的王牌驾驶员。
从此机体取得的实战资料，被活用在次期主力机GN-XⅡ的开发上。','{"id": 1379000500, "hp": 6499, "en": 65, "attack": 680, "defense": 588, "mobility": 685, "movement": 5, "max_hp": 46791, "max_en": 205, "max_attack": 4896, "max_defense": 4230, "max_mobility": 4691, "max_movement": 5, "sp_hp": 8899, "sp_en": 89, "sp_attack": 932, "sp_defense": 805, "sp_mobility": 937, "sp_movement": 5, "sp_max_hp": 64068, "sp_max_en": 280, "sp_max_attack": 6704, "sp_max_defense": 5792, "sp_max_mobility": 6423, "sp_max_movement": 5}','{"unit_id": 1379000500, "unit_ssp_initial_release_set_id": 1379000500, "unit_ssp_custom_core_group_id": 1379000500, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 137900050001, "unit_ssp_custom_core_group_id": 1379000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137900050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137900050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137900050001, "weapon_change": {"id": 137900050001, "before_weapon_id": 0, "after_weapon_id": 137900050090, "weapon": {"id": 137900050090, "name": "進階型GN鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137900050090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100011, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137900050090, "weapon_status": {"id": 137900050090, "range_min": 2, "range_max": 4, "power": 4850, "en