INSERT OR REPLACE INTO "units" VALUES(1379000610,'卓越型厄运式','卓越型GN-X',4,2,9,0,'10000000037903700','3790','g3790u00600','GNX-612T/AA',1,1,1,1,10956,75,960,924,797,5,78884,238,6911,6653,5418,5,79780,241,6989,6729,5480,5,1,1,3,1,3,'突袭登陆战用的特殊GN-X。
以从海上发动奇袭为目的开发的机体，被分类为GN-XⅢ的发展机，大量投入变革体的新技术，性能接近同期开发的次世代机GN-XⅣ。
在水中移动时，装上由感应器组件、武装组件及气垫组件组成的突袭登陆组件，登陆时即卸除。
双手设置的「GN苦无」是和「GN火神砲」一体化的实体剑，其中还内藏奇袭用的「GN镭射刺针」。
本机主要使用于A-Laws主导的特殊任务，驾驶员都是A-Laws所属兵，或是拥有独自行动许可的「特权者」。','{"id": 1379000610, "hp": 10956, "en": 75, "attack": 960, "defense": 924, "mobility": 797, "movement": 5, "max_hp": 78884, "max_en": 238, "max_attack": 6911, "max_defense": 6653, "max_mobility": 5418, "max_movement": 5, "sp_hp": 11081, "sp_en": 76, "sp_attack": 971, "sp_defense": 935, "sp_mobility": 806, "sp_movement": 5, "sp_max_hp": 79780, "sp_max_en": 241, "sp_max_attack": 6989, "sp_max_defense": 6729, "sp_max_mobility": 5480, "sp_max_movement": 5}','{"unit_id": 1379000610, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1379000610, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 137900061001, "unit_ssp_custom_core_group_id": 1379000610, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137900061001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137900061001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137900061001, "weapon_change": {"id": 137900061001, "before_weapon_id": 0, "after_weapon_id": 137900061090, "weapon": {"id": 137900061090, "name": "GN苦無 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137900061090, "attack_attr": 2, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280011, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137900061090, "weapon_status": {"id": 137900061090, "range_min": 2, "range_max": 3, "power": 