INSERT OR REPLACE INTO "units" VALUES(1379002010,'猎兵型权天使高达','驱逐型权天使高达',4,1,30,0,'10000000037903700','3790','g3790u02000','GNW-20000/J',1,1,1,1,8855,88,1020,835,786,5,63753,238,7342,6008,6281,5,64478,240,7426,6077,6353,5,3,3,3,1,2,'权天使高达的武装衍生机。
以单独面对大部队为前提设计的重武装型，装备了三架座天使高达系列分别搭载的兵装的衍生型。
本机的战术，是先利用「GN隐形力场」孤立敌方部队，接著用「GN发射器」进行远距离砲击，最后再把分散的敌方兵力各个击破，只靠单机便能胜任原本由三架座天使高达分担的工作。
但是重武装导致机动力大幅下降，本装备只限运用在与大部队战斗。','{"id": 1379002010, "hp": 8855, "en": 88, "attack": 1020, "defense": 835, "mobility": 786, "movement": 5, "max_hp": 63753, "max_en": 238, "max_attack": 7342, "max_defense": 6008, "max_mobility": 6281, "max_movement": 5, "sp_hp": 8956, "sp_en": 89, "sp_attack": 1032, "sp_defense": 844, "sp_mobility": 795, "sp_movement": 5, "sp_max_hp": 64478, "sp_max_en": 240, "sp_max_attack": 7426, "sp_max_defense": 6077, "sp_max_mobility": 6353, "sp_max_movement": 5}','{"unit_id": 1379002010, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1379002010, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 137900201001, "unit_ssp_custom_core_group_id": 1379002010, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 137900201001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 137900201001, "sort_order": 1, "release_function_type_index": 5, "target_id": 137900201001, "weapon_change": {"id": 137900201001, "before_weapon_id": 0, "after_weapon_id": 137900201090, "weapon": {"id": 137900201090, "name": "GN獠牙 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 137900201090, "attack_attr": 6, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340048, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 137900201090, "weapon_status": {"id": 137900201090, "range_min": 1, "range_max": 3, "power": 4800, "en": 60, "hit_ra