INSERT OR REPLACE INTO "units" VALUES(1401000110,'高达AGE-1巨剑型','高达AGE-1 巨剑型',4,2,32,0,'10000000040104000','4010','g4010u00100','AGE-SW',1,1,1,1,10120,75,842,1012,788,4,72864,238,6056,7287,5354,4,73692,241,6125,7370,5415,4,3,1,3,1,3,'装上「巨剑型」装备的高达AGE-1。
近距离战斗型态如同中世纪骑士一样，特征为装备的武器，有利伯塔之剑、盾牌及镭射军刀这些专精于近身战斗的武装。
在图迪亚举办毕业典礼时，该机体与哲哈特所驾驶的战达斯R交战，双方展开了激烈交锋。','{"id": 1401000110, "hp": 10120, "en": 75, "attack": 842, "defense": 1012, "mobility": 788, "movement": 4, "max_hp": 72864, "max_en": 238, "max_attack": 6056, "max_defense": 7287, "max_mobility": 5354, "max_movement": 4, "sp_hp": 10235, "sp_en": 76, "sp_attack": 851, "sp_defense": 1024, "sp_mobility": 797, "sp_movement": 4, "sp_max_hp": 73692, "sp_max_en": 241, "sp_max_attack": 6125, "sp_max_defense": 7370, "sp_max_mobility": 5415, "sp_max_movement": 4}','{"unit_id": 1401000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1401000110, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 140100011001, "unit_ssp_custom_core_group_id": 1401000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 140100011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 140100011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 140100011001, "weapon_change": {"id": 140100011001, "before_weapon_id": 0, "after_weapon_id": 140100011090, "weapon": {"id": 140100011090, "name": "利伯塔之劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 140100011090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280013, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 140100011090, "weapon_status": {"id": 140100011090, "range_min": 1, "range_max": 2, "power": 4650, "en"