INSERT OR REPLACE INTO "units" VALUES(1408000110,'高达AGE-1剃刀型','高达AGE-1 剃刀型',4,1,32,0,'10000000040804000','4080','g4080u00100','AGE-1R',1,1,1,1,8783,89,1010,838,792,4,63234,240,7272,6032,6336,4,63952,243,7355,6100,6408,4,3,1,3,1,3,'高达AGE-1速战型的发展型，各部位装备了实体剑「剃刀」。
透过机体轻量化及增设推进器等方式提升了运动性能，与速战型将其主武装席格刀发挥到最大极限的做法不同，利用了运用剃刀时所产生的惯性力进行机体控制，提高运动性能及攻击力。','{"id": 1408000110, "hp": 8783, "en": 89, "attack": 1010, "defense": 838, "mobility": 792, "movement": 4, "max_hp": 63234, "max_en": 240, "max_attack": 7272, "max_defense": 6032, "max_mobility": 6336, "max_movement": 4, "sp_hp": 8883, "sp_en": 90, "sp_attack": 1022, "sp_defense": 848, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 63952, "sp_max_en": 243, "sp_max_attack": 7355, "sp_max_defense": 6100, "sp_max_mobility": 6408, "sp_max_movement": 4}','{"unit_id": 1408000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1408000110, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 140800011001, "unit_ssp_custom_core_group_id": 1408000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 140800011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 140800011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 140800011001, "weapon_change": {"id": 140800011001, "before_weapon_id": 0, "after_weapon_id": 140800011090, "weapon": {"id": 140800011090, "name": "腳部剃刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 140800011090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280013, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 140800011090, "weapon_status": {"id": 140800011090, "range_min":