INSERT OR REPLACE INTO "units" VALUES(1408000300,'G西福斯','G赛佛斯',4,3,2,0,'10000000040804000','4080','g4080u00300','BMS-005',1,1,1,1,8033,80,763,801,835,5,57837,252,5491,5767,5724,5,64343,281,6108,6416,6368,5,3,1,3,1,2,'传闻由马度纳工房一手打造而成的机体。
在基本规格上，移除了左手掌并装备上带有爪状钩子的德斯破坏砲H，此举不难推测是反映出「不惜牺牲泛用性也要提升攻击力」的海盗思维。
虽仍需耗费一定劳力，但此机在设计上相对具有变更装备的弹性，除了据传与镭射军刀具备同等破坏力的高出力电热剑，左手也能换装为近战用的特殊武器。此外，似乎也有过视情况重新恢复左手掌功能的时候。','{"id": 1408000300, "hp": 8033, "en": 80, "attack": 763, "defense": 801, "mobility": 835, "movement": 5, "max_hp": 57837, "max_en": 252, "max_attack": 5491, "max_defense": 5767, "max_mobility": 5724, "max_movement": 5, "sp_hp": 8937, "sp_en": 89, "sp_attack": 849, "sp_defense": 891, "sp_mobility": 929, "sp_movement": 5, "sp_max_hp": 64343, "sp_max_en": 281, "sp_max_attack": 6108, "sp_max_defense": 6416, "sp_max_mobility": 6368, "sp_max_movement": 5}','{"unit_id": 1408000300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1408000300, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 140800030001, "unit_ssp_custom_core_group_id": 1408000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 140800030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 140800030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 140800030001, "weapon_change": {"id": 140800030001, "before_weapon_id": 0, "after_weapon_id": 140800030090, "weapon": {"id": 140800030090, "name": "德斯破壞砲H SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 140800030090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 2, "weapon_level_up_material": 10012, "weapon_effect": 290012, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 140800030090, "weapon_status": {"id": 140800030090, 