INSERT OR REPLACE INTO "units" VALUES(1408000410,'阿黛尔 强装型','亚德鲁 强装型',4,1,2,0,'10000000040804000','4080','g4080u00400','RGE-G1100ST',1,1,1,1,8352,89,1058,788,837,5,60132,253,7611,5673,6339,5,60816,256,7698,5737,6411,5,3,1,3,1,2,'成功量产高达AGE-1的基本骨架并加以改良而完成的亚德鲁，能够使用德斯步枪等以往仅有AGE-1和少部分特装机才能运用的各种强力武器。
其中最值得一提的就是导入AGE-1的换装系统，使其得以换装为重击型及速战型等型态，并将这项原本仅是针对具有高泛用性的维根MS所做的临时应对措施升华成一般战术一事。
换装系统的有效性在经过实证后，不但继承到后续的亚德鲁Mk-Ⅱ开发工程，也影响了往后联邦军的MS设计思维。
这套「强装型」换装系统原本虽是为了AGE-1而提出，但在实战中运用的纪录极少，仅在迎战维根MS时有部分亚德鲁装备过。
安装在双肩的巨大推进器可产生爆炸性的推力，再搭配专用武装鲁特雷博长矛，便能发挥出一击必杀的惊人攻击力。','{"id": 1408000410, "hp": 8352, "en": 89, "attack": 1058, "defense": 788, "mobility": 837, "movement": 5, "max_hp": 60132, "max_en": 253, "max_attack": 7611, "max_defense": 5673, "max_mobility": 6339, "max_movement": 5, "sp_hp": 8447, "sp_en": 90, "sp_attack": 1070, "sp_defense": 797, "sp_mobility": 846, "sp_movement": 5, "sp_max_hp": 60816, "sp_max_en": 256, "sp_max_attack": 7698, "sp_max_defense": 5737, "sp_max_mobility": 6411, "sp_max_movement": 5}','{"unit_id": 1408000410, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1408000410, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 140800041001, "unit_ssp_custom_core_group_id": 1408000410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 140800041001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 140800041001, "sort_order": 1, "release_function_type_index": 5, "target_id": 140800041001, "weapon_change": {"id": 140800041001, "before_weapon_id": 0, "after_weapon_id": 140800041090, "weapon": {"id": 140800041090, "name": "魯特雷博長矛 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 140800041090, "attack_attr": 2, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10011, "weapon_effect": 270002, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 140800041090, "weapon_status": {"id": 140800041090, "range_min": 1, "range_max": 3, "power": 