INSERT OR REPLACE INTO "units" VALUES(1408000500,'高达AGE-1 2号机 突击外装型','高达AGE-1 2号机 突击外装型',4,2,32,0,'10000000040804000','4080','g4080u00500','AGE-1AJ/2',1,1,1,1,10063,68,685,843,794,5,72454,240,4925,6066,4857,5,80605,267,5479,6748,5404,5,3,1,3,1,3,'继换装系统之后，为了增加高达AGE-1的泛用性，军方开发部门不经AGE系统直接开发出的，便是这项「外装系统」。
此系统的基本构想，是由安巴特一战后经过了一段时日才正式加入军方的迪基‧根希路一手架构的。
突击外装是以提升火力与防御力为重点的装备，除了为提升枪砲命中精度而加装各种感测器之外，也为因应据点攻击而增设提升了连续运用耐久度的主推进器。
由于本外装毕竟算是测试机，仅装备了2连装德斯步枪、德斯巨砲、镭射火神砲等可沿用至其他机体的武装。但日后AGE-1专用的格拉司通发射器问世，进而催生出了外装系统的最终进化型换装「全备光辉型」。
另外，在开发外装系统时建造的AGE-1 2号机，也成了日后开发的亚德鲁雏型。','{"id": 1408000500, "hp": 10063, "en": 68, "attack": 685, "defense": 843, "mobility": 794, "movement": 5, "max_hp": 72454, "max_en": 240, "max_attack": 4925, "max_defense": 6066, "max_mobility": 4857, "max_movement": 5, "sp_hp": 11196, "sp_en": 76, "sp_attack": 761, "sp_defense": 938, "sp_mobility": 883, "sp_movement": 5, "sp_max_hp": 80605, "sp_max_en": 267, "sp_max_attack": 5479, "sp_max_defense": 6748, "sp_max_mobility": 5404, "sp_max_movement": 5}','{"unit_id": 1408000500, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1408000500, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 140800050001, "unit_ssp_custom_core_group_id": 1408000500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 140800050001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 140800050001, "sort_order": 1, "release_function_type_index": 5, "target_id": 140800050001, "weapon_change": {"id": 140800050001, "before_weapon_id": 0, "after_weapon_id": 140800050090, "weapon": {"id": 140800050090, "name": "德斯巨砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 140800050090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 2, "weapon_level_up_material": 30022, "weapon_effect": 290012, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 140800050090, "weapon_status": {"id": 140800050090, "range_min": 3, "range_max": 4, "power": 4900, "en": 61