INSERT OR REPLACE INTO "units" VALUES(1409000600,'THE·高达','THE‧高达',4,1,32,0,'10000000040904000','4090','g4090u00600','-',1,1,1,1,8051,80,926,763,715,5,57963,216,6664,5488,5714,5,64484,240,7413,6106,6357,5,3,1,3,1,3,'必须先声明的是，「THE‧高达」的设计、造型、构造上有相当多部分与AGE-1相似。
