INSERT OR REPLACE INTO "units" VALUES(1431000200,'里格尔·莉莉','里格尔‧尼尼',3,3,2,0,'10000000043104300','4310','g4310u00200','EB-06/T2C',1,1,1,1,6666,70,734,665,732,4,47991,221,5279,4787,5016,4,61017,281,6712,6086,6377,4,3,1,3,1,2,'以古尼捷特制而成的哲安马高‧沙雷诺专用机。
哲安马高从提华兹处取得铁华团俘获的古尼捷， 并施以独门改造而成的机体。
改装头部和脚部的装甲、在背部装上红色耐热披风， 外观和原本的古尼捷有很大的差异。
装备超大型质量兵器「蛇腹斧」，可将刀刃的连结部位展开以延伸 攻击距离，并可利用离心力施予强力的攻击。','{"id": 1431000200, "hp": 6666, "en": 70, "attack": 734, "defense": 665, "mobility": 732, "movement": 4, "max_hp": 47991, "max_en": 221, "max_attack": 5279, "max_defense": 4787, "max_mobility": 5016, "max_movement": 4, "sp_hp": 8475, "sp_en": 89, "sp_attack": 933, "sp_defense": 846, "sp_mobility": 930, "sp_movement": 4, "sp_max_hp": 61017, "sp_max_en": 281, "sp_max_attack": 6712, "sp_max_defense": 6086, "sp_max_mobility": 6377, "sp_max_movement": 4}','{"unit_id": 1431000200, "unit_ssp_initial_release_set_id": 1431000200, "unit_ssp_custom_core_group_id": 1431000200, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 143100020001, "unit_ssp_custom_core_group_id": 1431000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100020001, "weapon_change": {"id": 143100020001, "before_weapon_id": 0, "after_weapon_id": 143100020090, "weapon": {"id": 143100020090, "name": "110mm步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100020090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100020090, "weapon_status": {"id": 143100020090, "range_min": 1, "range_max": 4, "