INSERT OR REPLACE INTO "units" VALUES(1431000300,'哈克利·罗迪 (桑波机)','哈古利‧罗迪 (森保机)',2,2,2,0,'10000000043104300','4310','g4310u00300','UGY-R41/H',1,1,1,1,8091,56,620,685,586,4,58255,176,4460,4929,3982,4,79764,241,6107,6749,5453,4,3,1,3,1,2,'佣兵哈古利兄妹使用的曼‧罗迪特制机。
哈古利兄妹偶然在太空垃圾带取得遭废弃的曼‧罗迪，并加以改装。
基本性能与曼‧罗迪无异，但因为头部和驾驶舱区块遭到破坏， 故换上新的组件，且未搭载阿赖耶识系统。
本机由哥哥森保‧哈古利驾驶，左肩施以蓝色涂装， 专用装备为和高达古辛的武器同型的「砍刀」。','{"id": 1431000300, "hp": 8091, "en": 56, "attack": 620, "defense": 685, "mobility": 586, "movement": 4, "max_hp": 58255, "max_en": 176, "max_attack": 4460, "max_defense": 4929, "max_mobility": 3982, "max_movement": 4, "sp_hp": 11079, "sp_en": 76, "sp_attack": 849, "sp_defense": 938, "sp_mobility": 802, "sp_movement": 4, "sp_max_hp": 79764, "sp_max_en": 241, "sp_max_attack": 6107, "sp_max_defense": 6749, "sp_max_mobility": 5453, "sp_max_movement": 4}','{"unit_id": 1431000300, "unit_ssp_initial_release_set_id": 1431000300, "unit_ssp_custom_core_group_id": 1431000300, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 143100030001, "unit_ssp_custom_core_group_id": 1431000300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100030001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100030001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100030001, "weapon_change": {"id": 143100030001, "before_weapon_id": 0, "after_weapon_id": 143100030090, "weapon": {"id": 143100030090, "name": "90mm衝鋒槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100030090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100030090, "weapon_status": {"id": 143100030090, "range_min": 1, "range_max": 3, "powe