INSERT OR REPLACE INTO "units" VALUES(1431000410,'哈克利·罗迪 (尤哈娜机)','哈古利‧罗迪 (尤汉娜机)',3,2,2,0,'10000000043104300','4310','g4310u00400','UGY-R41/H',1,1,1,1,8625,65,638,861,750,4,62100,228,4590,6198,4590,4,73692,270,5447,7355,5447,4,3,1,3,1,2,'佣兵哈古利兄妹使用的曼‧罗迪特制机。
哈古利兄妹偶然在太空垃圾带取得遭废弃的曼‧罗迪，并加以改装。
基本性能与曼‧罗迪无异，但因为头部和驾驶舱区块遭到破坏， 故换上新的组件，且未搭载阿赖耶识系统。
本机由妹妹尤汉娜‧哈古利驾驶，左肩施以黄色涂装， 专用装备为和高达古辛的武器同型的「长柄斧」。','{"id": 1431000410, "hp": 8625, "en": 65, "attack": 638, "defense": 861, "mobility": 750, "movement": 4, "max_hp": 62100, "max_en": 228, "max_attack": 4590, "max_defense": 6198, "max_mobility": 4590, "max_movement": 4, "sp_hp": 10235, "sp_en": 77, "sp_attack": 757, "sp_defense": 1022, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 73692, "sp_max_en": 270, "sp_max_attack": 5447, "sp_max_defense": 7355, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1431000410, "unit_ssp_initial_release_set_id": 1431000410, "unit_ssp_custom_core_group_id": 1431000410, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 143100041001, "unit_ssp_custom_core_group_id": 1431000410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100041001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100041001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100041001, "weapon_change": {"id": 143100041001, "before_weapon_id": 0, "after_weapon_id": 143100041090, "weapon": {"id": 143100041090, "name": "90mm衝鋒槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100041090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100041090, "weapon_status": {"id": 143100041090, "range_min": 1, "range_max": 3, "p