INSERT OR REPLACE INTO "units" VALUES(1431000550,'高达·阿斯塔罗特重生型 (EX)','高达亚斯塔录重生型 (EX)',5,3,2,0,'10000000043104300','4310','g4310u00550','ASW-G-29',1,1,1,1,8992,111,998,908,1091,5,64742,333,7185,6538,7855,5,64742,333,7185,6538,7855,5,3,1,3,1,2,'高达亚斯塔录的改装机。
高达亚斯塔录复原到原本样貌的82%时，遭娜娜奥‧纳卢连拿夺走， 当在木星圈的黑市中被发现时已遗失大部分的装备。
本机是将该高达亚斯塔录以其它MS的装备再度修复完成的机体， 又变回左右不对称的模样。
在改装的同时，追加内藏火药式「丹因斯尼夫」的「巨剑砍刀」， 并在左手装上兼具护盾功能的副拳套，武装方面获得大幅强化。
然而，配合阿捷‧米拉治的战斗特性施以重武装和重装甲， 导致机体欠缺平衡性，除了他以外没有人能够操纵。','{"id": 1431000550, "hp": 8992, "en": 111, "attack": 998, "defense": 908, "mobility": 1091, "movement": 5, "max_hp": 64742, "max_en": 333, "max_attack": 7185, "max_defense": 6538, "max_mobility": 7855, "max_movement": 5, "sp_hp": 8992, "sp_en": 111, "sp_attack": 998, "sp_defense": 908, "sp_mobility": 1091, "sp_movement": 5, "sp_max_hp": 64742, "sp_max_en": 333, "sp_max_attack": 7185, "sp_max_defense": 6538, "sp_max_mobility": 7855, "sp_max_movement": 5}','null','高達亞斯塔錄重生型 (EX)','scrape',1791488368,'v2026.10.08',1431000100);
INSERT OR REPLACE INTO "units" VALUES(1431000600,'卡利斯托','卡利斯托',2,3,22,0,'10000000043104300','4310','g4310u00600','STH-14/T2C',1,1,1,1,6459,66,613,655,678,4,46501,207,4410,4710,4648,4,63670,283,6038,6449,6364,4,3,2,3,1,2,'哲安马高‧沙雷诺持有的百里特制机。
在背包装上不同于原型机的大型推进器，并施以蓝色系涂装。
双手装备的「可变形刀盾」 原本是高达亚斯塔录原型的肩部平衡翼， 本机将其运用作为能发挥其强度的格斗用兵器。
本机被使用在袭击造访艾伯兰奇殖民卫星底域3的 阿捷‧米拉治等人，与高达亚斯塔录交战。','{"id": 1431000600, "hp": 6459, "en": 66, "attack": 613, "defense": 655, "mobility": 678, "movement": 4, "max_hp": 46501, "max_en": 207, "max_attack": 4410, "max_defense": 4710, "max_mobility": 4648, "max_movement": 4, "sp_hp": 8844, "sp_en": 90, "sp_attack": 839, "sp_defense": 896, "sp_mobility": 928, "sp_movement": 4, "sp_max_hp": 63670, "sp_max_en": 283, "sp_max_attack": 6038, "sp_max_defense": 6449, "sp_max_mobility": 6364, "sp_max_movement": 4}','{"unit_id": 1431000600, "unit_ssp_initial_release_set_id": 1431000600, "unit_ssp_custom_core_group_id": 1431000600, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}, "cores": [{"id": 143100060001, "unit_ssp_custom_core_group_id": 1431000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100060001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100060001, "weapon_change": {"id": 143100060001, "before_weapon_id": 0, "after_weapon_id": 143100060090, "weapon": {"id": 143100060090, "name": "四聯裝火箭發射器 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100060090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 200001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100060090, "weapon_status": {"id": 143100060090, "range_min": 2, "range_max": 5, "power":