INSERT OR REPLACE INTO "units" VALUES(1431000700,'拉布鲁斯','拉布鲁斯',1,2,2,0,'10000000043104300','4310','g4310u00700','UGY-R41/T2C',1,1,1,1,7511,51,506,632,604,4,54076,179,3643,4548,3693,4,80213,266,5404,6746,5478,4,3,1,3,1,2,'哲安马高‧沙雷诺持有的罗迪骨架特制机。
以护卫重要人士为目的，施以独门的改造， 加上厚重装甲，并在头部搭载能互相通讯的强化感应器。
武装配置和曼‧罗迪相同的「切割流星锤」及「90mm冲锋枪」。
本机被使用在袭击造访艾伯兰奇殖民卫星底域3的 阿捷‧米拉治等人，与出面迎击的加拉尔号角古尼捷队交战。','{"id": 1431000700, "hp": 7511, "en": 51, "attack": 506, "defense": 632, "mobility": 604, "movement": 4, "max_hp": 54076, "max_en": 179, "max_attack": 3643, "max_defense": 4548, "max_mobility": 3693, "max_movement": 4, "sp_hp": 11141, "sp_en": 76, "sp_attack": 751, "sp_defense": 937, "sp_mobility": 895, "sp_movement": 4, "sp_max_hp": 80213, "sp_max_en": 266, "sp_max_attack": 5404, "sp_max_defense": 6746, "sp_max_mobility": 5478, "sp_max_movement": 4}','{"unit_id": 1431000700, "unit_ssp_initial_release_set_id": 1431000700, "unit_ssp_custom_core_group_id": 1431000700, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 143100070001, "unit_ssp_custom_core_group_id": 1431000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100070001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100070001, "weapon_change": {"id": 143100070001, "before_weapon_id": 0, "after_weapon_id": 143100070090, "weapon": {"id": 143100070090, "name": "切割流星鎚 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100070090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 260008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100070090, "weapon_status": {"id": 143100070090, "range_min": 1, "range_max": 2, "po