INSERT OR REPLACE INTO "units" VALUES(1431000800,'高达·化勒','高达化勒',3,1,2,0,'10000000043104300','4310','g4310u00800','AGW-G-47',1,1,1,1,6659,71,838,631,668,5,47943,201,6034,4541,5063,5,60956,255,7672,5773,6437,5,3,1,3,1,2,'诺沙尼奥‧里昂尼持有的高达骨架型MS。
300年前的「厄祭战争」末期开发的72架高达骨架采用机中的一架， 搭载两座亚哈反应炉，同时运作从而获得庞大的输出。
塔度天普的解体事业在投标的废弃殖民卫星残骸中发现的机体， 当时的现场负责人诺沙尼奥暗中将其运出并占为己有。
发现时是呈现裸露出骨架的状态，诺沙尼奥利用加拉尔号角的 维尔‧克拉森提供的高达亚斯塔录的装甲将其复原。
借由高输出的背包及在脚部装设推进器，成为拥有优秀的机动性和 运动性的机体。
初次与高达亚斯塔录交战时是装备薙刀状的格斗兵器「长柄刀」及 「210mm对物步枪」，第二次则是以「挖掘槌」和护盾展开激战。','{"id": 1431000800, "hp": 6659, "en": 71, "attack": 838, "defense": 631, "mobility": 668, "movement": 5, "max_hp": 47943, "max_en": 201, "max_attack": 6034, "max_defense": 4541, "max_mobility": 5063, "max_movement": 5, "sp_hp": 8466, "sp_en": 90, "sp_attack": 1066, "sp_defense": 802, "sp_mobility": 850, "sp_movement": 5, "sp_max_hp": 60956, "sp_max_en": 255, "sp_max_attack": 7672, "sp_max_defense": 5773, "sp_max_mobility": 6437, "sp_max_movement": 5}','{"unit_id": 1431000800, "unit_ssp_initial_release_set_id": 1431000800, "unit_ssp_custom_core_group_id": 1431000800, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 143100080001, "unit_ssp_custom_core_group_id": 1431000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100080001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100080001, "weapon_change": {"id": 143100080001, "before_weapon_id": 0, "after_weapon_id": 143100080090, "weapon": {"id": 143100080090, "name": "挖掘槌 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100080090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 260008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100080090, "weapon_status": {"id": 143100080090, "range_min": 1, "range_max