INSERT OR REPLACE INTO "units" VALUES(1431000900,'高达·化勒（初期装备）','高达化勒（初期装备）',3,1,2,0,'10000000043104300','4310','g4310u00900','AGW-G-47',1,1,1,1,6939,71,805,594,703,5,49957,211,5792,4274,5060,5,63517,268,7364,5434,6433,5,3,1,3,1,2,'人类与无人大型机动兵器「MA」之间漫长而激烈的战争一度让人类濒临存亡危机，但在拥有高达骨架的72架MS投入战场之后，终于以人类的胜利宣告落幕。
在那之后，多数机体随著300年的岁月流逝而下落不明。直到近年，化勒才从自厄祭战争时代便已报废、长期遭到弃置的殖民卫星残骸中被人发现。
当时标得废弃殖民卫星解体业务包案的长生帮时任现场负责人诺沙尼奥‧里昂尼趁著职务之便，将沉眠于殖民卫星内部动力部分附近的化勒暗中运出，并当作私人所有物长期保管。
或许他早从这时候开始就稳扎稳打地做准备，等著日后反抗泰迪老爹也说不定。','{"id": 1431000900, "hp": 6939, "en": 71, "attack": 805, "defense": 594, "mobility": 703, "movement": 5, "max_hp": 49957, "max_en": 211, "max_attack": 5792, "max_defense": 4274, "max_mobility": 5060, "max_movement": 5, "sp_hp": 8822, "sp_en": 90, "sp_attack": 1023, "sp_defense": 755, "sp_mobility": 894, "sp_movement": 5, "sp_max_hp": 63517, "sp_max_en": 268, "sp_max_attack": 7364, "sp_max_defense": 5434, "sp_max_mobility": 6433, "sp_max_movement": 5}','{"unit_id": 1431000900, "unit_ssp_initial_release_set_id": 1431000900, "unit_ssp_custom_core_group_id": 1431000900, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 143100090001, "unit_ssp_custom_core_group_id": 1431000900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100090001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100090001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100090001, "weapon_change": {"id": 143100090001, "before_weapon_id": 0, "after_weapon_id": 143100090090, "weapon": {"id": 143100090090, "name": "長柄刀 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100090090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100090090, "weapon_status": {"id": 143100090090, "range_min": 1, "range_max": 2, "power": 4700, "en":