INSERT OR REPLACE INTO "units" VALUES(1431001200,'崔亚纳','崔亚纳',2,1,2,0,'10000000043104300','4310','g4310u01200','TMPM02/AC',1,1,1,1,5831,66,746,619,648,4,41977,196,5367,4454,4663,4,57476,268,7348,6098,6384,4,3,1,3,1,2,'针对重要人士暗杀任务的百炼特制机。
考量到重力环境下的运用而加以轻量化，并借由活用其机动性的 一击脱离战法，能够迅速完成暗杀任务。
另外也强化了感应器组件，头部变成有如戴上帽子的特异形状。
武装除了「130mm突击步枪」，还在肩甲内设置便于操作、 适合暗杀任务的「专用马尼亚戈刀」。
为了暗杀泰迪‧摩加顿而侵入艾伯兰奇5的殖民卫星， 与高达亚斯塔录展开交战。','{"id": 1431001200, "hp": 5831, "en": 66, "attack": 746, "defense": 619, "mobility": 648, "movement": 4, "max_hp": 41977, "max_en": 196, "max_attack": 5367, "max_defense": 4454, "max_mobility": 4663, "max_movement": 4, "sp_hp": 7983, "sp_en": 90, "sp_attack": 1021, "sp_defense": 847, "sp_mobility": 887, "sp_movement": 4, "sp_max_hp": 57476, "sp_max_en": 268, "sp_max_attack": 7348, "sp_max_defense": 6098, "sp_max_mobility": 6384, "sp_max_movement": 4}','{"unit_id": 1431001200, "unit_ssp_initial_release_set_id": 1431001200, "unit_ssp_custom_core_group_id": 1431001200, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 143100120001, "unit_ssp_custom_core_group_id": 1431001200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100120001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100120001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100120001, "weapon_change": {"id": 143100120001, "before_weapon_id": 0, "after_weapon_id": 143100120090, "weapon": {"id": 143100120090, "name": "130mm突擊步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100120090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100120090, "weapon_status": {"id": 143100120090, "range_min": 1, "range_max": 3, "power": 48