INSERT OR REPLACE INTO "units" VALUES(1431001500,'高达·但他林','高达但他林',3,2,2,0,'10000000043104300','4310','g4310u01500','AGW-G-71',1,1,1,1,7994,60,670,805,633,5,57555,190,4818,5792,4299,5,73177,242,6126,7364,5466,5,3,1,3,1,2,'札尔姆弗特家持有的高达骨架型MS。
300年前的「厄祭战争」末期开发的72架高达骨架采用机中的一架， 搭载两座亚哈反应炉，同时运作从而获得庞大的输出。
本机在高达骨架机中属最末期完成的机体，以率先投入实战的 同骨架机型的战斗资料为基础，反复进行大幅度的设计变更。
最终成为借由装备各种选配兵装来对应各种战局的机体， 虽然在战争终结阶段才完成，仍立下相当丰硕的战果， 被视为札尔姆弗特家的象征传承下来。
此外，裸装状态是指考虑到在重力环境下和殖民卫星内的战斗 而装上轻装甲，进而取得优异的机动性和敏捷性， 并发挥出高超的格斗战能力。','{"id": 1431001500, "hp": 7994, "en": 60, "attack": 670, "defense": 805, "mobility": 633, "movement": 5, "max_hp": 57555, "max_en": 190, "max_attack": 4818, "max_defense": 5792, "max_mobility": 4299, "max_movement": 5, "sp_hp": 10164, "sp_en": 77, "sp_attack": 851, "sp_defense": 1023, "sp_mobility": 804, "sp_movement": 5, "sp_max_hp": 73177, "sp_max_en": 242, "sp_max_attack": 6126, "sp_max_defense": 7364, "sp_max_mobility": 5466, "sp_max_movement": 5}','{"unit_id": 1431001500, "unit_ssp_initial_release_set_id": 1431001500, "unit_ssp_custom_core_group_id": 1431001500, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 143100150001, "unit_ssp_custom_core_group_id": 1431001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100150001, "weapon_change": {"id": 143100150001, "before_weapon_id": 0, "after_weapon_id": 143100150090, "weapon": {"id": 143100150090, "name": "刺刀步槍 (衝鋒槍) SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100150090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100150090, "weapon_status": {"id": 143100150090, "range_min": 1