INSERT OR REPLACE INTO "units" VALUES(1431001600,'高达·但他林 (T型推进器)','高达但他林 (T型推进器装备)',4,3,30,0,'10000000043104300','4310','g4310u01600','AGW-G-71',1,1,1,1,8004,81,840,719,842,5,57629,253,6042,5175,5771,5,64113,281,6722,5757,6420,5,3,3,3,1,2,'在高达但他林的背部装设「T型推进器」的状态。
透过大型背包，能单独进行长距离飞行，并擅常活用其机动力 采取突袭据点及一击脱离战法。
还能将背包展开、覆盖双手，变形为巨大手臂的半罩型T型态， 用以对应近距离战斗。
当出现在前往多特殖民卫星的阿捷‧米拉治等人面前时， 机体颜色改成札尔姆弗特家的纹章色黑色。','{"id": 1431001600, "hp": 8004, "en": 81, "attack": 840, "defense": 719, "mobility": 842, "movement": 5, "max_hp": 57629, "max_en": 253, "max_attack": 6042, "max_defense": 5175, "max_mobility": 5771, "max_movement": 5, "sp_hp": 8905, "sp_en": 90, "sp_attack": 934, "sp_defense": 800, "sp_mobility": 937, "sp_movement": 5, "sp_max_hp": 64113, "sp_max_en": 281, "sp_max_attack": 6722, "sp_max_defense": 5757, "sp_max_mobility": 6420, "sp_max_movement": 5}','{"unit_id": 1431001600, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1431001600, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 143100160001, "unit_ssp_custom_core_group_id": 1431001600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100160001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100160001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100160001, "weapon_change": {"id": 143100160001, "before_weapon_id": 0, "after_weapon_id": 143100160090, "weapon": {"id": 143100160090, "name": "刺刀步槍 (衝鋒槍) SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100160090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 190001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100160090, "weapon_status": {"id": 143100160090, "range_min": 2, "range_max": 5, "power": 490