": 143100160004, "unit_ssp_custom_core_group_id": 1431001600, "level": 15, "release_point": 3000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000043004310, "unit_ssp_custom_core_release_function_set_id": 143100160004, "display_icon_type_index": 2, "schedule_id": 9999990001, "release_condition_custom_core_id": 0, "releases": []}, {"id": 143100160005, "unit_ssp_custom_core_group_id": 1431001600, "level": 20, "release_point": 15000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100160005, "display_icon_type_index": 1, "schedule_id": 9999990001, "release_condition_custom_core_id": 143100160003, "releases": []}], "initial_release": null}','高達但他林 (T型推進器裝備)','scrape',1791488368,'v2026.10.08',NULL);
INSERT OR REPLACE INTO "units" VALUES(1431001710,'高达·但他林 (半罩型T)','高达但他林 (半罩型T)',4,1,2,0,'10000000043104300','4310','g4310u01700','AGW-G-71',1,1,1,1,8795,88,1014,750,880,5,63322,264,7296,5398,6333,5,64042,267,7379,5459,6405,5,3,1,3,1,2,'但他林是在计划建造72架的高达骨架之中，于开发末期完成的机体。
根据现存的厄祭战争当时的设计资料，可知本机曾在开发途中多次对建造计划进行了大幅度修改。
这么做的目的，是为了反映已投入对MA实战的其他高达骨架的战斗纪录，以进一步变更装备设计。
以「单机便能突破各种战局」为设计理念的但他林，也因而直到战争即将结束才终于完成。
尽管如此，但他林在对MA战中仍立下了充分的战果，使得保有本机的一族因功受赏，并获准自称为「札尔姆弗特家」。
在以七星势力为顶点的加拉尔号角战后体制之下，更是日益彰显出其存在感。
即使过了300年，但他林仍作为札尔姆弗特家的象征留存至今。','{"id": 1431001710, "hp": 8795, "en": 88, "attack": 1014, "defense": 750, "mobility": 880, "movement": 5, "max_hp": 63322, "max_en": 264, "max_attack": 7296, "max_defense": 5398, "max_mobility": 6333, "max_movement": 5, "sp_hp": 8895, "sp_en": 89, "sp_attack": 1025, "sp_defense": 759, "sp_mobility": 890, "sp_movement": 5, "sp_max_hp": 64042, "sp_max_en": 267, "sp_max_attack": 7379, "sp_max_defense": 5459, "sp_max_mobility": 6405, "sp_max_movement": 5}','{"unit_id": 1431001710, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1431001710, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 143100171001, "unit_ssp_custom_core_group_id": 1431001710, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100171001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100171001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100171001, "weapon_change": {"id": 143100171001, "before_weapon_id": 0, "after_weapon_id": 143100171090, "weapon": {"id": 143100171090, "name": "半罩型T SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100171090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240002, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100171090, "weapon_status": {"id": 143100171090, "range_min": 1, "range_max": 3, "power": 5050, "en": 63, "hit_rat