INSERT OR REPLACE INTO "units" VALUES(1431001810,'高达·格莫瑞','高达格莫瑞',4,3,2,0,'10000000043104300','4310','g4310u01800','ASW-G-56',1,1,1,1,8292,89,922,842,923,5,59699,280,6635,6056,6330,5,60377,283,6710,6125,6401,5,3,1,3,1,2,'纳迪拉家持有的高达骨架型MS。
在300年前的「厄祭战争」末期， 开发的72架高达骨架采用机中的一架。
搭载两座亚哈反应炉，同时运作从而获得庞大的输出。
覆盖上半身的黑色兜帽状装甲， 是强度优于纳米层装甲的「纳米披肩」， 在众多MS中具有首屈一指的防御力。
主武装为巨大锚型的格斗兵器「战斗锚」， 但经历厄祭战争后只剩下单刃， 再加上机体的外观，其姿态带给人「死神」的印象。','{"id": 1431001810, "hp": 8292, "en": 89, "attack": 922, "defense": 842, "mobility": 923, "movement": 5, "max_hp": 59699, "max_en": 280, "max_attack": 6635, "max_defense": 6056, "max_mobility": 6330, "max_movement": 5, "sp_hp": 8386, "sp_en": 90, "sp_attack": 932, "sp_defense": 851, "sp_mobility": 934, "sp_movement": 5, "sp_max_hp": 60377, "sp_max_en": 283, "sp_max_attack": 6710, "sp_max_defense": 6125, "sp_max_mobility": 6401, "sp_max_movement": 5}','{"unit_id": 1431001810, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1431001810, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 143100181001, "unit_ssp_custom_core_group_id": 1431001810, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100181001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100181001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100181001, "weapon_change": {"id": 143100181001, "before_weapon_id": 0, "after_weapon_id": 143100181090, "weapon": {"id": 143100181090, "name": "戰鬥錨 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100181090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240002, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100181090, "weapon_status": {"id": 143100181090, "range_min": 1, "range_max": 3, "power"