INSERT OR REPLACE INTO "units" VALUES(1431001910,'奥特琳德','奥特琳德',3,1,2,0,'10000000043104300','4310','g4310u01900','V03-0907',1,1,1,1,7541,76,858,711,671,4,54292,204,6173,5115,5365,4,64427,242,7325,6070,6366,4,3,1,3,1,2,'吉晋家持有的华尔基丽骨架型MS。
吉晋家代代传承的机体， 现在是加拉尔号角的内部统制部队奥雷尔斯的队长 吉吉尔‧吉晋的专用机。
采用和高达骨架同时期开发的华尔基丽骨架， 曾留下厄祭战争末期与纳迪拉家持有的高达格莫瑞 并肩战斗的纪录。
主武装是双刃格斗兵器「华尔基丽双剑」，也能分离成两把剑使用。
原本似乎具备禁止兵器「丹因斯尼夫」的发射装置， 在双剑及左肩的平衡翼上都还可看出端倪， 但现在多以活用华尔基丽骨架特有高机动力的格斗战为主体。','{"id": 1431001910, "hp": 7541, "en": 76, "attack": 858, "defense": 711, "mobility": 671, "movement": 4, "max_hp": 54292, "max_en": 204, "max_attack": 6173, "max_defense": 5115, "max_mobility": 5365, "max_movement": 4, "sp_hp": 8949, "sp_en": 90, "sp_attack": 1018, "sp_defense": 843, "sp_mobility": 796, "sp_movement": 4, "sp_max_hp": 64427, "sp_max_en": 242, "sp_max_attack": 7325, "sp_max_defense": 6070, "sp_max_mobility": 6366, "sp_max_movement": 4}','{"unit_id": 1431001910, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1431001910, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 143100191001, "unit_ssp_custom_core_group_id": 1431001910, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100191001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100191001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100191001, "weapon_change": {"id": 143100191001, "before_weapon_id": 0, "after_weapon_id": 143100191090, "weapon": {"id": 143100191090, "name": "華爾基麗雙劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100191090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250006, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100191090, "weapon_status": {"id": 143100191090, "range_min": 1, "range