INSERT OR REPLACE INTO "units" VALUES(1431002000,'尖刺式格雷兹','古尼捷‧斯达克尔',2,3,2,0,'10000000043104300','4310','g4310u02000','EB-06N',1,1,1,1,5352,67,599,542,657,4,38534,200,4309,3899,4728,4,57159,296,6391,5783,7013,4,3,1,3,1,2,'隶属于加拉尔号角的内部统制部队奥雷尔斯的古尼捷特制机。
为了能在各种场所保持姿态控制，在左腕安装缆线钩爪， 肩部及脚部等处则设置固定用吊臂。
另外，强化脚部的阻尼器使稳定性提高，擅长利用其优异的隐密能力 进行一击脱离作战。
武装为古尼捷的标准装备「120mm步枪」， 以及能使敌机的关节部和感应器失效的「电击棒」。','{"id": 1431002000, "hp": 5352, "en": 67, "attack": 599, "defense": 542, "mobility": 657, "movement": 4, "max_hp": 38534, "max_en": 200, "max_attack": 4309, "max_defense": 3899, "max_mobility": 4728, "max_movement": 4, "sp_hp": 7939, "sp_en": 99, "sp_attack": 888, "sp_defense": 804, "sp_mobility": 975, "sp_movement": 4, "sp_max_hp": 57159, "sp_max_en": 296, "sp_max_attack": 6391, "sp_max_defense": 5783, "sp_max_mobility": 7013, "sp_max_movement": 4}','{"unit_id": 1431002000, "unit_ssp_initial_release_set_id": 1431002000, "unit_ssp_custom_core_group_id": 1431002000, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 143100200001, "unit_ssp_custom_core_group_id": 1431002000, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100200001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100200001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100200001, "weapon_change": {"id": 143100200001, "before_weapon_id": 0, "after_weapon_id": 143100200090, "weapon": {"id": 143100200090, "name": "120mm步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100200090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100200090, "weapon_status": {"id": 143100200090, "range_min": 1, "range_max": 4, "power