INSERT OR REPLACE INTO "units" VALUES(1434000160,'XK','XK',4,2,2,0,'10000000043404300','4340','g4340u00100','ASW-G-XK',1,1,1,1,9222,69,682,916,801,5,66393,241,4910,6591,4899,5,73862,268,5462,7332,5450,5,3,1,3,1,2,'高达维度尔试作阶段的样貌。
