INSERT OR REPLACE INTO "units" VALUES(1750000110,'Z高达3号机B型','Z高达3号机B型',4,2,2,0,'10000750008000810','7500','g7500u00100','MSZ-006-3B',1,1,1,1,10956,75,822,930,880,4,78884,264,5914,6693,5386,4,79780,267,5981,6769,5447,4,3,1,3,1,2,'以Z高达3号机为基础，施以重视火力的改良，改装而成的机体。
伴随武装导致的重量增加，双脚部位追加了辅助推进器， 以及往左右展开的大型平衡推进尾翼等，运动性能也经过改良。
尽管本机被视为由葛雷‧沃尔夫搭乘的机体， 因而被通称为「灰Z」，不过受到对机体全面施加的抗镭射复膜的影响，机体色呈现黄色。','{"id": 1750000110, "hp": 10956, "en": 75, "attack": 822, "defense": 930, "mobility": 880, "movement": 4, "max_hp": 78884, "max_en": 264, "max_attack": 5914, "max_defense": 6693, "max_mobility": 5386, "max_movement": 4, "sp_hp": 11081, "sp_en": 76, "sp_attack": 831, "sp_defense": 941, "sp_mobility": 890, "sp_movement": 4, "sp_max_hp": 79780, "sp_max_en": 267, "sp_max_attack": 5981, "sp_max_defense": 6769, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1750000110, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1750000110, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 175000011001, "unit_ssp_custom_core_group_id": 1750000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 175000011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 175000011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 175000011001, "weapon_change": {"id": 175000011001, "before_weapon_id": 0, "after_weapon_id": 175000011090, "weapon": {"id": 175000011090, "name": "大型鐳射步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 175000011090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 175000011090, "weapon_status": {"id": 175000011090, "range_min": 2, "range_max": 4