INSERT OR REPLACE INTO "units" VALUES(1761000100,'精神感应高达Mk-Ⅲ','重高达Mk-Ⅲ',4,2,12,1,'10000000076100950','7610','g7610u00100','-',1,1,1,1,11013,81,1083,1091,850,4,79290,257,7798,7851,5780,4,74282,241,7306,7355,5415,4,3,1,3,1,1,'政府军极机密开发的MS，是在军方实验设施中对具有「超感觉化病毒」适性的受验对象「玛莉亚‧尼可勒斯」做匹配测试时，被直接抢走的机体。
战斗能力非常强，具有全方位的性能，能以装备在全身的大量「米加粒子砲」和双手的「大型镭射剑」、格斗技包办远近距离战斗。
从地球的政府军手中抢来的本机体，到了曾介入地球上发生的人称「烈火审判」这场大灾难的「政府军月面基地」手中，被利用来达成要以超越人类的新生人类治理理想世界的目的。','{"id": 1761000100, "hp": 11013, "en": 81, "attack": 1083, "defense": 1091, "mobility": 850, "movement": 4, "max_hp": 79290, "max_en": 257, "max_attack": 7798, "max_defense": 7851, "max_mobility": 5780, "max_movement": 4, "sp_hp": 10317, "sp_en": 76, "sp_attack": 1015, "sp_defense": 1022, "sp_mobility": 797, "sp_movement": 4, "sp_max_hp": 74282, "sp_max_en": 241, "sp_max_attack": 7306, "sp_max_defense": 7355, "sp_max_mobility": 5415, "sp_max_movement": 4}','null','重高達Mk-Ⅲ','scrape',1791488368,'v2026.10.08',NULL);
