INSERT OR REPLACE INTO "units" VALUES(1763000110,'扎尼','萨尼',2,3,2,0,'10000000076300010','7630','g7630u00100','RRf-06',1,1,1,1,6637,70,737,667,734,4,47785,221,5303,4798,5030,4,60755,281,6742,6100,6396,4,3,1,3,1,2,'联邦军夺得渣古Ⅱ并加以改造而成的最初期试作型MS，机体各部位都能发现到与渣古Ⅱ的共通处，但也由于联邦军预算和技术不足，整体的机体性能偏低。
这架机体原来就不是用作战力，毋宁说运用重点是放在收集MS相关资料，要说是联邦军MS的根基机体也不为过。','{"id": 1763000110, "hp": 6637, "en": 70, "attack": 737, "defense": 667, "mobility": 734, "movement": 4, "max_hp": 47785, "max_en": 221, "max_attack": 5303, "max_defense": 4798, "max_mobility": 5030, "max_movement": 4, "sp_hp": 8439, "sp_en": 89, "sp_attack": 937, "sp_defense": 848, "sp_mobility": 933, "sp_movement": 4, "sp_max_hp": 60755, "sp_max_en": 281, "sp_max_attack": 6742, "sp_max_defense": 6100, "sp_max_mobility": 6396, "sp_max_movement": 4}','{"unit_id": 1763000110, "unit_ssp_initial_release_set_id": 1763000110, "unit_ssp_custom_core_group_id": 1763000110, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 176300011001, "unit_ssp_custom_core_group_id": 1763000110, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 176300011001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 176300011001, "sort_order": 1, "release_function_type_index": 5, "target_id": 176300011001, "weapon_change": {"id": 176300011001, "before_weapon_id": 0, "after_weapon_id": 176300011090, "weapon": {"id": 176300011090, "name": "120mm低後座力加農砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 176300011090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 176300011090, "weapon_status": {"id": 176300011090, "range_min": 3, "range_max"