INSERT OR REPLACE INTO "units" VALUES(1764000110,'高达Mk-Ⅱ试作0号机','高达Mk-Ⅱ试作0号机',4,3,2,0,'10000764008000810','7640','g7640u00100','RX-178-X0',1,1,1,1,8783,88,924,794,924,5,63234,278,6653,5714,6336,5,63952,281,6729,5779,6408,5,3,1,3,1,2,'泰坦斯开发之高性能MS「高达Mk-Ⅱ」的先行型试作机体，开发时完全未考虑成本，且在操纵和整备上有许多问题，活动时间也极短。
