INSERT OR REPLACE INTO "units" VALUES(1771000210,'吉姆防卫特装型','吉姆防卫特装型',3,1,2,0,'10000000077100010','7710','g7710u00200','RGM-79HC',1,1,1,1,7500,75,863,717,671,4,54000,203,6210,5161,5368,4,64080,241,7370,6125,6370,4,3,1,3,1,2,'以联邦军开发的吉姆综合性能提升机型「吉姆狙击特装型」为基底，将重点放在我军、舰队、军事设施等方面的防卫任务而开发的改装机。
在大战后期，为了大规模作战的成功，战略据点等方面的防卫任务至关重要，由于行动难度高，此机体是以护卫对象前往作战座标的前导为目的而制造。
其机动性比基底机要高，武装方面有考虑到近距离战斗而新设计的格斗武装，和为了护卫任务而装备的五层复合专用大型盾牌「护卫盾牌」，诸如此类，短兵交战能力也有提升，但由于也是难以驾驭的机体，所以几乎都是交给熟练的驾驶员运用，在大战后有不少机体证实是存在的。','{"id": 1771000210, "hp": 7500, "en": 75, "attack": 863, "defense": 717, "mobility": 671, "movement": 4, "max_hp": 54000, "max_en": 203, "max_attack": 6210, "max_defense": 5161, "max_mobility": 5368, "max_movement": 4, "sp_hp": 8900, "sp_en": 89, "sp_attack": 1024, "sp_defense": 851, "sp_mobility": 797, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 241, "sp_max_attack": 7370, "sp_max_defense": 6125, "sp_max_mobility": 6370, "sp_max_movement": 4}','{"unit_id": 1771000210, "unit_ssp_initial_release_set_id": 1771000210, "unit_ssp_custom_core_group_id": 1771000210, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 177100021001, "unit_ssp_custom_core_group_id": 1771000210, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 177100021001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 177100021001, "sort_order": 1, "release_function_type_index": 5, "target_id": 177100021001, "weapon_change": {"id": 177100021001, "before_weapon_id": 0, "after_weapon_id": 177100021090, "weapon": {"id": 177100021090, "name": "鐳射噴槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 177100021090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 177100021090,