INSERT OR REPLACE INTO "units" VALUES(1850001400,'NT-X','高达NT-X',4,1,2,0,'10000850008000810','8500','g8500u01400','RX-78NT-X(MRX-003)',1,1,1,1,7267,80,918,764,797,5,52323,239,6610,5495,5736,5,58209,266,7353,6113,6382,5,3,1,3,1,2,'联邦军新人类专用试作ＭＳ「亚雷克斯」的延伸发展机，随著一年战争的终结，联邦军为了研究从旧自护公国各机关接收的脑波传导技术而开发的机体。
其具特征性的武装是在背部搭载线控式脑波传导浮游砲，可以发动全方位攻击，由于采用线控，因此没有新人类能力的一般驾驶员也能进行一定程度的操控，但当时联邦军的技术仍无法缩小脑波传导系统，于是成为超重量级机体。
然而，据说其武器实验资料成为日后准脑波传导式远距兵器「引导砲」等的根源，似乎影响了后来ＭＳ的开发。
此外，虽是在奥古斯塔研究所的主导下开发本机体，但之后转由村雨研究所接手，因此被编上「ＭＲＸ─００３」的型式编号。','{"id": 1850001400, "hp": 7267, "en": 80, "attack": 918, "defense": 764, "mobility": 797, "movement": 5, "max_hp": 52323, "max_en": 239, "max_attack": 6610, "max_defense": 5495, "max_mobility": 5736, "max_movement": 5, "sp_hp": 8085, "sp_en": 89, "sp_attack": 1022, "sp_defense": 849, "sp_mobility": 887, "sp_movement": 5, "sp_max_hp": 58209, "sp_max_en": 266, "sp_max_attack": 7353, "sp_max_defense": 6113, "sp_max_mobility": 6382, "sp_max_movement": 5}','{"unit_id": 1850001400, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1850001400, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 185000140001, "unit_ssp_custom_core_group_id": 1850001400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 185000140001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 185000140001, "sort_order": 1, "release_function_type_index": 5, "target_id": 185000140001, "weapon_change": {"id": 185000140001, "before_weapon_id": 0, "after_weapon_id": 185000140090, "weapon": {"id": 185000140090, "name": "有線式大型浮游砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 185000140090, "attack_attr": 5, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 350039, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 185000140090, "weapon_status": {"id": 185000140090, "range_min": 2, "range_max": 5, "p