INSERT OR REPLACE INTO "units" VALUES(1850001500,'量产型比格·萨姆','量产型魔霸',3,3,12,0,'10000000085000010','8500','g8500u01500','MA-09',1,2,1,1,7000,70,733,630,738,4,50400,221,5271,4536,5061,4,64080,281,6702,5768,6434,4,3,1,3,1,1,'自护公国对要塞用试作型重MA「魔霸」的量产型，是为了攻略联邦军本部「查布罗」而开发的机体。
为了改善「魔霸」续航力短且低生产率的问题，废除可以避免镭射武器攻击的特殊防御装置「I力场发生器」，将装甲表面改成抗镭射涂层。虽然对镭射攻击的防御力低落，但仍保有强力大型米加粒子砲，攻击力足以一击击沉战舰。
由于改善了生产率，使得量产化总算有了眉目，却在同一时间因自护公国注定败北，于是就这么迎接战争终结而未能量产。','{"id": 1850001500, "hp": 7000, "en": 70, "attack": 733, "defense": 630, "mobility": 738, "movement": 4, "max_hp": 50400, "max_en": 221, "max_attack": 5271, "max_defense": 4536, "max_mobility": 5061, "max_movement": 4, "sp_hp": 8900, "sp_en": 89, "sp_attack": 931, "sp_defense": 801, "sp_mobility": 939, "sp_movement": 4, "sp_max_hp": 64080, "sp_max_en": 281, "sp_max_attack": 6702, "sp_max_defense": 5768, "sp_max_mobility": 6434, "sp_max_movement": 4}','{"unit_id": 1850001500, "unit_ssp_initial_release_set_id": 1850001500, "unit_ssp_custom_core_group_id": 1850001500, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 185000150001, "unit_ssp_custom_core_group_id": 1850001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 185000150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 185000150001, "sort_order": 1, "release_function_type_index": 5, "target_id": 185000150001, "weapon_change": {"id": 185000150001, "before_weapon_id": 0, "after_weapon_id": 185000150090, "weapon": {"id": 185000150090, "name": "大型米加粒子砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 185000150090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 120006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 185000150090, "weapon_status": {"id": 185000150090, "range_min": 3, "range_max": 