INSERT OR REPLACE INTO "units" VALUES(1850002360,'强人改','强人改',4,2,2,0,'10000000085000950','8500','g8500u02300','MS-15K',1,1,1,1,9126,68,788,926,799,5,65704,240,5668,6665,4886,5,73096,267,6305,7415,5436,5,3,1,3,1,2,'阿古捷斯修改自护公国的通用试作型MS「强人」，发展其重视白刃战的设计概念而成的机体。
大幅强化了以强人为基础的机体性能，在武装方面也加大了强人专用镭射军刀的功率，变更为「大型镭射剑」，特化了其格斗战能力，足以发挥堪称阿古捷斯次期量产型MS的性能。
然而，同时却也因特化为格斗战用途而丧失了通用性，使其尽管拥有高于同期开发的MS「扎斯Ｊ」与「瑞莎」之性能，但最后仍未能获得量产。
不过，从此机体获得的资料，日后成为了开发「Ｒ‧查查」的基础。','{"id": 1850002360, "hp": 9126, "en": 68, "attack": 788, "defense": 926, "mobility": 799, "movement": 5, "max_hp": 65704, "max_en": 240, "max_attack": 5668, "max_defense": 6665, "max_mobility": 4886, "max_movement": 5, "sp_hp": 10153, "sp_en": 76, "sp_attack": 876, "sp_defense": 1030, "sp_mobility": 889, "sp_movement": 5, "sp_max_hp": 73096, "sp_max_en": 267, "sp_max_attack": 6305, "sp_max_defense": 7415, "sp_max_mobility": 5436, "sp_max_movement": 5}','{"unit_id": 1850002360, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1850002360, "unit_ssp_add_status_id": 100009, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100009, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 26, "ssp_mobility": 23, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 526, "ssp_max_mobility": 458}, "cores": [{"id": 185000236001, "unit_ssp_custom_core_group_id": 1850002360, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 185000236001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 185000236001, "sort_order": 1, "release_function_type_index": 5, "target_id": 185000236001, "weapon_change": {"id": 185000236001, "before_weapon_id": 0, "after_weapon_id": 185000236090, "weapon": {"id": 185000236090, "name": "大型鐳射劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 185000236090, "attack_attr": 2, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 240006, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 185000236090, "weapon_status": {"id": 185000236090, "range_min": 1, "range_max": 3, "power": 4950, "en": 62, "hit_r