INSERT OR REPLACE INTO "units" VALUES(1850002510,'高达Ez8重装型','高达Ez8重武装型',4,2,12,0,'10000000085000010','8500','g8500u02500','RX-79Ez-8/HAC',1,1,1,1,9661,75,914,1054,836,4,69557,251,6581,7588,5386,4,70348,254,6656,7675,5447,4,3,1,3,1,1,'联邦军的特装型MS。
