INSERT OR REPLACE INTO "units" VALUES(1850003010,'大魔无腿型','大魔无腿型',3,3,2,0,'10000000085000010','8500','g8500u03000','MS-09F/Bn',1,1,1,1,7515,75,713,750,786,5,54108,237,5130,5400,5390,5,64209,281,6088,6408,6396,5,3,1,3,1,2,'自护公国军的计划MS。
力奇‧大魔的衍生机型之一。
