INSERT OR REPLACE INTO "units" VALUES(1850003300,'巴力毗珥高达','贝芬格高达',4,1,22,1,'10000000085002300','8500','g8500u03300','GB-9700',1,1,1,1,8616,96,1086,906,945,4,62035,286,7816,6519,6797,4,58117,268,7323,6107,6368,4,3,2,3,1,2,'在第7次宇宙大战后期，不分联邦军、宇宙革命军，「新人类」的存在变得非常巨大，尤其是对普通士兵造成的心理影响，甚至严重到能够左右胜败的地步。
因此打倒敌方新人类士兵，能够带来超越实际战果的效果。
联邦军基于这项考量，开发出了「用来打倒新人类的新人类专用MS」。
由于身负这项特殊任务，本机无视成本追求高性能，装备了对BIT用连装电热钢索、近距离战斗用的钩爪臂、砲击战用的音速粉碎砲等武装，在任何局面都能发挥出极强大的战斗能力。','{"id": 1850003300, "hp": 8616, "en": 96, "attack": 1086, "defense": 906, "mobility": 945, "movement": 4, "max_hp": 62035, "max_en": 286, "max_attack": 7816, "max_defense": 6519, "max_mobility": 6797, "max_movement": 4, "sp_hp": 8072, "sp_en": 90, "sp_attack": 1017, "sp_defense": 849, "sp_mobility": 885, "sp_movement": 4, "sp_max_hp": 58117, "sp_max_en": 268, "sp_max_attack": 7323, "sp_max_defense": 6107, "sp_max_mobility": 6368, "sp_max_movement": 4}','null','貝芬格高達','scrape',1791488368,'v2026.10.08',NULL);
