INSERT OR REPLACE INTO "units" VALUES(1850004850,'赞斯派因 (EX)','渣斯派因 (EX)',5,3,30,0,'10000000085001750','8500','g8500u04850','ZMT-S37S',1,1,1,1,9874,100,1002,958,1056,5,71089,315,7212,6897,7237,5,71089,315,7212,6897,7237,5,3,3,3,1,2,'渣斯卡路帝国的试作MS。
G GENERATION系列的原创单位。
利用自神圣军事同盟夺得的米诺夫斯基驱动装置技术所开发出的高性能MS，由塔西罗‧瓦高主导开发工程。
装载了与V2高达同样的米诺夫斯基驱动装置组件，不但能发挥压倒性的机动性能，也同样能使用「光之翼」进行攻击。
此外还装备有脑波传导兵器「铃声浮游砲」，擅于施展能透过精神波引发幻觉作用的全方位攻击。
机体性能和一般武装都极为充实，单机战斗力与V2不相上下。
但试作机才刚完成，塔西罗便旋即身亡，渣斯卡路战争也在不久后落幕，使得本机直到最后一刻都未曾登上历史舞台。
有一说指出，塔西罗生前曾计划在他成功掌握帝国实权之后，要将本机指定为国家的象征。','{"id": 1850004850, "hp": 9874, "en": 100, "attack": 1002, "defense": 958, "mobility": 1056, "movement": 5, "max_hp": 71089, "max_en": 315, "max_attack": 7212, "max_defense": 6897, "max_mobility": 7237, "max_movement": 5, "sp_hp": 9874, "sp_en": 100, "sp_attack": 1002, "sp_defense": 958, "sp_mobility": 1056, "sp_movement": 5, "sp_max_hp": 71089, "sp_max_en": 315, "sp_max_attack": 7212, "sp_max_defense": 6897, "sp_max_mobility": 7237, "sp_max_movement": 5}','null','渣斯派因 (EX)','scrape',1791488368,'v2026.10.08',1175000601);
INSERT OR REPLACE INTO "units" VALUES(1850005310,'露维·捷露Ⅱ','露维‧捷露Ⅱ',4,2,5,0,'10000850008000810','8500','g8500u05300','AMA-002S',1,2,1,1,10179,75,1003,1011,799,5,73287,237,7219,7276,5431,5,74120,240,7301,7359,5493,5,3,1,1,1,1,'以阿古捷斯的宇宙用攻击型巨大MA「露维‧捷露」为基础，搭载上脑波传导系统的后继机，并将此MA整体涂装为以拥有「红色彗星」名号的马沙‧阿兹纳布之个人配色「红色」为主的专用机。
本机与露维‧捷露一样，在全身上下装设了高功率的推进器与强力的镭射兵器，以及能够使镭射兵器的攻击无效化的特殊防御装置「I力场发生器」。
除了维持了压倒性的战斗力之外，最大的特征要属能够透过机身搭载的脑波传导装置借由新人类的精神波进行远端遥控的无人攻击武器「感应砲」做出全方位攻击。
和即使由旧人类驾驶也能发挥性能的基础机相较之下，本机乃是新人类专用的机体。
然而，在格利普斯战役初期本机刚进入开发阶段时，马沙便已因加入奥干而离开阿古捷斯，且亦已察觉其开发成本极高，故失去了开发意义，最终未能实现。','{"id": 1850005310, "hp": 10179, "en": 75, "attack": 1003, "defense": 1011, "mobility": 799, "movement": 5, "max_hp": 73287, "max_en": 237, "max_attack": 7219, "max_defense": 7276, "max_mobility": 5431, "max_movement": 5, "sp_hp": 10295, "sp_en": 76, "sp_attack": 1014, "sp_defense": 1022, "sp_mobility": 808, "sp_movement": 5, "sp_max_hp": 74120, "sp_max_en": 240, "sp_max_attack": 7301, "sp_max_defense": 7359, "sp_max_mobility": 5493, "sp_max_movement": 5}','{"unit_id": 1850005310, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1850005310, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 185000531001, "unit_ssp_custom_core_group_id": 1850005310, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 185000531001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 185000531001, "sort_order": 1, "release_function_type_index": 5, "target_id": 185000531001, "weapon_change": {"id": 185000531001, "before_weapon_id": 0, "after_weapon_id": 185000531090, "weapon": {"id": 185000531090, "name": "偏向米加粒子砲 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 185000531090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 185000531090, "weapon_status": {"id": 185000531090, "range_min": 2, "