INSERT OR REPLACE INTO "units" VALUES(1850005400,'里格·林格','利古‧林格',4,3,4,0,'10000000085001750','8500','g8500u05400','ZMT-S35S',1,1,1,1,7242,88,799,716,883,5,52136,263,5751,5151,6355,5,58001,293,6398,5731,7070,5,3,3,1,1,1,'渣斯卡路帝国的特殊MS。
作为脑波传导要塞「天使之轮」的支援单位而开发的机体。
可与天使之轮的控制波共振、增幅，并以将之散播到地球全土为主要任务。
因此，本机内也安装有小型的环状脑波传导系统，单机也能发出低功率的控制波。
此外还以射击钩爪和扩散镭射进行武装，作为MS来看也具备高度的战斗能力。
原本和天使之轮同时进行开发，但战局骤变之后已不再需要本机，开发也随之停止。','{"id": 1850005400, "hp": 7242, "en": 88, "attack": 799, "defense": 716, "mobility": 883, "movement": 5, "max_hp": 52136, "max_en": 263, "max_attack": 5751, "max_defense": 5151, "max_mobility": 6355, "max_movement": 5, "sp_hp": 8056, "sp_en": 98, "sp_attack": 889, "sp_defense": 796, "sp_mobility": 982, "sp_movement": 5, "sp_max_hp": 58001, "sp_max_en": 293, "sp_max_attack": 6398, "sp_max_defense": 5731, "sp_max_mobility": 7070, "sp_max_movement": 5}','{"unit_id": 1850005400, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1850005400, "unit_ssp_add_status_id": 100011, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100011, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 23, "ssp_defense": 21, "ssp_mobility": 25, "ssp_max_hp": 4119, "ssp_max_en": 21, "ssp_max_attack": 458, "ssp_max_defense": 412, "ssp_max_mobility": 503}, "cores": [{"id": 185000540001, "unit_ssp_custom_core_group_id": 1850005400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 185000540001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 185000540001, "sort_order": 1, "release_function_type_index": 5, "target_id": 185000540001, "weapon_change": {"id": 185000540001, "before_weapon_id": 0, "after_weapon_id": 185000540090, "weapon": {"id": 185000540090, "name": "射擊鉤爪（射擊） SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 185000540090, "attack_attr": 3, "weapon_attr": 3, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 340055, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 185000540090, "weapon_status": {"id": 185000540090, "range_min": 3, "range_max": 5, "power": 4850, "en": 6